def display_path(path: Path) -> Path:
    resolved = path.resolve()
    try:
        return resolved.relative_to(ROOT)
    except ValueError:
        return resolved


def unique_preserving_order(values: Iterable[str]) -> tuple[str, ...]:
    output: list[str] = []
    seen: set[str] = set()
    for value in values:
        if value in seen:
            continue
        seen.add(value)
        output.append(value)
    return tuple(output)


def build_output_token_aliases() -> dict[str, tuple[str, ...]]:
    aliases = {
        "all": DEFAULT_OUTPUT_NAMES,
        "all-csv": CSV_OUTPUT_NAMES,
        "all_csv": CSV_OUTPUT_NAMES,
        TRACKER_OUTPUT_NAME: (TRACKER_OUTPUT_NAME,),
        "next-slice": NEXT_SLICE_OUTPUT_NAMES,
        "next_slice": NEXT_SLICE_OUTPUT_NAMES,
        "public-event": PUBLIC_EVENT_OUTPUT_NAMES,
        "public_event": PUBLIC_EVENT_OUTPUT_NAMES,
        "public-event-evidence": (PUBLIC_EVENT_EVIDENCE_CSV_NAME,),
        "public_event_evidence": (PUBLIC_EVENT_EVIDENCE_CSV_NAME,),
        "public-event-auxiliary": (PUBLIC_EVENT_AUXILIARY_EVIDENCE_CSV_NAME,),
        "public_event_auxiliary": (PUBLIC_EVENT_AUXILIARY_EVIDENCE_CSV_NAME,),
    }
    for csv_name in CSV_OUTPUT_NAMES:
        aliases[csv_name.lower()] = (csv_name,)
        aliases[Path(csv_name).stem.lower()] = (csv_name,)
    return aliases


def normalize_output_token(value: str) -> str:
    normalized = value.strip().replace("\\", "/")
    if "/" in normalized:
        normalized = normalized.rsplit("/", 1)[1]
    return normalized.lower()


def resolve_selected_output_names(values: Sequence[str] | None) -> tuple[str, ...]:
    if not values:
        return DEFAULT_OUTPUT_NAMES

    aliases = build_output_token_aliases()
    selected: list[str] = []
    for value in values:
        for token in value.split(","):
            normalized = normalize_output_token(token)
            if not normalized:
                continue
            if normalized not in aliases:
                available = ", ".join(("all", "all-csv", "next-slice", "public-event", TRACKER_OUTPUT_NAME))
                raise ValueError(f"Unknown output '{token.strip()}'. Use --list-outputs to see CSV names and aliases; common aliases: {available}.")
            selected.extend(aliases[normalized])

    selected_with_dependencies = list(selected)
    for name in selected:
        selected_with_dependencies.extend(OUTPUT_WRITE_DEPENDENCIES.get(name, ()))

    selected_names = set(unique_preserving_order(selected_with_dependencies))
    return tuple(name for name in DEFAULT_OUTPUT_NAMES if name in selected_names)


def output_names_for_help() -> tuple[str, ...]:
    return (
        "aliases: all, all-csv, next-slice, public-event, public-event-evidence, public-event-auxiliary, tracker",
        *CSV_OUTPUT_NAMES,
    )

