def split_top_level(text: str, delimiter: str = ",") -> list[str]:
    parts: list[str] = []
    current: list[str] = []
    depth = 0
    in_string = False
    index = 0

    while index < len(text):
        ch = text[index]
        if in_string:
            current.append(ch)
            if ch == "'":
                if index + 1 < len(text) and text[index + 1] == "'":
                    current.append(text[index + 1])
                    index += 1
                else:
                    in_string = False
            elif ch == "\\" and index + 1 < len(text):
                current.append(text[index + 1])
                index += 1
            index += 1
            continue

        if ch == "'":
            in_string = True
            current.append(ch)
        elif ch == "(":
            depth += 1
            current.append(ch)
        elif ch == ")":
            depth -= 1
            current.append(ch)
        elif ch == delimiter and depth == 0:
            parts.append("".join(current).strip())
            current = []
        else:
            current.append(ch)
        index += 1

    if current:
        parts.append("".join(current).strip())
    return parts


def parse_create_columns(path: Path, table_name: str) -> list[str]:
    text = path.read_text(encoding="utf-8", errors="replace")
    pattern = re.compile(
        rf"CREATE\s+TABLE(?:\s+IF\s+NOT\s+EXISTS)?\s+`?{re.escape(table_name)}`?\s*\((.*?)\);",
        re.IGNORECASE | re.DOTALL,
    )
    match = pattern.search(text)
    if not match:
        raise ValueError(f"Could not find CREATE TABLE for {table_name} in {path}")

    columns: list[str] = []
    for segment in split_top_level(match.group(1)):
        segment = segment.strip()
        if not segment:
            continue
        token = segment.split(None, 1)[0].strip("`")
        if token.upper() in {"PRIMARY", "KEY", "INDEX", "CONSTRAINT", "UNIQUE"}:
            continue
        columns.append(token)
    return columns


def iter_insert_payloads(text: str, table_name: str) -> Iterable[str]:
    pattern = re.compile(
        rf"INSERT\s+INTO\s+`?{re.escape(table_name)}`?(?:\s*\([^)]*\))?\s+VALUES\s*",
        re.IGNORECASE,
    )
    for match in pattern.finditer(text):
        index = match.end()
        in_string = False
        while index < len(text):
            ch = text[index]
            if in_string:
                if ch == "'":
                    if index + 1 < len(text) and text[index + 1] == "'":
                        index += 1
                    else:
                        in_string = False
                elif ch == "\\" and index + 1 < len(text):
                    index += 1
            elif ch == "'":
                in_string = True
            elif ch == ";":
                yield text[match.end() : index]
                break
            index += 1


def parse_sql_value(raw: str) -> str:
    value = raw.strip()
    if value.upper() == "NULL":
        return ""
    if len(value) >= 2 and value[0] == "'" and value[-1] == "'":
        inner = value[1:-1]
        inner = inner.replace("''", "'")
        inner = inner.replace("\\'", "'")
        inner = inner.replace("\\\\", "\\")
        return inner
    return value


def parse_row_values(row_text: str) -> list[str]:
    return [parse_sql_value(value) for value in split_top_level(row_text)]


def strip_insert_payload_tail(payload: str) -> str:
    depth = 0
    in_string = False
    index = 0

    while index < len(payload):
        ch = payload[index]
        if in_string:
            if ch == "'":
                if index + 1 < len(payload) and payload[index + 1] == "'":
                    index += 1
                else:
                    in_string = False
            elif ch == "\\" and index + 1 < len(payload):
                index += 1
        elif ch == "'":
            in_string = True
        elif ch == "(":
            depth += 1
        elif ch == ")":
            depth -= 1
        elif depth == 0 and re.match(r"ON\s+DUPLICATE\s+KEY\s+UPDATE\b", payload[index:], re.IGNORECASE):
            return payload[:index]
        index += 1

    return payload


def decode_sql_comment(value: str) -> str:
    match = re.fullmatch(r"CONVERT\s*\(\s*0x([0-9a-fA-F\s]+)\s+USING\s+utf8mb4\s*\)", value.strip(), re.DOTALL | re.IGNORECASE)
    if not match:
        return parse_sql_value(value)
    hex_text = re.sub(r"\s+", "", match.group(1))
    try:
        return bytes.fromhex(hex_text).decode("utf-8", errors="replace")
    except ValueError:
        return value


def iter_table_rows(path: Path, table_name: str) -> Iterable[list[str]]:
    text = path.read_text(encoding="utf-8", errors="replace")
    for payload in iter_insert_payloads(text, table_name):
        payload = strip_insert_payload_tail(payload)
        depth = 0
        in_string = False
        row_start: int | None = None
        index = 0
        while index < len(payload):
            ch = payload[index]
            if in_string:
                if ch == "'":
                    if index + 1 < len(payload) and payload[index + 1] == "'":
                        index += 1
                    else:
                        in_string = False
                elif ch == "\\" and index + 1 < len(payload):
                    index += 1
            elif ch == "'":
                in_string = True
            elif ch == "(":
                if depth == 0:
                    row_start = index + 1
                depth += 1
            elif ch == ")":
                depth -= 1
                if depth == 0 and row_start is not None:
                    yield parse_row_values(payload[row_start:index])
                    row_start = None
            index += 1


def load_table(sql_dir: Path, file_name: str, table_name: str) -> list[dict[str, str]]:
    path = sql_dir / file_name
    columns = parse_create_columns(path, table_name)
    rows: list[dict[str, str]] = []
    for values in iter_table_rows(path, table_name):
        rows.append({column: values[index] if index < len(values) else "" for index, column in enumerate(columns)})
    return rows


def load_insert_rows(path: Path, table_name: str, columns: tuple[str, ...]) -> list[dict[str, str]]:
    rows: list[dict[str, str]] = []
    if not path.exists():
        return rows
    for values in iter_table_rows(path, table_name):
        rows.append({column: values[index] if index < len(values) else "" for index, column in enumerate(columns)})
    return rows


def load_csv_rows(path: Path) -> list[dict[str, str]]:
    if not path.exists():
        raise FileNotFoundError(f"Missing CSV input: {path}")
    with path.open(encoding="utf-8-sig", newline="") as handle:
        return list(csv.DictReader(handle))


def to_int(value: str | None, default: int = 0) -> int:
    if value is None or value == "":
        return default
    try:
        return int(float(value))
    except ValueError:
        return default


def has_client_id(value: str | None) -> bool:
    value_int = to_int(value)
    return value_int not in {0, INVALID_CLIENT_ID}


def join_ids(values: Iterable[int | str]) -> str:
    ids = [str(value) for value in values if str(value) not in {"", "0"}]
    return ";".join(ids)


def split_joined_ids(value: object) -> list[int]:
    return [to_int(part) for part in str(value).split(";") if to_int(part)]


def split_joined_values(value: object) -> list[str]:
    return [part for part in str(value).split(";") if part]


def join_sample(values: Iterable[int | str], limit: int = 12) -> str:
    seen: set[str] = set()
    result: list[str] = []
    for value in values:
        text = str(value)
        if text in {"", "0"} or text in seen:
            continue
        seen.add(text)
        result.append(text)

    if len(result) <= limit:
        return ";".join(result)
    return ";".join(result[:limit] + [f"...+{len(result) - limit}"])


def join_text_sample(values: Iterable[int | str], limit: int = 8, separator: str = " || ") -> str:
    seen: set[str] = set()
    result: list[str] = []
    for value in values:
        text = str(value)
        if text in {"", "0"} or text in seen:
            continue
        seen.add(text)
        result.append(text)

    if len(result) <= limit:
        return separator.join(result)
    return separator.join(result[:limit] + [f"...+{len(result) - limit}"])


def format_named_counts(counter: Counter[str]) -> str:
    return ";".join(f"{name}={counter[name]}" for name in sorted(counter) if name)


def text_by_id(strings: dict[int, str], text_id: int) -> str:
    if text_id <= 0:
        return ""
    return strings.get(text_id, "")


def load_script_owners(script_root: Path) -> dict[int, list[str]]:
    owners: dict[int, list[str]] = defaultdict(list)
    owner_pattern = re.compile(r"ScriptFilterOwnerId\(([^)]+)\)")
    for path in sorted(script_root.rglob("*.cs")):
        if "obj" in path.parts:
            continue
        text = path.read_text(encoding="utf-8", errors="replace")
        for match in owner_pattern.finditer(text):
            for owner_id in re.findall(r"\d+", match.group(1)):
                owners[int(owner_id)].append(str(path.relative_to(ROOT)))
    return owners


def relative_display_path(path: Path, fallback_root: Path | None = None) -> str:
    try:
        return str(path.relative_to(ROOT))
    except ValueError:
        if fallback_root is not None:
            try:
                return str(path.relative_to(fallback_root))
            except ValueError:
                pass
        return str(path)


def script_kind(path: Path, class_name: str, block: str) -> str:
    if "IQuestScript" in block or "FollowUpQuestScript" in block:
        return "quest_script"
    if class_name.endswith("MapScript") or path.name.endswith("MapScript.cs"):
        return "map_script"
    if "PublicEventScript" in class_name or class_name.endswith("EventScript") or class_name.endswith("SubEventScript"):
        return "public_event_script"
    if "SpellScript" in class_name or "Spells" in path.parts:
        return "spell_script"
    if "Quests" in path.parts:
        return "quest_related_runtime_script"
    return "runtime_script"


def load_script_owner_details(script_root: Path) -> list[dict[str, object]]:
    details: list[dict[str, object]] = []
    for path in sorted(script_root.rglob("*.cs")):
        if "obj" in path.parts:
            continue
        text = path.read_text(encoding="utf-8", errors="replace")
        for owner_ids, block in quest_implementation_audit.iter_script_owner_blocks(text):
            class_match = re.search(r"\bclass\s+([A-Za-z_][A-Za-z0-9_]*)", block)
            class_name = class_match.group(1) if class_match else path.stem
            owner_id_list = sorted(owner_ids)
            kind = script_kind(path, class_name, block)
            for owner_id in owner_id_list:
                details.append(
                    {
                        "owner_id": owner_id,
                        "owner_ids_on_attribute": join_ids(owner_id_list),
                        "script_path": relative_display_path(path, script_root),
                        "script_class": class_name,
                        "script_kind": kind,
                    }
                )
    return sorted(details, key=lambda row: (to_int(str(row["owner_id"])), str(row["script_path"]), str(row["script_class"])))


def content_script_key(relative_parts: tuple[str, ...]) -> tuple[str, ...]:
    if len(relative_parts) > 2 and relative_parts[2] != "Script":
        return relative_parts[:3]
    return relative_parts[:2]


def load_map_scripts(script_root: Path) -> dict[int, dict[str, object]]:
    scripts: dict[int, dict[str, object]] = {}
    owner_pattern = re.compile(r"ScriptFilterOwnerId\(([^)]+)\)")
    public_event_pattern = re.compile(r"PublicEventId\s*=>\s*([0-9]+)u?")
    for path in sorted(script_root.rglob("*MapScript.cs")):
        if "obj" in path.parts:
            continue
        text = path.read_text(encoding="utf-8", errors="replace")
        owner_match = owner_pattern.search(text)
        if not owner_match:
            continue
        owner_ids = [int(value) for value in re.findall(r"\d+", owner_match.group(1))]
        public_events = [int(value) for value in public_event_pattern.findall(text)]
        for owner_id in owner_ids:
            relative_parts = path.relative_to(script_root).parts
            scripts[owner_id] = {
                "path": str(path.relative_to(ROOT)),
                "public_events": public_events,
                "folder": relative_parts[0],
                "content_key": content_script_key(relative_parts),
            }
    return scripts


def load_content_script_details(script_root: Path) -> dict[tuple[str, ...], dict[str, set[int] | list[str]]]:
    details: dict[tuple[str, ...], dict[str, set[int] | list[str]]] = defaultdict(lambda: {"paths": [], "owners": set()})
    owner_pattern = re.compile(r"ScriptFilterOwnerId\(([^)]+)\)")
    for path in sorted(script_root.rglob("*.cs")):
        if "obj" in path.parts:
            continue
        relative_parts = path.relative_to(script_root).parts
        if len(relative_parts) < 2:
            continue
        key = content_script_key(relative_parts)
        details[key]["paths"].append(str(path.relative_to(ROOT)))  # type: ignore[index]
        text = path.read_text(encoding="utf-8", errors="replace")
        for match in owner_pattern.finditer(text):
            for owner_id in re.findall(r"\d+", match.group(1)):
                details[key]["owners"].add(int(owner_id))  # type: ignore[index]
    return details


def quest_achievement_index(achievements: list[dict[str, str]], checklists: list[dict[str, str]]) -> dict[int, list[int]]:
    achievement_by_id = {to_int(row["ID"]): row for row in achievements}
    by_quest: dict[int, set[int]] = defaultdict(set)

    for row in achievements:
        achievement_id = to_int(row["ID"])
        if to_int(row["achievementTypeId"]) not in QUEST_ACHIEVEMENT_TYPES:
            continue
        for column in ("objectId", "objectIdAlt"):
            quest_id = to_int(row[column])
            if quest_id:
                by_quest[quest_id].add(achievement_id)

    for row in checklists:
        achievement_id = to_int(row["achievementId"])
        achievement = achievement_by_id.get(achievement_id)
        if not achievement or to_int(achievement["achievementTypeId"]) not in QUEST_ACHIEVEMENT_TYPES:
            continue
        for column in ("objectId", "objectIdAlt"):
            quest_id = to_int(row[column])
            if quest_id:
                by_quest[quest_id].add(achievement_id)

    return {quest_id: sorted(ids) for quest_id, ids in by_quest.items()}


def quest_loot_index(quest_rows: list[dict[str, str]], quest_loot_sql: Path) -> dict[int, int]:
    objective_to_quests: dict[int, list[int]] = defaultdict(list)
    for row in quest_rows:
        quest_id = to_int(row["ID"])
        for objective_column in QUEST_OBJECTIVE_COLUMNS:
            objective_id = to_int(row[objective_column])
            if objective_id:
                objective_to_quests[objective_id].append(quest_id)

    counts: dict[int, int] = defaultdict(int)
    if not quest_loot_sql.exists():
        return counts

    text = quest_loot_sql.read_text(encoding="utf-8", errors="replace")
    for match in re.finditer(r"\(\s*\d+\s*,\s*NULL\s*,\s*100\s*,\s*1\s*,\s*1\s*,\s*8\s*,\s*(\d+)\s*,", text):
        objective_id = int(match.group(1))
        for quest_id in objective_to_quests.get(objective_id, []):
            counts[quest_id] += 1
    return counts


def classify_quest_evidence(bucket: str) -> tuple[str, str]:
    if bucket == "curated_full":
        return "implemented_with_focused_tests_pending_manual_smoke", "not_retail_complete"
    if bucket == "generic_with_script":
        return "mapped_table_driven_with_script_hook_pending_world_smoke", "not_retail_complete"
    if bucket == "generic_table_driven":
        return "mapped_table_driven_pending_world_spawns_loot_smoke", "not_retail_complete"
    if bucket == "no_objectives":
        return MAPPED_ONLY_NO_OBJECTIVE_QUEST_STATUS, "not_retail_complete"
    if "partial" in bucket or "stub" in bucket:
        return "partial_or_stub_blocked", "not_retail_complete"
    if "blocked" in bucket:
        return "blocked_objective_family", "not_retail_complete"
    return "review_required", "not_retail_complete"


def quest_blocker_summary(
    bucket: str,
    quest_id: int | str = "",
    quest_name: str = "",
    world_zone_id: int | str = "",
    quest_category_id: int | str = "",
    quest_group_id: int | str = "",
    quest_type: int | str = "",
    quest_subtype_id: int | str = "",
    content_finder_type: int | str = "",
    faction_enum: int | str = "",
    con_level: int | str = "",
    prereq_level: int | str = "",
    prereq_flags: int | str = "",
    prereq_quest_ids: str = "",
    quest_exclusion_ids: str = "",
    prerequisite_id: int | str = "",
    objective_ids: str = "",
    objective_types: str = "",
    objective_data: str = "",
    reward_ids: str = "",
    reward_types: str = "",
    pushed_items: str = "",
    virtual_pushed_items: str = "",
    quest_virtual_loot_groups: int | str = "",
    achievement_ids: str = "",
    script_paths: str = "",
) -> str:
    def has_value(value: int | str) -> bool:
        return str(value) not in {"", "0"}

    subject = f"Quest2 {quest_id}" if quest_id != "" else "Quest2 row"
    if quest_name:
        subject += f" ({quest_name})"

    details: list[str] = []
    for label, value in (
        ("WorldZone", world_zone_id),
        ("category", quest_category_id),
        ("group", quest_group_id),
        ("type", quest_type),
        ("subtype", quest_subtype_id),
        ("contentFinder", content_finder_type),
        ("faction", faction_enum),
        ("conLevel", con_level),
        ("preqLevel", prereq_level),
        ("preqFlags", prereq_flags),
        ("Prerequisite", prerequisite_id),
    ):
        if has_value(value):
            details.append(f"{label} {value}")
    if prereq_quest_ids:
        details.append(f"required quests {prereq_quest_ids}")
    if quest_exclusion_ids:
        details.append(f"excluded quests {quest_exclusion_ids}")
    if objective_ids:
        details.append(f"objectives {objective_ids}")
    if objective_types:
        details.append(f"objective types {objective_types}")
    if objective_data:
        details.append(f"objective data/type/count {objective_data}")
    if reward_ids:
        details.append(f"Quest2Reward rows {reward_ids}")
    if reward_types:
        details.append(f"reward types {reward_types}")
    if pushed_items:
        details.append(f"pushed items {pushed_items}")
    if virtual_pushed_items:
        details.append(f"virtual pushed items {virtual_pushed_items}")
    if has_value(quest_virtual_loot_groups):
        details.append(f"quest virtual loot groups {quest_virtual_loot_groups}")
    if achievement_ids:
        details.append(f"achievement hooks {achievement_ids}")
    script_sample = join_text_sample(split_joined_values(script_paths), limit=3, separator=";")
    if script_sample:
        details.append(f"script owners {script_sample}")
    detail_clause = f" with {', '.join(details)}" if details else ""

    if bucket == "no_objectives":
        return (
            f"{subject}{detail_clause} is a zero-objective row. Shared QuestManager accept-to-achieved and receiver turn-in"
            " lifecycle paths have representative reward and achievement-hook tests, but retail completion still needs"
            " quest availability, row-specific receiver/dialog routing, row-specific reward and achievement side effects,"
            " and client/manual smoke."
        )
    if bucket == "curated_partial_stub_script":
        return (
            f"{subject}{detail_clause} has a tracked stub quest script owner, but the script has no implementation markers;"
            " retail completion needs row-specific mechanic proof, objective trigger ownership, follow-up/reward/achievement"
            " side effects, automated coverage, and client/manual smoke."
        )
    if bucket == "curated_full":
        return (
            f"{subject}{detail_clause} has focused runtime coverage, but the row is not retail-complete until the exact"
            " client dialog/receiver flow, objective triggers, reward and achievement side effects, negative cases, and"
            " manual smoke are verified."
        )
    if "blocked" in bucket:
        return (
            f"{subject}{detail_clause} has an objective family that is not mapped to a safe runtime producer; retail completion"
            " is blocked until client/table/decompile evidence proves the trigger semantics and a focused implementation is"
            " verified."
        )
    if "partial" in bucket:
        return (
            f"{subject}{detail_clause} has partial objective support; retail completion needs exact producer semantics,"
            " row-specific objective behavior, side effects, focused tests, and client/manual smoke."
        )
    if bucket == "generic_with_script":
        return (
            f"{subject}{detail_clause} is mapped through table data plus script ownership, but this is not a retail-complete"
            " gameplay claim; world placements, objective triggers, script side effects, loot cadence, rewards, achievements,"
            " and client smoke remain row-specific validation work."
        )
    return (
        f"{subject}{detail_clause} is mapped through generic table coverage, but this is not a retail-complete gameplay claim;"
        " world placements, objective triggers, loot cadence, rewards, achievements, and client smoke remain row-specific"
        " validation work."
    )


def objective_support_status(objective_type: int) -> str:
    if objective_type in quest_implementation_audit.GENERIC:
        return "mapped_generic_handler"
    if objective_type in quest_implementation_audit.PARTIAL:
        return "partial_handler"
    if objective_type in quest_implementation_audit.UNSUPPORTED:
        return "unsupported_or_unmapped"
    return "review_required"


def objective_evidence_status(quest_id: int, objective_type: int, has_objective_row: bool, objective: dict[str, str] | None = None) -> str:
    if not has_objective_row:
        return "missing_client_objective_row"
    support_status = objective_support_status(objective_type)
    if support_status == "mapped_generic_handler":
        if (
            objective_type == ACTIVATE_ENTITY_OBJECTIVE_TYPE
            and objective
            and to_int(objective.get("data")) == 0
            and to_int(objective.get("targetGroupIdRewardPane")) != 0
        ):
            credit_test_status = QUEST_OBJECTIVE_CREDIT_TESTS.get((quest_id, to_int(objective.get("ID"))))
            if credit_test_status:
                return credit_test_status
            return "mapped_activate_entity_reward_pane_target_group_with_test_pending_spawn_credit_smoke"
        if objective_type == ENTER_AREA_OBJECTIVE_TYPE and objective and objective_has_world_location_indicator(objective):
            return "mapped_enter_area_world_location_trigger_with_test_pending_trigger_placement_smoke"
        return "mapped_objective_handler_pending_world_trigger_smoke"
    if support_status == "partial_handler":
        return "partial_objective_handler_blocked"
    if support_status == "unsupported_or_unmapped":
        return "unsupported_or_unmapped_objective_type"
    return "review_required"


def objective_has_world_location_indicator(objective: dict[str, str]) -> bool:
    return any(
        to_int(objective.get(f"worldLocationsIdIndicator{suffix}"))
        for suffix in VIRTUAL_PUSHED_ITEM_SUFFIXES
    )


