def build_quest_rows(
    client_sql_dir: Path,
    script_main: Path,
    strings: dict[int, str],
    quest_rows: list[dict[str, str]],
    objective_rows: list[dict[str, str]],
    reward_rows: list[dict[str, str]],
    achievements: list[dict[str, str]],
    checklists: list[dict[str, str]],
) -> list[dict[str, object]]:
    objectives = {
        to_int(row["ID"]): {
            "id": to_int(row["ID"]),
            "type": to_int(row["type"]),
            "flags": to_int(row["flags"]),
            "count": to_int(row["count"]),
            "data": to_int(row["data"]),
        }
        for row in objective_rows
    }
    rewards_by_quest: dict[int, list[dict[str, str]]] = defaultdict(list)
    for row in reward_rows:
        rewards_by_quest[to_int(row["quest2Id"])].append(row)

    script_ids = quest_implementation_audit.load_script_ids(script_main)
    stub_script_ids = quest_implementation_audit.load_script_quality(script_main)
    script_owners = load_script_owners(script_main)
    achievement_by_quest = quest_achievement_index(achievements, checklists)
    quest_loot_counts = quest_loot_index(quest_rows, QUEST_LOOT_SQL)

    output: list[dict[str, object]] = []
    for row in sorted(quest_rows, key=lambda item: to_int(item["ID"])):
        quest_id = to_int(row["ID"])
        objective_ids = [
            to_int(row[column])
            for column in QUEST_OBJECTIVE_COLUMNS
            if to_int(row[column])
        ]
        quest_for_classification = {"id": quest_id, "objective_ids": tuple(objective_ids)}
        bucket = quest_implementation_audit.classify(quest_for_classification, objectives, script_ids, stub_script_ids)
        evidence_status, completion_status = classify_quest_evidence(bucket)
        quest_summary_override = QUEST_SUMMARY_OVERRIDES.get(quest_id, {})
        evidence_status = str(quest_summary_override.get("evidence_status", evidence_status))
        quest_rewards = rewards_by_quest.get(quest_id, [])
        reward_types = sorted({to_int(reward["quest2RewardTypeId"]) for reward in quest_rewards})
        pushed_items = [
            f"{to_int(row[f'pushed_itemId{suffix}'])}x{to_int(row[f'pushed_itemCount{suffix}'])}"
            for suffix in PUSHED_ITEM_SUFFIXES
            if to_int(row[f"pushed_itemId{suffix}"])
        ]
        virtual_pushed_items = [
            f"{to_int(row[f'virtualItemIdPushed{suffix}'])}x{to_int(row[f'virtualItemPushedCount{suffix}'])}"
            for suffix in VIRTUAL_PUSHED_ITEM_SUFFIXES
            if to_int(row[f"virtualItemIdPushed{suffix}"])
        ]
        prereq_quests = [to_int(row[column]) for column in ("preq_quest0", "preq_quest01", "preq_quest02") if to_int(row[column])]
        exclusion_quests = [to_int(row[column]) for column in ("questIdExclusionPreq0", "questIdExclusionPreq1", "questIdExclusionPreq2") if to_int(row[column])]
        objective_types = [objectives[objective_id]["type"] for objective_id in objective_ids if objective_id in objectives]
        objective_data = [
            f"{objective_id}:{objectives[objective_id]['type']}:{objectives[objective_id]['data']}:{objectives[objective_id]['count']}"
            for objective_id in objective_ids
            if objective_id in objectives
        ]
        prereq_quest_ids = join_ids(prereq_quests)
        quest_exclusion_ids = join_ids(exclusion_quests)
        objective_id_text = join_ids(objective_ids)
        objective_type_text = join_ids(objective_types)
        objective_data_text = join_ids(objective_data)
        quest2_reward_ids = join_ids(to_int(reward["ID"]) for reward in quest_rewards)
        quest2_reward_types = join_ids(reward_types)
        pushed_item_text = join_ids(pushed_items)
        virtual_pushed_item_text = join_ids(virtual_pushed_items)
        quest_virtual_loot_group_count = quest_loot_counts.get(quest_id, 0)
        related_achievement_ids = join_ids(achievement_by_quest.get(quest_id, []))
        script_path_text = join_ids(script_owners.get(quest_id, []))
        evidence_sources = "wildstar_client_mysql/Quest2.tbl.sql;wildstar_client_mysql/QuestObjective.tbl.sql;wildstar_client_mysql/Quest2Reward.tbl.sql;wildstar_client_mysql/Achievement*.tbl.sql;Source/NexusForever.Script.Main;Tools/DataMapping/sql/laughingws_quest_loot_seed.sql;Decomp/Analysis/QUEST_IMPLEMENTATION_STATUS.md"
        if bucket == "no_objectives":
            evidence_sources += ";Source/NexusForever.Game/Entity/QuestManager.cs;Source/NexusForever.Game.Tests/Quest/QuestTests.cs"
        evidence_sources = str(quest_summary_override.get("evidence_sources", evidence_sources))
        blocker_summary = str(
            quest_summary_override.get(
                "blocker_summary",
                quest_blocker_summary(
                    bucket,
                    quest_id,
                    text_by_id(strings, to_int(row["localizedTextIdTitle"])),
                    to_int(row["worldZoneId"]),
                    to_int(row["questCategoryId"]),
                    to_int(row["groupId"]),
                    to_int(row["type"]),
                    to_int(row["quest2SubTypeId"]),
                    to_int(row["questContentFinderTypeEnum"]),
                    to_int(row["questPlayerFactionEnum"]),
                    to_int(row["conLevel"]),
                    to_int(row["preq_level"]),
                    to_int(row["preq_flags"]),
                    prereq_quest_ids,
                    quest_exclusion_ids,
                    to_int(row["prerequisiteId"]),
                    objective_id_text,
                    objective_type_text,
                    objective_data_text,
                    quest2_reward_ids,
                    quest2_reward_types,
                    pushed_item_text,
                    virtual_pushed_item_text,
                    quest_virtual_loot_group_count,
                    related_achievement_ids,
                    script_path_text,
                ),
            )
        )

        output.append(
            {
                "quest_id": quest_id,
                "name": text_by_id(strings, to_int(row["localizedTextIdTitle"])),
                "bucket": bucket,
                "evidence_status": evidence_status,
                "completion_status": completion_status,
                "world_zone_id": to_int(row["worldZoneId"]),
                "quest_category_id": to_int(row["questCategoryId"]),
                "quest_group_id": to_int(row["groupId"]),
                "quest_type": to_int(row["type"]),
                "quest_subtype_id": to_int(row["quest2SubTypeId"]),
                "content_finder_type": to_int(row["questContentFinderTypeEnum"]),
                "faction_enum": to_int(row["questPlayerFactionEnum"]),
                "con_level": to_int(row["conLevel"]),
                "prereq_level": to_int(row["preq_level"]),
                "prereq_flags": to_int(row["preq_flags"]),
                "prereq_quest_ids": prereq_quest_ids,
                "quest_exclusion_ids": quest_exclusion_ids,
                "prerequisite_id": to_int(row["prerequisiteId"]),
                "objective_ids": objective_id_text,
                "objective_types": objective_type_text,
                "objective_data_type_data_count": objective_data_text,
                "quest2_reward_ids": quest2_reward_ids,
                "quest2_reward_types": quest2_reward_types,
                "pushed_items": pushed_item_text,
                "virtual_pushed_items": virtual_pushed_item_text,
                "quest_virtual_loot_groups": quest_virtual_loot_group_count,
                "related_achievement_ids": related_achievement_ids,
                "script_paths": script_path_text,
                "evidence_sources": evidence_sources,
                "manual_validation": "pending_or_not_applicable",
                "blocker_summary": blocker_summary,
            }
        )
    return output


def build_quest_objective_rows(
    strings: dict[int, str],
    quest_rows: list[dict[str, str]],
    objective_rows: list[dict[str, str]],
    quest_output: list[dict[str, object]],
) -> list[dict[str, object]]:
    objective_by_id = {to_int(row["ID"]): row for row in objective_rows}
    quest_status_by_id = {to_int(str(row["quest_id"])): row for row in quest_output}

    output: list[dict[str, object]] = []
    for quest in sorted(quest_rows, key=lambda item: to_int(item["ID"])):
        quest_id = to_int(quest["ID"])
        quest_status = quest_status_by_id.get(quest_id, {})
        for slot, column in enumerate(QUEST_OBJECTIVE_COLUMNS):
            objective_id = to_int(quest[column])
            if not objective_id:
                continue

            objective = objective_by_id.get(objective_id)
            objective_type = to_int(objective.get("type") if objective else None)
            has_objective_row = objective is not None
            indicator_ids = [
                to_int(objective[f"worldLocationsIdIndicator{suffix}"])
                for suffix in VIRTUAL_PUSHED_ITEM_SUFFIXES
                if objective and to_int(objective[f"worldLocationsIdIndicator{suffix}"])
            ]
            full_text_id = to_int(objective.get("localizedTextIdFull") if objective else None)
            short_text_id = to_int(objective.get("localizedTextIdShort") if objective else None)
            evidence_status = objective_evidence_status(quest_id, objective_type, has_objective_row, objective)
            override = QUEST_OBJECTIVE_EVIDENCE_OVERRIDES.get((quest_id, objective_id), {})
            evidence_status = override.get("evidence_status", evidence_status)

            output.append(
                {
                    "quest_id": quest_id,
                    "quest_name": text_by_id(strings, to_int(quest["localizedTextIdTitle"])),
                    "quest_bucket": quest_status.get("bucket", "review_required"),
                    "quest_completion_status": quest_status.get("completion_status", "not_retail_complete"),
                    "objective_slot": slot,
                    "objective_column": column,
                    "objective_id": objective_id,
                    "objective_type": objective_type,
                    "objective_flags": to_int(objective.get("flags") if objective else None),
                    "objective_data": to_int(objective.get("data") if objective else None),
                    "objective_count": to_int(objective.get("count") if objective else None),
                    "localized_text_full": text_by_id(strings, full_text_id),
                    "localized_text_short": text_by_id(strings, short_text_id),
                    "world_location_indicator_ids": join_ids(indicator_ids),
                    "max_time_allowed_ms": to_int(objective.get("maxTimeAllowedMS") if objective else None),
                    "target_group_id_reward_pane": to_int(objective.get("targetGroupIdRewardPane") if objective else None),
                    "quest_direction_id": to_int(objective.get("questDirectionId") if objective else None),
                    "support_status": objective_support_status(objective_type) if has_objective_row else "missing_client_objective_row",
                    "evidence_status": evidence_status,
                    "completion_status": "not_retail_complete",
                    "evidence_sources": override.get("evidence_sources", objective_evidence_sources(evidence_status)),
                    "manual_validation": "pending_or_not_applicable",
                    "blocker_summary": override.get("blocker_summary", objective_blocker_summary(evidence_status)),
                }
            )
    return output


def build_quest_reward_rows(
    strings: dict[int, str],
    quest_rows: list[dict[str, str]],
    reward_rows: list[dict[str, str]],
    quest_output: list[dict[str, object]],
) -> list[dict[str, object]]:
    quest_by_id = {to_int(row["ID"]): row for row in quest_rows}
    quest_status_by_id = {to_int(str(row["quest_id"])): row for row in quest_output}

    def base_row(quest_id: int) -> dict[str, object]:
        quest = quest_by_id.get(quest_id, {})
        quest_status = quest_status_by_id.get(quest_id, {})
        return {
            "quest_id": quest_id,
            "quest_name": text_by_id(strings, to_int(quest.get("localizedTextIdTitle"))),
            "quest_bucket": quest_status.get("bucket", "review_required"),
            "quest_completion_status": quest_status.get("completion_status", "not_retail_complete"),
        }

    output: list[dict[str, object]] = []
    for reward in sorted(reward_rows, key=lambda item: (to_int(item["quest2Id"]), to_int(item["ID"]))):
        quest_id = to_int(reward["quest2Id"])
        reward_type = to_int(reward["quest2RewardTypeId"])
        support_status = reward_support_status("Quest2Reward", reward_type)
        override = QUEST_REWARD_OVERRIDES.get((quest_id, "Quest2Reward", to_int(reward["ID"])), {})
        output.append(
            {
                **base_row(quest_id),
                "reward_source": "Quest2Reward",
                "reward_slot": "",
                "reward_id": to_int(reward["ID"]),
                "reward_type": reward_type,
                "object_id": to_int(reward["objectId"]),
                "object_amount": to_int(reward["objectAmount"]),
                "flags": to_int(reward["flags"]),
                "support_status": support_status,
                "evidence_status": override.get("evidence_status", support_status),
                "completion_status": "not_retail_complete",
                "evidence_sources": override.get("evidence_sources", quest_reward_evidence_sources(support_status)),
                "manual_validation": "pending_or_not_applicable",
                "blocker_summary": override.get("blocker_summary", quest_reward_blocker_summary(support_status)),
            }
        )

    for quest in sorted(quest_rows, key=lambda item: to_int(item["ID"])):
        quest_id = to_int(quest["ID"])
        for slot, suffix in enumerate(PUSHED_ITEM_SUFFIXES):
            item_id = to_int(quest[f"pushed_itemId{suffix}"])
            if not item_id:
                continue
            support_status = reward_support_status("Quest2.pushed_item", "pushed_item")
            output.append(
                {
                    **base_row(quest_id),
                    "reward_source": "Quest2.pushed_item",
                    "reward_slot": slot,
                    "reward_id": f"{quest_id}:pushed_item:{slot}",
                    "reward_type": "pushed_item",
                    "object_id": item_id,
                    "object_amount": to_int(quest[f"pushed_itemCount{suffix}"]),
                    "flags": "",
                    "support_status": support_status,
                    "evidence_status": support_status,
                    "completion_status": "not_retail_complete",
                    "evidence_sources": "wildstar_client_mysql/Quest2.tbl.sql;Source/NexusForever.Game/Entity/QuestManager.cs",
                    "manual_validation": "pending_or_not_applicable",
                    "blocker_summary": "Pushed quest items are client-state dependencies; accept/abandon cleanup, objective use, and replay behavior need row-specific smoke before retail completion.",
                }
            )

        for slot, suffix in enumerate(VIRTUAL_PUSHED_ITEM_SUFFIXES):
            item_id = to_int(quest[f"virtualItemIdPushed{suffix}"])
            if not item_id:
                continue
            support_status = reward_support_status("Quest2.virtual_pushed_item", "virtual_pushed_item")
            output.append(
                {
                    **base_row(quest_id),
                    "reward_source": "Quest2.virtual_pushed_item",
                    "reward_slot": slot,
                    "reward_id": f"{quest_id}:virtual_pushed_item:{slot}",
                    "reward_type": "virtual_pushed_item",
                    "object_id": item_id,
                    "object_amount": to_int(quest[f"virtualItemPushedCount{suffix}"]),
                    "flags": to_int(quest[f"virtualItemPushedObjectiveFlagsEnum{suffix}"]),
                    "support_status": support_status,
                    "evidence_status": support_status,
                    "completion_status": "not_retail_complete",
                    "evidence_sources": "wildstar_client_mysql/Quest2.tbl.sql;Source/NexusForever.Game/Entity/QuestManager.cs",
                    "manual_validation": "pending_or_not_applicable",
                    "blocker_summary": "Virtual pushed items are objective-state dependencies; client visibility, cleanup, and objective flag semantics need row-specific validation.",
                }
            )

        inline_rewards = (
            ("Quest2.reward_xp_override", "xp_override", "", quest["reward_xpOverride"], ""),
            ("Quest2.reward_cash_override", "cash_override", "", quest["reward_cashOverride"], ""),
            ("Quest2.reward_reputation_override", "reputation_override", quest["faction2IdRewardReputation00"], quest["rewardReputationOverride00"], "0"),
            ("Quest2.reward_reputation_override", "reputation_override", quest["faction2IdRewardReputation01"], quest["rewardReputationOverride01"], "1"),
        )
        for source, reward_type, object_id, amount, slot in inline_rewards:
            if not to_int(str(amount)) and not to_int(str(object_id)):
                continue
            support_status = reward_support_status(source, reward_type)
            override = QUEST_INLINE_REWARD_OVERRIDES.get((quest_id, source, str(slot)), {})
            output.append(
                {
                    **base_row(quest_id),
                    "reward_source": source,
                    "reward_slot": slot,
                    "reward_id": f"{quest_id}:{source}:{slot}",
                    "reward_type": reward_type,
                    "object_id": to_int(str(object_id)),
                    "object_amount": override.get("object_amount", amount),
                    "flags": "",
                    "support_status": override.get("support_status", support_status),
                    "evidence_status": override.get("evidence_status", support_status),
                    "completion_status": "not_retail_complete",
                    "evidence_sources": override.get("evidence_sources", "wildstar_client_mysql/Quest2.tbl.sql;Source/NexusForever.Game/Entity/QuestManager.cs;Source/NexusForever.Game/Quest/QuestInfo.cs"),
                    "manual_validation": "pending_or_not_applicable",
                    "blocker_summary": override.get("blocker_summary", "Inline quest reward values are mapped but require quest-specific completion smoke and client-visible grant verification."),
                }
            )

    return output


def build_quest_prerequisite_rows(
    strings: dict[int, str],
    quest_rows: list[dict[str, str]],
    prerequisite_rows: list[dict[str, str]],
    quest_output: list[dict[str, object]],
) -> list[dict[str, object]]:
    quest_by_id = {to_int(row["ID"]): row for row in quest_rows}
    prerequisite_by_id = {to_int(row["ID"]): row for row in prerequisite_rows}
    quest_status_by_id = {to_int(str(row["quest_id"])): row for row in quest_output}

    def quest_name(quest_id: int) -> str:
        quest = quest_by_id.get(quest_id, {})
        return text_by_id(strings, to_int(quest.get("localizedTextIdTitle")))

    def base_row(quest_id: int) -> dict[str, object]:
        quest_status = quest_status_by_id.get(quest_id, {})
        return {
            "quest_id": quest_id,
            "quest_name": quest_name(quest_id),
            "quest_bucket": quest_status.get("bucket", "review_required"),
            "quest_completion_status": quest_status.get("completion_status", "not_retail_complete"),
        }

    def prerequisite_blocker_summary(
        quest_id: int,
        dependency_type: str,
        dependency_slot: str | int,
        dependency_id: int | str,
        dependency_name: str,
        dependency_value: int | str,
        dependency_flags: int | str,
        object_id: int | str,
        comparison_id: int | str,
        prerequisite_type_id: int | str,
        localized_failure_text: str,
        evidence_status: str,
        fallback_summary: str,
    ) -> str:
        quest_clause = f"Quest2 {quest_id}"
        failure_clause = f" with failure text '{localized_failure_text}'" if localized_failure_text else ""
        if evidence_status == "blocked_missing_client_prerequisite_row_runtime_fail_closed":
            return (
                f"{quest_clause} references Prerequisite {dependency_id}, but that row is absent from the current Prerequisite client table."
                " Runtime validation now fails closed with a warning, and retail completion remains blocked until the missing"
                " Prerequisite row or reviewed replacement evidence is recovered."
            )
        if dependency_type == "level":
            return (
                f"{quest_clause} requires character level {dependency_value}. Retail completion needs quest visibility,"
                " accept-denial text, progression-chain behavior, and client smoke for this exact level gate."
            )
        if dependency_type == "preq_flags":
            return (
                f"{quest_clause} carries Quest2 preq_flags {dependency_flags}. Retail completion needs the flag semantics,"
                " visibility behavior, accept denial, and client smoke verified for this row."
            )
        if dependency_type in {"race", "class", "item"}:
            return (
                f"{quest_clause} has {dependency_type} prerequisite objectId {object_id}. Retail completion needs row-specific"
                " visibility, accept denial, inventory/character-state validation where applicable, and chain smoke."
            )
        if dependency_type == "quest_faction":
            return (
                f"{quest_clause} requires questPlayerFactionEnum {dependency_id} ({dependency_name}). Retail completion needs"
                " faction-specific visibility, accept denial, dialog availability, and client quest smoke."
            )
        if dependency_type == "required_quest":
            name_clause = f" ({dependency_name})" if dependency_name else ""
            return (
                f"{quest_clause} requires prerequisite quest slot {dependency_slot} -> Quest2 {dependency_id}{name_clause}."
                " Retail completion needs source and target quest visibility/progression, completion-state gating,"
                " denial behavior, and chain smoke together."
            )
        if dependency_type == "excluded_quest":
            name_clause = f" ({dependency_name})" if dependency_name else ""
            return (
                f"{quest_clause} excludes quest slot {dependency_slot} -> Quest2 {dependency_id}{name_clause}."
                " Retail completion needs row-specific visibility, exclusion-state gating, denial behavior, and chain smoke."
            )
        if dependency_type == "faction_level":
            return (
                f"{quest_clause} requires faction slot {dependency_slot} objectId {object_id} with {dependency_value}."
                " Retail completion needs reputation boundary semantics, comparison behavior, accept denial, and client smoke."
            )
        if dependency_type == "prerequisite_id":
            return (
                f"{quest_clause} references Prerequisite {dependency_id} with flags {dependency_flags}{failure_clause}."
                " Runtime maps the row through PrerequisiteManager, but retail completion needs row-specific visibility,"
                " accept denial, comparison semantics, and client smoke."
            )
        if dependency_type == "prerequisite_slot":
            return (
                f"{quest_clause} Prerequisite {dependency_id} slot {dependency_slot} uses prerequisiteTypeId {prerequisite_type_id},"
                f" objectId {object_id}, value {dependency_value}, comparison {comparison_id}, and flags {dependency_flags}{failure_clause}."
                " Retail completion needs exact handler behavior, comparison semantics, failure text, and client accept/visibility smoke."
            )
        return fallback_summary

    def add_row(
        output: list[dict[str, object]],
        quest_id: int,
        dependency_type: str,
        dependency_slot: str | int,
        dependency_id: int | str,
        dependency_name: str,
        dependency_value: int | str,
        dependency_flags: int | str,
        object_id: int | str,
        comparison_id: int | str,
        prerequisite_type_id: int | str,
        localized_failure_text: str,
        support_status: str,
        evidence_status: str,
        blocker_summary: str,
        evidence_sources: str | None = None,
    ) -> None:
        row = {
            **base_row(quest_id),
            "dependency_type": dependency_type,
            "dependency_slot": dependency_slot,
            "dependency_id": dependency_id,
            "dependency_name": dependency_name,
            "dependency_value": dependency_value,
            "dependency_flags": dependency_flags,
            "object_id": object_id,
            "comparison_id": comparison_id,
            "prerequisite_type_id": prerequisite_type_id,
            "localized_failure_text": localized_failure_text,
            "support_status": support_status,
            "evidence_status": evidence_status,
            "completion_status": "not_retail_complete",
            "evidence_sources": evidence_sources or "wildstar_client_mysql/Quest2.tbl.sql;wildstar_client_mysql/Prerequisite.tbl.sql;Source/NexusForever.Game/Entity/QuestManager.cs;Source/NexusForever.Game/Prerequisite/PrerequisiteManager.cs",
            "manual_validation": "pending_or_not_applicable",
            "blocker_summary": prerequisite_blocker_summary(
                quest_id,
                dependency_type,
                dependency_slot,
                dependency_id,
                dependency_name,
                dependency_value,
                dependency_flags,
                object_id,
                comparison_id,
                prerequisite_type_id,
                localized_failure_text,
                evidence_status,
                blocker_summary,
            ),
        }
        row.update(QUEST_PREREQUISITE_OVERRIDES.get((quest_id, dependency_type, str(dependency_slot), to_int(str(dependency_id))), {}))
        output.append(row)

    output: list[dict[str, object]] = []
    for quest in sorted(quest_rows, key=lambda item: to_int(item["ID"])):
        quest_id = to_int(quest["ID"])
        if to_int(quest.get("preq_level")):
            add_row(
                output,
                quest_id,
                "level",
                "",
                "",
                "",
                to_int(quest.get("preq_level")),
                "",
                "",
                "",
                "",
                "",
                "mapped_quest_accept_validation_pending_row_smoke",
                "client_quest2_level_gate_pending_accept_smoke",
                "Level prerequisite is table-backed but not retail-complete until quest visibility, accept denial text, and progression chain behavior are smoked.",
            )
        if to_int(quest.get("preq_flags")):
            add_row(
                output,
                quest_id,
                "preq_flags",
                "",
                "",
                "",
                "",
                to_int(quest.get("preq_flags")),
                "",
                "",
                "",
                "",
                "mapped_client_flag_dependency_pending_semantic_smoke",
                "client_quest2_preq_flags_pending_semantic_smoke",
                "Quest2 prerequisite flags remain row-specific until visibility and accept semantics are proven against client behavior.",
            )
        for dependency_type, column in (("race", "preq_race"), ("class", "preq_class"), ("item", "preq_item")):
            if has_client_id(quest.get(column)):
                add_row(
                    output,
                    quest_id,
                    dependency_type,
                    "",
                    to_int(quest.get(column)),
                    "",
                    "",
                    "",
                    to_int(quest.get(column)),
                    "",
                    "",
                    "",
                    "mapped_quest_accept_validation_pending_row_smoke",
                    f"client_quest2_{column}_pending_accept_smoke",
                    "Quest2 prerequisite dependency is mapped through accept validation but still needs row-specific visibility, denial, and chain smoke.",
                )
        quest_faction = to_int(quest.get("questPlayerFactionEnum"))
        if quest_faction in {0, 1}:
            add_row(
                output,
                quest_id,
                "quest_faction",
                "",
                quest_faction,
                "Exile" if quest_faction == 0 else "Dominion",
                "",
                "",
                quest_faction,
                "",
                "",
                "",
                "mapped_quest_accept_validation_pending_row_smoke",
                "client_quest2_questPlayerFactionEnum_pending_accept_smoke",
                "Quest2 faction prerequisite dependency is mapped through accept validation but still needs row-specific visibility, denial, and chain smoke.",
            )

        for slot, column in enumerate(("preq_quest0", "preq_quest01", "preq_quest02")):
            dependency_id = to_int(quest.get(column))
            if not dependency_id:
                continue
            add_row(
                output,
                quest_id,
                "required_quest",
                slot,
                dependency_id,
                quest_name(dependency_id),
                "",
                "",
                dependency_id,
                "",
                "",
                "",
                "mapped_quest_chain_validation_pending_chain_smoke",
                "client_quest2_required_quest_pending_chain_smoke",
                "Quest-chain prerequisite is mapped but not retail-complete until source and target quest visibility/progression are smoked together.",
            )

        for slot, column in enumerate(("questIdExclusionPreq0", "questIdExclusionPreq1", "questIdExclusionPreq2")):
            dependency_id = to_int(quest.get(column))
            if not dependency_id:
                continue
            add_row(
                output,
                quest_id,
                "excluded_quest",
                slot,
                dependency_id,
                quest_name(dependency_id),
                "",
                "",
                dependency_id,
                "",
                "",
                "",
                "mapped_quest_exclusion_validation_pending_chain_smoke",
                "client_quest2_excluded_quest_pending_chain_smoke",
                "Quest exclusion prerequisite is mapped but needs row-specific visibility and chain smoke before retail completion.",
            )

        for slot, suffix in enumerate(("0", "01", "02")):
            faction_id = to_int(quest.get(f"factionIdPreq{suffix}"))
            level_preq = to_int(quest.get(f"factionLevelPreq{suffix}"))
            level_comp_preq = to_int(quest.get(f"factionLevelCompPreq{suffix}"))
            if not faction_id and not level_preq and not level_comp_preq:
                continue
            add_row(
                output,
                quest_id,
                "faction_level",
                slot,
                faction_id,
                "",
                f"levelPreq={level_preq};levelCompPreq={level_comp_preq}",
                "",
                faction_id,
                "",
                "",
                "",
                "mapped_quest_accept_validation_pending_reputation_smoke",
                "client_quest2_faction_level_pending_accept_smoke",
                "Faction-level prerequisite is mapped but needs row-specific reputation boundary and accept-denial smoke.",
            )

        prerequisite_id = to_int(quest.get("prerequisiteId"))
        if has_client_id(quest.get("prerequisiteId")):
            prerequisite = prerequisite_by_id.get(prerequisite_id)
            if not prerequisite:
                add_row(
                    output,
                    quest_id,
                    "prerequisite_id",
                    "",
                    prerequisite_id,
                    "",
                    "",
                    "",
                    prerequisite_id,
                    "",
                    "",
                    "",
                    "blocked_missing_client_prerequisite_row_runtime_fail_closed",
                    "blocked_missing_client_prerequisite_row_runtime_fail_closed",
                    "Quest2 references a prerequisite id that was not found in the local Prerequisite client table; runtime prerequisite validation now fails closed with a warning, but row-specific retail completion remains blocked until the missing client prerequisite row or replacement evidence is recovered.",
                    evidence_sources="wildstar_client_mysql/Quest2.tbl.sql;wildstar_client_mysql/Prerequisite.tbl.sql;Source/NexusForever.Game/Entity/QuestManager.cs;Source/NexusForever.Game/Prerequisite/PrerequisiteManager.cs;Source/NexusForever.Game.Tests/Entity/PrerequisiteManagerTests.cs",
                )
                continue

            add_row(
                output,
                quest_id,
                "prerequisite_id",
                "",
                prerequisite_id,
                "",
                "",
                to_int(prerequisite.get("flags")),
                prerequisite_id,
                "",
                "",
                text_by_id(strings, to_int(prerequisite.get("localizedTextIdFailure"))),
                "mapped_prerequisite_manager_pending_row_smoke",
                "client_prerequisite_row_pending_accept_smoke",
                "Client prerequisite row is mapped through PrerequisiteManager but needs row-specific accept/visibility smoke before retail completion.",
            )

            for slot in PREREQUISITE_SLOT_SUFFIXES:
                prerequisite_type_id = to_int(prerequisite.get(f"prerequisiteTypeId{slot}"))
                if not prerequisite_type_id:
                    continue
                add_row(
                    output,
                    quest_id,
                    "prerequisite_slot",
                    slot,
                    prerequisite_id,
                    "",
                    to_int(prerequisite.get(f"value{slot}")),
                    to_int(prerequisite.get("flags")),
                    to_int(prerequisite.get(f"objectId{slot}")),
                    to_int(prerequisite.get(f"prerequisiteComparisonId{slot}")),
                    prerequisite_type_id,
                    text_by_id(strings, to_int(prerequisite.get("localizedTextIdFailure"))),
                    "mapped_prerequisite_manager_pending_row_smoke",
                    "client_prerequisite_slot_pending_handler_smoke",
                    "Prerequisite slot has a runtime manager path but remains row-specific until exact handler, comparison, and failure behavior are verified.",
                )

    return output


def build_objective_claim_index(quest_rows: list[dict[str, str]]) -> dict[int, list[dict[str, object]]]:
    claims: dict[int, list[dict[str, object]]] = defaultdict(list)
    for quest in quest_rows:
        quest_id = to_int(quest["ID"])
        for slot, column in enumerate(QUEST_OBJECTIVE_COLUMNS):
            objective_id = to_int(quest[column])
            if objective_id:
                claims[objective_id].append({"quest_id": quest_id, "objective_slot": slot, "objective_column": column})
    return claims


def build_quest_loot_rows(
    strings: dict[int, str],
    quest_rows: list[dict[str, str]],
    objective_rows: list[dict[str, str]],
    quest_output: list[dict[str, object]],
    quest_loot_sql: Path = QUEST_LOOT_SQL,
) -> list[dict[str, object]]:
    loot_groups = load_insert_rows(
        quest_loot_sql,
        "loot_group",
        ("id", "parentId", "probability", "minDrop", "maxDrop", "conditionType", "condition", "comment"),
    )
    loot_items = load_insert_rows(
        quest_loot_sql,
        "loot_item",
        ("id", "type", "staticId", "probability", "minCount", "maxCount", "comment"),
    )
    entity_loot_rows = load_insert_rows(quest_loot_sql, "entity_loot", ("id", "lootGroupId", "comment"))

    objective_by_id = {to_int(row["ID"]): row for row in objective_rows}
    quest_by_id = {to_int(row["ID"]): row for row in quest_rows}
    quest_status_by_id = {to_int(str(row["quest_id"])): row for row in quest_output}
    objective_claims = build_objective_claim_index(quest_rows)

    items_by_group: dict[int, list[dict[str, str]]] = defaultdict(list)
    for row in loot_items:
        items_by_group[to_int(row["id"])].append(row)

    entities_by_group: dict[int, list[dict[str, str]]] = defaultdict(list)
    for row in entity_loot_rows:
        entities_by_group[to_int(row["lootGroupId"])].append(row)

    def base_row(quest_id: int, objective_id: int, claim: dict[str, object]) -> dict[str, object]:
        quest = quest_by_id.get(quest_id, {})
        objective = objective_by_id.get(objective_id, {})
        quest_status = quest_status_by_id.get(quest_id, {})
        return {
            "quest_id": quest_id,
            "quest_name": text_by_id(strings, to_int(quest.get("localizedTextIdTitle"))),
            "quest_bucket": quest_status.get("bucket", "review_required" if quest_id else "orphaned_reference"),
            "quest_completion_status": quest_status.get("completion_status", "not_retail_complete"),
            "objective_id": objective_id,
            "objective_slot": claim.get("objective_slot", ""),
            "objective_type": to_int(objective.get("type")),
            "objective_name": text_by_id(strings, to_int(objective.get("localizedTextIdFull"))) or text_by_id(strings, to_int(objective.get("localizedTextIdShort"))),
        }

    def append_loot_row(
        output: list[dict[str, object]],
        quest_id: int,
        objective_id: int,
        claim: dict[str, object],
        dependency_type: str,
        loot_group_id: int,
        entity_id: int | str,
        item_type: int | str,
        static_id: int | str,
        probability: int | str,
        min_count: int | str,
        max_count: int | str,
        condition_type: int | str,
        condition_id: int | str,
        comment: str,
        evidence_status: str,
        blocker_summary: str,
        evidence_sources: str = QUEST_LOOT_BASE_EVIDENCE_SOURCES,
    ) -> None:
        output.append(
            {
                **base_row(quest_id, objective_id, claim),
                "dependency_type": dependency_type,
                "loot_group_id": loot_group_id,
                "entity_id": entity_id,
                "item_type": item_type,
                "static_id": static_id,
                "probability": probability,
                "min_count": min_count,
                "max_count": max_count,
                "condition_type": condition_type,
                "condition_id": condition_id,
                "comment": comment,
                "evidence_status": evidence_status,
                "completion_status": "not_retail_complete",
                "evidence_sources": evidence_sources,
                "manual_validation": "pending",
                "blocker_summary": blocker_summary,
            }
        )

    def objective_data_id(objective_id: int) -> int:
        return to_int(objective_by_id.get(objective_id, {}).get("data"))

    def has_matching_virtual_collect_item(loot_group_id: int, objective_id: int) -> bool:
        objective = objective_by_id.get(objective_id, {})
        objective_data = objective_data_id(objective_id)
        if to_int(objective.get("type")) != QUEST_OBJECTIVE_VIRTUAL_COLLECT_TYPE or not objective_data:
            return False
        return any(
            to_int(item.get("type")) == LOOT_ITEM_TYPE_VIRTUAL_ITEM and to_int(item.get("staticId")) == objective_data
            for item in items_by_group.get(loot_group_id, [])
        )

    def is_matching_virtual_collect_item(objective_id: int, item_type: int | str, static_id: int | str) -> bool:
        objective = objective_by_id.get(objective_id, {})
        objective_data = objective_data_id(objective_id)
        return (
            to_int(objective.get("type")) == QUEST_OBJECTIVE_VIRTUAL_COLLECT_TYPE
            and objective_data
            and to_int(item_type) == LOOT_ITEM_TYPE_VIRTUAL_ITEM
            and to_int(static_id) == objective_data
        )

    def loot_status(dependency_type: str, orphaned: bool, virtual_collect_loot: bool = False) -> str:
        if not orphaned:
            if virtual_collect_loot:
                return {
                    "loot_group": RUNTIME_VIRTUAL_COLLECT_LOOT_GROUP_STATUS,
                    "loot_item": RUNTIME_VIRTUAL_COLLECT_LOOT_ITEM_STATUS,
                    "entity_loot": RUNTIME_VIRTUAL_COLLECT_ENTITY_LOOT_STATUS,
                }[dependency_type]
            return {
                "loot_group": "reviewed_laughingws_loot_group_pending_drop_smoke",
                "loot_item": "reviewed_laughingws_loot_item_pending_drop_smoke",
                "entity_loot": "reviewed_laughingws_entity_loot_binding_pending_spawn_and_drop_smoke",
            }[dependency_type]
        return {
            "loot_group": REJECTED_ORPHANED_LOOT_GROUP_STATUS,
            "loot_item": REJECTED_ORPHANED_LOOT_ITEM_STATUS,
            "entity_loot": REJECTED_ORPHANED_ENTITY_LOOT_STATUS,
        }[dependency_type]

    def loot_blocker_summary(
        dependency_type: str,
        objective_id: int,
        orphaned: bool,
        loot_group_id: int,
        entity_id: int | str = "",
        item_type: int | str = "",
        static_id: int | str = "",
        probability: int | str = "",
        min_count: int | str = "",
        max_count: int | str = "",
        condition_type: int | str = "",
        condition_id: int | str = "",
        comment: str = "",
        virtual_collect_loot: bool = False,
        objective_data: int | str = "",
    ) -> str:
        condition_clause = f" conditionType {condition_type} condition {condition_id}" if condition_type != "" or condition_id != "" else ""
        probability_clause = f" probability {probability}" if probability != "" else ""
        count_clause = ""
        if min_count != "" or max_count != "":
            count_clause = f" count {min_count}-{max_count}"
        comment_clause = f" ({comment})" if comment else ""
        if orphaned:
            return (
                f"Reviewed LaughingWS {dependency_type.replace('_', ' ')} evidence is rejected for runtime promotion because conditionType 8 references"
                f" QuestObjective {objective_id}, but that objective is absent from current-client Quest2 ownership. Revive only with current build"
                " Quest2/QuestObjective evidence that owns this objective id, or with a reviewed replacement objective mapping plus source entity/drop smoke."
            )
        if virtual_collect_loot and dependency_type == "loot_group":
            return (
                f"Reviewed LaughingWS loot_group {loot_group_id}{comment_clause} is bound to VirtualCollect QuestObjective {objective_id}"
                f" for virtual item {objective_data}{condition_clause}{probability_clause}{count_clause}. Generic runtime virtual-item loot"
                " delivery updates QuestObjectiveType.VirtualCollect and is covered by LootInstanceDeliveryTests.cs; retail completion still needs"
                " proof that this source/drop trigger is produced by the source entity, plus drop cadence, inventory cleanup, and client-visible loot UI smoke."
            )
        if virtual_collect_loot and dependency_type == "loot_item":
            return (
                f"Reviewed quest-loot item for loot_group {loot_group_id} item type {item_type} staticId {static_id}{comment_clause}"
                f"{probability_clause}{count_clause} matches VirtualCollect QuestObjective {objective_id} data {objective_data}. Runtime virtual-item"
                " loot delivery updates QuestObjectiveType.VirtualCollect in LootInstanceItem.cs and is test-pinned by LootInstanceDeliveryTests.cs."
                " Retail completion still needs objective-specific source/drop trigger proof, drop chance/count behavior, inventory cleanup/persistence,"
                " and client-visible loot validation."
            )
        if virtual_collect_loot:
            return (
                f"Reviewed entity_loot binding entity {entity_id} -> loot_group {loot_group_id}{comment_clause} is gated by VirtualCollect"
                f" QuestObjective {objective_id}{condition_clause} for virtual item {objective_data}. The matching VirtualItem delivery path is"
                " runtime-tested, but retail completion still needs source entity spawn, drop generation trigger, encounter/objective timing,"
                " duplicate/negative cases, and client loot smoke together."
            )
        if dependency_type == "loot_group":
            return (
                f"Reviewed LaughingWS loot_group {loot_group_id}{comment_clause} is bound to QuestObjective {objective_id}"
                f"{condition_clause}{probability_clause}{count_clause}. Retail completion needs the matching quest objective trigger,"
                " source entity spawn/encounter timing, drop cadence, inventory behavior, and client loot smoke."
            )
        if dependency_type == "loot_item":
            return (
                f"Reviewed quest-loot item for loot_group {loot_group_id} item type {item_type} staticId {static_id}{comment_clause}"
                f"{probability_clause}{count_clause} is gated by QuestObjective {objective_id}. Retail completion needs objective-specific"
                " drop chance/count behavior, inventory cleanup/persistence, and client-visible loot validation."
            )
        return (
            f"Reviewed entity_loot binding entity {entity_id} -> loot_group {loot_group_id}{comment_clause} is gated by QuestObjective {objective_id}"
            f"{condition_clause}. Retail completion needs the source entity spawn, encounter/objective timing, drop behavior,"
            " and client loot smoke together."
        )

    output: list[dict[str, object]] = []
    for group in sorted(loot_groups, key=lambda item: to_int(item["id"])):
        loot_group_id = to_int(group["id"])
        objective_id = to_int(group["condition"]) if to_int(group["conditionType"]) == 8 else 0
        claims = objective_claims.get(objective_id, [{"quest_id": 0, "objective_slot": "", "objective_column": ""}])
        orphaned = objective_id and objective_id not in objective_claims
        virtual_collect_loot = not orphaned and has_matching_virtual_collect_item(loot_group_id, objective_id)
        virtual_collect_sources = QUEST_VIRTUAL_ITEM_LOOT_EVIDENCE_SOURCES if virtual_collect_loot else QUEST_LOOT_BASE_EVIDENCE_SOURCES
        objective_data = objective_data_id(objective_id)
        for claim in claims:
            quest_id = to_int(str(claim["quest_id"]))
            append_loot_row(
                output,
                quest_id,
                objective_id,
                claim,
                "loot_group",
                loot_group_id,
                "",
                "",
                "",
                to_int(group["probability"]),
                to_int(group["minDrop"]),
                to_int(group["maxDrop"]),
                to_int(group["conditionType"]),
                objective_id,
                decode_sql_comment(group["comment"]),
                loot_status("loot_group", orphaned, virtual_collect_loot),
                loot_blocker_summary(
                    "loot_group",
                    objective_id,
                    orphaned,
                    loot_group_id,
                    probability=to_int(group["probability"]),
                    min_count=to_int(group["minDrop"]),
                    max_count=to_int(group["maxDrop"]),
                    condition_type=to_int(group["conditionType"]),
                    condition_id=objective_id,
                    comment=decode_sql_comment(group["comment"]),
                    virtual_collect_loot=virtual_collect_loot,
                    objective_data=objective_data,
                ),
                evidence_sources=virtual_collect_sources,
            )

            for item in sorted(items_by_group.get(loot_group_id, []), key=lambda row: (to_int(row["type"]), to_int(row["staticId"]))):
                virtual_collect_item = is_matching_virtual_collect_item(objective_id, to_int(item["type"]), to_int(item["staticId"]))
                append_loot_row(
                    output,
                    quest_id,
                    objective_id,
                    claim,
                    "loot_item",
                    loot_group_id,
                    "",
                    to_int(item["type"]),
                    to_int(item["staticId"]),
                    to_int(item["probability"]),
                    to_int(item["minCount"]),
                    to_int(item["maxCount"]),
                    to_int(group["conditionType"]),
                    objective_id,
                    decode_sql_comment(item["comment"]),
                    loot_status("loot_item", orphaned, virtual_collect_item),
                    loot_blocker_summary(
                        "loot_item",
                        objective_id,
                        orphaned,
                        loot_group_id,
                        item_type=to_int(item["type"]),
                        static_id=to_int(item["staticId"]),
                        probability=to_int(item["probability"]),
                        min_count=to_int(item["minCount"]),
                        max_count=to_int(item["maxCount"]),
                        comment=decode_sql_comment(item["comment"]),
                        virtual_collect_loot=virtual_collect_item,
                        objective_data=objective_data,
                    ),
                    evidence_sources=QUEST_VIRTUAL_ITEM_LOOT_EVIDENCE_SOURCES if virtual_collect_item else QUEST_LOOT_BASE_EVIDENCE_SOURCES,
                )

            for entity_loot in sorted(entities_by_group.get(loot_group_id, []), key=lambda row: to_int(row["id"])):
                append_loot_row(
                    output,
                    quest_id,
                    objective_id,
                    claim,
                    "entity_loot",
                    loot_group_id,
                    to_int(entity_loot["id"]),
                    "",
                    "",
                    "",
                    "",
                    "",
                    to_int(group["conditionType"]),
                    objective_id,
                    decode_sql_comment(entity_loot["comment"]),
                    loot_status("entity_loot", orphaned, virtual_collect_loot),
                    loot_blocker_summary(
                        "entity_loot",
                        objective_id,
                        orphaned,
                        loot_group_id,
                        entity_id=to_int(entity_loot["id"]),
                        condition_type=to_int(group["conditionType"]),
                        condition_id=objective_id,
                        comment=decode_sql_comment(entity_loot["comment"]),
                        virtual_collect_loot=virtual_collect_loot,
                        objective_data=objective_data,
                    ),
                    evidence_sources=virtual_collect_sources,
                )

    return output


def build_quest_world_dependency_rows(
    strings: dict[int, str],
    quests: list[dict[str, str]],
    objectives: list[dict[str, str]],
    quest_output: list[dict[str, object]],
    quest_directions: list[dict[str, str]],
    quest_direction_entries: list[dict[str, str]],
    target_groups: list[dict[str, str]],
    world_locations: list[dict[str, str]],
    world_zones: list[dict[str, str]],
    runtime_entity_rows: list[dict[str, str]] | None = None,
) -> list[dict[str, object]]:
    quest_status_by_id = {to_int(str(row["quest_id"])): row for row in quest_output}
    objective_by_id = {to_int(row["ID"]): row for row in objectives}
    direction_by_id = {to_int(row["ID"]): row for row in quest_directions}
    direction_entry_by_id = {to_int(row["ID"]): row for row in quest_direction_entries}
    target_group_by_id = {to_int(row["ID"]): row for row in target_groups}
    world_location_by_id = {to_int(row["ID"]): row for row in world_locations}
    world_zone_by_id = {to_int(row["ID"]): row for row in world_zones}
    direction_entry_columns = tuple(f"questDirectionEntryId{index:02d}" for index in range(16))
    target_group_data_columns = tuple(f"data{index}" for index in range(7))
    objective_indicator_columns = ("worldLocationsIdIndicator00", "worldLocationsIdIndicator01", "worldLocationsIdIndicator02", "worldLocationsIdIndicator03")
    runtime_entity_rows = (
        load_insert_rows(RUNTIME_WORLD_SEED_SQL, "entity", INSTANCE_ENTITY_COLUMNS)
        if runtime_entity_rows is None
        else runtime_entity_rows
    )
    runtime_entities_by_creature: dict[int, list[dict[str, str]]] = defaultdict(list)
    for row in runtime_entity_rows:
        creature_id = to_int(row.get("creature"))
        if creature_id:
            runtime_entities_by_creature[creature_id].append(row)

    def zone_name(world_zone_id: int) -> str:
        zone = world_zone_by_id.get(world_zone_id, {})
        return text_by_id(strings, to_int(zone.get("localizedTextIdName") if zone else None))

    def location_context(world_location_id: int) -> dict[str, object]:
        location = world_location_by_id.get(world_location_id)
        if not location:
            return {
                "world_location_id": world_location_id or "",
                "world_id": "",
                "world_zone_id": "",
                "world_zone_name": "",
                "position_x": "",
                "position_y": "",
                "position_z": "",
                "radius": "",
                "phases": "",
            }

        world_zone_id = to_int(location["worldZoneId"])
        return {
            "world_location_id": world_location_id,
            "world_id": to_int(location["worldId"]),
            "world_zone_id": world_zone_id,
            "world_zone_name": zone_name(world_zone_id),
            "position_x": location["position0"],
            "position_y": location["position1"],
            "position_z": location["position2"],
            "radius": location["radius"],
            "phases": location["phases"],
        }

    def world_dependency_blocker_summary(
        *,
        quest_id: int,
        dependency_type: str,
        dependency_source: str,
        dependency_id: object,
        dependency_name: str,
        objective_id: int,
        objective_type: object,
        source_slot: str,
        world_location_id: int,
        world_zone_id: int,
        world_zone_name: str,
        position_x: object,
        position_y: object,
        position_z: object,
        radius: object,
        quest_direction_id: int,
        quest_direction_entry_id: int,
        target_group_id: int,
        target_group_type: object,
        target_group_data: object,
        prerequisite_id: int,
        evidence_status: str,
        fallback_summary: str,
    ) -> str:
        custom_or_runtime = not evidence_status.startswith("client_") and not evidence_status.startswith("missing_") and not evidence_status.startswith("blocked_missing_")
        if custom_or_runtime:
            return fallback_summary
        generic_world_dependency_summaries = {
            "Quest direction row is tracked, but retail completion needs path-arrow routing, zone exclusion behavior, and client quest guidance smoke.",
            "Quest direction entry is tracked, but retail completion needs the referenced world location, route arrow visibility, faction gating, and client guidance smoke.",
            "QuestDirection references a missing client QuestDirectionEntry row; runtime objective guidance now fails closed by leaving the location unresolved instead of inventing a route target, but retail completion remains blocked until the missing client row or replacement route evidence is recovered.",
            "Inactive quest-direction location is tracked, but retail completion needs state transition proof and client guidance smoke.",
            "Target-group dependency is tracked, but retail completion needs target membership, spawn availability, objective credit, and client smoke.",
            "Nested target-group dependency is tracked, but retail completion needs child membership, spawn availability, objective credit, and client smoke.",
            "TargetGroup.data points at a missing client TargetGroup row; runtime target expansion now fails closed by skipping the missing child without inventing objective targets, but retail completion remains blocked until the missing client row or replacement member evidence is recovered.",
            "Target-group member is tracked, but retail completion needs spawn availability, kill/interact credit semantics, and objective completion smoke.",
            "Quest world-zone dependency is tracked, but retail completion needs map availability, quest activation, and zone-specific gameplay smoke.",
            "Quest receiver location is tracked, but retail completion needs NPC/object spawn, dialog availability, completion routing, and client quest smoke.",
            "Alternate quest receiver location is tracked, but retail completion needs prerequisite selection, NPC/object spawn, dialog routing, and client quest smoke.",
            "Objective indicator location is tracked, but retail completion needs trigger/entity placement, minimap/map guidance, and objective smoke.",
            "Quest references an objective row that is missing from the client table; retail completion is blocked pending source-table reconciliation.",
        }
        if fallback_summary not in generic_world_dependency_summaries:
            return fallback_summary

        quest_clause = f"Quest2 {quest_id}"
        objective_clause = f" objective {objective_id}" if objective_id else ""
        if objective_type != "":
            objective_clause += f" type {objective_type}"
        location_clause = ""
        if world_location_id:
            location_clause = f" WorldLocation2 {world_location_id}"
            if world_zone_id:
                location_clause += f" in WorldZone {world_zone_id}"
                if world_zone_name:
                    location_clause += f" ({world_zone_name})"
            if position_x != "" or position_y != "" or position_z != "":
                location_clause += f" at {position_x},{position_y},{position_z}"
            if radius != "":
                location_clause += f" radius {radius}"
        zone_clause = f" WorldZone {world_zone_id} ({world_zone_name})" if world_zone_id and world_zone_name else f" WorldZone {world_zone_id}" if world_zone_id else ""
        prerequisite_clause = f" with prerequisite {prerequisite_id}" if prerequisite_id else ""
        slot_clause = f" slot {source_slot}" if source_slot != "" else ""

        if dependency_type == "quest_world_zone":
            return (
                f"{quest_clause} is assigned to{zone_clause} from {dependency_source}. Retail completion needs map availability,"
                " quest activation/visibility, episode/zone ordering, and zone-specific gameplay smoke for this exact WorldZone."
            )
        if dependency_type == "quest_receiver_location":
            return (
                f"{quest_clause} receiver{location_clause} comes from {dependency_source}. Retail completion needs the receiver"
                " NPC/object spawn, dialog availability, completion routing, reward/achievement side effects, and client quest smoke."
            )
        if dependency_type == "quest_alt_receiver_location":
            return (
                f"{quest_clause} alternate receiver{slot_clause}{location_clause}{prerequisite_clause} comes from {dependency_source}."
                " Retail completion needs prerequisite selection, NPC/object spawn, dialog routing, reward side effects, and client quest smoke."
            )
        if dependency_type == "quest_direction":
            return (
                f"{quest_clause}{objective_clause} uses QuestDirection {quest_direction_id or dependency_id} from {dependency_source}{slot_clause}"
                f"{zone_clause}. Retail completion needs path-arrow routing, zone exclusion behavior, faction/prerequisite gating,"
                " and client quest guidance smoke."
            )
        if dependency_type == "quest_direction_entry":
            if evidence_status == "blocked_missing_client_quest_direction_entry_row_runtime_fail_closed":
                return (
                    f"{quest_clause}{objective_clause} QuestDirection {quest_direction_id} references missing QuestDirectionEntry"
                    f" {quest_direction_entry_id} from {dependency_source}.{source_slot}. Runtime objective guidance now fails closed"
                    " by leaving the location unresolved instead of inventing a route target, but retail completion remains"
                    " blocked until the missing client row or replacement route evidence is recovered."
                )
            return (
                f"{quest_clause}{objective_clause} QuestDirection {quest_direction_id} entry {quest_direction_entry_id}{location_clause}"
                f" from {dependency_source}.{source_slot}. Retail completion needs route arrow visibility, location reachability,"
                " faction/prerequisite gating, and client guidance smoke."
            )
        if dependency_type == "quest_direction_entry_inactive_location":
            return (
                f"{quest_clause}{objective_clause} inactive QuestDirection {quest_direction_id} entry {quest_direction_entry_id}{location_clause}"
                f" from {dependency_source}.{source_slot}. Retail completion needs inactive/active state transition proof and client guidance smoke."
            )
        if dependency_type == "target_group":
            name_clause = f" ({dependency_name})" if dependency_name else ""
            return (
                f"{quest_clause}{objective_clause} references TargetGroup {target_group_id or dependency_id}{name_clause}"
                f" type {target_group_type} from {dependency_source}. Retail completion needs target membership review,"
                " spawn availability, objective credit semantics, and client smoke."
            )
        if dependency_type == "nested_target_group":
            name_clause = f" ({dependency_name})" if dependency_name else ""
            if evidence_status == "blocked_missing_client_nested_target_group_row_runtime_fail_closed":
                return (
                    f"{quest_clause}{objective_clause} TargetGroup {target_group_id} data slot {source_slot} points at missing"
                    f" child TargetGroup {target_group_data}. Runtime target expansion now fails closed by skipping the missing"
                    " child without inventing objective targets, but retail completion remains blocked until the missing client"
                    " row or reviewed replacement member evidence is recovered."
                )
            return (
                f"{quest_clause}{objective_clause} TargetGroup {target_group_id}{name_clause} data slot {source_slot}"
                f" links nested TargetGroup {target_group_data}. Retail completion needs child membership review,"
                " spawn availability, objective credit semantics, and client smoke."
            )
        if dependency_type == "target_group_member":
            name_clause = f" ({dependency_name})" if dependency_name else ""
            return (
                f"{quest_clause}{objective_clause} TargetGroup {target_group_id}{name_clause} member slot {source_slot}"
                f" references Creature2/object {target_group_data}. Retail completion needs spawn availability,"
                " kill/interact credit semantics, objective completion behavior, and client smoke."
            )
        if dependency_type == "objective_indicator_location":
            return (
                f"{quest_clause}{objective_clause} indicator{slot_clause}{location_clause} comes from {dependency_source}."
                " Retail completion needs trigger/entity placement, minimap/map guidance, objective credit timing,"
                " and client objective smoke."
            )
        if dependency_type == "missing_objective_row":
            return (
                f"{quest_clause} references missing QuestObjective {objective_id} in {source_slot}. Retail completion is blocked"
                " until current-client QuestObjective evidence or reviewed replacement objective mapping is recovered."
            )
        if dependency_type == "target_group_cycle":
            return (
                f"{quest_clause}{objective_clause} TargetGroup {target_group_id} loops back through nested TargetGroup data."
                " Retail completion needs manual table review before this dependency can be trusted."
            )
        return fallback_summary

    def append_row(
        output: list[dict[str, object]],
        *,
        quest: dict[str, str],
        dependency_source: str,
        dependency_type: str,
        dependency_id: object,
        dependency_name: str = "",
        objective_id: int = 0,
        objective_type: object = "",
        source_slot: str = "",
        world_location_id: int = 0,
        world_zone_id: int = 0,
        quest_direction_id: int = 0,
        quest_direction_entry_id: int = 0,
        target_group_id: int = 0,
        target_group_type: object = "",
        target_group_data: object = "",
        prerequisite_id: int = 0,
        evidence_status: str,
        blocker_summary: str,
        evidence_sources: str | None = None,
    ) -> None:
        quest_id = to_int(quest["ID"])
        quest_status = quest_status_by_id.get(quest_id, {})
        location_data = location_context(world_location_id)
        resolved_world_zone_id = world_zone_id or to_int(str(location_data["world_zone_id"]))
        resolved_world_zone_name = zone_name(resolved_world_zone_id) if resolved_world_zone_id else location_data["world_zone_name"]
        output.append(
            {
                "quest_id": quest_id,
                "title": text_by_id(strings, to_int(quest["localizedTextIdTitle"])),
                "quest_bucket": quest_status.get("bucket", ""),
                "quest_completion_status": quest_status.get("completion_status", "not_retail_complete"),
                "dependency_source": dependency_source,
                "dependency_type": dependency_type,
                "dependency_id": dependency_id,
                "dependency_name": dependency_name,
                "objective_id": objective_id or "",
                "objective_type": objective_type,
                "source_slot": source_slot,
                "world_location_id": location_data["world_location_id"],
                "world_id": location_data["world_id"],
                "world_zone_id": resolved_world_zone_id or "",
                "world_zone_name": resolved_world_zone_name,
                "position_x": location_data["position_x"],
                "position_y": location_data["position_y"],
                "position_z": location_data["position_z"],
                "radius": location_data["radius"],
                "phases": location_data["phases"],
                "quest_direction_id": quest_direction_id or "",
                "quest_direction_entry_id": quest_direction_entry_id or "",
                "target_group_id": target_group_id or "",
                "target_group_type": target_group_type,
                "target_group_data": target_group_data,
                "prerequisite_id": prerequisite_id or "",
                "evidence_status": evidence_status,
                "evidence_sources": evidence_sources or "wildstar_client_mysql/Quest2.tbl.sql;wildstar_client_mysql/QuestObjective.tbl.sql;wildstar_client_mysql/QuestDirection.tbl.sql;wildstar_client_mysql/QuestDirectionEntry.tbl.sql;wildstar_client_mysql/TargetGroup.tbl.sql;wildstar_client_mysql/WorldLocation2.tbl.sql;wildstar_client_mysql/WorldZone.tbl.sql;Source/NexusForever.Script.Main;Source/NexusForever.Game/Quest",
                "manual_validation": "pending",
                "completion_status": "not_retail_complete",
                "blocker_summary": world_dependency_blocker_summary(
                    quest_id=quest_id,
                    dependency_type=dependency_type,
                    dependency_source=dependency_source,
                    dependency_id=dependency_id,
                    dependency_name=dependency_name,
                    objective_id=objective_id,
                    objective_type=objective_type,
                    source_slot=source_slot,
                    world_location_id=to_int(str(location_data["world_location_id"])),
                    world_zone_id=resolved_world_zone_id,
                    world_zone_name=str(resolved_world_zone_name),
                    position_x=location_data["position_x"],
                    position_y=location_data["position_y"],
                    position_z=location_data["position_z"],
                    radius=location_data["radius"],
                    quest_direction_id=quest_direction_id,
                    quest_direction_entry_id=quest_direction_entry_id,
                    target_group_id=target_group_id,
                    target_group_type=target_group_type,
                    target_group_data=target_group_data,
                    prerequisite_id=prerequisite_id,
                    evidence_status=evidence_status,
                    fallback_summary=blocker_summary,
                ),
            }
        )

    def append_direction_rows(
        output: list[dict[str, object]],
        quest: dict[str, str],
        source: str,
        source_slot: str,
        direction_id: int,
        objective_id: int = 0,
        objective_type: object = "",
        prerequisite_id: int = 0,
    ) -> None:
        direction = direction_by_id.get(direction_id)
        append_row(
            output,
            quest=quest,
            dependency_source=source,
            dependency_type="quest_direction",
            dependency_id=direction_id,
            objective_id=objective_id,
            objective_type=objective_type,
            source_slot=source_slot,
            quest_direction_id=direction_id,
            prerequisite_id=prerequisite_id,
            world_zone_id=to_int(direction.get("worldZoneIdExcludedZone") if direction else None),
            evidence_status="client_quest_direction_pending_path_arrow_smoke" if direction else "missing_client_quest_direction_row",
            blocker_summary="Quest direction row is tracked, but retail completion needs path-arrow routing, zone exclusion behavior, and client quest guidance smoke.",
        )
        if not direction:
            return

        for column in direction_entry_columns:
            entry_id = to_int(direction[column])
            if not entry_id:
                continue
            entry = direction_entry_by_id.get(entry_id)
            world_location_id = to_int(entry.get("worldLocation2Id") if entry else None)
            inactive_world_location_id = to_int(entry.get("worldLocation2IdInactive") if entry else None)
            if entry:
                direction_entry_evidence_status = "client_quest_direction_entry_pending_location_smoke"
                direction_entry_evidence_sources = None
                direction_entry_blocker_summary = "Quest direction entry is tracked, but retail completion needs the referenced world location, route arrow visibility, faction gating, and client guidance smoke."
            else:
                direction_entry_evidence_status = "blocked_missing_client_quest_direction_entry_row_runtime_fail_closed"
                direction_entry_evidence_sources = "wildstar_client_mysql/Quest2.tbl.sql;wildstar_client_mysql/QuestObjective.tbl.sql;wildstar_client_mysql/QuestDirection.tbl.sql;wildstar_client_mysql/QuestDirectionEntry.tbl.sql;Source/NexusForever.Game/Quest/Quest.cs;Source/NexusForever.Game.Tests/Quest/QuestTests.cs"
                direction_entry_blocker_summary = "QuestDirection references a missing client QuestDirectionEntry row; runtime objective guidance now fails closed by leaving the location unresolved instead of inventing a route target, but retail completion remains blocked until the missing client row or replacement route evidence is recovered."
            append_row(
                output,
                quest=quest,
                dependency_source=source,
                dependency_type="quest_direction_entry",
                dependency_id=f"{direction_id}:{entry_id}",
                objective_id=objective_id,
                objective_type=objective_type,
                source_slot=column,
                world_location_id=world_location_id,
                world_zone_id=to_int(entry.get("worldZoneId") if entry else None),
                quest_direction_id=direction_id,
                quest_direction_entry_id=entry_id,
                prerequisite_id=prerequisite_id,
                evidence_status=direction_entry_evidence_status,
                evidence_sources=direction_entry_evidence_sources,
                blocker_summary=direction_entry_blocker_summary,
            )
            if inactive_world_location_id:
                append_row(
                    output,
                    quest=quest,
                    dependency_source=source,
                    dependency_type="quest_direction_entry_inactive_location",
                    dependency_id=f"{direction_id}:{entry_id}:inactive",
                    objective_id=objective_id,
                    objective_type=objective_type,
                    source_slot=column,
                    world_location_id=inactive_world_location_id,
                    world_zone_id=to_int(entry.get("worldZoneId") if entry else None),
                    quest_direction_id=direction_id,
                    quest_direction_entry_id=entry_id,
                    prerequisite_id=prerequisite_id,
                    evidence_status="client_quest_direction_inactive_location_pending_state_smoke",
                    blocker_summary="Inactive quest-direction location is tracked, but retail completion needs state transition proof and client guidance smoke.",
                )

    def append_target_group_rows(
        output: list[dict[str, object]],
        quest: dict[str, str],
        objective_id: int,
        objective_type: object,
        target_group_id: int,
        dependency_source: str = "QuestObjective.targetGroupIdRewardPane",
        visited_target_groups: set[int] | None = None,
    ) -> None:
        visited_target_groups = set() if visited_target_groups is None else set(visited_target_groups)
        if target_group_id in visited_target_groups:
            append_row(
                output,
                quest=quest,
                dependency_source=dependency_source,
                dependency_type="target_group_cycle",
                dependency_id=target_group_id,
                objective_id=objective_id,
                objective_type=objective_type,
                target_group_id=target_group_id,
                evidence_status="blocked_target_group_cycle",
                blocker_summary="Nested target-group dependency loops back to an already visited TargetGroup row; retail completion needs manual table review before this dependency can be trusted.",
            )
            return
        visited_target_groups.add(target_group_id)
        target_group = target_group_by_id.get(target_group_id)
        target_group_name = text_by_id(strings, to_int(target_group.get("localizedTextIdDisplayString") if target_group else None))
        target_group_type = to_int(target_group.get("type") if target_group else None)
        target_group_override = TARGET_GROUP_EVIDENCE_OVERRIDES.get((to_int(quest["ID"]), objective_id, target_group_id), {})
        append_row(
            output,
            quest=quest,
            dependency_source=dependency_source,
            dependency_type="target_group",
            dependency_id=target_group_id,
            dependency_name=target_group_name,
            objective_id=objective_id,
            objective_type=objective_type,
            target_group_id=target_group_id,
            target_group_type=target_group_type,
            evidence_status=target_group_override.get("evidence_status", "client_target_group_pending_objective_entity_smoke" if target_group else "missing_client_target_group_row"),
            evidence_sources=target_group_override.get("evidence_sources"),
            blocker_summary=target_group_override.get("blocker_summary", "Target-group dependency is tracked, but retail completion needs target membership, spawn availability, objective credit, and client smoke."),
        )
        if not target_group:
            return

        if target_group_type == OTHER_TARGET_GROUP_CREATURES_TYPE:
            for column in target_group_data_columns:
                data_id = to_int(target_group[column])
                if not data_id:
                    continue
                nested_target_group = target_group_by_id.get(data_id)
                if nested_target_group:
                    nested_evidence_status = "client_nested_target_group_pending_member_smoke"
                    nested_evidence_sources = None
                    nested_blocker_summary = "Nested target-group dependency is tracked, but retail completion needs child membership, spawn availability, objective credit, and client smoke."
                else:
                    nested_evidence_status = "blocked_missing_client_nested_target_group_row_runtime_fail_closed"
                    nested_evidence_sources = "wildstar_client_mysql/QuestObjective.tbl.sql;wildstar_client_mysql/TargetGroup.tbl.sql;Source/NexusForever.Game/AssetManager.cs;Source/NexusForever.Game.Tests/Quest/AssetManagerTargetGroupTests.cs"
                    nested_blocker_summary = "TargetGroup.data points at a missing client TargetGroup row; runtime target expansion now fails closed by skipping the missing child without inventing objective targets, but retail completion remains blocked until the missing client row or replacement member evidence is recovered."
                append_row(
                    output,
                    quest=quest,
                    dependency_source="TargetGroup.data",
                    dependency_type="nested_target_group",
                    dependency_id=f"{target_group_id}:{column}:{data_id}",
                    dependency_name=target_group_name,
                    objective_id=objective_id,
                    objective_type=objective_type,
                    source_slot=column,
                    target_group_id=target_group_id,
                    target_group_type=target_group_type,
                    target_group_data=data_id,
                    evidence_status=nested_evidence_status,
                    evidence_sources=nested_evidence_sources,
                    blocker_summary=nested_blocker_summary,
                )
                if nested_target_group:
                    append_target_group_rows(
                        output,
                        quest,
                        objective_id,
                        objective_type,
                        data_id,
                        f"TargetGroup.data from {target_group_id}",
                        set(visited_target_groups),
                    )
            return

        for column in target_group_data_columns:
            data_id = to_int(target_group[column])
            if not data_id:
                continue
            runtime_spawns = runtime_entities_by_creature.get(data_id, [])
            runtime_worlds = join_ids(sorted({to_int(row.get("world")) for row in runtime_spawns}))
            runtime_areas = join_ids(sorted({to_int(row.get("area")) for row in runtime_spawns}))
            credit_test_status = TARGET_GROUP_MEMBER_CREDIT_TESTS.get((to_int(quest["ID"]), objective_id, target_group_id, data_id))
            script_spawn = TARGET_GROUP_MEMBER_SCRIPT_SPAWNS.get((to_int(quest["ID"]), objective_id, target_group_id, data_id))
            if runtime_spawns and credit_test_status:
                runtime_spawn_status = credit_test_status
                if credit_test_status.startswith("runtime_q4696_"):
                    runtime_spawn_sources = "wildstar_client_mysql/Quest2.tbl.sql;wildstar_client_mysql/QuestObjective.tbl.sql;wildstar_client_mysql/QuestDirection.tbl.sql;wildstar_client_mysql/QuestDirectionEntry.tbl.sql;wildstar_client_mysql/Creature2.tbl.sql;wildstar_client_mysql/TargetGroup.tbl.sql;wildstar_client_mysql/WorldLocation2.tbl.sql;wildstar_client_mysql/WorldZone.tbl.sql;Tools/DataMapping/sql/runtime_world_seed.sql;Source/NexusForever.Script.Main/Quests/Galeras/Q4696LeavingTheTempleOfOsiric.cs;Source/NexusForever.Game/Quest/Quest.cs;Source/NexusForever.Game/Quest/QuestObjective.cs;Source/NexusForever.Game.Tests/Quests/GalerasQuestScriptTests.cs;Source/NexusForever.Game.Tests/Quest/QuestTests.cs;Source/NexusForever.Game.Tests/Quest/AssetManagerTargetGroupTests.cs;Source/NexusForever.Game.Tests/Quest/QuestObjectiveTests.cs"
                    runtime_spawn_blocker = (
                        f"Target-group member {data_id} has {len(runtime_spawns)} runtime entity spawn row(s)"
                        f"{' in world(s) ' + runtime_worlds if runtime_worlds else ''}"
                        f"{' area(s) ' + runtime_areas if runtime_areas else ''}. Q4696TempleRetreatEnemyEntityScript credits QuestObjectiveType.ActivateEntity for this member on kill while Q4696 is accepted, and generic objective target-group expansion maps the credit to objective 6508. Retail completion still needs spawn placement/density review, live/client combat objective smoke, exact spawn/despawn and quest-state visibility timing, loot/reward side effects, and surrounding quest script flow."
                    )
                else:
                    runtime_spawn_sources = "wildstar_client_mysql/Quest2.tbl.sql;wildstar_client_mysql/QuestObjective.tbl.sql;wildstar_client_mysql/QuestDirection.tbl.sql;wildstar_client_mysql/QuestDirectionEntry.tbl.sql;wildstar_client_mysql/TargetGroup.tbl.sql;wildstar_client_mysql/WorldLocation2.tbl.sql;wildstar_client_mysql/WorldZone.tbl.sql;Tools/DataMapping/sql/runtime_world_seed.sql;Source/NexusForever.Script.Main;Source/NexusForever.Game/Quest/Quest.cs;Source/NexusForever.Game/Quest/QuestObjective.cs;Source/NexusForever.Game.Tests/Quest/QuestTests.cs"
                    runtime_spawn_blocker = (
                        f"Target-group member has {len(runtime_spawns)} runtime entity spawn row(s)"
                        f"{' in world(s) ' + runtime_worlds if runtime_worlds else ''}"
                        f"{' area(s) ' + runtime_areas if runtime_areas else ''}, and Q4696-shaped Quest.ObjectiveUpdate credit is covered by a focused test, but retail completion still needs spawn placement/density review, live/client objective smoke, loot/reward side effects, and surrounding quest script flow."
                    )
            elif runtime_spawns:
                runtime_spawn_status = "runtime_entity_spawn_present_pending_credit_client_smoke"
                runtime_spawn_sources = "wildstar_client_mysql/Quest2.tbl.sql;wildstar_client_mysql/QuestObjective.tbl.sql;wildstar_client_mysql/QuestDirection.tbl.sql;wildstar_client_mysql/QuestDirectionEntry.tbl.sql;wildstar_client_mysql/TargetGroup.tbl.sql;wildstar_client_mysql/WorldLocation2.tbl.sql;wildstar_client_mysql/WorldZone.tbl.sql;Tools/DataMapping/sql/runtime_world_seed.sql;Source/NexusForever.Script.Main;Source/NexusForever.Game/Quest"
                runtime_spawn_blocker = (
                    f"Target-group member has {len(runtime_spawns)} runtime entity spawn row(s)"
                    f"{' in world(s) ' + runtime_worlds if runtime_worlds else ''}"
                    f"{' area(s) ' + runtime_areas if runtime_areas else ''}, but retail completion still needs spawn placement/density review, kill/interact credit semantics, and objective completion/client smoke."
                )
            elif script_spawn:
                runtime_spawn_status = script_spawn.get("evidence_status") or credit_test_status or "runtime_script_spawn_present_pending_credit_client_smoke"
                runtime_spawn_sources = script_spawn.get("evidence_sources")
                runtime_spawn_blocker = script_spawn["blocker_summary"]
            else:
                runtime_spawn_status = "client_target_group_member_pending_spawn_and_credit_smoke"
                runtime_spawn_sources = None
                runtime_spawn_blocker = "Target-group member is tracked, but retail completion needs spawn availability, kill/interact credit semantics, and objective completion smoke."
            append_row(
                output,
                quest=quest,
                dependency_source="TargetGroup.data",
                dependency_type="target_group_member",
                dependency_id=f"{target_group_id}:{column}:{data_id}",
                dependency_name=target_group_name,
                objective_id=objective_id,
                objective_type=objective_type,
                source_slot=column,
                target_group_id=target_group_id,
                target_group_type=to_int(target_group["type"]),
                target_group_data=data_id,
                evidence_status=runtime_spawn_status,
                evidence_sources=runtime_spawn_sources,
                blocker_summary=runtime_spawn_blocker,
            )

    output: list[dict[str, object]] = []
    for quest in sorted(quests, key=lambda row: to_int(row["ID"])):
        world_zone_id = to_int(quest["worldZoneId"])
        if world_zone_id:
            world_zone_override = QUEST_WORLD_ZONE_OVERRIDES.get(
                (to_int(quest["ID"]), "quest_world_zone", world_zone_id),
                {},
            )
            append_row(
                output,
                quest=quest,
                dependency_source="Quest2.worldZoneId",
                dependency_type="quest_world_zone",
                dependency_id=world_zone_id,
                dependency_name=zone_name(world_zone_id),
                world_zone_id=world_zone_id,
                evidence_status=world_zone_override.get("evidence_status", "client_quest_world_zone_pending_map_and_activation_smoke"),
                evidence_sources=world_zone_override.get("evidence_sources"),
                blocker_summary=world_zone_override.get(
                    "blocker_summary",
                    "Quest world-zone dependency is tracked, but retail completion needs map availability, quest activation, and zone-specific gameplay smoke.",
                ),
            )

        receiver_location_id = to_int(quest["WorldLocation2IdReceiver"])
        if receiver_location_id:
            receiver_override = QUEST_RECEIVER_LOCATION_OVERRIDES.get(
                (to_int(quest["ID"]), "quest_receiver_location", receiver_location_id),
                {},
            )
            append_row(
                output,
                quest=quest,
                dependency_source="Quest2.WorldLocation2IdReceiver",
                dependency_type="quest_receiver_location",
                dependency_id=receiver_location_id,
                source_slot="WorldLocation2IdReceiver",
                world_location_id=receiver_location_id,
                evidence_status=receiver_override.get("evidence_status", "client_quest_receiver_location_pending_dialog_smoke"),
                evidence_sources=receiver_override.get("evidence_sources"),
                blocker_summary=receiver_override.get(
                    "blocker_summary",
                    "Quest receiver location is tracked, but retail completion needs NPC/object spawn, dialog availability, completion routing, and client quest smoke.",
                ),
            )

        completion_direction_id = to_int(quest["questDirectionIdCompletion"])
        if completion_direction_id:
            append_direction_rows(output, quest, "Quest2.questDirectionIdCompletion", "questDirectionIdCompletion", completion_direction_id)

        for index in range(3):
            suffix = f"{index:02d}"
            location_id = to_int(quest[f"worldLocation2IdAltReceiver{suffix}"])
            prerequisite_id = to_int(quest[f"prerequisiteIdAltReceiver{suffix}"])
            direction_id = to_int(quest[f"questDirectionIdAltReceiver{suffix}"])
            if location_id:
                receiver_override = QUEST_RECEIVER_LOCATION_OVERRIDES.get(
                    (to_int(quest["ID"]), "quest_alt_receiver_location", location_id),
                    {},
                )
                append_row(
                    output,
                    quest=quest,
                    dependency_source="Quest2.worldLocation2IdAltReceiver",
                    dependency_type="quest_alt_receiver_location",
                    dependency_id=location_id,
                    source_slot=suffix,
                    world_location_id=location_id,
                    prerequisite_id=prerequisite_id,
                    quest_direction_id=direction_id,
                    evidence_status=receiver_override.get("evidence_status", "client_quest_alt_receiver_location_pending_prereq_dialog_smoke"),
                    evidence_sources=receiver_override.get("evidence_sources"),
                    blocker_summary=receiver_override.get(
                        "blocker_summary",
                        "Alternate quest receiver location is tracked, but retail completion needs prerequisite selection, NPC/object spawn, dialog routing, and client quest smoke.",
                    ),
                )
            if direction_id:
                append_direction_rows(output, quest, "Quest2.questDirectionIdAltReceiver", suffix, direction_id, prerequisite_id=prerequisite_id)

        for objective_column in QUEST_OBJECTIVE_COLUMNS:
            objective_id = to_int(quest[objective_column])
            if not objective_id:
                continue
            objective = objective_by_id.get(objective_id)
            objective_type = to_int(objective.get("type") if objective else None)
            if not objective:
                append_row(
                    output,
                    quest=quest,
                    dependency_source="Quest2.objective",
                    dependency_type="missing_objective_row",
                    dependency_id=objective_id,
                    objective_id=objective_id,
                    source_slot=objective_column,
                    evidence_status="missing_client_quest_objective_row",
                    blocker_summary="Quest references an objective row that is missing from the client table; retail completion is blocked pending source-table reconciliation.",
                )
                continue

            for column in objective_indicator_columns:
                location_id = to_int(objective[column])
                if not location_id:
                    continue
                runtime_placement = (
                    RUNTIME_WORLD_LOCATION_TRIGGER_PLACEMENTS.get((to_int(quest["ID"]), objective_id, location_id))
                    or RUNTIME_OBJECTIVE_INDICATOR_PLACEMENTS.get((to_int(quest["ID"]), objective_id, location_id), {})
                )
                append_row(
                    output,
                    quest=quest,
                    dependency_source="QuestObjective.worldLocationsIdIndicator",
                    dependency_type="objective_indicator_location",
                    dependency_id=f"{objective_id}:{column}:{location_id}",
                    objective_id=objective_id,
                    objective_type=objective_type,
                    source_slot=column,
                    world_location_id=location_id,
                    evidence_status=runtime_placement.get("evidence_status", "client_objective_indicator_location_pending_world_trigger_smoke"),
                    blocker_summary=runtime_placement.get("blocker_summary", "Objective indicator location is tracked, but retail completion needs trigger/entity placement, minimap/map guidance, and objective smoke."),
                    evidence_sources=runtime_placement.get("evidence_sources"),
                )

            target_group_id = to_int(objective["targetGroupIdRewardPane"])
            if target_group_id:
                append_target_group_rows(output, quest, objective_id, objective_type, target_group_id)

            if objective_type in (KILL_TARGET_GROUP_OBJECTIVE_TYPE, ACTIVATE_TARGET_GROUP_CHECKLIST_OBJECTIVE_TYPE):
                target_group_id = to_int(objective["data"])
                if target_group_id:
                    append_target_group_rows(output, quest, objective_id, objective_type, target_group_id, "QuestObjective.data")

            direction_id = to_int(objective["questDirectionId"])
            if direction_id:
                append_direction_rows(output, quest, "QuestObjective.questDirectionId", objective_column, direction_id, objective_id=objective_id, objective_type=objective_type)

    return output


def build_quest_achievement_rows(
    strings: dict[int, str],
    quests: list[dict[str, str]],
    quest_output: list[dict[str, object]],
    achievements: list[dict[str, str]],
    checklists: list[dict[str, str]],
) -> list[dict[str, object]]:
    quest_by_id = {to_int(row["ID"]): row for row in quests}
    quest_status_by_id = {to_int(str(row["quest_id"])): row for row in quest_output}
    achievement_by_id = {to_int(row["ID"]): row for row in achievements}

    def base_row(quest_id: int) -> dict[str, object]:
        quest = quest_by_id.get(quest_id, {})
        quest_status = quest_status_by_id.get(quest_id, {})
        return {
            "quest_id": quest_id,
            "title": text_by_id(strings, to_int(quest.get("localizedTextIdTitle"))),
            "quest_bucket": quest_status.get("bucket", "orphaned_achievement_reference"),
            "quest_completion_status": quest_status.get("completion_status", "not_retail_complete"),
        }

    def achievement_blocker_summary(
        dependency_type: str,
        quest_id: int,
        achievement: dict[str, str],
        source_field: str,
        checklist: dict[str, str] | None,
    ) -> str:
        achievement_id = to_int(achievement["ID"])
        title = text_by_id(strings, to_int(achievement.get("localizedTextIdTitle")))
        title_clause = f" ({title})" if title else ""
        progress_text = text_by_id(strings, to_int(achievement.get("localizedTextIdProgress")))
        progress_clause = f" progress text '{progress_text}'" if progress_text else ""
        achievement_clause = (
            f"Achievement {achievement_id}{title_clause} type {to_int(achievement.get('achievementTypeId'))}"
            f" category {to_int(achievement.get('achievementCategoryId'))} flags {to_int(achievement.get('flags'))}"
            f" worldZone {to_int(achievement.get('worldZoneId'))}{progress_clause}"
        )
        tier_clause = ""
        parent_tier = to_int(achievement.get("achievementIdParentTier"))
        if parent_tier:
            tier_clause = f", parent tier {parent_tier}"
        title_reward_clause = ""
        character_title_id = to_int(achievement.get("characterTitleId"))
        if character_title_id:
            title_reward_clause = f", character title {character_title_id}"
        prerequisite_values = [
            to_int(achievement.get("prerequisiteId")),
            to_int(achievement.get("prerequisiteIdServer")),
            to_int(achievement.get("prerequisiteIdObjective")),
            to_int(achievement.get("prerequisiteIdObjectiveAlt")),
        ]
        prerequisite_clause = ""
        if any(prerequisite_values):
            prerequisite_clause = f", prerequisites {join_ids(value for value in prerequisite_values if value)}"
        if dependency_type == "achievement":
            object_value = to_int(achievement.get(source_field.split(".")[-1]))
            return (
                f"{achievement_clause} references Quest2 {quest_id} through {source_field}={object_value}{tier_clause}"
                f"{title_reward_clause}{prerequisite_clause}. Retail completion needs quest progression hook ownership,"
                " duplicate/parent-tier behavior, title/reward behavior, achievement persistence, and client achievement UI smoke."
            )

        checklist_id = to_int(checklist.get("ID") if checklist else None)
        checklist_bit = to_int(checklist.get("bit") if checklist else None)
        checklist_object_id = to_int(checklist.get("objectId") if checklist else None)
        checklist_object_id_alt = to_int(checklist.get("objectIdAlt") if checklist else None)
        checklist_prerequisite_id = to_int(checklist.get("prerequisiteId") if checklist else None)
        checklist_prerequisite_id_alt = to_int(checklist.get("prerequisiteIdAlt") if checklist else None)
        checklist_prerequisite_clause = ""
        checklist_prerequisites = [value for value in (checklist_prerequisite_id, checklist_prerequisite_id_alt) if value]
        if checklist_prerequisites:
            checklist_prerequisite_clause = f", checklist prerequisites {join_ids(checklist_prerequisites)}"
        return (
            f"AchievementChecklist {checklist_id} links {achievement_clause} to bit {checklist_bit}, objectId {checklist_object_id},"
            f" objectIdAlt {checklist_object_id_alt}, and Quest2 {quest_id} through {source_field}{checklist_prerequisite_clause}"
            f"{tier_clause}{title_reward_clause}{prerequisite_clause}. Retail completion needs quest progression hook ownership,"
            " duplicate checklist behavior, parent-tier/title/reward behavior, achievement persistence, and client achievement UI smoke."
        )

    def append_row(
        output: list[dict[str, object]],
        *,
        quest_id: int,
        dependency_type: str,
        achievement: dict[str, str],
        source_field: str,
        checklist: dict[str, str] | None = None,
    ) -> None:
        achievement_id = to_int(achievement["ID"])
        checklist_id = to_int(checklist.get("ID") if checklist else None)
        override = QUEST_ACHIEVEMENT_OVERRIDES.get((quest_id, dependency_type, achievement_id, checklist_id), {})
        default_evidence_status = (
            "client_achievement_row_pending_progression_hook_smoke"
            if dependency_type == "achievement"
            else "client_achievement_checklist_row_pending_progression_hook_smoke"
        )
        output.append(
            {
                **base_row(quest_id),
                "dependency_type": dependency_type,
                "achievement_id": achievement_id,
                "achievement_title": text_by_id(strings, to_int(achievement.get("localizedTextIdTitle"))),
                "achievement_description": text_by_id(strings, to_int(achievement.get("localizedTextIdDesc"))),
                "achievement_progress_text": text_by_id(strings, to_int(achievement.get("localizedTextIdProgress"))),
                "achievement_type_id": to_int(achievement.get("achievementTypeId")),
                "achievement_category_id": to_int(achievement.get("achievementCategoryId")),
                "achievement_flags": to_int(achievement.get("flags")),
                "world_zone_id": to_int(achievement.get("worldZoneId")),
                "source_field": source_field,
                "object_id": to_int(achievement.get("objectId")),
                "object_id_alt": to_int(achievement.get("objectIdAlt")),
                "value": to_int(achievement.get("value")),
                "character_title_id": to_int(achievement.get("characterTitleId")),
                "prerequisite_id": to_int(achievement.get("prerequisiteId")),
                "prerequisite_id_server": to_int(achievement.get("prerequisiteIdServer")),
                "prerequisite_id_objective": to_int(achievement.get("prerequisiteIdObjective")),
                "prerequisite_id_objective_alt": to_int(achievement.get("prerequisiteIdObjectiveAlt")),
                "achievement_id_parent_tier": to_int(achievement.get("achievementIdParentTier")),
                "checklist_id": checklist_id or "",
                "checklist_bit": to_int(checklist.get("bit") if checklist else None) if checklist else "",
                "checklist_object_id": to_int(checklist.get("objectId") if checklist else None) if checklist else "",
                "checklist_object_id_alt": to_int(checklist.get("objectIdAlt") if checklist else None) if checklist else "",
                "checklist_prerequisite_id": to_int(checklist.get("prerequisiteId") if checklist else None) if checklist else "",
                "checklist_prerequisite_id_alt": to_int(checklist.get("prerequisiteIdAlt") if checklist else None) if checklist else "",
                "evidence_status": override.get("evidence_status", default_evidence_status),
                "evidence_sources": override.get("evidence_sources", "wildstar_client_mysql/Achievement.tbl.sql;wildstar_client_mysql/AchievementChecklist.tbl.sql;wildstar_client_mysql/Quest2.tbl.sql;Source/NexusForever.Game/Achievement;Source/NexusForever.Script.Main"),
                "manual_validation": "pending",
                "completion_status": "not_retail_complete",
                "blocker_summary": override.get(
                    "blocker_summary",
                    achievement_blocker_summary(dependency_type, quest_id, achievement, source_field, checklist),
                ),
            }
        )

    output: list[dict[str, object]] = []
    for achievement in sorted(achievements, key=lambda row: to_int(row["ID"])):
        if to_int(achievement["achievementTypeId"]) not in QUEST_ACHIEVEMENT_TYPES:
            continue
        for source_field in ("objectId", "objectIdAlt"):
            quest_id = to_int(achievement[source_field])
            if quest_id:
                append_row(output, quest_id=quest_id, dependency_type="achievement", achievement=achievement, source_field=f"Achievement.{source_field}")

    for checklist in sorted(checklists, key=lambda row: to_int(row["ID"])):
        achievement = achievement_by_id.get(to_int(checklist["achievementId"]))
        if not achievement or to_int(achievement["achievementTypeId"]) not in QUEST_ACHIEVEMENT_TYPES:
            continue
        for source_field in ("objectId", "objectIdAlt"):
            quest_id = to_int(checklist[source_field])
            if quest_id:
                append_row(
                    output,
                    quest_id=quest_id,
                    dependency_type="achievement_checklist",
                    achievement=achievement,
                    checklist=checklist,
                    source_field=f"AchievementChecklist.{source_field}",
                )

    return output


def build_quest_script_rows(
    strings: dict[int, str],
    quests: list[dict[str, str]],
    quest_output: list[dict[str, object]],
    script_main: Path,
) -> list[dict[str, object]]:
    quest_by_id = {to_int(row["ID"]): row for row in quests}
    quest_status_by_id = {to_int(str(row["quest_id"])): row for row in quest_output}
    stub_script_ids = quest_implementation_audit.load_script_quality(script_main)

    def evidence_status(owner_id: int, kind: str, quest_status: dict[str, object]) -> str:
        if owner_id in quest_by_id and kind == "quest_script":
            bucket = str(quest_status.get("bucket", ""))
            if bucket == "curated_full":
                return "runtime_curated_quest_script_pending_manual_smoke"
            if bucket == "no_objectives":
                if owner_id in NO_OBJECTIVE_SCRIPT_LIFECYCLE_TESTED_QUEST_IDS:
                    return "implemented_no_objective_script_lifecycle_tests_pending_dialog_smoke"
                return MAPPED_ONLY_NO_OBJECTIVE_SCRIPT_STATUS
            if bucket == "curated_partial_stub_script" or owner_id in stub_script_ids:
                return "runtime_stub_quest_script_blocked"
            if bucket == "generic_with_script":
                return "runtime_generic_quest_script_hook_pending_world_smoke"
            return "runtime_quest_script_hook_pending_review"
        if owner_id in quest_by_id:
            return "runtime_non_quest_script_owner_matches_quest_id_review_required"
        if kind == "map_script":
            return "runtime_map_script_owner_pending_zone_smoke"
        if kind == "public_event_script":
            return "runtime_public_event_script_owner_pending_event_smoke"
        if kind == "spell_script":
            return "runtime_spell_script_owner_pending_spell_smoke"
        return "runtime_script_owner_not_current_quest_pending_owner_family_review"

    def blocker_summary(owner_id: int, kind: str, quest_status: dict[str, object]) -> str:
        if owner_id in quest_by_id and kind == "quest_script":
            bucket = str(quest_status.get("bucket", ""))
            if bucket == "no_objectives":
                if owner_id in NO_OBJECTIVE_SCRIPT_LIFECYCLE_TESTED_QUEST_IDS:
                    return "No-objective quest script hook is row-tested through the shared QuestManager accept-to-achieved and visible-receiver completion paths for this Quest2 row; retail completion still needs client-visible dialog activation, exact row-specific reward and achievement side effects, and client/manual smoke."
                return "No-objective quest script hook is tracked; shared QuestManager coverage now places zero-objective quests directly in Achieved state after accept and covers representative visible-receiver turn-in, reward grant, and achievement-hook paths, but retail completion still needs row-specific receiver/dialog routing, reward and achievement side effects, and client/manual smoke."
            if bucket != "curated_full" and (bucket == "curated_partial_stub_script" or owner_id in stub_script_ids):
                return "Stub quest script hook is tracked, but the source has no implementation markers; retail completion needs row-specific mechanic proof, objective trigger ownership, side effects, focused tests, and client/manual smoke."
            return "Quest script hook is tracked, but retail completion needs objective/follow-up behavior proof, reward and achievement side effects, automated coverage, and client/manual smoke."
        if owner_id in quest_by_id:
            return "ScriptFilterOwnerId matches a current Quest2 id but the script is not classified as an IQuestScript; retail completion needs owner-family review before treating it as quest behavior."
        return "ScriptFilterOwnerId does not match a current Quest2 row; tracked as related Script.Main runtime content pending owner-family evidence and smoke before it can support quest retail-completeness claims."

    output: list[dict[str, object]] = []
    for detail in load_script_owner_details(script_main):
        owner_id = to_int(str(detail["owner_id"]))
        quest = quest_by_id.get(owner_id, {})
        quest_status = quest_status_by_id.get(owner_id, {})
        kind = str(detail["script_kind"])
        override = QUEST_SCRIPT_OVERRIDES.get(owner_id, {})
        default_evidence_sources = "Source/NexusForever.Script.Main;wildstar_client_mysql/Quest2.tbl.sql;Tools/WikiArchiveAudit/quest_implementation_audit.py;Decomp/Analysis/QUEST_IMPLEMENTATION_STATUS.md"
        if owner_id in quest_by_id and kind == "quest_script" and str(quest_status.get("bucket", "")) == "no_objectives":
            default_evidence_sources += ";Source/NexusForever.Game/Entity/QuestManager.cs;Source/NexusForever.Game.Tests/Quest/QuestTests.cs"
        output.append(
            {
                "owner_id": owner_id,
                "quest_id": owner_id if owner_id in quest_by_id else "",
                "quest_title": text_by_id(strings, to_int(quest.get("localizedTextIdTitle"))),
                "quest_bucket": quest_status.get("bucket", ""),
                "quest_completion_status": quest_status.get("completion_status", ""),
                "quest_link_status": "current_quest" if owner_id in quest_by_id else "non_quest_script_owner",
                "script_kind": kind,
                "script_class": detail["script_class"],
                "script_path": detail["script_path"],
                "owner_ids_on_attribute": detail["owner_ids_on_attribute"],
                "evidence_status": override.get("evidence_status", evidence_status(owner_id, kind, quest_status)),
                "evidence_sources": override.get("evidence_sources", default_evidence_sources),
                "manual_validation": "pending",
                "completion_status": "not_retail_complete",
                "blocker_summary": override.get("blocker_summary", blocker_summary(owner_id, kind, quest_status)),
            }
        )

    return output


def creature_relation_evidence_status(match_status: str, relation_type: str, current_quest: bool, runtime_spawn_count: int = 0) -> str:
    if not current_quest:
        return "datamapping_quest_relation_not_current_client_quest_row_blocked"
    if match_status == "unmatched":
        return "datamapping_creature_bridge_unmatched_blocked"
    if match_status == "ambiguous_name":
        return "datamapping_creature_bridge_ambiguous_pending_review"
    if runtime_spawn_count:
        if match_status == "reviewed":
            return f"runtime_spawn_present_reviewed_{relation_type}_creature_relation_pending_dialog_credit_smoke"
        if match_status in {"unique_name", "scored_name"}:
            return f"runtime_spawn_present_datamapping_{relation_type}_creature_relation_pending_bridge_review_credit_smoke"
    if match_status == "reviewed":
        return f"reviewed_{relation_type}_creature_relation_pending_spawn_dialog_credit_smoke"
    if match_status in {"unique_name", "scored_name"}:
        return f"datamapping_{relation_type}_creature_relation_pending_review_and_smoke"
    return f"datamapping_{relation_type}_creature_relation_pending_review"


def creature_relation_evidence_sources(evidence_status: str, relation_type: str, runtime_spawn_count: int) -> str:
    relation_sources = {
        "starter": "jabbithole_mysql/quest_starter_creatures.sql",
        "finisher": "jabbithole_mysql/quest_finisher_creatures.sql",
        "objective": "jabbithole_mysql/quest_creatures.sql",
    }
    sources = [
        "Tools/DataMapping/output/creature_quest_map.csv",
        "Tools/DataMapping/output/creature_map.csv",
        "Tools/DataMapping/output/creature_spawn_map.csv",
        "Tools/DataMapping/map_wildstar_data.py",
        "jabbithole_mysql/creatures.sql",
    ]
    relation_source = relation_sources.get(relation_type)
    if relation_source:
        sources.append(relation_source)
    sources.extend(
        [
            "wildstar_client_mysql/Quest2.tbl.sql",
            "wildstar_client_mysql/Creature2.tbl.sql",
            "Source/NexusForever.Game/Entity",
            "Source/NexusForever.Script.Main",
        ]
    )
    if runtime_spawn_count:
        sources.append("Tools/DataMapping/sql/runtime_world_seed.sql")
    if evidence_status in {
        "datamapping_creature_bridge_unmatched_blocked",
        "datamapping_creature_bridge_ambiguous_pending_review",
        "datamapping_quest_relation_not_current_client_quest_row_blocked",
    }:
        sources.append("Tools/DataMapping/README.md")
    return ";".join(sources)


def creature_relation_blocker_summary(
    match_status: str,
    runtime_spawn_count: int,
    runtime_worlds: str,
    runtime_areas: str,
    runtime_datamapping_position_match_count: int = 0,
    runtime_matched_source_coordinate_ids: Iterable[int] | None = None,
    datamapping_unpromoted_spawn_count: int = 0,
    datamapping_unpromoted_source_coordinate_ids: Iterable[int] | None = None,
    source_relation_id: int = 0,
    relation_type: str = "",
    quest_id: int = 0,
    jabbithole_creature_id: int = 0,
    source_name: str = "",
    creature2_id: int = 0,
    creature2_name: str = "",
) -> str:
    relation_clause = (
        f"{relation_type} source_relation_id {source_relation_id}"
        if relation_type and source_relation_id
        else "Quest creature relationship"
    )
    quest_clause = f" for Quest2 {quest_id}" if quest_id else ""
    source_clause = ""
    if jabbithole_creature_id:
        source_clause = f" from Jabbithole creature {jabbithole_creature_id}"
        if source_name:
            source_clause += f" ({source_name})"
    creature_clause = ""
    if creature2_id:
        creature_clause = f" to Creature2 {creature2_id}"
        if creature2_name:
            creature_clause += f" ({creature2_name})"

    exact_match_clause = ""
    if runtime_datamapping_position_match_count:
        exact_match_clause = (
            f", including {runtime_datamapping_position_match_count} promoted runtime row(s) that exactly match"
            f" DataMapping source_coordinate_id(s) {join_ids(sorted(runtime_matched_source_coordinate_ids or []))}"
        )
    unpromoted_ids = join_ids(sorted(datamapping_unpromoted_source_coordinate_ids or []))
    unpromoted_source_clause = f" (source_coordinate_id(s) {unpromoted_ids})" if unpromoted_ids else ""
    unpromoted_clause = ""
    if datamapping_unpromoted_spawn_count:
        unpromoted_clause = (
            f", and {datamapping_unpromoted_spawn_count} DataMapping placement row(s) remain unpromoted to runtime seed"
            f"{unpromoted_source_clause}"
        )

    if match_status == "unmatched":
        return (
            f"{relation_clause}{quest_clause}{source_clause} is blocked because DataMapping has match_status unmatched"
            " and no current Creature2 bridge. Retail implementation needs a reviewed current-client Creature2 bridge"
            " or reviewed replacement relation before runtime spawn/dialog/objective-credit behavior and client/manual smoke can be claimed."
        )
    if runtime_spawn_count and match_status == "ambiguous_name":
        return (
            f"{relation_clause}{quest_clause}{source_clause}{creature_clause} is tracked, and the selected Creature2 candidate has {runtime_spawn_count} runtime entity spawn row(s)"
            f"{' in world(s) ' + runtime_worlds if runtime_worlds else ''}"
            f"{' area(s) ' + runtime_areas if runtime_areas else ''}"
            f"{exact_match_clause}{unpromoted_clause}, but the Creature2 bridge remains ambiguous; retail completion needs reviewed bridge disambiguation, spawn placement/density review, runtime dialog/objective-credit behavior, and client/manual smoke."
        )
    if runtime_spawn_count:
        return (
            f"{relation_clause}{quest_clause}{source_clause}{creature_clause} has {runtime_spawn_count} runtime entity spawn row(s)"
            f"{' in world(s) ' + runtime_worlds if runtime_worlds else ''}"
            f"{' area(s) ' + runtime_areas if runtime_areas else ''}"
            f"{exact_match_clause}{unpromoted_clause}, but retail completion still needs bridge review where applicable, runtime dialog/objective-credit behavior, and client/manual smoke."
        )
    if datamapping_unpromoted_spawn_count:
        return (
            f"{relation_clause}{quest_clause}{source_clause}{creature_clause} is tracked from DataMapping with {datamapping_unpromoted_spawn_count} placement row(s) not yet promoted to runtime seed"
            f"{unpromoted_source_clause}, but retail completion needs reviewed Creature2 bridge evidence, runtime spawn/dialog/objective-credit behavior, and client/manual smoke."
        )
    return (
        f"{relation_clause}{quest_clause}{source_clause}{creature_clause} is tracked from DataMapping, but retail completion needs"
        " current-client quest ownership, reviewed Creature2 bridge, runtime spawn/dialog/objective-credit behavior, and client/manual smoke."
    )


def build_quest_creature_rows(
    strings: dict[int, str],
    quests: list[dict[str, str]],
    quest_output: list[dict[str, object]],
    creature_quest_map_path: Path,
    runtime_entity_rows: list[dict[str, str]] | None = None,
    creature_spawn_rows: list[dict[str, str]] | None = None,
) -> list[dict[str, object]]:
    quest_by_id = {to_int(row["ID"]): row for row in quests}
    quest_status_by_id = {to_int(str(row["quest_id"])): row for row in quest_output}
    rows = load_csv_rows(creature_quest_map_path)
    if creature_spawn_rows is None:
        creature_spawn_map_path = creature_quest_map_path.with_name("creature_spawn_map.csv")
        creature_spawn_rows = load_csv_rows(creature_spawn_map_path) if creature_spawn_map_path.exists() else []
    runtime_entity_rows = (
        load_insert_rows(RUNTIME_WORLD_SEED_SQL, "entity", INSTANCE_ENTITY_COLUMNS)
        if runtime_entity_rows is None
        else runtime_entity_rows
    )
    runtime_entities_by_creature: dict[int, list[dict[str, str]]] = defaultdict(list)
    for row in runtime_entity_rows:
        creature_id = to_int(row.get("creature"))
        if creature_id:
            runtime_entities_by_creature[creature_id].append(row)

    datamapping_spawns_by_creature: dict[tuple[int, int], list[dict[str, str]]] = defaultdict(list)
    for row in creature_spawn_rows:
        jabbithole_creature_id = to_int(row.get("jabbithole_creature_id"))
        creature2_id = to_int(row.get("creature2_id"))
        if jabbithole_creature_id and creature2_id:
            datamapping_spawns_by_creature[(jabbithole_creature_id, creature2_id)].append(row)

    def position_key(row: dict[str, str], world_column: str, area_column: str) -> tuple[int, int, int, int, int]:
        return (
            to_int(row.get(world_column)),
            to_int(row.get(area_column)),
            to_int(row.get("x")),
            to_int(row.get("y")),
            to_int(row.get("z")),
        )

    def datamapping_position_summary(row: dict[str, str]) -> str:
        return "/".join(
            [
                str(to_int(row.get("worldid"))),
                str(to_int(row.get("worldzoneid"))),
                str(to_int(row.get("x"))),
                str(to_int(row.get("y"))),
                str(to_int(row.get("z"))),
            ]
        )

    output: list[dict[str, object]] = []
    for row in sorted(rows, key=lambda item: (to_int(item.get("quest2_id")), str(item.get("relation_type", "")), to_int(item.get("source_relation_id")))):
        quest_id = to_int(row.get("quest2_id"))
        quest = quest_by_id.get(quest_id, {})
        quest_status = quest_status_by_id.get(quest_id, {})
        relation_type = str(row.get("relation_type", ""))
        match_status = str(row.get("match_status", ""))
        current_quest = quest_id in quest_by_id
        source_relation_id = to_int(row.get("source_relation_id"))
        override = QUEST_CREATURE_RELATION_OVERRIDES.get((quest_id, relation_type, source_relation_id), {})
        jabbithole_creature_id = to_int(row.get("jabbithole_creature_id"))
        raw_creature2_id = to_int(row.get("original_creature2_id") or row.get("creature2_id"))
        creature2_id = to_int(override.get("creature2_id", row.get("creature2_id")))
        if override.get("match_status"):
            match_status = str(override["match_status"])
        runtime_spawns = runtime_entities_by_creature.get(creature2_id, [])
        runtime_spawn_count = len(runtime_spawns)
        runtime_worlds = join_ids(sorted({to_int(spawn.get("world")) for spawn in runtime_spawns}))
        runtime_areas = join_ids(sorted({to_int(spawn.get("area")) for spawn in runtime_spawns}))
        datamapping_spawns: list[dict[str, str]] = []
        seen_datamapping_source_ids: set[int] = set()
        for candidate_creature2_id in (creature2_id, raw_creature2_id):
            for spawn in datamapping_spawns_by_creature.get((jabbithole_creature_id, candidate_creature2_id), []):
                source_coordinate_id = to_int(spawn.get("source_coordinate_id"))
                if source_coordinate_id in seen_datamapping_source_ids:
                    continue
                seen_datamapping_source_ids.add(source_coordinate_id)
                datamapping_spawns.append(spawn)

        datamapping_positions_by_key: dict[tuple[int, int, int, int, int], list[int]] = defaultdict(list)
        for spawn in datamapping_spawns:
            datamapping_positions_by_key[position_key(spawn, "worldid", "worldzoneid")].append(to_int(spawn.get("source_coordinate_id")))

        matched_source_coordinate_ids: set[int] = set()
        matched_runtime_entity_ids: set[int] = set()
        for spawn in runtime_spawns:
            matching_source_ids = datamapping_positions_by_key.get(position_key(spawn, "world", "area"), [])
            if not matching_source_ids:
                continue
            matched_source_coordinate_ids.update(matching_source_ids)
            matched_runtime_entity_ids.add(to_int(spawn.get("id")))
        unpromoted_datamapping_spawns = [
            spawn
            for spawn in datamapping_spawns
            if to_int(spawn.get("source_coordinate_id")) not in matched_source_coordinate_ids
        ]
        unpromoted_source_coordinate_ids = {
            to_int(spawn.get("source_coordinate_id"))
            for spawn in unpromoted_datamapping_spawns
        }

        evidence_status = override.get("evidence_status") or creature_relation_evidence_status(match_status, relation_type, current_quest, runtime_spawn_count)
        evidence_sources = override.get("evidence_sources") or creature_relation_evidence_sources(evidence_status, relation_type, runtime_spawn_count)
        blocker_summary = override.get("blocker_summary") or creature_relation_blocker_summary(
            match_status,
            runtime_spawn_count,
            runtime_worlds,
            runtime_areas,
            len(matched_runtime_entity_ids),
            matched_source_coordinate_ids,
            len(unpromoted_datamapping_spawns),
            unpromoted_source_coordinate_ids,
            source_relation_id,
            relation_type,
            quest_id,
            jabbithole_creature_id,
            row.get("source_name", ""),
            creature2_id,
            override.get("creature2_name", row.get("creature2_name", "")),
        )
        output.append(
            {
                "quest_id": quest_id,
                "quest_title": text_by_id(strings, to_int(quest.get("localizedTextIdTitle"))) or row.get("quest_name", ""),
                "quest_bucket": quest_status.get("bucket", "non_current_client_quest_reference" if not current_quest else "review_required"),
                "quest_completion_status": quest_status.get("completion_status", "not_retail_complete"),
                "quest_link_status": "current_quest" if current_quest else "non_current_client_quest_reference",
                "relation_type": relation_type,
                "source_relation_id": source_relation_id,
                "jabbithole_creature_id": to_int(row.get("jabbithole_creature_id")),
                "creature2_id": creature2_id if creature2_id else "",
                "source_name": row.get("source_name", ""),
                "creature2_name": override.get("creature2_name", row.get("creature2_name", "")),
                "match_status": match_status,
                "runtime_spawn_count": runtime_spawn_count or "",
                "runtime_spawn_worlds": runtime_worlds,
                "runtime_spawn_areas": runtime_areas,
                "datamapping_spawn_count": len(datamapping_spawns) or "",
                "datamapping_source_coordinate_id_sample": join_sample(sorted(seen_datamapping_source_ids)),
                "datamapping_spawn_worlds": join_ids(sorted({to_int(spawn.get("worldid")) for spawn in datamapping_spawns})),
                "datamapping_spawn_areas": join_ids(sorted({to_int(spawn.get("worldzoneid")) for spawn in datamapping_spawns})),
                "datamapping_spawn_position_sample": join_sample(
                    (datamapping_position_summary(spawn) for spawn in sorted(datamapping_spawns, key=lambda item: to_int(item.get("source_coordinate_id")))),
                    limit=8,
                ),
                "runtime_datamapping_position_match_count": len(matched_runtime_entity_ids) or "",
                "runtime_matched_source_coordinate_ids": join_ids(sorted(matched_source_coordinate_ids)),
                "runtime_matched_entity_ids": join_ids(sorted(matched_runtime_entity_ids)),
                "datamapping_unpromoted_spawn_count": len(unpromoted_datamapping_spawns) or "",
                "datamapping_unpromoted_source_coordinate_ids": join_ids(sorted(unpromoted_source_coordinate_ids)),
                "datamapping_unpromoted_position_sample": join_sample(
                    (datamapping_position_summary(spawn) for spawn in sorted(unpromoted_datamapping_spawns, key=lambda item: to_int(item.get("source_coordinate_id")))),
                    limit=8,
                ),
                "jabbithole_quest_id": to_int(row.get("jabbithole_quest_id")),
                "jabbithole_quest_name": row.get("quest_name", ""),
                "quest_level": to_int(row.get("quest_level")),
                "quest_min_level": to_int(row.get("quest_min_level")),
                "quest_type": to_int(row.get("quest_type")),
                "path_quest_type": to_int(row.get("path_quest_type")),
                "last_seen_in": to_int(row.get("last_seen_in")),
                "evidence_status": evidence_status,
                "evidence_sources": evidence_sources,
                "manual_validation": "pending",
                "completion_status": "not_retail_complete",
                "blocker_summary": blocker_summary,
            }
        )

    return output


def objective_bridge_evidence_status(match_status: str, current_quest: bool, has_client_objective: bool) -> str:
    if not current_quest:
        return "datamapping_objective_not_current_client_quest_row_blocked"
    if match_status == "matched" and has_client_objective:
        return "datamapping_jabbithole_objective_matched_pending_text_order_smoke"
    if match_status == "unmatched":
        return "datamapping_jabbithole_objective_unmatched_blocked"
    return "datamapping_jabbithole_objective_pending_review"


def objective_bridge_evidence_sources(evidence_status: str) -> str:
    sources = [
        "Tools/DataMapping/output/quest_objective_map.csv",
        "Tools/DataMapping/map_wildstar_data.py",
        "jabbithole_mysql/quest_objectives.sql",
        "wildstar_client_mysql/Quest2.tbl.sql",
        "wildstar_client_mysql/QuestObjective.tbl.sql",
        "Source/NexusForever.Game/Quest",
    ]
    if evidence_status in {
        "datamapping_jabbithole_objective_unmatched_blocked",
        "datamapping_objective_not_current_client_quest_row_blocked",
    }:
        sources.append("Tools/DataMapping/README.md")
    return ";".join(sources)


def objective_bridge_blocker_summary(
    evidence_status: str,
    quest_id: int,
    jabbithole_objective_id: int,
    objective_order: int,
    jabbithole_objective_text: str,
    quest_objective_id: int = 0,
    client_objective_text: str = "",
    objective_type: int = 0,
    objective_data: int = 0,
    objective_count: int = 0,
) -> str:
    text_clause = f" with source text '{jabbithole_objective_text}'" if jabbithole_objective_text else ""
    client_text_clause = f" and client text '{client_objective_text}'" if client_objective_text else ""
    objective_detail_clause = ""
    if objective_type or objective_data or objective_count:
        objective_detail_clause = f" type {objective_type} data {objective_data} count {objective_count}"
    if evidence_status == "datamapping_jabbithole_objective_unmatched_blocked":
        return (
            f"Jabbithole objective {jabbithole_objective_id} for Quest2 {quest_id} objective order {objective_order}{text_clause}"
            " is blocked because Tools/DataMapping/output/quest_objective_map.csv has match_status unmatched and no current"
            " QuestObjective id. Retail implementation needs a current build Quest2 objective slot and QuestObjective row matching"
            " this Jabbithole objective, or a reviewed replacement bridge in DataMapping output/review plus runtime trigger,"
            " objective-credit, and client quest smoke."
        )
    if evidence_status == "datamapping_jabbithole_objective_matched_pending_text_order_smoke":
        return (
            f"Jabbithole objective {jabbithole_objective_id} for Quest2 {quest_id} objective order {objective_order}{text_clause}"
            f" maps to current QuestObjective {quest_objective_id}{objective_detail_clause}{client_text_clause}."
            " Retail completion needs text/order reconciliation against the current client row, runtime trigger behavior,"
            " objective-credit ownership, and client quest smoke."
        )
    if evidence_status == "datamapping_objective_not_current_client_quest_row_blocked":
        return (
            f"Jabbithole objective {jabbithole_objective_id} maps to Quest2 {quest_id}, but that quest id is not present in the"
            " current client Quest2 table. The row remains blocked until current build Quest2 evidence recovers this quest/objective"
            " ownership, or the source objective is rejected as stale DataMapping evidence after review."
        )
    return "Jabbithole objective evidence is tracked, but retail completion needs current-client objective mapping, text/order reconciliation, runtime trigger behavior, and quest smoke."


def build_quest_objective_evidence_rows(
    strings: dict[int, str],
    quests: list[dict[str, str]],
    quest_output: list[dict[str, object]],
    quest_objective_map_path: Path,
) -> list[dict[str, object]]:
    quest_by_id = {to_int(row["ID"]): row for row in quests}
    quest_status_by_id = {to_int(str(row["quest_id"])): row for row in quest_output}
    rows = load_csv_rows(quest_objective_map_path)

    output: list[dict[str, object]] = []
    for row in sorted(rows, key=lambda item: (to_int(item.get("quest2_id")), to_int(item.get("objective_order")), to_int(item.get("jabbithole_quest_objective_id")))):
        quest_id = to_int(row.get("quest2_id"))
        quest = quest_by_id.get(quest_id, {})
        quest_status = quest_status_by_id.get(quest_id, {})
        match_status = str(row.get("match_status", ""))
        objective_id = to_int(row.get("quest_objective_id"))
        current_quest = quest_id in quest_by_id
        has_client_objective = objective_id > 0 and match_status == "matched"
        jabbithole_objective_id = to_int(row.get("jabbithole_quest_objective_id"))
        evidence_status = objective_bridge_evidence_status(match_status, current_quest, has_client_objective)
        output_row = {
            "quest_id": quest_id,
            "quest_title": text_by_id(strings, to_int(quest.get("localizedTextIdTitle"))) or row.get("client_quest_name", "") or row.get("quest_name", ""),
            "quest_bucket": quest_status.get("bucket", "non_current_client_quest_reference" if not current_quest else "review_required"),
            "quest_completion_status": quest_status.get("completion_status", "not_retail_complete"),
            "quest_link_status": "current_quest" if current_quest else "non_current_client_quest_reference",
            "jabbithole_quest_objective_id": jabbithole_objective_id,
            "jabbithole_quest_id": to_int(row.get("jabbithole_quest_id")),
            "jabbithole_quest_name": row.get("quest_name", ""),
            "client_quest_name": row.get("client_quest_name", ""),
            "objective_order": to_int(row.get("objective_order")),
            "quest_objective_id": objective_id if objective_id else "",
            "match_status": match_status,
            "jabbithole_objective_text": row.get("jabbithole_objective_text", ""),
            "client_objective_text": row.get("client_objective_text", ""),
            "objective_type": to_int(row.get("objective_type")) if row.get("objective_type") else "",
            "objective_data": to_int(row.get("objective_data")) if row.get("objective_data") else "",
            "objective_count": to_int(row.get("objective_count")) if row.get("objective_count") else "",
            "quest_direction_id": to_int(row.get("quest_direction_id")) if row.get("quest_direction_id") else "",
            "world_location_0": to_int(row.get("world_location_0")) if row.get("world_location_0") else "",
            "world_location_1": to_int(row.get("world_location_1")) if row.get("world_location_1") else "",
            "world_location_2": to_int(row.get("world_location_2")) if row.get("world_location_2") else "",
            "world_location_3": to_int(row.get("world_location_3")) if row.get("world_location_3") else "",
            "last_seen_in": to_int(row.get("last_seen_in")) if row.get("last_seen_in") else "",
            "evidence_status": evidence_status,
            "evidence_sources": objective_bridge_evidence_sources(evidence_status),
            "manual_validation": "pending",
            "completion_status": "not_retail_complete",
            "blocker_summary": objective_bridge_blocker_summary(
                evidence_status,
                quest_id,
                jabbithole_objective_id,
                to_int(row.get("objective_order")),
                row.get("jabbithole_objective_text", ""),
                objective_id,
                row.get("client_objective_text", ""),
                to_int(row.get("objective_type")),
                to_int(row.get("objective_data")),
                to_int(row.get("objective_count")),
            ),
        }
        output_row.update(QUEST_OBJECTIVE_BRIDGE_OVERRIDES.get((quest_id, jabbithole_objective_id), {}))
        output.append(output_row)

    return output


def reward_bridge_evidence_status(reward_kind: str, current_quest: bool, client_object_id: int, game_reward_id: int) -> str:
    if not current_quest:
        return "datamapping_reward_not_current_client_quest_row_blocked"
    if reward_kind == "item" and client_object_id and game_reward_id:
        return "datamapping_jabbithole_item_reward_matched_pending_choice_smoke"
    if reward_kind == "currency" and client_object_id == 1 and not game_reward_id:
        return "datamapping_jabbithole_cash_reward_inline_pending_amount_smoke"
    if reward_kind == "currency" and client_object_id:
        return "datamapping_jabbithole_currency_reward_matched_pending_grant_smoke"
    if reward_kind == "reputation" and client_object_id:
        return "datamapping_jabbithole_reputation_reward_matched_pending_amount_smoke"
    if reward_kind == "tradeskill" and client_object_id and game_reward_id:
        return "datamapping_jabbithole_tradeskill_reward_matched_pending_grant_smoke"
    return f"datamapping_jabbithole_{reward_kind}_reward_pending_review"


def reward_bridge_evidence_sources(file_name: str, reward_kind: str, evidence_status: str) -> str:
    reward_object_sources = {
        "item": "wildstar_client_mysql/Item2.tbl.sql",
        "currency": "wildstar_client_mysql/CurrencyType.tbl.sql",
        "reputation": "wildstar_client_mysql/Faction2.tbl.sql",
        "tradeskill": "wildstar_client_mysql/Tradeskill.tbl.sql",
    }
    sources = [
        f"Tools/DataMapping/output/{file_name}",
        "Tools/DataMapping/map_wildstar_data.py",
        "wildstar_client_mysql/Quest2.tbl.sql",
        "wildstar_client_mysql/Quest2Reward.tbl.sql",
    ]
    reward_object_source = reward_object_sources.get(reward_kind)
    if reward_object_source:
        sources.append(reward_object_source)
    sources.append("Source/NexusForever.Game/Quest")
    if evidence_status == "datamapping_reward_not_current_client_quest_row_blocked":
        sources.append("Tools/DataMapping/README.md")
    return ";".join(sources)


def reward_bridge_blocker_summary(
    evidence_status: str,
    reward_kind: str,
    source_map: str,
    source_reward_id: int,
    quest_id: int,
    jabbithole_object_id: int,
    client_object_id: int,
    jabbithole_name: str,
    client_name: str,
    game_reward_id: int,
    amount: int,
    fixed_reward: str,
) -> str:
    client_labels = {
        "item": "Item2",
        "currency": "CurrencyType",
        "reputation": "Faction2",
        "tradeskill": "Tradeskill",
    }
    client_label = client_labels.get(reward_kind, "client reward object")
    source_clause = f"{source_map} source_reward_id {source_reward_id} maps Quest2 {quest_id} {reward_kind} reward"
    jabbithole_clause = f" from Jabbithole {reward_kind} {jabbithole_object_id}" if jabbithole_object_id else ""
    if jabbithole_clause and jabbithole_name:
        jabbithole_clause += f" ({jabbithole_name})"
    client_clause = f" to {client_label} {client_object_id}" if client_object_id else ""
    if client_clause and client_name:
        client_clause += f" ({client_name})"
    reward_clause = f" via Quest2Reward {game_reward_id}" if game_reward_id else ""
    amount_clause = f" amount {amount}" if amount else ""
    fixed_clause = f" fixed_reward={fixed_reward}" if fixed_reward else ""

    if evidence_status == "datamapping_reward_not_current_client_quest_row_blocked":
        return (
            f"{source_clause}{jabbithole_clause}{client_clause}, but Quest2 {quest_id} is not present in the current"
            " client Quest2 table. The reward row remains blocked until current build Quest2 reward ownership is recovered,"
            " or the source reward is rejected as stale DataMapping evidence after review."
        )
    if evidence_status == "datamapping_jabbithole_cash_reward_inline_pending_amount_smoke":
        return (
            f"{source_clause}{jabbithole_clause}{client_clause}{amount_clause}{fixed_clause} as an inline credits reward."
            " Retail completion needs cash amount/formula reconciliation, runtime credit grant and persistence,"
            " reward UI presentation, and client quest smoke."
        )
    if evidence_status.startswith("datamapping_jabbithole_") and "_reward_matched_" in evidence_status:
        return (
            f"{source_clause}{jabbithole_clause}{client_clause}{reward_clause}{amount_clause}{fixed_clause}."
            " Retail completion needs fixed/choice semantics, runtime grant and persistence, reward UI presentation,"
            " and client quest smoke."
        )
    return (
        f"{source_clause}{jabbithole_clause}{client_clause}{reward_clause}{amount_clause}{fixed_clause}, but retail completion"
        " needs client reward mapping, fixed/choice semantics, grant behavior, UI presentation, and quest smoke."
    )


def build_canonical_item_reward_index(reward_rows: list[dict[str, str]]) -> dict[tuple[int, int, int, int], tuple[int, ...]]:
    index: dict[tuple[int, int, int, int], set[int]] = defaultdict(set)
    for reward in reward_rows:
        if to_int(reward.get("quest2RewardTypeId")) != QUEST2_REWARD_TYPE_ITEM:
            continue

        quest_id = to_int(reward.get("quest2Id"))
        item_id = to_int(reward.get("objectId"))
        amount = to_int(reward.get("objectAmount"))
        flags = to_int(reward.get("flags"))
        reward_id = to_int(reward.get("ID"))
        if quest_id and item_id and amount and reward_id:
            index[(quest_id, item_id, amount, flags)].add(reward_id)

    return {key: tuple(sorted(value)) for key, value in index.items()}


def build_canonical_item_reward_by_id(reward_rows: list[dict[str, str]]) -> dict[tuple[int, int], dict[str, int]]:
    index: dict[tuple[int, int], dict[str, int]] = {}
    for reward in reward_rows:
        if to_int(reward.get("quest2RewardTypeId")) != QUEST2_REWARD_TYPE_ITEM:
            continue

        quest_id = to_int(reward.get("quest2Id"))
        reward_id = to_int(reward.get("ID"))
        if not quest_id or not reward_id:
            continue

        index[(quest_id, reward_id)] = {
            "item_id": to_int(reward.get("objectId")),
            "amount": to_int(reward.get("objectAmount")),
            "flags": to_int(reward.get("flags")),
        }

    return index


def item_reward_flags_from_fixed_reward(fixed_reward: str | None) -> int | None:
    normalized = str(fixed_reward or "").strip().lower()
    if normalized == "true":
        return 0
    if normalized == "false":
        return 1
    return None


def append_evidence_sources(existing_sources: str, additional_sources: Iterable[str]) -> str:
    sources = [source for source in existing_sources.split(";") if source]
    seen = set(sources)
    for source in additional_sources:
        if source and source not in seen:
            sources.append(source)
            seen.add(source)
    return ";".join(sources)


def apply_item_reward_id_reconciliation(
    output_row: dict[str, object],
    quest_id: int,
    client_object_id: int,
    amount: int,
    fixed_reward: str,
    game_reward_id: int,
    canonical_item_reward_ids: dict[tuple[int, int, int, int], tuple[int, ...]],
    canonical_item_reward_by_id: dict[tuple[int, int], dict[str, int]],
) -> None:
    if not quest_id or not client_object_id or not amount or not game_reward_id:
        return

    fixed_reward_flags = item_reward_flags_from_fixed_reward(fixed_reward)
    if fixed_reward_flags is None:
        return

    canonical_reward_ids = canonical_item_reward_ids.get((quest_id, client_object_id, amount, fixed_reward_flags), ())
    output_row["canonical_reward_ids"] = join_ids(canonical_reward_ids)
    if not canonical_reward_ids:
        output_row["canonical_reward_match_status"] = "canonical_tuple_unmatched"
        return
    if game_reward_id in canonical_reward_ids:
        output_row["canonical_reward_match_status"] = "canonical_reward_id_matched"
        return

    colliding_reward = canonical_item_reward_by_id.get((quest_id, game_reward_id))
    output_row["canonical_reward_match_status"] = "canonical_reward_id_mismatch"
    output_row["evidence_sources"] = append_evidence_sources(
        str(output_row["evidence_sources"]),
        (
            "Tools/DataMapping/output/quest_reward_client_map.csv",
            "wildstar_client_mysql/Quest2Reward.tbl.sql",
        ),
    )
    if colliding_reward:
        output_row["evidence_status"] = "datamapping_jabbithole_item_reward_game_reward_id_mismatch_pending_review"
        output_row["blocker_summary"] = (
            f"DataMapping/Jabbithole source_reward_id {output_row['source_reward_id']} maps Q{quest_id} Item2 {client_object_id} "
            f"amount {amount} fixed_reward={fixed_reward} to game_reward_id {game_reward_id}, but canonical build 16042 "
            f"Quest2Reward row {join_ids(canonical_reward_ids)} has the same quest/item/amount/flags {fixed_reward_flags}. "
            f"The source game_reward_id collides with current Quest2Reward row {game_reward_id} for Item2 {colliding_reward['item_id']} "
            f"amount {colliding_reward['amount']} flags {colliding_reward['flags']}. Do not use the Jabbithole game_reward_id "
            "as canonical reward-id proof until the source mismatch is reconciled. Retail completion still needs source provenance, "
            "client reward-choice UI smoke, runtime grant/persistence validation, and end-to-end quest smoke."
        )
        return

    output_row["canonical_reward_match_status"] = "canonical_reward_id_source_stale_tuple_matched"
    output_row["evidence_status"] = "datamapping_jabbithole_item_reward_stale_source_game_reward_id_canonical_tuple_matched_pending_choice_smoke"
    output_row["blocker_summary"] = (
        f"DataMapping/Jabbithole source_reward_id {output_row['source_reward_id']} maps Q{quest_id} Item2 {client_object_id} "
        f"amount {amount} fixed_reward={fixed_reward} to stale source game_reward_id {game_reward_id}; that reward id is not a "
        f"current build 16042 Quest2Reward row for Q{quest_id}. Canonical Quest2Reward row {join_ids(canonical_reward_ids)} "
        f"has the same quest/item/amount/flags {fixed_reward_flags}, so this is tracked as a source-provenance alias only, "
        "not canonical reward-id proof. Retail completion still needs client reward-choice UI smoke, runtime grant/persistence "
        "validation, and end-to-end quest smoke."
    )


def build_quest_reward_evidence_rows(
    strings: dict[int, str],
    quests: list[dict[str, str]],
    reward_rows: list[dict[str, str]],
    quest_output: list[dict[str, object]],
    data_mapping_output: Path,
) -> list[dict[str, object]]:
    quest_by_id = {to_int(row["ID"]): row for row in quests}
    quest_status_by_id = {to_int(str(row["quest_id"])): row for row in quest_output}
    canonical_item_reward_ids = build_canonical_item_reward_index(reward_rows)
    canonical_item_reward_by_id = build_canonical_item_reward_by_id(reward_rows)
    source_maps = (
        {
            "reward_kind": "item",
            "file_name": "quest_reward_item_map.csv",
            "jabbithole_object_column": "jabbithole_item_id",
            "client_object_column": "item2_id",
            "jabbithole_name_column": "item_name",
            "client_name_column": "item_name",
        },
        {
            "reward_kind": "currency",
            "file_name": "quest_reward_currency_map.csv",
            "jabbithole_object_column": "jabbithole_currency_id",
            "client_object_column": "currency_type_id",
            "jabbithole_name_column": "currency_name",
            "client_name_column": "client_currency_name",
        },
        {
            "reward_kind": "reputation",
            "file_name": "quest_reward_reputation_map.csv",
            "jabbithole_object_column": "jabbithole_reputation_reward_id",
            "client_object_column": "faction2_id",
            "jabbithole_name_column": "reputation_name",
            "client_name_column": "client_faction_name",
        },
        {
            "reward_kind": "tradeskill",
            "file_name": "quest_reward_tradeskill_map.csv",
            "jabbithole_object_column": "jabbithole_tradeskill_reward_id",
            "client_object_column": "tradeskill_id",
            "jabbithole_name_column": "tradeskill_name",
            "client_name_column": "client_tradeskill_name",
        },
    )

    output: list[dict[str, object]] = []
    for source in source_maps:
        reward_kind = str(source["reward_kind"])
        file_name = str(source["file_name"])
        rows = load_csv_rows(data_mapping_output / file_name)
        for row in rows:
            quest_id = to_int(row.get("quest2_id"))
            quest = quest_by_id.get(quest_id, {})
            quest_status = quest_status_by_id.get(quest_id, {})
            current_quest = quest_id in quest_by_id
            client_object_id = to_int(row.get(str(source["client_object_column"])))
            game_reward_id = to_int(row.get("game_reward_id"))
            source_reward_id = to_int(row.get("source_reward_id"))
            amount = to_int(row.get("amount"))
            evidence_status = reward_bridge_evidence_status(reward_kind, current_quest, client_object_id, game_reward_id)
            output_row = {
                "quest_id": quest_id,
                "quest_title": text_by_id(strings, to_int(quest.get("localizedTextIdTitle"))) or row.get("client_quest_name", "") or row.get("quest_name", ""),
                "quest_bucket": quest_status.get("bucket", "non_current_client_quest_reference" if not current_quest else "review_required"),
                "quest_completion_status": quest_status.get("completion_status", "not_retail_complete"),
                "quest_link_status": "current_quest" if current_quest else "non_current_client_quest_reference",
                "reward_kind": reward_kind,
                "source_map": file_name,
                "source_reward_id": source_reward_id,
                "jabbithole_quest_id": to_int(row.get("jabbithole_quest_id")),
                "jabbithole_quest_name": row.get("quest_name", ""),
                "client_quest_name": row.get("client_quest_name", ""),
                "jabbithole_reward_object_id": to_int(row.get(str(source["jabbithole_object_column"]))),
                "client_reward_object_id": client_object_id if client_object_id else "",
                "jabbithole_reward_name": row.get(str(source["jabbithole_name_column"]), ""),
                "client_reward_name": row.get(str(source["client_name_column"]), ""),
                "game_reward_id": game_reward_id if game_reward_id else "",
                "canonical_reward_ids": "",
                "canonical_reward_match_status": "",
                "amount": amount,
                "fixed_reward": row.get("fixed_reward", ""),
                "last_seen_in": to_int(row.get("last_seen_in")) if row.get("last_seen_in") else "",
                "evidence_status": evidence_status,
                "evidence_sources": reward_bridge_evidence_sources(file_name, reward_kind, evidence_status),
                "manual_validation": "pending",
                "completion_status": "not_retail_complete",
                "blocker_summary": reward_bridge_blocker_summary(
                    evidence_status,
                    reward_kind,
                    file_name,
                    source_reward_id,
                    quest_id,
                    to_int(row.get(str(source["jabbithole_object_column"]))),
                    client_object_id,
                    row.get(str(source["jabbithole_name_column"]), ""),
                    row.get(str(source["client_name_column"]), ""),
                    game_reward_id,
                    amount,
                    row.get("fixed_reward", ""),
                ),
            }
            if reward_kind == "item" and current_quest:
                apply_item_reward_id_reconciliation(
                    output_row,
                    quest_id,
                    client_object_id,
                    amount,
                    str(row.get("fixed_reward", "")),
                    game_reward_id,
                    canonical_item_reward_ids,
                    canonical_item_reward_by_id,
                )
            output_row.update(QUEST_REWARD_EVIDENCE_OVERRIDES.get((quest_id, reward_kind, file_name, source_reward_id), {}))
            output.append(output_row)

    return sorted(output, key=lambda item: (to_int(str(item["quest_id"])), str(item["reward_kind"]), to_int(str(item["source_reward_id"]))))


def quest_zone_evidence_status(match_status: str, current_quest: bool) -> str:
    if not current_quest:
        return "datamapping_zone_not_current_client_quest_row_blocked"
    if match_status == "matched":
        return "datamapping_quest_zone_matched_pending_runtime_visibility_smoke"
    if match_status == "partial":
        return "datamapping_quest_zone_partial_match_pending_zone_review"
    if match_status == "unmatched":
        return "datamapping_quest_zone_unmatched_blocked"
    return "datamapping_quest_zone_pending_review"


def quest_zone_evidence_sources(evidence_status: str) -> str:
    sources = [
        "Tools/DataMapping/output/quest_zone_map.csv",
        "Tools/DataMapping/map_wildstar_data.py",
        "jabbithole_mysql/quest_zones.sql",
        "jabbithole_mysql/quest_call_zones.sql",
        "wildstar_client_mysql/Quest2.tbl.sql",
        "wildstar_client_mysql/WorldZone.tbl.sql",
        "Source/NexusForever.Game/Quest",
    ]
    if evidence_status in {
        "datamapping_quest_zone_partial_match_pending_zone_review",
        "datamapping_quest_zone_unmatched_blocked",
        "datamapping_zone_not_current_client_quest_row_blocked",
    }:
        sources.append("Tools/DataMapping/README.md")
    return ";".join(sources)


def quest_zone_blocker_summary(
    evidence_status: str,
    source_relation_id: int,
    relation_source: str,
    quest_id: int,
    jabbithole_zone_id: int,
    jabbithole_zone_name: str,
    world_zone_id: int | str,
    client_world_zone_name: str,
    match_status: str,
) -> str:
    zone_clause = f"Jabbithole zone {jabbithole_zone_id}"
    if jabbithole_zone_name:
        zone_clause += f" ({jabbithole_zone_name})"
    client_clause = f" to WorldZone {world_zone_id}"
    if client_world_zone_name:
        client_clause += f" ({client_world_zone_name})"

    if evidence_status == "datamapping_quest_zone_partial_match_pending_zone_review":
        if client_world_zone_name:
            review_detail = (
                " Tools/DataMapping/output/quest_zone_map.csv found a current WorldZone row/name for the source game id,"
                " but still marks the bridge partial; review needs table or live-client evidence that this is the correct"
                " current build 16042 zone for the quest relation."
            )
        else:
            review_detail = (
                f" Tools/DataMapping/output/quest_zone_map.csv has no current build 16042 WorldZone row/name for"
                f" mapped WorldZone {world_zone_id}; treat the source id as stale or missing until WorldZone.tbl,"
                " MapZone/QuestDirection evidence, or accepted live client route evidence identifies the current replacement."
            )
        return (
            f"{relation_source} row {source_relation_id} links Quest2 {quest_id} {zone_clause}{client_clause},"
            f" but Tools/DataMapping/output/quest_zone_map.csv marks match_status {match_status}.{review_detail}"
            " Retail implementation needs"
            " a reviewed current WorldZone bridge that reconciles the Jabbithole zone/name with build 16042 WorldZone data,"
            " followed by quest visibility/routing, map guidance, episode/zone ordering, and client quest smoke."
        )
    if evidence_status == "datamapping_quest_zone_matched_pending_runtime_visibility_smoke":
        return (
            f"{relation_source} row {source_relation_id} links Quest2 {quest_id} {zone_clause}{client_clause}"
            f" with match_status {match_status}. The zone bridge is mapped, but retail completion needs runtime quest"
            " visibility/routing using this current WorldZone bridge, map guidance, episode/zone ordering, and client quest smoke."
        )
    if evidence_status == "datamapping_quest_zone_unmatched_blocked":
        return (
            f"{relation_source} row {source_relation_id} links Quest2 {quest_id} to {zone_clause}, but"
            " Tools/DataMapping/output/quest_zone_map.csv has match_status unmatched and no current WorldZone id."
            " Retail implementation needs a current WorldZone bridge or reviewed replacement zone evidence before runtime"
            " visibility/routing can be claimed."
        )
    if evidence_status == "datamapping_zone_not_current_client_quest_row_blocked":
        return (
            f"{relation_source} row {source_relation_id} references Quest2 {quest_id}, but that quest id is not present in"
            " the current client Quest2 table. The row remains blocked until current build Quest2 evidence recovers the"
            " quest/zone relationship, or the source relation is rejected as stale DataMapping evidence after review."
        )
    return "Jabbithole quest zone evidence is tracked, but retail completion needs zone bridge review, quest visibility/routing behavior, map guidance, and quest smoke."


def build_quest_zone_evidence_rows(
    strings: dict[int, str],
    quests: list[dict[str, str]],
    quest_output: list[dict[str, object]],
    quest_zone_map_path: Path,
) -> list[dict[str, object]]:
    quest_by_id = {to_int(row["ID"]): row for row in quests}
    quest_status_by_id = {to_int(str(row["quest_id"])): row for row in quest_output}
    rows = load_csv_rows(quest_zone_map_path)

    output: list[dict[str, object]] = []
    for row in sorted(rows, key=lambda item: (to_int(item.get("quest2_id")), str(item.get("relation_source", "")), to_int(item.get("source_relation_id")))):
        quest_id = to_int(row.get("quest2_id"))
        quest = quest_by_id.get(quest_id, {})
        quest_status = quest_status_by_id.get(quest_id, {})
        current_quest = quest_id in quest_by_id
        match_status = str(row.get("match_status", ""))
        evidence_status = quest_zone_evidence_status(match_status, current_quest)
        relation_source = row.get("relation_source", "")
        source_relation_id = to_int(row.get("source_relation_id"))
        output_row = {
            "quest_id": quest_id,
            "quest_title": text_by_id(strings, to_int(quest.get("localizedTextIdTitle"))) or row.get("client_quest_name", "") or row.get("jabbithole_quest_name", ""),
            "quest_bucket": quest_status.get("bucket", "non_current_client_quest_reference" if not current_quest else "review_required"),
            "quest_completion_status": quest_status.get("completion_status", "not_retail_complete"),
            "quest_link_status": "current_quest" if current_quest else "non_current_client_quest_reference",
            "relation_source": relation_source,
            "source_relation_id": source_relation_id,
            "jabbithole_quest_id": to_int(row.get("jabbithole_quest_id")),
            "jabbithole_quest_name": row.get("jabbithole_quest_name", ""),
            "client_quest_name": row.get("client_quest_name", ""),
            "jabbithole_zone_id": to_int(row.get("jabbithole_zone_id")),
            "world_zone_id": to_int(row.get("world_zone_id")) if row.get("world_zone_id") else "",
            "jabbithole_zone_name": row.get("jabbithole_zone_name", ""),
            "client_world_zone_name": row.get("client_world_zone_name", ""),
            "match_status": match_status,
            "enabled": row.get("enabled", ""),
            "last_seen_in": to_int(row.get("last_seen_in")) if row.get("last_seen_in") else "",
            "evidence_status": evidence_status,
            "evidence_sources": quest_zone_evidence_sources(evidence_status),
            "manual_validation": "pending",
            "completion_status": "not_retail_complete",
            "blocker_summary": quest_zone_blocker_summary(
                evidence_status,
                source_relation_id,
                relation_source,
                quest_id,
                to_int(row.get("jabbithole_zone_id")),
                row.get("jabbithole_zone_name", ""),
                to_int(row.get("world_zone_id")) if row.get("world_zone_id") else "",
                row.get("client_world_zone_name", ""),
                match_status,
            ),
        }
        output_row.update(
            QUEST_ZONE_EVIDENCE_OVERRIDES.get(
                (quest_id, relation_source, source_relation_id),
                {},
            )
        )
        output.append(output_row)

    return output


def quest_episode_evidence_status(current_quest: bool, episode_id: int, episode_match_status: str) -> str:
    if not current_quest:
        return "datamapping_episode_not_current_client_quest_row_blocked"
    if not episode_id:
        return "datamapping_episode_missing_client_episode_blocked"
    if episode_match_status == "matched":
        return "datamapping_episode_quest_matched_pending_order_progression_smoke"
    if episode_match_status == "missing_episode_bridge":
        return "datamapping_episode_quest_missing_episode_bridge_blocked"
    if episode_match_status == "unmatched":
        return "datamapping_episode_unmatched_blocked"
    return "datamapping_episode_quest_pending_review"


def quest_episode_evidence_sources(evidence_status: str) -> str:
    sources = [
        "Tools/DataMapping/output/episode_quest_client_map.csv",
        "Tools/DataMapping/output/quest_episode_map.csv",
        "Tools/DataMapping/map_wildstar_data.py",
        "jabbithole_mysql/quest_episodes.sql",
        "wildstar_client_mysql/Episode.tbl.sql",
        "wildstar_client_mysql/EpisodeQuest.tbl.sql",
        "wildstar_client_mysql/Quest2.tbl.sql",
        "Source/NexusForever.Game/Quest",
    ]
    if evidence_status in {
        "datamapping_episode_quest_missing_episode_bridge_blocked",
        "datamapping_episode_not_current_client_quest_row_blocked",
        "datamapping_episode_missing_client_episode_blocked",
        "datamapping_episode_unmatched_blocked",
    }:
        sources.append("Tools/DataMapping/README.md")
    return ";".join(sources)


def quest_episode_blocker_summary(
    evidence_status: str,
    episode_quest_id: int,
    episode_id: int,
    episode_name: str,
    quest_id: int,
    order_index: int,
    flags: int | str = "",
    jabbithole_episode_id: int | str = "",
    jabbithole_episode_name: str = "",
    client_episode_name: str = "",
    client_world_zone_id: int | str = "",
    client_world_zone_name: str = "",
    slug: str = "",
    episode_quests_count: int | str = "",
    enabled: str = "",
    last_seen_in: int | str = "",
) -> str:
    episode_clause = f" Episode {episode_id}" if episode_id else " a missing Episode id"
    name_clause = f" ({episode_name})" if episode_name else ""
    flag_clause = f" flags {flags}" if flags != "" else ""
    if evidence_status == "datamapping_episode_quest_missing_episode_bridge_blocked":
        return (
            f"EpisodeQuest row {episode_quest_id} links Quest2 {quest_id} order {order_index}{flag_clause} to{episode_clause}{name_clause},"
            " but Tools/DataMapping/output/quest_episode_map.csv has no bridge from that current Episode id to a Jabbithole"
            " quest episode. Retail implementation needs a current Episode/EpisodeQuest bridge reconciled with"
            " jabbithole_mysql/quest_episodes.sql or a reviewed replacement episode bridge, followed by quest order,"
            " episode visibility/progression, UI, and quest-chain smoke."
        )
    if evidence_status == "datamapping_episode_quest_matched_pending_order_progression_smoke":
        source_clause = f"Jabbithole episode {jabbithole_episode_id}" if jabbithole_episode_id != "" else "Jabbithole episode"
        if jabbithole_episode_name:
            source_clause += f" ({jabbithole_episode_name})"
        client_clause = f"Episode {episode_id}"
        if client_episode_name or episode_name:
            client_clause += f" ({client_episode_name or episode_name})"
        if client_world_zone_id != "":
            client_clause += f" in WorldZone {client_world_zone_id}"
            if client_world_zone_name:
                client_clause += f" ({client_world_zone_name})"
        details = []
        if slug:
            details.append(f"slug {slug}")
        if episode_quests_count != "":
            details.append(f"episode quest count {episode_quests_count}")
        if enabled != "":
            details.append(f"enabled {enabled}")
        if last_seen_in != "":
            details.append(f"last_seen_in {last_seen_in}")
        detail_clause = f"; {', '.join(details)}" if details else ""
        return (
            f"EpisodeQuest row {episode_quest_id} links Quest2 {quest_id} order {order_index}{flag_clause} to"
            f" {client_clause}; Tools/DataMapping/output/quest_episode_map.csv maps match_status matched to"
            f" {source_clause}{detail_clause}. The episode bridge is mapped, but retail completion needs runtime episode"
            " ordering/progression semantics, quest visibility and turn-in state, UI presentation, and quest-chain smoke for this row."
        )
    if evidence_status == "datamapping_episode_not_current_client_quest_row_blocked":
        return (
            f"EpisodeQuest row {episode_quest_id} references Quest2 {quest_id}, but that quest id is not present in the current"
            " client Quest2 table. The row remains blocked until current build Quest2 evidence recovers the quest, or the"
            " episode relation is rejected as stale DataMapping evidence after review."
        )
    if evidence_status == "datamapping_episode_missing_client_episode_blocked":
        return (
            f"EpisodeQuest row {episode_quest_id} for Quest2 {quest_id} has no current Episode id. Retail implementation needs"
            " a current Episode/EpisodeQuest source row or a reviewed replacement episode bridge before runtime visibility can be claimed."
        )
    if evidence_status == "datamapping_episode_unmatched_blocked":
        return (
            f"EpisodeQuest row {episode_quest_id} links Quest2 {quest_id} to{episode_clause}{name_clause}, but the episode bridge"
            " is unmatched. Retail implementation needs a reviewed current-client Episode to Jabbithole episode bridge plus"
            " quest order/progression and client episode UI smoke."
        )
    return "Quest episode evidence is tracked, but retail completion needs episode bridge review, quest ordering/progression semantics, UI presentation, and quest-chain smoke."


def build_quest_episode_evidence_rows(
    strings: dict[int, str],
    quests: list[dict[str, str]],
    quest_output: list[dict[str, object]],
    data_mapping_output: Path,
) -> list[dict[str, object]]:
    quest_by_id = {to_int(row["ID"]): row for row in quests}
    quest_status_by_id = {to_int(str(row["quest_id"])): row for row in quest_output}
    episode_rows = load_csv_rows(data_mapping_output / "quest_episode_map.csv")
    episode_by_id = {to_int(row.get("episode_id")): row for row in episode_rows if to_int(row.get("episode_id"))}
    rows = load_csv_rows(data_mapping_output / "episode_quest_client_map.csv")

    output: list[dict[str, object]] = []
    for row in sorted(rows, key=lambda item: (to_int(item.get("episode_id")), to_int(item.get("order_index")), to_int(item.get("episode_quest_id")))):
        quest_id = to_int(row.get("quest2_id"))
        episode_id = to_int(row.get("episode_id"))
        quest = quest_by_id.get(quest_id, {})
        quest_status = quest_status_by_id.get(quest_id, {})
        episode = episode_by_id.get(episode_id, {})
        current_quest = quest_id in quest_by_id
        episode_match_status = str(episode.get("match_status", "missing_episode_bridge"))
        evidence_status = quest_episode_evidence_status(current_quest, episode_id, episode_match_status)
        episode_quest_id = to_int(row.get("episode_quest_id"))
        output_row = {
            "quest_id": quest_id if quest_id else "",
            "quest_title": text_by_id(strings, to_int(quest.get("localizedTextIdTitle"))) or row.get("quest_name", ""),
            "quest_bucket": quest_status.get("bucket", "non_current_client_quest_reference" if not current_quest else "review_required"),
            "quest_completion_status": quest_status.get("completion_status", "not_retail_complete"),
            "quest_link_status": "current_quest" if current_quest else "non_current_client_quest_reference",
            "episode_quest_id": episode_quest_id,
            "episode_id": episode_id if episode_id else "",
            "episode_name": row.get("episode_name", ""),
            "order_index": to_int(row.get("order_index")),
            "flags": to_int(row.get("flags")),
            "episode_bridge_status": "mapped_episode" if episode else "missing_episode_bridge",
            "episode_match_status": episode_match_status,
            "jabbithole_episode_id": to_int(episode.get("jabbithole_episode_id")) if episode else "",
            "jabbithole_episode_name": episode.get("jabbithole_episode_name", ""),
            "client_episode_name": episode.get("client_episode_name", ""),
            "client_world_zone_id": to_int(episode.get("client_world_zone_id")) if episode.get("client_world_zone_id") else "",
            "client_world_zone_name": episode.get("client_world_zone_name", ""),
            "slug": episode.get("slug", ""),
            "episode_quests_count": to_int(episode.get("quests_count")) if episode.get("quests_count") else "",
            "enabled": episode.get("enabled", ""),
            "last_seen_in": to_int(episode.get("last_seen_in")) if episode.get("last_seen_in") else "",
            "evidence_status": evidence_status,
            "evidence_sources": quest_episode_evidence_sources(evidence_status),
            "manual_validation": "pending",
            "completion_status": "not_retail_complete",
            "blocker_summary": quest_episode_blocker_summary(
                evidence_status,
                episode_quest_id,
                episode_id,
                row.get("episode_name", ""),
                quest_id,
                to_int(row.get("order_index")),
                to_int(row.get("flags")),
                to_int(episode.get("jabbithole_episode_id")) if episode else "",
                episode.get("jabbithole_episode_name", ""),
                episode.get("client_episode_name", ""),
                to_int(episode.get("client_world_zone_id")) if episode.get("client_world_zone_id") else "",
                episode.get("client_world_zone_name", ""),
                episode.get("slug", ""),
                to_int(episode.get("quests_count")) if episode.get("quests_count") else "",
                episode.get("enabled", ""),
                to_int(episode.get("last_seen_in")) if episode.get("last_seen_in") else "",
            ),
        }
        output_row.update(
            QUEST_EPISODE_EVIDENCE_OVERRIDES.get(
                (quest_id, episode_quest_id, episode_id),
                {},
            )
        )
        output.append(output_row)

    return output


def public_event_link_status(event_id: int, public_event_by_id: dict[int, dict[str, str]]) -> str:
    if not event_id:
        return "missing_public_event_id"
    return "current_public_event" if event_id in public_event_by_id else "non_current_public_event_reference"


def public_event_evidence_status(
    evidence_kind: str,
    event_current: bool,
    match_status: str,
    related_client_id: int,
    parent_link_status: str = "",
    child_link_status: str = "",
    objective_type: int = 0,
    objective_object_id: int = 0,
    world_location_id: int = 0,
    objective_object_is_target_group: bool = False,
) -> str:
    if not event_current:
        return "datamapping_public_event_not_current_client_event_row_blocked"
    if parent_link_status == "non_current_public_event_reference":
        return "datamapping_public_event_parent_not_current_blocked"
    if child_link_status == "non_current_public_event_reference":
        return "datamapping_public_event_child_not_current_blocked"

    if evidence_kind == "public_event_objective":
        if match_status == "matched" and related_client_id:
            if objective_type == PUBLIC_EVENT_KILL_TARGET_GROUP_OBJECTIVE_TYPE and objective_object_id:
                return "runtime_public_event_kill_target_group_credit_tested_pending_spawn_event_smoke"
            if (
                objective_type in PUBLIC_EVENT_KILL_EVENT_UNIT_OBJECTIVE_TYPES
                and (objective_object_id == 0 or objective_object_is_target_group)
            ):
                return "runtime_public_event_event_owned_unit_kill_credit_tested_pending_event_spawn_smoke"
            if (
                objective_type == PUBLIC_EVENT_PARTICIPANTS_IN_TRIGGER_VOLUME_OBJECTIVE_TYPE
                and objective_object_id
                and world_location_id
            ):
                return "runtime_public_event_participants_trigger_volume_world_location_credit_tested_pending_trigger_placement_smoke"
            if objective_type == PUBLIC_EVENT_KILL_CLUSTER_TARGET_GROUP_OBJECTIVE_TYPE and objective_object_id:
                return "runtime_public_event_kill_cluster_target_group_credit_tested_pending_spawn_event_smoke"
            if objective_type == PUBLIC_EVENT_TURNSTILE_OBJECTIVE_TYPE and objective_object_id and world_location_id:
                return "runtime_public_event_turnstile_world_location_entry_credit_tested_pending_trigger_placement_smoke"
            if objective_type == PUBLIC_EVENT_EXTERMINATE_OBJECTIVE_TYPE and objective_object_id:
                return "runtime_public_event_exterminate_target_group_kill_credit_tested_pending_spawn_event_smoke"
            if objective_type == PUBLIC_EVENT_VIRTUAL_COLLECT_OBJECTIVE_TYPE and objective_object_id:
                return "runtime_public_event_virtual_collect_loot_delivery_credit_tested_pending_source_smoke"
            return "mapped_public_event_objective_blocked_missing_runtime_producer_evidence"
        if match_status == "event_mismatch":
            return "datamapping_public_event_objective_event_mismatch_blocked"
        if match_status.startswith("unmatched"):
            return "datamapping_public_event_objective_unmatched_blocked"
        return "datamapping_public_event_objective_pending_review"

    if evidence_kind == "public_event_mission":
        if child_link_status == "current_public_event":
            return "runtime_public_event_mission_child_event_template_routing_tested_pending_transition_ui_and_client_smoke"
        return "mapped_public_event_mission_text_blocked_missing_child_event_transition_evidence"

    if evidence_kind == "public_event_zone":
        if related_client_id:
            return "mapped_public_event_zone_blocked_missing_runtime_visibility_bridge_evidence"
        return "datamapping_public_event_zone_missing_client_zone_blocked"

    if evidence_kind == "public_event_creature":
        if match_status == "unmatched":
            return "blocked_public_event_creature_unmatched_missing_client_creature_bridge"
        if match_status == "ambiguous_name":
            return "blocked_public_event_creature_ambiguous_requires_bridge_review"
        if match_status == "reviewed":
            return "reviewed_public_event_creature_blocked_spawn_credit_smoke"
        if match_status in {"unique_name", "scored_name"}:
            return "mapped_public_event_creature_blocked_missing_reviewed_bridge_spawn_credit_smoke"
        return "datamapping_public_event_creature_pending_review"

    return "datamapping_public_event_pending_review"


def public_event_objective_blocked_summary(
    related_client_id: int,
    objective_type: int,
    objective_object_id: int,
    objective_count: int,
    world_location_id: int,
    quest_direction_id: int,
    target_group_id: int,
    client_objective_text: str,
    objective_object_is_target_group: bool,
) -> str:
    objective_type_name = PUBLIC_EVENT_OBJECTIVE_TYPE_NAMES.get(objective_type, f"type {objective_type}")
    detail_parts = [
        f"type {objective_type_name} ({objective_type})",
        f"ObjectId {objective_object_id}",
        f"Count {objective_count}",
    ]
    if world_location_id:
        detail_parts.append(f"WorldLocation2 {world_location_id}")
    if quest_direction_id:
        detail_parts.append(f"QuestDirection {quest_direction_id}")
    if target_group_id:
        detail_parts.append(f"TargetGroupRewardPane {target_group_id}")
    if client_objective_text:
        detail_parts.append(f"text '{client_objective_text}'")

    if objective_type in {3, 4, 17, 18}:
        missing = "a reviewed activate/talk entity or target-group producer with repeat/checklist semantics"
    elif objective_type in {5, 9, 25}:
        missing = "a reviewed script producer that identifies trigger timing, owner event, count/delta semantics, and replay behavior"
    elif objective_type in {7, 26, 28}:
        missing = "depot/carry/deposit or resource acquisition evidence that proves source ownership and objective-credit timing"
    elif objective_type in {12, 13, 21, 32}:
        missing = "defense, timer, resource-pool, or victory-pool state evidence that proves the runtime producer and state transitions"
    elif objective_type in {6, 19}:
        missing = "both object and WorldLocation2 trigger placement evidence for the generic trigger producer"
    elif objective_type == 20:
        missing = "a TargetGroup-backed ObjectId or another verified exterminate producer"
    elif objective_type == 22:
        missing = "a virtual item ObjectId/source or another verified virtual-collect producer"
    elif objective_type in PUBLIC_EVENT_KILL_EVENT_UNIT_OBJECTIVE_TYPES:
        missing = (
            "a TargetGroup-backed ObjectId for the event-owned kill route"
            if objective_object_id and not objective_object_is_target_group
            else "event-owned spawn/import evidence for the owning PublicEventId route"
        )
    elif objective_type == 2:
        missing = "collectable item/source evidence that identifies the item or pickup producer"
    else:
        missing = "a client/decompile/live evidence source that proves the safe runtime producer"

    return (
        f"Public-event objective {related_client_id} is mapped to a current client row ({'; '.join(detail_parts)}), "
        f"but remains blocked because it is missing {missing}. Required evidence source: client/decompile/live capture, "
        "or a reviewed runtime script/placement/data promotion that proves producer ownership, activation timing, "
        "objective delta/replay behavior, rewards/medals, and client smoke without querying reference tables at runtime."
    )


def build_public_event_evidence_rows(
    strings: dict[int, str],
    public_events: list[dict[str, str]],
    data_mapping_output: Path,
) -> list[dict[str, object]]:
    public_event_by_id = {to_int(row["ID"]): row for row in public_events}
    target_group_rows = load_csv_rows(data_mapping_output / "client_source_targetgroup_map.csv")
    target_group_members: dict[int, tuple[int, ...]] = {}
    for row in target_group_rows:
        target_group_id = to_int(row.get("ID"))
        if not target_group_id:
            continue

        members = tuple(
            member_id
            for member_id in (to_int(row.get(f"data{i}")) for i in range(7))
            if member_id
        )
        if members:
            target_group_members[target_group_id] = members

    target_group_ids = set(target_group_members)

    def event_name(event_id: int, fallback: str = "") -> str:
        event = public_event_by_id.get(event_id, {})
        return text_by_id(strings, to_int(event.get("localizedTextIdName"))) or fallback

    def common(
        evidence_kind: str,
        source_map: str,
        source_row_id: int,
        public_event_id: int,
        jabbithole_public_event_id: int,
        public_event_name: str,
        client_public_event_name: str,
        parent_public_event_id: int = 0,
        child_public_event_id: int = 0,
    ) -> dict[str, object]:
        return {
            "evidence_kind": evidence_kind,
            "source_map": source_map,
            "source_row_id": source_row_id,
            "jabbithole_public_event_id": jabbithole_public_event_id,
            "public_event_id": public_event_id if public_event_id else "",
            "public_event_name": public_event_name,
            "client_public_event_name": event_name(public_event_id, client_public_event_name),
            "public_event_link_status": public_event_link_status(public_event_id, public_event_by_id),
            "parent_public_event_id": parent_public_event_id if parent_public_event_id else "",
            "parent_event_link_status": public_event_link_status(parent_public_event_id, public_event_by_id) if parent_public_event_id else "",
            "child_public_event_id": child_public_event_id if child_public_event_id else "",
            "child_event_link_status": public_event_link_status(child_public_event_id, public_event_by_id) if child_public_event_id else "",
        }

    output: list[dict[str, object]] = []

    objective_source = "public_event_objective_map.csv"
    objective_rows = load_csv_rows(data_mapping_output / objective_source)
    public_event_multi_member_target_groups_by_creature: dict[tuple[int, int], list[tuple[int, int, tuple[int, ...]]]] = defaultdict(list)
    for row in objective_rows:
        event_id = to_int(row.get("public_event_id"))
        objective_id = to_int(row.get("public_event_objective_id"))
        target_group_id = to_int(row.get("objective_object_id"))
        members = target_group_members.get(target_group_id, ())
        if event_id and objective_id and target_group_id and len(members) > 1:
            for member_id in members:
                public_event_multi_member_target_groups_by_creature[(event_id, member_id)].append(
                    (objective_id, target_group_id, members)
                )

    for row in objective_rows:
        event_id = to_int(row.get("public_event_id"))
        related_client_id = to_int(row.get("public_event_objective_id"))
        match_status = str(row.get("match_status", ""))
        objective_type = to_int(row.get("objective_type"))
        objective_object_id = to_int(row.get("objective_object_id"))
        objective_object_is_target_group = objective_object_id in target_group_ids
        world_location_id = to_int(row.get("world_location_id"))
        target_group_id = to_int(row.get("target_group_id_reward_pane"))
        if objective_type in {
            PUBLIC_EVENT_KILL_TARGET_GROUP_OBJECTIVE_TYPE,
            PUBLIC_EVENT_KILL_CLUSTER_TARGET_GROUP_OBJECTIVE_TYPE,
            PUBLIC_EVENT_EXTERMINATE_OBJECTIVE_TYPE,
        } and objective_object_id:
            target_group_id = objective_object_id
        if objective_type in PUBLIC_EVENT_KILL_EVENT_UNIT_OBJECTIVE_TYPES and objective_object_is_target_group:
            target_group_id = objective_object_id
        evidence_status = public_event_evidence_status(
            "public_event_objective",
            event_id in public_event_by_id,
            match_status,
            related_client_id,
            objective_type=objective_type,
            objective_object_id=objective_object_id,
            world_location_id=world_location_id,
            objective_object_is_target_group=objective_object_is_target_group,
        )
        if evidence_status == "runtime_public_event_kill_target_group_credit_tested_pending_spawn_event_smoke":
            evidence_sources = "Tools/DataMapping/output/public_event_objective_map.csv;Tools/DataMapping/map_wildstar_data.py;wildstar_client_mysql/PublicEvent.tbl.sql;wildstar_client_mysql/PublicEventObjective.tbl.sql;wildstar_client_mysql/TargetGroup.tbl.sql;Source/NexusForever.Game/Entity/UnitEntity.cs;Source/NexusForever.Game/AssetManager.cs;Source/NexusForever.Game.Tests/Entity/UnitEntityDamageResultTests.cs"
            blocker_summary = f"Public-event KillTargetGroup objective {related_client_id} has mapped TargetGroup ObjectId {objective_object_id}; the runtime UnitEntity target-group kill reward path dispatches PublicEventObjectiveType.KillTargetGroup for resolved creature target groups, covered by focused mapped TargetGroup tests. Retail completion still needs row-specific event activation, spawn/import proof, objective timing, reward/medal behavior, replay/negative cases, and client smoke."
        elif evidence_status == "runtime_public_event_event_owned_unit_kill_credit_tested_pending_event_spawn_smoke":
            evidence_sources = "Tools/DataMapping/output/public_event_objective_map.csv;Tools/DataMapping/output/client_source_targetgroup_map.csv;Tools/DataMapping/map_wildstar_data.py;wildstar_client_mysql/PublicEvent.tbl.sql;wildstar_client_mysql/PublicEventObjective.tbl.sql;wildstar_client_mysql/TargetGroup.tbl.sql;Source/NexusForever.Game/Entity/UnitEntity.cs;Source/NexusForever.Game/AssetManager.cs;Source/NexusForever.Game.Tests/Entity/UnitEntityDamageResultTests.cs"
            object_clause = (
                "object 0 event-owned-unit credit"
                if objective_object_id == 0
                else f"TargetGroup-backed ObjectId {objective_object_id}"
            )
            blocker_summary = f"Public-event event-unit kill objective {related_client_id} uses {object_clause}; the runtime UnitEntity public-event-owned kill path dispatches KillEventUnit, KillEventObjectiveUnit, KillClusterEventUnit, and KillClusterEventObjectiveUnit updates to the owning event, including target-group object variants when the killed creature resolves to the mapped TargetGroup. Focused tests cover zero-object and TargetGroup object credit. Retail completion still needs row-specific event-owned spawn/import proof, event activation, objective timing, reward/medal behavior, replay/negative cases, and client smoke."
        elif evidence_status == "runtime_public_event_participants_trigger_volume_world_location_credit_tested_pending_trigger_placement_smoke":
            evidence_sources = "Tools/DataMapping/output/public_event_objective_map.csv;Tools/DataMapping/map_wildstar_data.py;wildstar_client_mysql/PublicEvent.tbl.sql;wildstar_client_mysql/PublicEventObjective.tbl.sql;wildstar_client_mysql/WorldLocation2.tbl.sql;Source/NexusForever.Game/Entity/Trigger/VolumeGridTriggerEntity.cs;Source/NexusForever.Game/Entity/Trigger/WorldLocationVolumeGridTriggerEntity.cs;Source/NexusForever.Game.Tests/Entity/VolumeGridTriggerEntityTests.cs"
            blocker_summary = f"Public-event ParticipantsInTriggerVolume objective {related_client_id} has mapped object id {objective_object_id} and WorldLocation2 {world_location_id}; the runtime WorldLocationVolumeGridTriggerEntity/VolumeGridTriggerEntity path credits PublicEventObjectiveType.ParticipantsInTriggerVolume on player enter and removes one count on leave, with duplicate and vertical-clamp tests. Retail completion still needs row-specific trigger placement/import, phase activation, replay/cleanup, reward/medal behavior, and client smoke."
        elif evidence_status == "runtime_public_event_kill_cluster_target_group_credit_tested_pending_spawn_event_smoke":
            evidence_sources = "Tools/DataMapping/output/public_event_objective_map.csv;Tools/DataMapping/map_wildstar_data.py;wildstar_client_mysql/PublicEvent.tbl.sql;wildstar_client_mysql/PublicEventObjective.tbl.sql;wildstar_client_mysql/TargetGroup.tbl.sql;Source/NexusForever.Game/Entity/UnitEntity.cs;Source/NexusForever.Game/AssetManager.cs;Source/NexusForever.Game.Tests/Entity/UnitEntityDamageResultTests.cs"
            blocker_summary = f"Public-event KillClusterTargetGroup objective {related_client_id} has mapped TargetGroup ObjectId {objective_object_id}; the runtime UnitEntity target-group kill reward path dispatches PublicEventObjectiveType.KillClusterTargetGroup for resolved creature target groups, covered by focused mapped TargetGroup tests. Retail completion still needs row-specific event activation, spawn/import proof, objective timing, reward/medal behavior, replay/negative cases, and client smoke."
        elif evidence_status == "runtime_public_event_turnstile_world_location_entry_credit_tested_pending_trigger_placement_smoke":
            evidence_sources = "Tools/DataMapping/output/public_event_objective_map.csv;Tools/DataMapping/map_wildstar_data.py;wildstar_client_mysql/PublicEvent.tbl.sql;wildstar_client_mysql/PublicEventObjective.tbl.sql;wildstar_client_mysql/WorldLocation2.tbl.sql;Source/NexusForever.Game/Entity/Trigger/TurnstileTriggerEntity.cs;Source/NexusForever.Game/Entity/Trigger/WorldLocationVolumeGridTriggerEntity.cs;Source/NexusForever.Game.Tests/Entity/VolumeGridTriggerEntityTests.cs"
