def challenge_evidence_status(
    evidence_kind: str,
    current_challenge: bool,
    match_status: str,
    related_client_id: int,
    relation_source: str = "",
    reward_type: int | None = None,
) -> str:
    if not current_challenge:
        return "datamapping_challenge_not_current_client_challenge_row_blocked"
    if evidence_kind == "challenge":
        if match_status == "matched":
            return "runtime_challenge_lifecycle_progress_tier_reward_track_tested_pending_content_smoke"
        return "datamapping_challenge_unmatched_blocked"
    if evidence_kind == "challenge_creature":
        if match_status == "unmatched":
            return "datamapping_challenge_creature_unmatched_blocked"
        if match_status == "ambiguous_name":
            return "datamapping_challenge_creature_ambiguous_pending_review"
        if match_status == "reviewed":
            return "runtime_challenge_creature_target_group_hook_tested_pending_spawn_smoke"
        if match_status in {"unique_name", "scored_name"}:
            return "datamapping_challenge_creature_runtime_hook_tested_pending_review_and_spawn_smoke"
        return "datamapping_challenge_creature_pending_review"
    if evidence_kind == "challenge_reward_item":
        if related_client_id:
            if relation_source == "reward_track_challenge_item" and reward_type == 0:
                return "runtime_challenge_reward_track_item_grant_tested_pending_ui_selection_smoke"
            return "datamapping_challenge_direct_reward_item_pending_reward_track_bridge"
        return "datamapping_challenge_reward_item_unmatched_blocked"
    return "datamapping_challenge_pending_review"


def build_challenge_evidence_rows(data_mapping_output: Path) -> list[dict[str, object]]:
    challenge_rows = load_csv_rows(data_mapping_output / "challenge_map.csv")
    challenge_by_id = {to_int(row.get("challenge_id")): row for row in challenge_rows if to_int(row.get("challenge_id"))}

    def common(evidence_kind: str, source_map: str, source_row_id: int, row: dict[str, str]) -> dict[str, object]:
        challenge_id = to_int(row.get("challenge_id"))
        challenge = challenge_by_id.get(challenge_id, {})
        current_challenge = challenge_id in challenge_by_id
        return {
            "evidence_kind": evidence_kind,
            "source_map": source_map,
            "source_row_id": source_row_id,
            "jabbithole_challenge_id": to_int(row.get("jabbithole_challenge_id")),
            "challenge_id": challenge_id if challenge_id else "",
            "challenge_name": row.get("challenge_name", "") or row.get("jabbithole_challenge_name", ""),
            "client_challenge_name": row.get("client_challenge_name", "") or challenge.get("client_challenge_name", ""),
            "challenge_link_status": "current_challenge" if current_challenge else "non_current_challenge_reference",
            "challenge_type": to_int(row.get("challenge_type")) if row.get("challenge_type") else to_int(challenge.get("challenge_type")) if challenge.get("challenge_type") else "",
            "client_challenge_type": to_int(challenge.get("client_challenge_type")) if challenge.get("client_challenge_type") else "",
            "goals": row.get("goals", "") or challenge.get("goals", ""),
            "client_world_zone_id": to_int(challenge.get("client_world_zone_id")) if challenge.get("client_world_zone_id") else "",
            "challenge_reward_track_id": to_int(row.get("challenge_reward_track_id")) if row.get("challenge_reward_track_id") else to_int(challenge.get("challenge_reward_track_id")) if challenge.get("challenge_reward_track_id") else "",
            "client_reward_track_id": to_int(challenge.get("client_reward_track_id")) if challenge.get("client_reward_track_id") else "",
        }

    output: list[dict[str, object]] = []
    for row in challenge_rows:
        challenge_id = to_int(row.get("challenge_id"))
        match_status = str(row.get("match_status", ""))
        output.append(
            {
                **common("challenge", "challenge_map.csv", to_int(row.get("jabbithole_challenge_id")), row),
                "related_jabbithole_id": to_int(row.get("jabbithole_challenge_id")),
                "related_client_id": challenge_id if challenge_id else "",
                "related_source_name": row.get("jabbithole_challenge_name", ""),
                "related_client_name": row.get("client_challenge_name", ""),
                "relation_source": "",
                "match_status": match_status,
                "description": row.get("description", ""),
                "reward_index": "",
                "reward_type": "",
                "amount": "",
                "tier": "",
                "last_seen_in": to_int(row.get("last_seen_in")) if row.get("last_seen_in") else "",
                "evidence_status": challenge_evidence_status("challenge", challenge_id in challenge_by_id, match_status, challenge_id),
                "evidence_sources": "Tools/DataMapping/output/challenge_map.csv;Tools/DataMapping/map_wildstar_data.py;wildstar_client_mysql/Challenge.tbl.sql;Source/NexusForever.Game/Challenges",
                "manual_validation": "pending",
                "completion_status": "not_retail_complete",
                "blocker_summary": "Challenge lifecycle, public progress credit, tier completion, persistence, and first-supported RewardTrack item grants are implemented and tested; retail completion still needs content smoke, timed scoring semantics, reward UI selection/win chance, challenge-specific achievement trigger evidence, and remaining objective-producer evidence.",
            }
        )

    creature_source = "challenge_creature_map.csv"
    for row in load_csv_rows(data_mapping_output / creature_source):
        challenge_id = to_int(row.get("challenge_id"))
        related_client_id = to_int(row.get("creature2_id"))
        match_status = str(row.get("match_status", ""))
        output.append(
            {
                **common("challenge_creature", creature_source, to_int(row.get("source_relation_id")), row),
                "related_jabbithole_id": to_int(row.get("jabbithole_creature_id")),
                "related_client_id": related_client_id if related_client_id else "",
                "related_source_name": row.get("source_name", ""),
                "related_client_name": row.get("creature2_name", ""),
                "relation_source": "challenge_creature",
                "match_status": match_status,
                "description": "",
                "reward_index": "",
                "reward_type": "",
                "amount": "",
                "tier": "",
                "last_seen_in": to_int(row.get("last_seen_in")) if row.get("last_seen_in") else "",
                "evidence_status": challenge_evidence_status("challenge_creature", challenge_id in challenge_by_id, match_status, related_client_id),
                "evidence_sources": "Tools/DataMapping/output/challenge_creature_map.csv;Tools/DataMapping/map_wildstar_data.py;wildstar_client_mysql/Challenge.tbl.sql;wildstar_client_mysql/Creature2.tbl.sql;Source/NexusForever.Game/Challenges",
                "manual_validation": "pending",
                "completion_status": "not_retail_complete",
                "blocker_summary": "Combat and activation target-group challenge hooks are implemented and tested; retail completion still needs reviewed Creature2 bridge coverage, spawn availability, and objective smoke for each content row.",
            }
        )

    reward_source = "challenge_reward_item_map.csv"
    for row in load_csv_rows(data_mapping_output / reward_source):
        challenge_id = to_int(row.get("challenge_id"))
        related_client_id = to_int(row.get("item2_id"))
        relation_source = row.get("relation_source", "")
        reward_type = to_int(row.get("reward_type")) if row.get("reward_type") else None
        output.append(
            {
                **common("challenge_reward_item", reward_source, to_int(row.get("source_relation_id")), row),
                "related_jabbithole_id": to_int(row.get("jabbithole_item_id")),
                "related_client_id": related_client_id if related_client_id else "",
                "related_source_name": row.get("item_name", ""),
                "related_client_name": row.get("item_name", ""),
                "relation_source": relation_source,
                "match_status": "matched" if related_client_id else "unmatched_item",
                "description": "",
                "reward_index": to_int(row.get("reward_index")) if row.get("reward_index") else "",
                "reward_type": reward_type if reward_type is not None else "",
                "amount": to_int(row.get("amount")) if row.get("amount") else "",
                "tier": to_int(row.get("tier")) if row.get("tier") else "",
                "last_seen_in": to_int(row.get("last_seen_in")) if row.get("last_seen_in") else "",
                "evidence_status": challenge_evidence_status("challenge_reward_item", challenge_id in challenge_by_id, "matched" if related_client_id else "unmatched_item", related_client_id, relation_source, reward_type),
                "evidence_sources": "Tools/DataMapping/output/challenge_reward_item_map.csv;Tools/DataMapping/map_wildstar_data.py;wildstar_client_mysql/Challenge.tbl.sql;wildstar_client_mysql/RewardTrack*.tbl.sql;wildstar_client_mysql/Item2.tbl.sql;Source/NexusForever.Game/Challenges",
                "manual_validation": "pending",
                "completion_status": "not_retail_complete",
                "blocker_summary": "First-supported RewardTrack item grants are implemented and tested for item reward choices; retail completion still needs direct-reward bridge evidence, reward UI selection/presentation, medal win chance, and challenge smoke.",
            }
        )

    return sorted(output, key=lambda item: (str(item["evidence_kind"]), to_int(str(item["challenge_id"])), to_int(str(item["source_row_id"]))))


def path_evidence_status(
    evidence_kind: str,
    path_mission_id: int,
    path_episode_id: int,
    current_mission: bool,
    current_episode: bool,
    match_status: str,
    related_client_id: int,
    world_zone_id: int = 0,
) -> str:
    if evidence_kind == "path_mission":
        if not current_mission:
            return "blocked_missing_client_path_mission"
        if path_mission_id in IMPLEMENTED_NORTHERN_WILDS_PATH_MISSIONS:
            return "implemented_northern_wilds_path_mission_runtime_verified"
        return "mapped_only_path_mission_blocked_runtime_owner_and_path_smoke"
    if evidence_kind == "path_episode":
        if current_episode and match_status == "matched":
            if path_episode_id in IMPLEMENTED_NORTHERN_WILDS_PATH_EPISODES:
                return "implemented_northern_wilds_path_episode_activation_verified"
            return "mapped_only_path_episode_blocked_runtime_zone_bridge_and_progression_smoke"
        return "blocked_path_episode_unmatched_bridge"
    if evidence_kind == "path_episode_mission":
        if not current_episode:
            return "blocked_path_episode_mission_missing_episode_bridge"
        if not current_mission:
            return "blocked_path_episode_mission_missing_client_mission"
        if (path_mission_id, path_episode_id) in IMPLEMENTED_NORTHERN_WILDS_PATH_EPISODE_MISSIONS:
            return "implemented_northern_wilds_path_episode_mission_activation_verified"
        return "mapped_only_path_episode_mission_blocked_activation_order_objective_smoke"
    if evidence_kind == "path_episode_reward":
        if not current_episode:
            return "blocked_path_episode_reward_missing_episode_bridge"
        if not related_client_id:
            return "blocked_path_episode_reward_item_unmatched"
        if path_episode_id in IMPLEMENTED_NORTHERN_WILDS_PATH_EPISODES:
            return "runtime_northern_wilds_path_episode_reward_type2_grant_tested_pending_presentation_smoke"
        return "mapped_only_path_episode_reward_item_blocked_reward_grant_presentation_evidence"
    if evidence_kind == "path_episode_zone":
        if not current_episode:
            return "blocked_path_episode_zone_missing_episode_bridge"
        if not related_client_id:
            return "blocked_path_episode_zone_missing_client_zone"
        if (path_episode_id, world_zone_id) in IMPLEMENTED_NORTHERN_WILDS_PATH_EPISODE_ZONES:
            return "implemented_northern_wilds_runtime_episode_zone_bridge_verified"
        return "mapped_only_path_episode_zone_blocked_runtime_visibility_smoke"
    if evidence_kind == "path_mission_creature":
        if not current_mission:
            return "blocked_path_mission_creature_missing_client_mission"
        if match_status == "unmatched":
            return "blocked_path_mission_creature_unmatched_bridge"
        if (path_mission_id, related_client_id) in IMPLEMENTED_NORTHERN_WILDS_PATH_MISSION_CREATURES:
            return "implemented_northern_wilds_path_mission_creature_credit_verified"
        if match_status == "ambiguous_name":
            return "blocked_path_mission_creature_ambiguous_requires_bridge_review"
        if match_status == "reviewed":
            return "mapped_only_reviewed_path_mission_creature_blocked_spawn_credit_smoke"
        if match_status in {"unique_name", "scored_name"}:
            return "mapped_only_path_mission_creature_blocked_review_and_spawn_credit_smoke"
        return "mapped_only_path_mission_creature_blocked_bridge_review"
    return "mapped_only_path_mission_blocked_review"


def path_evidence_blocker_summary(evidence_kind: str, evidence_status: str) -> str:
    if evidence_status.startswith("implemented_northern_wilds_"):
        return "Northern Wilds runtime-owned PathEpisode/PathMission coverage is implemented and focused tests verify activation, objective credit, persistence, reward boundaries, and negative cases; retail_complete still waits for end-to-end client smoke."
    if evidence_status == "runtime_northern_wilds_path_episode_reward_type2_grant_tested_pending_presentation_smoke":
        return "Northern Wilds PathEpisode reward type-2 grants are implemented and focused tests verify completed-episode reward delivery plus no-premature-grant boundaries; retail_complete still waits for client reward presentation, timing, count, overflow, inventory persistence, and end-to-end path smoke."
    if "ambiguous_requires_bridge_review" in evidence_status:
        return "Blocked until a reviewed Creature2/source-spawn identity or live path capture resolves the ambiguous DataMapping creature bridge."
    if "unmatched" in evidence_status:
        return "Blocked until a matching current client row or reviewed runtime-owned bridge exists for the mapped DataMapping source row."
    if "missing" in evidence_status:
        return "Blocked until the missing current client table row or reviewed runtime-owned episode/mission bridge is identified."
    if evidence_kind == "path_mission":
        return "Mapped-only PathMission row is blocked until a runtime-owned producer/objective hook and client path smoke prove activation, progress, reward, and UI semantics."
    if evidence_kind == "path_episode":
        return "Mapped-only PathEpisode row is blocked until runtime zone ownership, episode activation/progression sequencing, and client smoke are reviewed."
    if evidence_kind == "path_episode_mission":
        return "Mapped-only PathEpisodeMission row is blocked until activation ordering, prerequisite/faction visibility, objective credit, and episode progression smoke are captured."
    if evidence_kind == "path_episode_reward":
        return "Mapped-only PathEpisode reward row is blocked until retail grant timing, item selection/presentation, count, and overflow semantics are captured."
    if evidence_kind == "path_episode_zone":
        return "Mapped-only PathEpisode zone row is blocked until runtime world/root-zone ownership and path visibility/routing smoke are reviewed."
    if evidence_kind == "path_mission_creature":
        return "Mapped-only path creature row is blocked until reviewed Creature2 placement plus spawn/objective credit smoke is captured."
    return "Mapped-only path evidence row is blocked until a reviewed runtime owner and client smoke evidence are available."


def build_path_mission_evidence_rows(data_mapping_output: Path) -> list[dict[str, object]]:
    mission_rows = load_csv_rows(data_mapping_output / "path_mission_client_map.csv")
    mission_by_id = {to_int(row.get("path_mission_id")): row for row in mission_rows if to_int(row.get("path_mission_id"))}
    episode_rows = load_csv_rows(data_mapping_output / "path_episode_map.csv")
    episode_by_id = {to_int(row.get("path_episode_id")): row for row in episode_rows if to_int(row.get("path_episode_id"))}
    matched_episode_ids = {episode_id for episode_id, row in episode_by_id.items() if row.get("match_status") == "matched"}

    def common(
        evidence_kind: str,
        source_map: str,
        source_row_id: int,
        path_mission_id: int = 0,
        path_episode_id: int = 0,
        row: dict[str, str] | None = None,
    ) -> dict[str, object]:
        row = row or {}
        mission = mission_by_id.get(path_mission_id, {})
        episode = episode_by_id.get(path_episode_id, {})
        return {
            "evidence_kind": evidence_kind,
            "source_map": source_map,
            "source_row_id": source_row_id,
            "jabbithole_path_mission_id": to_int(row.get("jabbithole_path_mission_id")) if row.get("jabbithole_path_mission_id") else "",
            "path_mission_id": path_mission_id if path_mission_id else "",
            "path_mission_name": row.get("path_mission_name", "") or mission.get("path_mission_name", ""),
            "client_path_mission_name": row.get("client_path_mission_name", "") or mission.get("path_mission_name", ""),
            "path_mission_link_status": "current_path_mission" if path_mission_id in mission_by_id else "no_path_mission_reference" if not path_mission_id else "non_current_path_mission_reference",
            "jabbithole_path_episode_id": to_int(row.get("jabbithole_path_episode_id")) if row.get("jabbithole_path_episode_id") else "",
            "path_episode_id": path_episode_id if path_episode_id else "",
            "path_episode_name": row.get("path_episode_name", "") or row.get("jabbithole_name", "") or episode.get("jabbithole_name", ""),
            "client_path_episode_name": row.get("client_path_episode_name", "") or episode.get("client_path_episode_name", ""),
            "path_episode_link_status": "current_path_episode" if path_episode_id in matched_episode_ids else "no_path_episode_reference" if not path_episode_id else "non_current_path_episode_reference",
            "player_path_id": to_int(row.get("player_path_id")) if row.get("player_path_id") else to_int(row.get("jabbithole_player_path_id")) if row.get("jabbithole_player_path_id") else "",
            "path_type": to_int(row.get("path_type")) if row.get("path_type") else to_int(mission.get("path_type")) if mission.get("path_type") else "",
            "mission_type": to_int(row.get("mission_type")) if row.get("mission_type") else to_int(mission.get("mission_type")) if mission.get("mission_type") else "",
            "mission_subtype": to_int(row.get("mission_subtype")) if row.get("mission_subtype") else "",
        }

    output: list[dict[str, object]] = []

    for row in mission_rows:
        mission_id = to_int(row.get("path_mission_id"))
        evidence_status = path_evidence_status("path_mission", mission_id, 0, mission_id in mission_by_id, False, "", mission_id)
        output.append(
            {
                **common("path_mission", "path_mission_client_map.csv", mission_id, mission_id, 0, row),
                "related_jabbithole_id": "",
                "related_client_id": mission_id,
                "related_source_name": row.get("path_mission_name", ""),
                "related_client_name": row.get("path_mission_name", ""),
                "match_status": "client_row",
                "needed": "",
                "amount": "",
                "world_zone_id": "",
                "world_location_ids": join_ids(to_int(row.get(f"world_location_{index}")) for index in range(4)),
                "last_seen_in": "",
                "evidence_status": evidence_status,
                "evidence_sources": "Tools/DataMapping/output/path_mission_client_map.csv;Tools/DataMapping/map_wildstar_data.py;wildstar_client_mysql/PathMission.tbl.sql;Source/NexusForever.Game/Entity/PathManager.cs;Source/NexusForever.Game/Entity/PathRewardGrant.cs;Source/NexusForever.Game.Static/PlayerPath",
                "manual_validation": "pending",
                "completion_status": "not_retail_complete",
                "blocker_summary": path_evidence_blocker_summary("path_mission", evidence_status),
            }
        )

    for row in episode_rows:
        episode_id = to_int(row.get("path_episode_id"))
        match_status = str(row.get("match_status", ""))
        evidence_status = path_evidence_status("path_episode", 0, episode_id, False, episode_id in episode_by_id and match_status == "matched", match_status, episode_id)
        output.append(
            {
                **common("path_episode", "path_episode_map.csv", to_int(row.get("jabbithole_path_episode_id")), 0, episode_id, row),
                "related_jabbithole_id": to_int(row.get("jabbithole_path_episode_id")),
                "related_client_id": episode_id if episode_id else "",
                "related_source_name": row.get("jabbithole_name", ""),
                "related_client_name": row.get("client_path_episode_name", ""),
                "match_status": match_status,
                "needed": "",
                "amount": "",
                "world_zone_id": to_int(row.get("client_world_zone_id")) if row.get("client_world_zone_id") else to_int(row.get("world_zone_id")) if row.get("world_zone_id") else "",
                "world_location_ids": "",
                "last_seen_in": to_int(row.get("last_seen_in")) if row.get("last_seen_in") else "",
                "evidence_status": evidence_status,
                "evidence_sources": "Tools/DataMapping/output/path_episode_map.csv;Tools/DataMapping/map_wildstar_data.py;wildstar_client_mysql/PathEpisode.tbl.sql;Source/NexusForever.Game/Entity/PathManager.cs;Source/NexusForever.Game.Static/PlayerPath",
                "manual_validation": "pending",
                "completion_status": "not_retail_complete",
                "blocker_summary": path_evidence_blocker_summary("path_episode", evidence_status),
            }
        )

    for row in load_csv_rows(data_mapping_output / "path_episode_mission_map.csv"):
        mission_id = to_int(row.get("path_mission_id"))
        episode_id = to_int(row.get("path_episode_id"))
        evidence_status = path_evidence_status("path_episode_mission", mission_id, episode_id, mission_id in mission_by_id, episode_id in matched_episode_ids, "", mission_id)
        output.append(
            {
                **common("path_episode_mission", "path_episode_mission_map.csv", to_int(row.get("source_relation_id")), mission_id, episode_id, row),
                "related_jabbithole_id": to_int(row.get("jabbithole_path_mission_id")),
                "related_client_id": mission_id if mission_id else "",
                "related_source_name": row.get("path_mission_name", ""),
                "related_client_name": row.get("client_path_mission_name", ""),
                "match_status": "matched" if mission_id in mission_by_id and episode_id in episode_by_id else "missing_bridge",
                "needed": to_int(row.get("needed")) if row.get("needed") else "",
                "amount": "",
                "world_zone_id": "",
                "world_location_ids": "",
                "last_seen_in": to_int(row.get("last_seen_in")) if row.get("last_seen_in") else "",
                "evidence_status": evidence_status,
                "evidence_sources": "Tools/DataMapping/output/path_episode_mission_map.csv;Tools/DataMapping/map_wildstar_data.py;wildstar_client_mysql/PathEpisode*.tbl.sql;wildstar_client_mysql/PathMission.tbl.sql;Source/NexusForever.Game/Entity/PathManager.cs;Source/NexusForever.Game.Static/PlayerPath",
                "manual_validation": "pending",
                "completion_status": "not_retail_complete",
                "blocker_summary": path_evidence_blocker_summary("path_episode_mission", evidence_status),
            }
        )

    for row in load_csv_rows(data_mapping_output / "path_episode_reward_map.csv"):
        episode_id = to_int(row.get("path_episode_id"))
        item_id = to_int(row.get("item2_id"))
        evidence_status = path_evidence_status("path_episode_reward", 0, episode_id, False, episode_id in matched_episode_ids, "", item_id)
        output.append(
            {
                **common("path_episode_reward", "path_episode_reward_map.csv", to_int(row.get("source_relation_id")), 0, episode_id, row),
                "related_jabbithole_id": "",
                "related_client_id": item_id if item_id else "",
                "related_source_name": row.get("item_name", ""),
                "related_client_name": row.get("item_name", ""),
                "match_status": "matched" if item_id else "unmatched_item",
                "needed": "",
                "amount": to_int(row.get("amount")) if row.get("amount") else "",
                "world_zone_id": "",
                "world_location_ids": "",
                "last_seen_in": to_int(row.get("last_seen_in")) if row.get("last_seen_in") else "",
                "evidence_status": evidence_status,
                "evidence_sources": "Tools/DataMapping/output/path_episode_reward_map.csv;Tools/DataMapping/map_wildstar_data.py;wildstar_client_mysql/PathEpisode*.tbl.sql;wildstar_client_mysql/Item2.tbl.sql;Source/NexusForever.Game/Entity/PathManager.cs;Source/NexusForever.Game/Entity/PathRewardGrant.cs;Source/NexusForever.Game.Tests/Entity/PathManagerTests.cs;Source/NexusForever.Game.Static/PlayerPath",
                "manual_validation": "pending",
                "completion_status": "not_retail_complete",
                "blocker_summary": path_evidence_blocker_summary("path_episode_reward", evidence_status),
            }
        )

    for row in load_csv_rows(data_mapping_output / "path_episode_zone_map.csv"):
        episode_id = to_int(row.get("path_episode_id"))
        world_zone_id = to_int(row.get("world_zone_id"))
        evidence_status = path_evidence_status("path_episode_zone", 0, episode_id, False, episode_id in matched_episode_ids, "", world_zone_id, world_zone_id)
        output.append(
            {
                **common("path_episode_zone", "path_episode_zone_map.csv", to_int(row.get("source_relation_id")), 0, episode_id, row),
                "related_jabbithole_id": to_int(row.get("jabbithole_zone_id")),
                "related_client_id": world_zone_id if world_zone_id else "",
                "related_source_name": row.get("zone_name", ""),
                "related_client_name": row.get("client_zone_name", ""),
                "match_status": "matched" if world_zone_id else "missing_client_zone",
                "needed": "",
                "amount": "",
                "world_zone_id": world_zone_id if world_zone_id else "",
                "world_location_ids": "",
                "last_seen_in": to_int(row.get("last_seen_in")) if row.get("last_seen_in") else "",
                "evidence_status": evidence_status,
                "evidence_sources": "Tools/DataMapping/output/path_episode_zone_map.csv;Tools/DataMapping/map_wildstar_data.py;wildstar_client_mysql/PathEpisode*.tbl.sql;wildstar_client_mysql/WorldZone.tbl.sql;Source/NexusForever.Game/Entity/PathManager.cs;Source/NexusForever.Game.Static/PlayerPath",
                "manual_validation": "pending",
                "completion_status": "not_retail_complete",
                "blocker_summary": path_evidence_blocker_summary("path_episode_zone", evidence_status),
            }
        )

    for row in load_csv_rows(data_mapping_output / "creature_path_mission_map.csv"):
        mission_id = to_int(row.get("path_mission_id"))
        creature_id = to_int(row.get("creature2_id"))
        match_status = str(row.get("match_status", ""))
        evidence_status = path_evidence_status("path_mission_creature", mission_id, 0, mission_id in mission_by_id, False, match_status, creature_id)
        output.append(
            {
                **common("path_mission_creature", "creature_path_mission_map.csv", to_int(row.get("source_relation_id")), mission_id, 0, row),
                "related_jabbithole_id": to_int(row.get("jabbithole_creature_id")),
                "related_client_id": creature_id if creature_id else "",
                "related_source_name": row.get("source_name", ""),
                "related_client_name": row.get("creature2_name", ""),
                "match_status": match_status,
                "needed": to_int(row.get("needed")) if row.get("needed") else "",
                "amount": "",
                "world_zone_id": to_int(row.get("real_zone_id")) if row.get("real_zone_id") else "",
                "world_location_ids": "",
                "last_seen_in": to_int(row.get("last_seen_in")) if row.get("last_seen_in") else "",
                "evidence_status": evidence_status,
                "evidence_sources": "Tools/DataMapping/output/creature_path_mission_map.csv;Tools/DataMapping/map_wildstar_data.py;wildstar_client_mysql/PathMission.tbl.sql;wildstar_client_mysql/Creature2.tbl.sql;Source/NexusForever.Game/Entity/PathManager.cs;Source/NexusForever.Game.Static/PlayerPath",
                "manual_validation": "pending",
                "completion_status": "not_retail_complete",
                "blocker_summary": path_evidence_blocker_summary("path_mission_creature", evidence_status),
            }
        )

    return sorted(output, key=lambda item: (str(item["evidence_kind"]), to_int(str(item["path_episode_id"])), to_int(str(item["path_mission_id"])), to_int(str(item["source_row_id"]))))


def contract_evidence_status(evidence_kind: str, current_quest: bool, match_status: str, related_client_id: int) -> str:
    if evidence_kind in {"contract", "contract_creature"} and not current_quest:
        return "datamapping_contract_not_current_client_quest_row_blocked"
    if evidence_kind == "contract":
        if match_status == "matched":
            return "implemented_contract_quest_manager_backed_pending_rotation_client_smoke"
        return "datamapping_contract_quest_unmatched_blocked"
    if evidence_kind == "contract_creature":
        if match_status == "unmatched":
            return "datamapping_contract_creature_unmatched_blocked"
        if match_status == "ambiguous_name":
            return "datamapping_contract_creature_ambiguous_pending_review"
        if match_status == "reviewed":
            return "implemented_contract_creature_reviewed_bridge_objective_credit_pending_spawn_client_smoke"
        if match_status in {"unique_name", "scored_name"}:
            return "mapped_only_contract_creature_pending_bridge_review_spawn_client_smoke"
        return "mapped_only_contract_creature_pending_bridge_review"
    if evidence_kind == "contract_reward_item":
        if related_client_id:
            return "mapped_only_contract_reward_track_item_pending_choice_presentation_client_smoke"
        return "datamapping_contract_reward_item_unmatched_blocked"
    return "mapped_only_contract_pending_review"


def build_contract_evidence_rows(
    strings: dict[int, str],
    quests: list[dict[str, str]],
    quest_output: list[dict[str, object]],
    data_mapping_output: Path,
) -> list[dict[str, object]]:
    quest_by_id = {to_int(row["ID"]): row for row in quests}
    quest_status_by_id = {to_int(str(row["quest_id"])): row for row in quest_output}

    def base_row(evidence_kind: str, source_map: str, source_row_id: int, quest_id: int, row: dict[str, str]) -> dict[str, object]:
        quest = quest_by_id.get(quest_id, {})
        quest_status = quest_status_by_id.get(quest_id, {})
        current_quest = quest_id in quest_by_id if quest_id else False
        return {
            "evidence_kind": evidence_kind,
            "source_map": source_map,
            "source_row_id": source_row_id,
            "quest_id": quest_id if quest_id else "",
            "quest_title": text_by_id(strings, to_int(quest.get("localizedTextIdTitle"))) or row.get("client_quest_name", "") or row.get("jabbithole_quest_name", ""),
            "quest_bucket": quest_status.get("bucket", "non_current_client_quest_reference" if quest_id and not current_quest else ""),
            "quest_completion_status": quest_status.get("completion_status", "not_retail_complete" if quest_id else ""),
            "quest_link_status": "current_quest" if current_quest else "non_current_client_quest_reference" if quest_id else "not_quest_scoped",
            "jabbithole_contract_id": to_int(row.get("jabbithole_contract_id")) if row.get("jabbithole_contract_id") else "",
            "contract_game_id": to_int(row.get("contract_game_id")) if row.get("contract_game_id") else "",
            "jabbithole_quest_id": to_int(row.get("jabbithole_quest_id")) if row.get("jabbithole_quest_id") else "",
            "jabbithole_quest_name": row.get("jabbithole_quest_name", ""),
            "client_quest_name": row.get("client_quest_name", ""),
            "contract_quality": to_int(row.get("quality")) if row.get("quality") else "",
            "contract_type": to_int(row.get("contract_type")) if row.get("contract_type") else "",
            "reward_track_type": to_int(row.get("reward_track_type")) if row.get("reward_track_type") else "",
            "xp": to_int(row.get("xp")) if row.get("xp") else "",
        }

    output: list[dict[str, object]] = []
    contract_source = "contract_map.csv"
    for row in load_csv_rows(data_mapping_output / contract_source):
        quest_id = to_int(row.get("quest2_id"))
        match_status = str(row.get("match_status", ""))
        output.append(
            {
                **base_row("contract", contract_source, to_int(row.get("jabbithole_contract_id")), quest_id, row),
                "related_jabbithole_id": to_int(row.get("jabbithole_contract_id")),
                "related_client_id": to_int(row.get("contract_game_id")) if row.get("contract_game_id") else "",
                "related_source_name": row.get("jabbithole_quest_name", ""),
                "related_client_name": row.get("client_quest_name", ""),
                "match_status": match_status,
                "relation_match_status": "",
                "tier": "",
                "cost": "",
                "amount": "",
                "choice_idx": "",
                "is_casque": "",
                "enabled": row.get("enabled", ""),
                "first_seen_in": to_int(row.get("first_seen_in")) if row.get("first_seen_in") else "",
                "last_seen_in": to_int(row.get("last_seen_in")) if row.get("last_seen_in") else "",
                "evidence_status": contract_evidence_status("contract", quest_id in quest_by_id, match_status, quest_id),
                "evidence_sources": "Tools/DataMapping/output/contract_map.csv;Tools/DataMapping/map_wildstar_data.py;wildstar_client_mysql/Quest2.tbl.sql;wildstar_client_mysql/PeriodicQuest*.tbl.sql;Source/NexusForever.Game/Quest/ContractManager.cs;Source/NexusForever.Game/Entity/QuestManager.cs;Source/NexusForever.Network.World/Message/Model/ServerQuestContractGoodQualityChanged.cs;Source/NexusForever.Game.Tests/Quest/QuestTests.cs",
                "manual_validation": "pending",
                "completion_status": "not_retail_complete",
                "blocker_summary": "Contract quest evidence is manager-backed from typed Quest2, QuestObjective, Quest2Reward, Item2, and PeriodicQuestGroup tables, with focused tests covering objective families, UI-safe validation, receiverless accept/complete, periodic capacity, fixed item rewards, and contract achievements. Retail-complete proof still needs exact random rotation or board timing/type-filter evidence and client smoke.",
            }
        )

    creature_source = "contract_creature_map.csv"
    for row in load_csv_rows(data_mapping_output / creature_source):
        quest_id = to_int(row.get("quest2_id"))
        match_status = str(row.get("match_status", ""))
        output.append(
            {
                **base_row("contract_creature", creature_source, to_int(row.get("source_relation_id")), quest_id, row),
                "related_jabbithole_id": to_int(row.get("jabbithole_creature_id")),
                "related_client_id": to_int(row.get("creature2_id")) if row.get("creature2_id") else "",
                "related_source_name": row.get("source_name", ""),
                "related_client_name": row.get("creature2_name", ""),
                "match_status": match_status,
                "relation_match_status": row.get("relation_match_status", ""),
                "tier": "",
                "cost": "",
                "amount": "",
                "choice_idx": "",
                "is_casque": "",
                "enabled": row.get("enabled", ""),
                "first_seen_in": "",
                "last_seen_in": to_int(row.get("last_seen_in")) if row.get("last_seen_in") else "",
                "evidence_status": contract_evidence_status("contract_creature", quest_id in quest_by_id, match_status, to_int(row.get("creature2_id"))),
                "evidence_sources": "Tools/DataMapping/output/contract_creature_map.csv;Tools/DataMapping/map_wildstar_data.py;wildstar_client_mysql/Quest2.tbl.sql;wildstar_client_mysql/Creature2.tbl.sql;Source/NexusForever.Game/Quest/ContractManager.cs;Source/NexusForever.Game/Quest/QuestObjective.cs;Source/NexusForever.Game/AssetManager.cs;Source/NexusForever.Game.Tests/Quest/QuestTests.cs",
                "manual_validation": "pending",
                "completion_status": "not_retail_complete",
                "blocker_summary": "Contract creature evidence feeds the table-backed contract objective path; reviewed bridges have generic target-group/objective-credit test coverage, while mapped-only bridges still need review. Retail-complete proof still needs spawn availability, placement/tap behavior, and client contract smoke.",
            }
        )

    reward_source = "contract_reward_map.csv"
    for row in load_csv_rows(data_mapping_output / reward_source):
        item_id = to_int(row.get("item2_id"))
        output.append(
            {
                **base_row("contract_reward_item", reward_source, to_int(row.get("source_reward_id")), 0, row),
                "related_jabbithole_id": to_int(row.get("raw_item_id")) if row.get("raw_item_id") else "",
                "related_client_id": item_id if item_id else "",
                "related_source_name": row.get("item_name", ""),
                "related_client_name": row.get("item_name", ""),
                "match_status": row.get("match_status", ""),
                "relation_match_status": "",
                "tier": to_int(row.get("tier")) if row.get("tier") else "",
                "cost": to_int(row.get("cost")) if row.get("cost") else "",
                "amount": to_int(row.get("amount")) if row.get("amount") else "",
                "choice_idx": to_int(row.get("choice_idx")) if row.get("choice_idx") else "",
                "is_casque": row.get("is_casque", ""),
                "enabled": row.get("enabled", ""),
                "first_seen_in": "",
                "last_seen_in": to_int(row.get("last_seen_in")) if row.get("last_seen_in") else "",
                "evidence_status": contract_evidence_status("contract_reward_item", True, row.get("match_status", ""), item_id),
                "evidence_sources": "Tools/DataMapping/output/contract_reward_map.csv;Tools/DataMapping/map_wildstar_data.py;wildstar_client_mysql/PeriodicQuest*.tbl.sql;wildstar_client_mysql/RewardTrack*.tbl.sql;wildstar_client_mysql/Item2.tbl.sql;Source/NexusForever.Game/Quest/ContractManager.cs;Source/NexusForever.Game/Entity/QuestManager.cs;Source/NexusForever.Game.Tests/Quest/QuestTests.cs",
                "manual_validation": "pending",
                "completion_status": "not_retail_complete",
                "blocker_summary": "Contract Quest2Reward item grants are implemented for runtime-owned fixed rewards, but contract_reward_map reward-track rows remain mapped-only until tier/choice selection, reward-track presentation, and client smoke are evidenced.",
            }
        )

    return sorted(output, key=lambda item: (str(item["evidence_kind"]), to_int(str(item["quest_id"])), to_int(str(item["source_row_id"]))))


def instance_portal_evidence_status(evidence_kind: str, bridge_rows: list[dict[str, str]]) -> str:
    if evidence_kind == "instance_portal_definition":
        return "client_instance_portal_definition_without_creature_link_blocked"

    match_statuses = {row.get("match_status", "") for row in bridge_rows}
    review_decisions = {row.get("review_decision", "") for row in bridge_rows}
    if "approved" in review_decisions or "reviewed" in match_statuses:
        return "reviewed_instance_portal_creature_pending_entry_smoke"
    if bridge_rows:
        return "datamapping_instance_portal_creature_pending_review_and_entry_smoke"
    return "client_instance_portal_creature_link_pending_world_placement_review"


def build_instance_portal_evidence_rows(
    strings: dict[int, str],
    instance_portals: list[dict[str, str]],
    creatures: list[dict[str, str]],
    data_mapping_output: Path,
) -> list[dict[str, object]]:
    portal_by_id = {to_int(row["ID"]): row for row in instance_portals}
    creature_portal_rows = [row for row in creatures if to_int(row.get("instancePortalId"))]
    creature_bridges: dict[int, list[dict[str, str]]] = defaultdict(list)
    for row in load_csv_rows(data_mapping_output / "creature_map.csv"):
        if row.get("creature_type") == "InstancePortal" or to_int(row.get("entity_type")) == 14:
            creature_bridges[to_int(row.get("creature2_id"))].append(row)

    def join_unique(values: Iterable[object]) -> str:
        unique = sorted({str(value) for value in values if str(value) not in {"", "0"}})
        return ";".join(unique)

    def bridge_status(bridge_rows: list[dict[str, str]]) -> str:
        if not bridge_rows:
            return "missing_datamapping_creature_bridge"
        if any(row.get("review_decision") == "approved" or row.get("match_status") == "reviewed" for row in bridge_rows):
            return "reviewed_datamapping_creature_bridge"
        return "candidate_datamapping_creature_bridge"

    def placement_rows(runtime_placement: dict[str, object] | None) -> list[dict[str, int]]:
        if not runtime_placement:
            return []
        placements = runtime_placement.get("placements")
        if placements:
            return list(placements)
        return [runtime_placement]

    def placement_value(
        runtime_placement: dict[str, object] | None,
        field: str,
        *,
        unique: bool = False,
    ) -> object:
        values = [row[field] for row in placement_rows(runtime_placement) if row.get(field) not in {"", None}]
        if unique:
            values = list(dict.fromkeys(values))
        if not values:
            return ""
        if len(values) == 1:
            return values[0]
        return ";".join(str(value) for value in values)

    def portal_common(portal_id: int) -> dict[str, object]:
        portal = portal_by_id.get(portal_id, {})
        return {
            "instance_portal_id": portal_id if portal_id else "",
            "instance_portal_name": text_by_id(strings, to_int(portal.get("localizedTextIdName"))) or portal.get("localizedTextIdName_text", ""),
            "instance_portal_type": to_int(portal.get("instancePortalTypeEnum")) if portal.get("instancePortalTypeEnum") else "",
            "portal_min_level": to_int(portal.get("minLevel")) if portal.get("minLevel") else "",
            "portal_max_level": to_int(portal.get("maxLevel")) if portal.get("maxLevel") else "",
            "expected_completion_time": to_int(portal.get("expectedCompletionTime")) if portal.get("expectedCompletionTime") else "",
        }

    output: list[dict[str, object]] = []
    linked_portal_ids: set[int] = set()
    for creature in sorted(creature_portal_rows, key=lambda row: (to_int(row.get("instancePortalId")), to_int(row.get("ID")))):
        portal_id = to_int(creature.get("instancePortalId"))
        linked_portal_ids.add(portal_id)
        creature_id = to_int(creature.get("ID"))
        bridge_rows = creature_bridges.get(creature_id, [])
        runtime_placement = REVIEWED_INSTANCE_PORTAL_PLACEMENTS.get((portal_id, creature_id))
        mapped_only_placement_blocker = MAPPED_ONLY_INSTANCE_PORTAL_PLACEMENT_BLOCKERS.get((portal_id, creature_id))
        output.append(
            {
                "evidence_kind": "instance_portal_creature",
                "source_table": "Creature2.tbl.sql",
                "source_row_id": creature_id,
                **portal_common(portal_id),
                "portal_link_status": "client_creature_linked" if portal_id in portal_by_id else "creature_references_missing_portal_definition",
                "creature2_id": creature_id,
                "creature_name": text_by_id(strings, to_int(creature.get("localizedTextIdName"))),
                "creature_min_level": to_int(creature.get("minLevel")) if creature.get("minLevel") else "",
                "creature_max_level": to_int(creature.get("maxLevel")) if creature.get("maxLevel") else "",
                "datamapping_bridge_status": (
                    "reviewed_datamapping_creature_bridge"
                    if runtime_placement
                    else bridge_status(bridge_rows)
                ),
                "datamapping_bridge_count": len(bridge_rows),
                "jabbithole_creature_ids": join_unique(row.get("jabbithole_creature_id") for row in bridge_rows),
                "datamapping_match_statuses": join_unique(row.get("match_status") for row in bridge_rows),
                "datamapping_review_decisions": join_unique(row.get("review_decision") for row in bridge_rows),
                "source_names": join_unique(row.get("source_name") for row in bridge_rows),
                "world_ids": join_unique(row.get("worldid") for row in bridge_rows),
                "world_zone_ids": join_unique(row.get("worldzoneid") for row in bridge_rows),
                "zone_ids": join_unique(row.get("zone_id") for row in bridge_rows),
                "runtime_placement_status": (
                    "reviewed_runtime_seed_placement_pending_exit_behavior_client_smoke"
                    if runtime_placement
                    else (
                        mapped_only_placement_blocker["runtime_placement_status"]
                        if mapped_only_placement_blocker
                        else "not_runtime_seed_reviewed"
                    )
                ),
                "runtime_entity_id": placement_value(runtime_placement, "runtime_entity_id"),
                "runtime_source_coordinate_id": placement_value(runtime_placement, "source_coordinate_id"),
                "runtime_world_id": placement_value(runtime_placement, "world_id", unique=True),
                "runtime_area_id": placement_value(runtime_placement, "area_id", unique=True),
                "evidence_status": (
                    "implemented_instance_portal_placement_model_pending_exit_behavior_client_smoke"
                    if runtime_placement
                    else (
                        mapped_only_placement_blocker["evidence_status"]
                        if mapped_only_placement_blocker
                        else instance_portal_evidence_status("instance_portal_creature", bridge_rows)
                    )
                ),
                "evidence_sources": (
                    "wildstar_client_mysql/InstancePortal.tbl.sql;wildstar_client_mysql/Creature2.tbl.sql;"
                    "Tools/DataMapping/output/client_source_instanceportal_map.csv;Tools/DataMapping/output/creature_map.csv;"
                    "Tools/DataMapping/creature_bridge_overrides.csv;"
                    "Tools/DataMapping/sql/apply_safe_world_imports_from_staging.sql;"
                    "Tools/DataMapping/export_runtime_world_seed.py;Tools/DataMapping/sql/runtime_world_seed.sql;"
                    "Tools/DataMapping/sql/verify_safe_world_imports.sql;"
                    "Tools/DataMapping/test_safe_world_import_source_coordinate_filter.py;"
                    "Source/NexusForever.Game/Entity/InstancePortalEntity.cs;"
                    "Source/NexusForever.WorldServer/Network/Message/Handler/Instance"
                    if runtime_placement
                    else (
                        "wildstar_client_mysql/InstancePortal.tbl.sql;wildstar_client_mysql/Creature2.tbl.sql;"
                        "Tools/DataMapping/output/client_source_instanceportal_map.csv;"
                        "Tools/DataMapping/output/creature_map.csv;Tools/DataMapping/output/creature_spawn_map.csv;"
                        "Tools/DataMapping/output/public_event_zone_map.csv;"
                        "Tools/DataMapping/output/creature_public_event_map.csv;"
                        "Tools/DataMapping/output/world_location_client_map.csv;"
                        "Source/NexusForever.Game/Entity/InstancePortalEntity.cs;"
                        "Source/NexusForever.WorldServer/Network/Message/Handler/Instance"
                        if mapped_only_placement_blocker
                        else "wildstar_client_mysql/InstancePortal.tbl.sql;wildstar_client_mysql/Creature2.tbl.sql;"
                        "Tools/DataMapping/output/client_source_instanceportal_map.csv;Tools/DataMapping/output/creature_map.csv;"
                        "Source/NexusForever.Game/Entity/InstancePortalEntity.cs;"
                        "Source/NexusForever.WorldServer/Network/Message/Handler/Instance"
                    )
                ),
                "manual_validation": "pending",
                "completion_status": "not_retail_complete",
                "blocker_summary": (
                    "Runtime-owned placement and InstancePortal model availability are implemented for "
                    f"{'entities' if len(placement_rows(runtime_placement)) > 1 else 'entity'} "
                    f"{placement_value(runtime_placement, 'runtime_entity_id')} at world "
                    f"{placement_value(runtime_placement, 'world_id', unique=True)} / area "
                    f"{placement_value(runtime_placement, 'area_id', unique=True)}, but retail completion remains "
                    "blocked on portal activation/exit "
                    "semantics, destination/return behavior, difficulty or prerequisite handling, and client smoke."
                    if runtime_placement
                    else (
                        mapped_only_placement_blocker["blocker_summary"]
                        if mapped_only_placement_blocker
                        else "Instance portal Creature2 link is tracked, but retail completion needs portal placement review, "
                        "level/prerequisite behavior, entry/exit or difficulty handling, queue/instance selection where relevant, "
                        "and client smoke."
                    )
                ),
            }
        )

    for portal_id in sorted(set(portal_by_id) - linked_portal_ids):
        output.append(
            {
                "evidence_kind": "instance_portal_definition",
                "source_table": "InstancePortal.tbl.sql",
                "source_row_id": portal_id,
                **portal_common(portal_id),
                "portal_link_status": "definition_without_creature_link",
                "creature2_id": "",
                "creature_name": "",
                "creature_min_level": "",
                "creature_max_level": "",
                "datamapping_bridge_status": "no_client_creature_link",
                "datamapping_bridge_count": 0,
                "jabbithole_creature_ids": "",
                "datamapping_match_statuses": "",
                "datamapping_review_decisions": "",
                "source_names": "",
                "world_ids": "",
                "world_zone_ids": "",
                "zone_ids": "",
                "runtime_placement_status": "not_runtime_seed_reviewed",
                "runtime_entity_id": "",
                "runtime_source_coordinate_id": "",
                "runtime_world_id": "",
                "runtime_area_id": "",
                "evidence_status": instance_portal_evidence_status("instance_portal_definition", []),
                "evidence_sources": "wildstar_client_mysql/InstancePortal.tbl.sql;Tools/DataMapping/output/client_source_instanceportal_map.csv;Source/NexusForever.Game/Entity/InstancePortalEntity.cs",
                "manual_validation": "pending",
                "completion_status": "not_retail_complete",
                "blocker_summary": "Instance portal definition has no current Creature2.instancePortalId link, so retail completion needs a creature/object bridge or rejection proof before it can support playable content.",
            }
        )

    return sorted(output, key=lambda item: (str(item["evidence_kind"]), to_int(str(item["instance_portal_id"])), to_int(str(item["source_row_id"]))))


def strip_csharp_comments_preserve_lines(text: str) -> str:
    output: list[str] = []
    index = 0
    in_string = False
    in_char = False
    in_line_comment = False
    in_block_comment = False
    verbatim_string = False

    while index < len(text):
        ch = text[index]
        next_ch = text[index + 1] if index + 1 < len(text) else ""

        if in_line_comment:
            if ch == "\n":
                in_line_comment = False
                output.append(ch)
            else:
                output.append(" ")
            index += 1
            continue

        if in_block_comment:
            if ch == "*" and next_ch == "/":
                output.extend([" ", " "])
                in_block_comment = False
                index += 2
            else:
                output.append("\n" if ch == "\n" else " ")
                index += 1
            continue

        if in_string:
            output.append(ch)
            if verbatim_string and ch == '"' and next_ch == '"':
                output.append(next_ch)
                index += 2
                continue
            if ch == '"' and (verbatim_string or index == 0 or text[index - 1] != "\\"):
                in_string = False
                verbatim_string = False
            index += 1
            continue

        if in_char:
            output.append(ch)
            if ch == "'" and (index == 0 or text[index - 1] != "\\"):
                in_char = False
            index += 1
            continue

        if ch == "/" and next_ch == "/":
            output.extend([" ", " "])
            in_line_comment = True
            index += 2
            continue

        if ch == "/" and next_ch == "*":
            output.extend([" ", " "])
            in_block_comment = True
            index += 2
            continue

        if ch == '"':
            in_string = True
            verbatim_string = index > 0 and text[index - 1] == "@"
            output.append(ch)
            index += 1
            continue

        if ch == "'":
            in_char = True
            output.append(ch)
            index += 1
            continue

        output.append(ch)
        index += 1

    return "".join(output)


def csharp_namespace(text: str) -> str:
    match = re.search(r"\bnamespace\s+([A-Za-z_][A-Za-z0-9_.]*)\s*(?:\{|;)", text)
    return match.group(1) if match else ""


def load_communicator_message_enums(script_roots: list[Path]) -> dict[str, dict[str, int]]:
    enum_pattern = re.compile(r"\benum\s+CommunicatorMessage\s*\{(.*?)\}", re.DOTALL)
    member_pattern = re.compile(r"\b([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(\d+)u?\b")
    enums: dict[str, dict[str, int]] = defaultdict(dict)

    for script_root in script_roots:
        for path in sorted(script_root.rglob("*.cs")):
            if "obj" in path.parts:
                continue
            text = path.read_text(encoding="utf-8", errors="replace")
            namespace = csharp_namespace(text)
            for enum_match in enum_pattern.finditer(text):
                for member_match in member_pattern.finditer(enum_match.group(1)):
                    enums[namespace][member_match.group(1)] = to_int(member_match.group(2))

    return dict(enums)


def resolve_communicator_message(
    namespace: str,
    member_name: str,
    communicator_enums: dict[str, dict[str, int]],
) -> tuple[int, str]:
    namespace_parts = namespace.split(".") if namespace else []
    for index in range(len(namespace_parts), 0, -1):
        candidate_namespace = ".".join(namespace_parts[:index])
        candidate_members = communicator_enums.get(candidate_namespace, {})
        if member_name in candidate_members:
            return candidate_members[member_name], candidate_namespace

    matches = [(enum_namespace, members[member_name]) for enum_namespace, members in communicator_enums.items() if member_name in members]
    if len(matches) == 1:
        return matches[0][1], matches[0][0]

    return 0, ""


def load_cinematic_implementations(cinematic_root: Path) -> dict[str, dict[str, object]]:
    class_pattern = re.compile(r"\bclass\s+([A-Za-z_][A-Za-z0-9_]*)\s*:\s*([^\{]+)")
    duration_pattern = re.compile(r"\bDuration\s*=\s*(\d+)u?\b")
    cinematic_id_pattern = re.compile(r"\bCinematicId\s*=\s*(\d+)u?\b")
    implementations: dict[str, dict[str, object]] = {}

    if not cinematic_root.exists():
        return implementations

    for path in sorted(cinematic_root.rglob("*.cs")):
        if "obj" in path.parts:
            continue
        text = path.read_text(encoding="utf-8", errors="replace")
        stripped = strip_csharp_comments_preserve_lines(text)
        class_match = class_pattern.search(stripped)
        if not class_match:
            continue

        class_name = class_match.group(1)
        base_types = [part.strip() for part in class_match.group(2).split(",")]
        interfaces = [part for part in base_types if re.fullmatch(r"I[A-Za-z_][A-Za-z0-9_]*", part)]
        duration_match = duration_pattern.search(stripped)
        cinematic_id_match = cinematic_id_pattern.search(stripped)
        duration_ms = to_int(duration_match.group(1)) if duration_match else 0
        cinematic_id = to_int(cinematic_id_match.group(1)) if cinematic_id_match else 0
        lower_text = text.lower()
        is_placeholder = (
            duration_ms == 0
            or cinematic_id == 0
            or "wip" in lower_text
            or "unmapped" in lower_text
            or "placeholder" in lower_text
        )

        for interface_name in interfaces:
            implementations[interface_name] = {
                "implementation_class": class_name,
                "implementation_path": relative_display_path(path, cinematic_root),
                "duration_ms": duration_ms if duration_match else "",
                "cinematic_id": cinematic_id if cinematic_id_match else "",
                "has_cinematic_id_assignment": bool(cinematic_id_match),
                "runtime_payload_status": "runtime_placeholder_or_wip_payload" if is_placeholder else "runtime_payload_present",
            }

    return implementations


def script_presentation_evidence_status(
    evidence_kind: str,
    client_link_status: str,
    runtime_payload_status: str = "",
) -> str:
    if evidence_kind == "script_communicator_message":
        if client_link_status == "client_row_matched":
            return "script_communicator_message_client_row_matched_pending_trigger_targeting_ui_smoke"
        if client_link_status == "unresolved_script_symbol":
            return "script_communicator_message_unresolved_symbol_blocked"
        return "script_communicator_message_missing_client_row_blocked"

    if evidence_kind == "script_cinematic_finish_hook":
        return "script_cinematic_finish_hook_pending_exact_cinematic_id_gate_and_smoke"

    if evidence_kind == "script_cinematic_reference":
        if runtime_payload_status == "implementation_missing":
            return "script_cinematic_interface_unimplemented_blocked"
        if runtime_payload_status == "runtime_placeholder_or_wip_payload":
            return "script_cinematic_placeholder_pending_payload_mapping"
        if client_link_status == "client_row_matched":
            return "script_cinematic_runtime_payload_present_pending_trigger_timing_client_smoke"
        if client_link_status in {"missing_runtime_cinematic_id", "zero_runtime_cinematic_id"}:
            return "script_cinematic_payload_missing_client_cinematic_id_pending_mapping"
        return "script_cinematic_id_missing_client_row_blocked"

    return "script_presentation_dependency_pending_review"


def build_script_presentation_evidence_rows(
    data_mapping_output: Path,
    script_roots: list[Path],
    cinematic_root: Path = DEFAULT_GAME_CINEMATICS,
) -> list[dict[str, object]]:
    communicator_client_rows = {
        to_int(row.get("ID")): row
        for row in load_csv_rows(data_mapping_output / "client_source_communicatormessages_map.csv")
    }
    cinematic_client_ids = {
        to_int(row.get("ID"))
        for row in load_csv_rows(data_mapping_output / "client_source_cinematic_map.csv")
        if to_int(row.get("ID"))
    }
    communicator_enums = load_communicator_message_enums(script_roots)
    cinematic_implementations = load_cinematic_implementations(cinematic_root)

    communicator_pattern = re.compile(r"\bCommunicatorMessage\.([A-Za-z_][A-Za-z0-9_]*)\b")
    generic_cinematic_pattern = re.compile(r"\b(?P<method>[A-Za-z_][A-Za-z0-9_\.]*)\s*<(?P<interface>I[A-Za-z_][A-Za-z0-9_]*)>\s*\(")
    cinematic_finish_pattern = re.compile(r"\bvoid\s+OnCinematicFinish\s*\([^)]*\)")
    owner_pattern = re.compile(r"ScriptFilterOwnerId\(([^)]+)\)")
    output: list[dict[str, object]] = []

    def script_scope(script_root: Path) -> str:
        try:
            return "script_main" if script_root.samefile(DEFAULT_SCRIPT_MAIN) else "script_instance"
        except OSError:
            return script_root.name

    def owner_ids(text: str) -> str:
        ids: set[int] = set()
        for match in owner_pattern.finditer(text):
            ids.update(to_int(value) for value in re.findall(r"\d+", match.group(1)) if to_int(value))
        return join_ids(sorted(ids))

    def line_number(text: str, index: int) -> int:
        return text.count("\n", 0, index) + 1

    for script_root in script_roots:
        for path in sorted(script_root.rglob("*.cs")):
            if "obj" in path.parts:
                continue
            text = path.read_text(encoding="utf-8", errors="replace")
            stripped = strip_csharp_comments_preserve_lines(text)
            namespace = csharp_namespace(text)
            relative_path = relative_display_path(path, script_root)
            scope = script_scope(script_root)
            script_owner_ids = owner_ids(text)

            for match in communicator_pattern.finditer(stripped):
                member_name = match.group(1)
                message_id, enum_namespace = resolve_communicator_message(namespace, member_name, communicator_enums)
                client_row = communicator_client_rows.get(message_id, {})
                client_link_status = "client_row_matched" if client_row else "client_row_missing" if message_id else "unresolved_script_symbol"
                output.append(
                    {
                        "evidence_kind": "script_communicator_message",
                        "script_scope": scope,
                        "source_path": relative_path,
                        "source_line": line_number(stripped, match.start()),
                        "script_owner_ids": script_owner_ids,
                        "source_call": "",
                        "source_symbol": f"CommunicatorMessage.{member_name}",
                        "reference_id": message_id if message_id else "",
                        "client_link_status": client_link_status,
                        "client_text": client_row.get("localizedTextIdMessage_text", ""),
                        "client_world_id": to_int(client_row.get("worldId")) if client_row.get("worldId") else "",
                        "client_world_zone_id": to_int(client_row.get("worldZoneId")) if client_row.get("worldZoneId") else "",
                        "client_creature_id": to_int(client_row.get("creatureId")) if client_row.get("creatureId") else "",
                        "cinematic_interface": "",
                        "cinematic_implementation_class": "",
                        "cinematic_implementation_path": "",
                        "cinematic_duration_ms": "",
                        "runtime_payload_status": "",
                        "enum_namespace": enum_namespace,
                        "evidence_status": script_presentation_evidence_status("script_communicator_message", client_link_status),
                        "evidence_sources": "Source/NexusForever.Script.Main;Source/NexusForever.Script.Instance;Tools/DataMapping/output/client_source_communicatormessages_map.csv;wildstar_client_mysql/CommunicatorMessages.tbl.sql;Source/NexusForever.Game/Quest",
                        "manual_validation": "pending",
                        "completion_status": "not_retail_complete",
                        "blocker_summary": "Scripted communicator message evidence is tracked, but retail completion needs exact trigger timing, recipient/faction targeting, chained message behavior, UI presentation, and content smoke.",
                    }
                )

            for match in generic_cinematic_pattern.finditer(stripped):
                method_name = match.group("method").split(".")[-1]
                if "Cinematic" not in method_name:
                    continue

                interface_name = match.group("interface")
                implementation = cinematic_implementations.get(interface_name, {})
                runtime_payload_status = str(implementation.get("runtime_payload_status", "implementation_missing"))
                cinematic_id = implementation.get("cinematic_id", "")
                cinematic_id_int = to_int(str(cinematic_id)) if cinematic_id != "" else 0
                if not implementation:
                    client_link_status = "implementation_missing"
                elif not implementation.get("has_cinematic_id_assignment"):
                    client_link_status = "missing_runtime_cinematic_id"
                elif cinematic_id_int == 0:
                    client_link_status = "zero_runtime_cinematic_id"
                elif cinematic_id_int in cinematic_client_ids:
                    client_link_status = "client_row_matched"
                else:
                    client_link_status = "client_row_missing"

                output.append(
                    {
                        "evidence_kind": "script_cinematic_reference",
                        "script_scope": scope,
                        "source_path": relative_path,
                        "source_line": line_number(stripped, match.start()),
                        "script_owner_ids": script_owner_ids,
                        "source_call": method_name,
                        "source_symbol": interface_name,
                        "reference_id": cinematic_id if cinematic_id != "" else "",
                        "client_link_status": client_link_status,
                        "client_text": "",
                        "client_world_id": "",
                        "client_world_zone_id": "",
                        "client_creature_id": "",
                        "cinematic_interface": interface_name,
                        "cinematic_implementation_class": implementation.get("implementation_class", ""),
                        "cinematic_implementation_path": implementation.get("implementation_path", ""),
                        "cinematic_duration_ms": implementation.get("duration_ms", ""),
                        "runtime_payload_status": runtime_payload_status,
                        "enum_namespace": "",
                        "evidence_status": script_presentation_evidence_status("script_cinematic_reference", client_link_status, runtime_payload_status),
                        "evidence_sources": "Source/NexusForever.Script.Main;Source/NexusForever.Script.Instance;Source/NexusForever.Game/Cinematic/Cinematics;Source/NexusForever.Game.Abstract/Cinematic/Cinematics;Tools/DataMapping/output/client_source_cinematic_map.csv;wildstar_client_mysql/Cinematic.tbl.sql",
                        "manual_validation": "pending",
                        "completion_status": "not_retail_complete",
                        "blocker_summary": "Scripted cinematic reference is tracked, but retail completion needs exact trigger/replay timing, Cinematic.tbl id linkage, actor/camera/text payload proof, completion callback behavior, and client smoke.",
                    }
                )

            for match in cinematic_finish_pattern.finditer(stripped):
                output.append(
                    {
                        "evidence_kind": "script_cinematic_finish_hook",
                        "script_scope": scope,
                        "source_path": relative_path,
                        "source_line": line_number(stripped, match.start()),
                        "script_owner_ids": script_owner_ids,
                        "source_call": "OnCinematicFinish",
                        "source_symbol": "cinematicId",
                        "reference_id": "",
                        "client_link_status": "runtime_callback_without_exact_client_id_gate",
                        "client_text": "",
                        "client_world_id": "",
                        "client_world_zone_id": "",
                        "client_creature_id": "",
                        "cinematic_interface": "",
                        "cinematic_implementation_class": "",
                        "cinematic_implementation_path": "",
                        "cinematic_duration_ms": "",
                        "runtime_payload_status": "runtime_finish_callback_present",
                        "enum_namespace": "",
                        "evidence_status": script_presentation_evidence_status("script_cinematic_finish_hook", "runtime_callback_without_exact_client_id_gate"),
                        "evidence_sources": "Source/NexusForever.Script.Main;Source/NexusForever.Script.Instance;Source/NexusForever.Game/Cinematic;wildstar_client_mysql/Cinematic.tbl.sql",
                        "manual_validation": "pending",
                        "completion_status": "not_retail_complete",
                        "blocker_summary": "Cinematic finish hook is tracked, but retail completion needs exact Cinematic.tbl id gating, replay/cancel behavior, progression side effects, and client smoke.",
                    }
                )

    return sorted(
        output,
        key=lambda item: (
            str(item["evidence_kind"]),
            str(item["script_scope"]),
            str(item["source_path"]),
            to_int(str(item["source_line"])),
            str(item["source_symbol"]),
        ),
    )


def load_script_enum_values(script_roots: list[Path], enum_name: str) -> dict[str, dict[str, int]]:
    enum_pattern = re.compile(rf"\benum\s+{re.escape(enum_name)}\s*\{{(.*?)\}}", re.DOTALL)
    member_pattern = re.compile(r"\b([A-Za-z_][A-Za-z0-9_]*)\b(?:\s*=\s*(\d+)u?)?")
    enum_values: dict[str, dict[str, int]] = defaultdict(dict)

    for script_root in script_roots:
        for path in sorted(script_root.rglob("*.cs")):
            if "obj" in path.parts:
                continue
            text = path.read_text(encoding="utf-8", errors="replace")
            stripped = strip_csharp_comments_preserve_lines(text)
            namespace = csharp_namespace(text)
            for enum_match in enum_pattern.finditer(stripped):
                current_value = -1
                for segment in split_top_level(enum_match.group(1)):
                    segment = segment.strip()
                    if not segment:
                        continue
                    match = member_pattern.match(segment)
                    if not match:
                        continue
                    if match.group(2) is not None:
                        current_value = to_int(match.group(2))
                    else:
                        current_value += 1
                    enum_values[namespace][match.group(1)] = current_value

    return dict(enum_values)


def resolve_script_enum_value(
    namespace: str,
    enum_values: dict[str, dict[str, int]],
    member_name: str,
) -> tuple[int, str]:
    namespace_parts = namespace.split(".") if namespace else []
    for index in range(len(namespace_parts), 0, -1):
        candidate_namespace = ".".join(namespace_parts[:index])
        candidate_members = enum_values.get(candidate_namespace, {})
        if member_name in candidate_members:
            return candidate_members[member_name], candidate_namespace

    matches = [(enum_namespace, members[member_name]) for enum_namespace, members in enum_values.items() if member_name in members]
    if len(matches) == 1:
        return matches[0][1], matches[0][0]

    return 0, ""


def classify_script_event_flow_call(line_text: str, enum_name: str) -> str:
    if "ActivateObjective(" in line_text:
        return "ActivateObjective"
    if "UpdateObjective(" in line_text:
        return "UpdateObjective"
    if "SetPhase(" in line_text:
        return "SetPhase"
    if "case " in line_text:
        return "switch_case"
    if enum_name == "PublicEventPhase" and ".Phase" in line_text:
        return "phase_guard"
    if enum_name == "PublicEventObjective" and "objective.Entry.Id" in line_text:
        return "objective_status_gate"
    return "reference"


def script_event_flow_evidence_status(evidence_kind: str, reference_link_status: str, owner_link_status: str) -> str:
    if evidence_kind == "script_public_event_objective_reference":
        if reference_link_status == "unresolved_script_symbol":
            return "script_public_event_objective_unresolved_symbol_blocked"
        if reference_link_status == "client_row_missing":
            return "script_public_event_objective_missing_client_row_blocked"
        if owner_link_status == "script_owner_matches_objective_public_event":
            return "script_public_event_objective_parent_event_matched_pending_activation_credit_smoke"
        return "script_public_event_objective_client_row_matched_pending_owner_flow_review"

    if evidence_kind == "script_public_event_phase_reference":
        if reference_link_status == "unresolved_script_symbol":
            return "script_public_event_phase_unresolved_symbol_blocked"
        if owner_link_status == "script_owner_matches_public_event":
            return "script_public_event_phase_script_state_owner_matched_pending_phase_order_smoke"
        return "script_public_event_phase_script_state_pending_owner_mapping_and_smoke"

    return "script_public_event_flow_pending_review"


def build_script_event_flow_evidence_rows(
    strings: dict[int, str],
    public_events: list[dict[str, str]],
    public_event_objectives: list[dict[str, str]],
    script_roots: list[Path],
) -> list[dict[str, object]]:
    public_event_by_id = {to_int(row["ID"]): row for row in public_events}
    objective_by_id = {to_int(row["ID"]): row for row in public_event_objectives}
    objective_enums = load_script_enum_values(script_roots, "PublicEventObjective")
    phase_enums = load_script_enum_values(script_roots, "PublicEventPhase")
    reference_patterns = {
        "script_public_event_objective_reference": ("PublicEventObjective", re.compile(r"\bPublicEventObjective\.([A-Za-z_][A-Za-z0-9_]*)\b")),
        "script_public_event_phase_reference": ("PublicEventPhase", re.compile(r"\bPublicEventPhase\.([A-Za-z_][A-Za-z0-9_]*)\b")),
    }
    owner_pattern = re.compile(r"ScriptFilterOwnerId\(([^)]+)\)")
    output: list[dict[str, object]] = []

    def script_scope(script_root: Path) -> str:
        try:
            return "script_main" if script_root.samefile(DEFAULT_SCRIPT_MAIN) else "script_instance"
        except OSError:
            return script_root.name

    def owner_ids(text: str) -> list[int]:
        ids: set[int] = set()
        for match in owner_pattern.finditer(text):
            ids.update(to_int(value) for value in re.findall(r"\d+", match.group(1)) if to_int(value))
        return sorted(ids)

    def line_number(text: str, index: int) -> int:
        return text.count("\n", 0, index) + 1

    def line_at(text: str, index: int) -> str:
        line_start = text.rfind("\n", 0, index) + 1
        line_end = text.find("\n", index)
        if line_end == -1:
            line_end = len(text)
        return text[line_start:line_end].strip()

    def event_name(event_id: int) -> str:
        event = public_event_by_id.get(event_id, {})
        return text_by_id(strings, to_int(event.get("localizedTextIdName")))

    def event_common(event_id: int) -> dict[str, object]:
        event = public_event_by_id.get(event_id, {})
        return {
            "public_event_id": event_id if event_id else "",
            "public_event_name": event_name(event_id),
            "public_event_world_id": to_int(event.get("worldId")) if event.get("worldId") else "",
            "public_event_world_zone_id": to_int(event.get("worldZoneId")) if event.get("worldZoneId") else "",
            "public_event_type": to_int(event.get("publicEventTypeEnum")) if event.get("publicEventTypeEnum") else "",
            "public_event_parent_id": to_int(event.get("publicEventIdParent")) if event.get("publicEventIdParent") else "",
        }

    def objective_common(objective_id: int) -> dict[str, object]:
        objective = objective_by_id.get(objective_id, {})
        return {
            "objective_type": to_int(objective.get("publicEventObjectiveTypeEnum")) if objective.get("publicEventObjectiveTypeEnum") else "",
            "objective_count": to_int(objective.get("count")) if objective.get("count") else "",
            "objective_object_id": to_int(objective.get("objectId")) if objective.get("objectId") else "",
            "objective_world_location_id": to_int(objective.get("worldLocation2Id")) if objective.get("worldLocation2Id") else "",
            "objective_target_group_id": to_int(objective.get("targetGroupIdRewardPane")) if objective.get("targetGroupIdRewardPane") else "",
            "objective_display_order": to_int(objective.get("displayOrder")) if objective.get("displayOrder") else "",
            "objective_text": text_by_id(strings, to_int(objective.get("localizedTextId"))),
            "objective_short_text": text_by_id(strings, to_int(objective.get("localizedTextIdShort"))),
        }

    for script_root in script_roots:
        for path in sorted(script_root.rglob("*.cs")):
            if "obj" in path.parts:
                continue
            text = path.read_text(encoding="utf-8", errors="replace")
            stripped = strip_csharp_comments_preserve_lines(text)
            namespace = csharp_namespace(text)
            relative_path = relative_display_path(path, script_root)
            scope = script_scope(script_root)
            script_owner_ids = owner_ids(text)
            owner_public_event_ids = [owner_id for owner_id in script_owner_ids if owner_id in public_event_by_id]

            for evidence_kind, (enum_name, pattern) in reference_patterns.items():
                enum_values = objective_enums if enum_name == "PublicEventObjective" else phase_enums
                for match in pattern.finditer(stripped):
                    member_name = match.group(1)
                    reference_id, enum_namespace = resolve_script_enum_value(namespace, enum_values, member_name)
                    source_line_text = line_at(stripped, match.start())
                    source_call = classify_script_event_flow_call(source_line_text, enum_name)

                    objective = objective_by_id.get(reference_id, {}) if enum_name == "PublicEventObjective" else {}
                    objective_event_id = to_int(objective.get("publicEventId"))
                    if enum_name == "PublicEventObjective":
                        reference_link_status = "client_row_matched" if objective else "client_row_missing" if reference_id else "unresolved_script_symbol"
                        owner_link_status = (
                            "script_owner_matches_objective_public_event"
                            if objective_event_id in script_owner_ids
                            else "script_owner_is_related_public_event"
                            if set(owner_public_event_ids)
                            else "script_owner_not_public_event"
                        )
                        public_event_id = objective_event_id
                    else:
                        reference_link_status = "script_enum_value_resolved" if enum_namespace else "unresolved_script_symbol"
                        owner_link_status = "script_owner_matches_public_event" if owner_public_event_ids else "script_owner_not_public_event"
                        public_event_id = owner_public_event_ids[0] if len(owner_public_event_ids) == 1 else 0

                    source_line = line_number(stripped, match.start())
                    row = {
                        "evidence_kind": evidence_kind,
                        "script_scope": scope,
                        "source_path": relative_path,
                        "source_line": source_line,
                        "script_owner_ids": join_ids(script_owner_ids),
                        "source_call": source_call,
                        "source_symbol": f"{enum_name}.{member_name}",
                        "reference_id": reference_id if reference_id or enum_namespace else "",
                        "reference_link_status": reference_link_status,
                        "owner_link_status": owner_link_status,
                        **event_common(public_event_id),
                        **objective_common(reference_id if enum_name == "PublicEventObjective" else 0),
                        "enum_namespace": enum_namespace,
                        "evidence_status": script_event_flow_evidence_status(evidence_kind, reference_link_status, owner_link_status),
                        "evidence_sources": "Source/NexusForever.Script.Main;Source/NexusForever.Script.Instance;wildstar_client_mysql/PublicEvent.tbl.sql;wildstar_client_mysql/PublicEventObjective.tbl.sql;Source/NexusForever.Game/PublicEvent",
                        "manual_validation": "pending",
                        "completion_status": "not_retail_complete",
                        "blocker_summary": (
                            "Scripted public-event objective reference is tracked, but retail completion needs exact activation/update timing, producer semantics, objective credit, phase progression, reward/challenge side effects, and content smoke."
                            if enum_name == "PublicEventObjective"
                            else "Scripted public-event phase reference is tracked as script-owned state, but retail completion needs phase order proof, objective activation timing, replay/cancel behavior, and content smoke."
                        ),
                    }
                    row.update(
                        SCRIPT_EVENT_FLOW_EVIDENCE_OVERRIDES.get(
                            (relative_path, source_line, evidence_kind, source_call, f"{enum_name}.{member_name}"),
                            {},
                        )
                    )
                    output.append(row)

    return sorted(
        output,
        key=lambda item: (
            str(item["evidence_kind"]),
            str(item["script_scope"]),
            str(item["source_path"]),
            to_int(str(item["source_line"])),
            str(item["source_symbol"]),
        ),
    )


def load_public_event_objective_type_values() -> dict[str, int]:
    path = ROOT / "Source" / "NexusForever.Game.Static" / "PublicEvent" / "PublicEventObjectiveType.cs"
    text = path.read_text(encoding="utf-8", errors="replace")
    stripped = strip_csharp_comments_preserve_lines(text)
    enum_match = re.search(r"\benum\s+PublicEventObjectiveType\s*\{(.*?)\}", stripped, re.DOTALL)
    if not enum_match:
        return {}

    values: dict[str, int] = {}
    current_value = -1
    for segment in split_top_level(enum_match.group(1)):
        segment = segment.strip()
        if not segment:
            continue
        match = re.match(r"\b([A-Za-z_][A-Za-z0-9_]*)\b(?:\s*=\s*([A-Za-z_][A-Za-z0-9_]*|\d+)u?)?", segment)
        if not match:
            continue
        name = match.group(1)
        assigned = match.group(2)
        if assigned is None:
            current_value += 1
        elif assigned.isdigit():
            current_value = to_int(assigned)
        elif assigned in values:
            current_value = values[assigned]
        else:
            continue
        values[name] = current_value
    return values


def load_quest_objective_type_values() -> dict[str, int]:
    path = ROOT / "Source" / "NexusForever.Game.Static" / "Quest" / "QuestObjectiveType.cs"
    text = path.read_text(encoding="utf-8", errors="replace")
    stripped = strip_csharp_comments_preserve_lines(text)
    enum_match = re.search(r"\benum\s+QuestObjectiveType\s*\{(.*?)\}", stripped, re.DOTALL)
    if not enum_match:
        return {}

    values: dict[str, int] = {}
    current_value = -1
    for segment in split_top_level(enum_match.group(1)):
        segment = segment.strip()
        if not segment:
            continue
        match = re.match(r"\b([A-Za-z_][A-Za-z0-9_]*)\b(?:\s*=\s*([A-Za-z_][A-Za-z0-9_]*|\d+)u?)?", segment)
        if not match:
            continue
        name = match.group(1)
        assigned = match.group(2)
        if assigned is None:
            current_value += 1
        elif assigned.isdigit():
            current_value = to_int(assigned)
        elif assigned in values:
            current_value = values[assigned]
        else:
            continue
        values[name] = current_value
    return values


def build_script_objective_producer_evidence_rows(
    strings: dict[int, str],
    public_events: list[dict[str, str]],
    public_event_objectives: list[dict[str, str]],
    script_roots: list[Path],
) -> list[dict[str, object]]:
    public_event_by_id = {to_int(row["ID"]): row for row in public_events}
    objective_by_id = {to_int(row["ID"]): row for row in public_event_objectives}
    objectives_by_type_object: dict[tuple[int, int], list[dict[str, str]]] = defaultdict(list)
    for objective in public_event_objectives:
        objectives_by_type_object[(to_int(objective.get("publicEventObjectiveTypeEnum")), to_int(objective.get("objectId")))].append(objective)

    objective_enums = load_script_enum_values(script_roots, "PublicEventObjective")
    objective_type_values = load_public_event_objective_type_values()
    objective_type_names = {value: name for name, value in objective_type_values.items()}
    credit_base_pattern = re.compile(r":\s*base\s*\(((?:[^()]|\([^)]*\))*)\)", re.DOTALL)
    class_pattern = re.compile(r"\bclass\s+([A-Za-z_][A-Za-z0-9_]*)")
    script_name_pattern = re.compile(r"ScriptFilterScriptName\(\"([^\"]+)\"\)")
    owner_pattern = re.compile(r"ScriptFilterOwnerId\(([^)]+)\)")
    const_pattern = re.compile(r"\bconst\s+(?:uint|int)\s+([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(\d+)u?\s*;")
    output: list[dict[str, object]] = []

    def script_scope(script_root: Path) -> str:
        try:
            return "script_main" if script_root.samefile(DEFAULT_SCRIPT_MAIN) else "script_instance"
        except OSError:
            return script_root.name

    def owner_ids(text: str) -> list[int]:
        ids: set[int] = set()
        for match in owner_pattern.finditer(text):
            ids.update(to_int(value) for value in re.findall(r"\d+", match.group(1)) if to_int(value))
        return sorted(ids)

    def line_number(text: str, index: int) -> int:
        return text.count("\n", 0, index) + 1

    def source_excerpt(text: str, index: int) -> str:
        line_start = text.rfind("\n", 0, index) + 1
        line_end = text.find("\n", index)
        if line_end == -1:
            line_end = len(text)
        return re.sub(r"\s+", " ", text[line_start:line_end].strip())

    def is_method_declaration(text: str, index: int) -> bool:
        line_start = text.rfind("\n", 0, index) + 1
        line_prefix = text[line_start:index]
        return re.search(r"\b(?:private|protected|public|internal)\b", line_prefix) is not None

    def iter_invocations(text: str, method_name: str) -> Iterator[tuple[int, str]]:
        pattern = re.compile(rf"\b{re.escape(method_name)}\s*\(")
        for match in pattern.finditer(text):
            depth = 1
            index = match.end()
            start = index
            quote = ""
            escaped = False
            while index < len(text):
                char = text[index]
                if quote:
                    if escaped:
                        escaped = False
                    elif char == "\\":
                        escaped = True
                    elif char == quote:
                        quote = ""
                elif char in {'"', "'"}:
                    quote = char
                elif char == "(":
                    depth += 1
                elif char == ")":
                    depth -= 1
                    if depth == 0:
                        yield match.start(), text[start:index]
                        break
                index += 1

    def clean_expression(expression: str) -> str:
        expression = expression.strip()
        expression = re.sub(r"^\(\s*uint\s*\)", "", expression).strip()
        if re.fullmatch(r"\d+[uU]", expression):
            expression = expression[:-1]
        return expression

    def resolve_objective(expression: str, namespace: str, const_values: dict[str, int]) -> tuple[int, str, str]:
        expression = clean_expression(expression)
        enum_match = re.fullmatch(r"PublicEventObjective\.([A-Za-z_][A-Za-z0-9_]*)", expression)
        if enum_match:
            value, enum_namespace = resolve_script_enum_value(namespace, objective_enums, enum_match.group(1))
            return value, f"PublicEventObjective.{enum_match.group(1)}", enum_namespace
        if expression in const_values:
            return const_values[expression], expression, ""
        if re.fullmatch(r"\d+", expression):
            return to_int(expression), expression, ""
        return 0, expression, ""

    def resolve_objective_references(expression: str, namespace: str, const_values: dict[str, int]) -> list[tuple[int, str, str]]:
        objective_id, source_symbol, enum_namespace = resolve_objective(expression, namespace, const_values)
        if objective_id or "?" not in expression or ":" not in expression:
            return [(objective_id, source_symbol, enum_namespace)]

        resolved: list[tuple[int, str, str]] = []
        seen_symbols: set[str] = set()
        for enum_match in re.finditer(r"PublicEventObjective\.[A-Za-z_][A-Za-z0-9_]*", expression):
            symbol = enum_match.group(0)
            if symbol in seen_symbols:
                continue
            seen_symbols.add(symbol)
            resolved.append(resolve_objective(symbol, namespace, const_values))
        return resolved or [(objective_id, source_symbol, enum_namespace)]

    def resolve_objective_type(expression: str) -> tuple[int, str]:
        expression = clean_expression(expression)
        type_match = re.fullmatch(r"PublicEventObjectiveType\.([A-Za-z_][A-Za-z0-9_]*)", expression)
        if not type_match:
            return 0, expression
        type_name = type_match.group(1)
        return objective_type_values.get(type_name, 0), type_name

    def resolve_object_id(expression: str, const_values: dict[str, int]) -> tuple[int, str]:
        expression = clean_expression(expression)
        if expression in const_values:
            return const_values[expression], expression
        if re.fullmatch(r"\d+", expression):
            return to_int(expression), expression
        return 0, expression

    def event_name(event_id: int) -> str:
        event = public_event_by_id.get(event_id, {})
        return text_by_id(strings, to_int(event.get("localizedTextIdName")))

    def objective_name(objective: dict[str, str]) -> str:
        return text_by_id(strings, to_int(objective.get("localizedTextId"))) or text_by_id(strings, to_int(objective.get("localizedTextIdShort")))

    def join_limited(values: Iterable[int], limit: int = 20) -> str:
        unique = sorted({value for value in values if value})
        if len(unique) > limit:
            return ";".join(str(value) for value in unique[:limit]) + f";...+{len(unique) - limit}"
        return join_ids(unique)

    def owner_link_status(script_owner_ids: list[int], matched_objectives: list[dict[str, str]]) -> str:
        matched_event_ids = {to_int(row.get("publicEventId")) for row in matched_objectives if to_int(row.get("publicEventId"))}
        if matched_event_ids and matched_event_ids.intersection(script_owner_ids):
            return "script_owner_matches_public_event"
        if any(owner_id in public_event_by_id for owner_id in script_owner_ids):
            return "script_owner_is_different_public_event"
        if script_owner_ids:
            return "script_owner_entity_or_trigger"
        return "script_owner_unknown"

    kill_style_objective_type_names = {
        "KillClusterEventObjectiveUnit",
        "KillClusterEventUnit",
        "KillClusterTargetGroup",
        "KillEventObjectiveUnit",
        "KillEventUnit",
        "KillOtherTeam",
        "KillTargetGroup",
    }
    checklist_objective_type_names = {
        "ActivateTargetGroupChecklist",
        "TalkToChecklist",
    }

    def evidence_status(
        evidence_kind: str,
        producer_targeting: str,
        reference_link_status: str,
        owner_status: str,
        match_count: int,
        objective_type_name: str = "",
    ) -> str:
        if reference_link_status in {"direct_objective_row_matched", "typed_objective_row_matched"}:
            if objective_type_name in checklist_objective_type_names:
                if owner_status == "script_owner_matches_public_event":
                    return "runtime_public_event_checklist_objective_bitfield_routing_tested_pending_content_smoke"
                return "script_objective_producer_checklist_matched_pending_owner_flow_review"
            if producer_targeting == "direct_objective" and objective_type_name in kill_style_objective_type_names:
                if owner_status == "script_owner_matches_public_event":
                    return "direct_objective_id_matches_client_kill_type_pending_timing_and_script_type_review"
                return "direct_objective_id_matches_client_kill_type_pending_owner_and_script_type_review"
            if objective_type_name in {"ScriptWithoutCount", "ScriptWithoutMax"}:
                status_prefix = "script_without_count" if objective_type_name == "ScriptWithoutCount" else "script_without_max"
                action = "activation" if evidence_kind.startswith("script_activate_objective") else "credit"
                if owner_status == "script_owner_matches_public_event":
                    return f"{status_prefix}_direct_objective_{action}_matched_pending_timing_smoke"
                return f"{status_prefix}_direct_objective_{action}_matched_pending_owner_flow_review"
            if owner_status == "script_owner_matches_public_event":
                return "script_objective_producer_matched_pending_credit_timing_smoke"
            return "script_objective_producer_matched_pending_owner_flow_review"
        if reference_link_status == "typed_objective_broad_match":
            return "script_objective_producer_broad_type_object_match_pending_owner_review"
        if reference_link_status == "no_client_objective_match":
            return "script_objective_producer_no_client_objective_match_blocked"
        if evidence_kind == "script_objective_credit_base":
            return "script_objective_credit_base_unresolved_objective_blocked"
        return "script_objective_producer_unresolved_symbol_blocked"

    def blocker_summary(evidence_kind: str, producer_targeting: str, objective_type_name: str) -> str:
        if objective_type_name in checklist_objective_type_names:
            return "Public-event checklist objective producer is runtime-backed with QuestChecklistIdx bitfield routing into ObjectiveData, duplicate/invalid bit replay guards, and focused script-producer coverage. Retail completion still needs row-specific producer timing, owner/event routing where applicable, reward/challenge side effects, and content smoke."
        if producer_targeting == "direct_objective" and objective_type_name in kill_style_objective_type_names:
            return "Direct objective-id script producer matches a client kill-style public-event objective row; do not treat this as generic kill-style routing until script-vs-kill semantics, exact producer timing, owner/event routing, objective credit behavior, repeated/negative delta handling, reward/challenge side effects, and content smoke are proven."
        if objective_type_name in {"ScriptWithoutCount", "ScriptWithoutMax"}:
            action = "activation" if evidence_kind.startswith("script_activate_objective") else "credit"
            return f"Direct objective-id script {action} matches a client {objective_type_name} public-event objective row; keep this script-only objective separate from KillTargetGroup/KillEventUnit routing until exact script trigger timing, owner/event routing, objective credit behavior, repeated/negative delta handling, reward/challenge side effects, and content smoke are proven."
        return "Scripted public-event objective producer is tracked, but retail completion needs exact producer trigger timing, owner/event routing, objective credit behavior, repeated/negative delta handling, reward/challenge side effects, and content smoke."

    def build_row(
        evidence_kind: str,
        scope: str,
        relative_path: str,
        line: int,
        script_owner_ids: list[int],
        source_call: str,
        source_symbol: str,
        producer_targeting: str,
        objective_id: int,
        objective_type_id: int,
        objective_type_name: str,
        object_id: int,
        update_count: str,
        matched_objectives: list[dict[str, str]],
        reference_link_status: str,
        owner_status: str,
        enum_namespace: str,
        script_filter_name: str,
        excerpt: str,
    ) -> dict[str, object]:
        matched_objective = matched_objectives[0] if matched_objectives else {}
        row_objective_type_id = objective_type_id
        row_objective_type_name = objective_type_name
        row_object_id = object_id
        if matched_objective:
            matched_type_id = to_int(matched_objective.get("publicEventObjectiveTypeEnum"))
            if not row_objective_type_name and (matched_type_id or matched_type_id == 0):
                row_objective_type_id = matched_type_id
                row_objective_type_name = objective_type_names.get(matched_type_id, "")
            if producer_targeting == "direct_objective":
                row_object_id = to_int(matched_objective.get("objectId"))
        if not row_objective_type_name and producer_targeting == "unresolved":
            row_objective_type_name = "unresolved"

        row_objective_id = objective_id
        if not row_objective_id and producer_targeting == "typed_objective" and len(matched_objectives) == 1:
            row_objective_id = to_int(matched_objectives[0].get("ID"))

        matched_event_ids = sorted({to_int(row.get("publicEventId")) for row in matched_objectives if to_int(row.get("publicEventId"))})
        row = {
            "evidence_kind": evidence_kind,
            "script_scope": scope,
            "source_path": relative_path,
            "source_line": line,
            "script_owner_ids": join_ids(script_owner_ids),
            "script_filter_name": script_filter_name,
            "source_call": source_call,
            "source_symbol": source_symbol,
            "source_excerpt": excerpt,
            "producer_targeting": producer_targeting,
            "objective_id": row_objective_id if row_objective_id else "",
            "objective_type_id": row_objective_type_id
            if row_objective_type_name != "unresolved" and (row_objective_type_name or row_objective_type_id)
            else "",
            "objective_type_name": row_objective_type_name,
            "object_id": row_object_id if row_object_id or producer_targeting == "typed_objective" else "",
            "update_count": update_count,
            "matched_objective_count": len(matched_objectives),
            "matched_public_event_objective_ids": join_limited(to_int(row.get("ID")) for row in matched_objectives),
            "matched_public_event_ids": join_limited(matched_event_ids),
            "matched_public_event_names": ";".join(event_name(event_id) for event_id in matched_event_ids[:20] if event_name(event_id)),
            "matched_objective_names": ";".join(objective_name(row) for row in matched_objectives[:20] if objective_name(row)),
            "reference_link_status": reference_link_status,
            "owner_link_status": owner_status,
            "enum_namespace": enum_namespace,
            "evidence_status": evidence_status(
                evidence_kind,
                producer_targeting,
                reference_link_status,
                owner_status,
                len(matched_objectives),
                row_objective_type_name,
            ),
            "evidence_sources": "Source/NexusForever.Script.Main;Source/NexusForever.Script.Instance;Source/NexusForever.Game/PublicEvent;Source/NexusForever.Game.Static/PublicEvent/PublicEventObjectiveType.cs;wildstar_client_mysql/PublicEvent.tbl.sql;wildstar_client_mysql/PublicEventObjective.tbl.sql",
            "manual_validation": "pending",
            "completion_status": "not_retail_complete",
            "blocker_summary": blocker_summary(evidence_kind, producer_targeting, row_objective_type_name),
        }
        override_key = (
            relative_path,
            str(row["matched_public_event_objective_ids"]),
            str(row["object_id"]),
        )
        override = SCRIPT_OBJECTIVE_PRODUCER_OVERRIDES.get(override_key)
        instance_dependency_world_id = 0
        if relative_path.startswith("Source\\NexusForever.Script.Instance\\WorldStory\\HallOfTheHundred\\"):
            instance_dependency_world_id = 3009
        elif relative_path.startswith("Source\\NexusForever.Script.Instance\\Expedition\\Gauntlet\\"):
            instance_dependency_world_id = 2183

        if not override and instance_dependency_world_id:
            matched_objective_ids = [
                to_int(part)
                for part in str(row["matched_public_event_objective_ids"]).split(";")
                if to_int(part)
            ]
            if len(matched_objective_ids) == 1:
                dependency_override = INSTANCE_OBJECTIVE_DEPENDENCY_OVERRIDES.get(
                    (instance_dependency_world_id, matched_objective_ids[0]),
                    {},
                )
                if dependency_override:
                    override = {
                        key: dependency_override[key]
                        for key in [
                            "script_owner_ids",
                            "evidence_status",
                            "evidence_sources",
                            "manual_validation",
                            "blocker_summary",
                        ]
                        if key in dependency_override
                    }
                    if row["owner_link_status"] == "script_owner_unknown":
                        override["owner_link_status"] = "script_owner_entity_filter_mapped_to_public_event"
        if override:
            row.update(override)
        return row

    def append_direct_objective_rows(
        evidence_kind: str,
        scope: str,
        relative_path: str,
        call_start: int,
        script_owner_ids: list[int],
        source_call: str,
        objective_expression: str,
        update_count: str,
        namespace: str,
        const_values: dict[str, int],
        script_filter_name: str,
        excerpt: str,
    ) -> None:
        resolved_references = resolve_objective_references(objective_expression, namespace, const_values)
        if (
            len(resolved_references) == 1
            and not resolved_references[0][0]
            and clean_expression(objective_expression) in {"Objective", "objective", "objectiveId"}
        ):
            return

        for objective_id, source_symbol, enum_namespace in resolved_references:
            matched_objectives = [objective_by_id[objective_id]] if objective_id in objective_by_id else []
            reference_link_status = "direct_objective_row_matched" if matched_objectives else "no_client_objective_match" if objective_id else "unresolved_symbol"
            owner_status = owner_link_status(script_owner_ids, matched_objectives)
            output.append(
                build_row(
                    evidence_kind,
                    scope,
                    relative_path,
                    line_number(stripped, call_start),
                    script_owner_ids,
                    source_call,
                    source_symbol,
                    "direct_objective" if objective_id else "unresolved",
                    objective_id,
                    0,
                    "",
                    0,
                    update_count,
                    matched_objectives,
                    reference_link_status,
                    owner_status,
                    enum_namespace,
                    script_filter_name,
                    excerpt,
                )
            )

    for script_root in script_roots:
        for path in sorted(script_root.rglob("*.cs")):
            if "obj" in path.parts:
                continue
            text = path.read_text(encoding="utf-8", errors="replace")
            stripped = strip_csharp_comments_preserve_lines(text)
            namespace = csharp_namespace(text)
            const_values = {match.group(1): to_int(match.group(2)) for match in const_pattern.finditer(stripped)}
            relative_path = relative_display_path(path, script_root)
            scope = script_scope(script_root)
            script_owner_ids = owner_ids(text)
            script_name_match = script_name_pattern.search(text)
            script_filter_name = script_name_match.group(1) if script_name_match else ""

            if "PublicEventObjectiveCreditEntityScript" in stripped and path.name != "PublicEventObjectiveCreditEntityScript.cs":
                class_match = class_pattern.search(stripped)
                class_name = class_match.group(1) if class_match else path.stem
                for match in credit_base_pattern.finditer(stripped):
                    args = split_top_level(match.group(1))
                    if not args:
                        continue
                    objective_args = args[2:] if len(args) > 2 else [args[-1]]
                    for objective_arg in objective_args:
                        objective_id, source_symbol, enum_namespace = resolve_objective(objective_arg, namespace, const_values)
                        matched_objectives = [objective_by_id[objective_id]] if objective_id in objective_by_id else []
                        reference_link_status = "direct_objective_row_matched" if matched_objectives else "no_client_objective_match" if objective_id else "unresolved_symbol"
                        owner_status = owner_link_status(script_owner_ids, matched_objectives)
                        output.append(
                            build_row(
                                "script_objective_credit_base",
                                scope,
                                relative_path,
                                line_number(stripped, match.start()),
                                script_owner_ids,
                                "PublicEventObjectiveCreditEntityScript",
                                source_symbol or class_name,
                                "direct_objective",
                                objective_id,
                                0,
                                "",
                                0,
                                "1",
                                matched_objectives,
                                reference_link_status,
                                owner_status,
                                enum_namespace,
                                script_filter_name,
                                source_excerpt(stripped, match.start()),
                            )
                        )

            for match in credit_base_pattern.finditer(stripped):
                args = split_top_level(match.group(1))
                if len(args) < 2:
                    continue
                if not re.fullmatch(r"PublicEventObjectiveType\.[A-Za-z_][A-Za-z0-9_]*", clean_expression(args[0])):
                    continue
                objective_type_id, objective_type_name = resolve_objective_type(args[0])
                object_id, _ = resolve_object_id(args[1], const_values)
                if not object_id:
                    continue
                matched_objectives = objectives_by_type_object.get((objective_type_id, object_id), [])
                if matched_objectives and any(owner_id in public_event_by_id for owner_id in script_owner_ids):
                    matched_objectives = [row for row in matched_objectives if to_int(row.get("publicEventId")) in script_owner_ids] or matched_objectives
                reference_link_status = (
                    "typed_objective_row_matched"
                    if 0 < len(matched_objectives) <= 20
                    else "typed_objective_broad_match"
                    if len(matched_objectives) > 20
                    else "no_client_objective_match"
                )
                owner_status = owner_link_status(script_owner_ids, matched_objectives)
                output.append(
                    build_row(
                        "script_typed_objective_credit_base",
                        scope,
                        relative_path,
                        line_number(stripped, match.start()),
                        script_owner_ids,
                        "typed_objective_base",
                        f"PublicEventObjectiveType.{objective_type_name}",
                        "typed_objective",
                        0,
                        objective_type_id,
                        objective_type_name,
                        object_id,
                        "1",
                        matched_objectives,
                        reference_link_status,
                        owner_status,
                        "",
                        script_filter_name,
                        source_excerpt(stripped, match.start()),
                    )
                )

            if path.name == "PublicEventObjectiveCreditEntityScript.cs":
                continue

            for call_start, call_args in iter_invocations(stripped, "UpdateObjective"):
                args = split_top_level(call_args)
                if not args:
                    continue
                type_index = next((index for index, arg in enumerate(args) if "PublicEventObjectiveType." in arg), -1)
                if type_index != -1 and type_index + 2 < len(args):
                    objective_type_id, objective_type_name = resolve_objective_type(args[type_index])
                    object_id, object_symbol = resolve_object_id(args[type_index + 1], const_values)
                    update_count = clean_expression(args[type_index + 2])
                    matched_objectives = objectives_by_type_object.get((objective_type_id, object_id), []) if objective_type_id or object_id else []
                    if matched_objectives and any(owner_id in public_event_by_id for owner_id in script_owner_ids):
                        matched_objectives = [row for row in matched_objectives if to_int(row.get("publicEventId")) in script_owner_ids] or matched_objectives
                    reference_link_status = (
                        "typed_objective_row_matched"
                        if 0 < len(matched_objectives) <= 20
                        else "typed_objective_broad_match"
                        if len(matched_objectives) > 20
                        else "no_client_objective_match"
                    )
                    owner_status = owner_link_status(script_owner_ids, matched_objectives)
                    output.append(
                        build_row(
                            "script_update_objective_call",
                            scope,
                            relative_path,
                            line_number(stripped, call_start),
                            script_owner_ids,
                            "UpdateObjective",
                            f"PublicEventObjectiveType.{objective_type_name}" if objective_type_name else clean_expression(args[type_index]),
                            "typed_objective",
                            0,
                            objective_type_id,
                            objective_type_name,
                            object_id,
                            update_count,
                            matched_objectives,
                            reference_link_status,
                            owner_status,
                            "",
                            script_filter_name,
                            source_excerpt(stripped, call_start),
                        )
                    )
                    continue

                update_count = clean_expression(args[1]) if len(args) > 1 else ""
                append_direct_objective_rows(
                    "script_update_objective_call",
                    scope,
                    relative_path,
                    call_start,
                    script_owner_ids,
                    "UpdateObjective",
                    args[0],
                    update_count,
                    namespace,
                    const_values,
                    script_filter_name,
                    source_excerpt(stripped, call_start),
                )

            for call_start, call_args in iter_invocations(stripped, "ActivateObjective"):
                args = split_top_level(call_args)
                if not args:
                    continue
                update_count = clean_expression(args[1]) if len(args) > 1 else ""
                append_direct_objective_rows(
                    "script_activate_objective_call",
                    scope,
                    relative_path,
                    call_start,
                    script_owner_ids,
                    "ActivateObjective",
                    args[0],
                    update_count,
                    namespace,
                    const_values,
                    script_filter_name,
                    source_excerpt(stripped, call_start),
                )

            for call_start, call_args in iter_invocations(stripped, "ActivateWipOptionalObjective"):
                if is_method_declaration(stripped, call_start):
                    continue
                args = split_top_level(call_args)
                if not args:
                    continue
                append_direct_objective_rows(
                    "script_activate_objective_helper_call",
                    scope,
                    relative_path,
                    call_start,
                    script_owner_ids,
                    "ActivateWipOptionalObjective",
                    args[0],
                    clean_expression(args[1]) if len(args) > 1 else "wip_optional_roll",
                    namespace,
                    const_values,
                    script_filter_name,
                    source_excerpt(stripped, call_start),
                )

            for call_start, call_args in iter_invocations(stripped, "SeedParticipantsInRangeObjective"):
                if is_method_declaration(stripped, call_start):
                    continue
                args = split_top_level(call_args)
                if not args:
                    continue
                append_direct_objective_rows(
                    "script_update_objective_helper_call",
                    scope,
                    relative_path,
                    call_start,
                    script_owner_ids,
                    "SeedParticipantsInRangeObjective",
                    args[0],
                    "range_participant_count",
                    namespace,
                    const_values,
                    script_filter_name,
                    source_excerpt(stripped, call_start),
                )

    has_default_script_instance = False
    for script_root in script_roots:
        try:
            if script_root.samefile(DEFAULT_SCRIPT_INSTANCE):
                has_default_script_instance = True
                break
        except OSError:
            continue
    if has_default_script_instance:
        existing_rows = {
            (
                str(row["source_path"]),
                str(row["matched_public_event_objective_ids"]),
                str(row["object_id"]),
            )
            for row in output
        }
        for manual_row in SCRIPT_OBJECTIVE_PRODUCER_MANUAL_DIRECT_OBJECTIVES:
            objective_id = to_int(str(manual_row["objective_id"]))
            matched_objectives = [objective_by_id[objective_id]] if objective_id in objective_by_id else []
            object_id = to_int(matched_objectives[0].get("objectId")) if matched_objectives else 0
            output_key = (str(manual_row["source_path"]), str(objective_id), str(object_id))
            if output_key in existing_rows:
                continue

            output.append(
                build_row(
                    "script_update_objective_inherited_trigger",
                    "script_instance",
                    str(manual_row["source_path"]),
                    to_int(str(manual_row["source_line"])),
                    list(manual_row["script_owner_ids"]),
                    "SkullcanoGroupObjectiveTriggerScript.UpdateObjective",
                    str(manual_row["source_symbol"]),
                    "direct_objective",
                    objective_id,
                    0,
                    "",
                    0,
                    str(manual_row["update_count"]),
                    matched_objectives,
                    "direct_objective_row_matched" if matched_objectives else "no_client_objective_match",
                    owner_link_status(list(manual_row["script_owner_ids"]), matched_objectives),
                    "NexusForever.Script.Instance.Dungeon.Skullcano",
                    "",
                    str(manual_row["source_excerpt"]),
                )
            )

    return sorted(
        output,
        key=lambda item: (
            str(item["evidence_kind"]),
            str(item["script_scope"]),
            str(item["source_path"]),
            to_int(str(item["source_line"])),
            str(item["source_symbol"]),
        ),
    )


def build_script_quest_progression_evidence_rows(
    strings: dict[int, str],
    quests: list[dict[str, str]],
    quest_output: list[dict[str, object]],
    objective_rows: list[dict[str, str]],
    achievements: list[dict[str, str]],
    script_main: Path,
) -> list[dict[str, object]]:
    quest_by_id = {to_int(row["ID"]): row for row in quests}
    quest_status_by_id = {to_int(str(row["quest_id"])): row for row in quest_output}
    objective_by_id = {to_int(row["ID"]): row for row in objective_rows}
    objective_claims = build_objective_claim_index(quests)
    achievement_by_id = {to_int(row["ID"]): row for row in achievements}
    objective_type_values = load_quest_objective_type_values()
    objective_type_names = {value: name for name, value in objective_type_values.items()}

    objectives_by_type_object: dict[tuple[int, int], list[dict[str, str]]] = defaultdict(list)
    for objective in objective_rows:
        objectives_by_type_object[(to_int(objective.get("type")), to_int(objective.get("data")))].append(objective)

    owner_pattern = re.compile(r"ScriptFilterOwnerId\(([^)]+)\)")
    creature_pattern = re.compile(r"ScriptFilterCreatureId\(([^)]+)\)")
    script_name_pattern = re.compile(r"ScriptFilterScriptName\(\"([^\"]+)\"\)")
    const_pattern = re.compile(r"\b(?:const|static\s+readonly)\s+(?:s?byte|u?short|u?int|u?long)\s+([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(\d+)u?\s*;")
    output: list[dict[str, object]] = []

    def script_scope(script_root: Path) -> str:
        try:
            return "script_main" if script_root.samefile(DEFAULT_SCRIPT_MAIN) else script_root.name
        except OSError:
            return script_root.name

    def filter_ids(text: str, pattern: re.Pattern[str]) -> list[int]:
        ids: set[int] = set()
        for match in pattern.finditer(text):
            ids.update(to_int(value) for value in re.findall(r"\d+", match.group(1)) if to_int(value))
        return sorted(ids)

    def matching_brace_index(text: str, open_brace_index: int) -> int:
        depth = 0
        index = open_brace_index
        quote = ""
        escaped = False
        while index < len(text):
            char = text[index]
            if quote:
                if escaped:
                    escaped = False
                elif char == "\\":
                    escaped = True
                elif char == quote:
                    quote = ""
            elif char in {'"', "'"}:
                quote = char
            elif char == "{":
                depth += 1
            elif char == "}":
                depth -= 1
                if depth == 0:
                    return index
            index += 1
        return -1

    def script_filter_contexts(text: str) -> list[dict[str, object]]:
        contexts: list[dict[str, object]] = []
        previous_class_end = 0
        for match in re.finditer(r"\bclass\s+([A-Za-z_][A-Za-z0-9_]*)\b", text):
            open_brace_index = text.find("{", match.end())
            if open_brace_index == -1:
                continue
            close_brace_index = matching_brace_index(text, open_brace_index)
            if close_brace_index == -1:
                continue
            header = text[previous_class_end:match.start()]
            script_name_match = script_name_pattern.search(header)
            contexts.append(
                {
                    "start": open_brace_index,
                    "end": close_brace_index,
                    "owner_ids": filter_ids(header, owner_pattern),
                    "creature_ids": filter_ids(header, creature_pattern),
                    "script_filter_name": script_name_match.group(1) if script_name_match else "",
                }
            )
            previous_class_end = close_brace_index + 1
        return contexts

    def script_filter_context(
        contexts: list[dict[str, object]],
        text: str,
        call_start: int,
    ) -> tuple[list[int], list[int], str]:
        for context in contexts:
            if to_int(str(context["start"])) <= call_start <= to_int(str(context["end"])):
                return (
                    list(context["owner_ids"]),  # type: ignore[arg-type]
                    list(context["creature_ids"]),  # type: ignore[arg-type]
                    str(context["script_filter_name"]),
                )
        script_name_match = script_name_pattern.search(text)
        return filter_ids(text, owner_pattern), filter_ids(text, creature_pattern), script_name_match.group(1) if script_name_match else ""

    def context_block_for_call(contexts: list[dict[str, object]], text: str, call_start: int) -> str:
        for context in contexts:
            if to_int(str(context["start"])) <= call_start <= to_int(str(context["end"])):
                return text[to_int(str(context["start"])) : to_int(str(context["end"])) + 1]
        return text

    def quest_state_guard_ids_for_call(
        contexts: list[dict[str, object]],
        text: str,
        call_start: int,
        const_values: dict[str, int],
    ) -> list[int]:
        block = context_block_for_call(contexts, text, call_start)
        quest_ids: set[int] = set()
        for guard_match in re.finditer(r"\bGetQuestState\s*\(([^)]*)\)", block):
            quest_id, _, _ = resolve_numeric_reference(guard_match.group(1), const_values)
            if quest_id in quest_by_id:
                quest_ids.add(quest_id)
        return sorted(quest_ids)

    def line_number(text: str, index: int) -> int:
        return text.count("\n", 0, index) + 1

    def source_excerpt(text: str, index: int) -> str:
        line_start = text.rfind("\n", 0, index) + 1
        line_end = text.find("\n", index)
        if line_end == -1:
            line_end = len(text)
        return re.sub(r"\s+", " ", text[line_start:line_end].strip())

    def clean_expression(expression: str) -> str:
        expression = expression.strip()
        expression = re.sub(r"^\(\s*(?:ushort|uint|int)\s*\)", "", expression).strip()
        if re.fullmatch(r"\d+[uU]", expression):
            expression = expression[:-1]
        return expression

    def iter_invocations(text: str, method_name: str) -> Iterator[tuple[int, str]]:
        pattern = re.compile(rf"\b{re.escape(method_name)}\s*\(")
        for match in pattern.finditer(text):
            depth = 1
            index = match.end()
            start = index
            quote = ""
            escaped = False
            while index < len(text):
                char = text[index]
                if quote:
                    if escaped:
                        escaped = False
                    elif char == "\\":
                        escaped = True
                    elif char == quote:
                        quote = ""
                elif char in {'"', "'"}:
                    quote = char
                elif char == "(":
                    depth += 1
                elif char == ")":
                    depth -= 1
                    if depth == 0:
                        yield match.start(), text[start:index]
                        break
                index += 1

    def is_method_declaration_line(text: str, call_start: int, method_name: str) -> bool:
        line = source_excerpt(text, call_start)
        return re.match(rf"(?:public|private|protected|internal)\s+.*\b{re.escape(method_name)}\s*\(", line) is not None

    def resolve_numeric_reference(expression: str, const_values: dict[str, int]) -> tuple[int, str, str]:
        expression = clean_expression(expression)
        if expression in const_values:
            return const_values[expression], expression, "numeric_constant_resolved"
        if re.fullmatch(r"\d+", expression):
            return to_int(expression), expression, "numeric_literal_resolved"
        return 0, expression, "source_expression_tracked" if expression else "source_expression_empty"

    def resolve_objective_type(expression: str) -> tuple[int, str]:
        expression = clean_expression(expression)
        type_match = re.fullmatch(r"QuestObjectiveType\.([A-Za-z_][A-Za-z0-9_]*)", expression)
        if not type_match:
            return 0, expression
        type_name = type_match.group(1)
        return objective_type_values.get(type_name, 0), type_name

    def quest_title(quest_id: int) -> str:
        quest = quest_by_id.get(quest_id, {})
        return text_by_id(strings, to_int(quest.get("localizedTextIdTitle")))

    def objective_text(objective: dict[str, str]) -> str:
        return text_by_id(strings, to_int(objective.get("localizedTextIdFull"))) or text_by_id(strings, to_int(objective.get("localizedTextIdShort")))

    def achievement_title(achievement_id: int) -> str:
        achievement = achievement_by_id.get(achievement_id, {})
        return text_by_id(strings, to_int(achievement.get("localizedTextIdTitle")))

    def join_limited(values: Iterable[int], limit: int = 20) -> str:
        unique = sorted({value for value in values if value})
        if len(unique) > limit:
            return ";".join(str(value) for value in unique[:limit]) + f";...+{len(unique) - limit}"
        return join_ids(unique)

    def quest_ids_for_objectives(matched_objectives: list[dict[str, str]]) -> list[int]:
        quest_ids: set[int] = set()
        for objective in matched_objectives:
            for claim in objective_claims.get(to_int(objective.get("ID")), []):
                quest_ids.add(to_int(str(claim.get("quest_id"))))
        return sorted(quest_ids)

    def achievement_quest_ids(achievement: dict[str, str] | None) -> list[int]:
        if not achievement or to_int(achievement.get("achievementTypeId")) not in QUEST_ACHIEVEMENT_TYPES:
            return []
        return sorted({to_int(achievement.get("objectId")), to_int(achievement.get("objectIdAlt"))} - {0})

    def owner_link_status(script_owner_ids: list[int], matched_quest_ids: list[int], source_trace_detail: str = "") -> str:
        if set(script_owner_ids).intersection(matched_quest_ids):
            return "script_owner_matches_quest"
        guard_match = re.search(r"\bguard_quest_ids=([^;]+)", source_trace_detail)
        if not script_owner_ids and guard_match:
            guard_quest_ids = {to_int(value) for value in re.findall(r"\d+", guard_match.group(1))}
            if guard_quest_ids.intersection(matched_quest_ids):
                return "quest_state_guard_matches_quest"
        if any(owner_id in quest_by_id for owner_id in script_owner_ids):
            return "script_owner_is_other_current_quest"
        if script_owner_ids:
            return "script_owner_not_current_quest"
        return "script_owner_not_declared"

    def choose_quest_id(script_owner_ids: list[int], matched_quest_ids: list[int]) -> int:
        matching_owner_ids = sorted(set(script_owner_ids).intersection(matched_quest_ids))
        if matching_owner_ids:
            return matching_owner_ids[0]
        if len(matched_quest_ids) == 1:
            return matched_quest_ids[0]
        owner_quest_ids = sorted(owner_id for owner_id in script_owner_ids if owner_id in quest_by_id)
        return owner_quest_ids[0] if len(owner_quest_ids) == 1 else 0

    def trace_status(reference_link_status: str, source_symbol: str, source_trace_detail: str = "") -> tuple[str, str, str]:
        if reference_link_status in {"direct_objective_row_matched", "quest_row_matched", "achievement_row_matched", "typed_objective_row_matched"}:
            return "literal_or_constant_client_reference_tracked", source_trace_detail or source_symbol, "Source/NexusForever.Script.Main;wildstar_client_mysql"
        if reference_link_status == "typed_objective_broad_match":
            return "typed_objective_client_reference_broad_match", source_trace_detail or source_symbol, "Source/NexusForever.Script.Main;wildstar_client_mysql/QuestObjective.tbl.sql"
        if "dynamic" in reference_link_status:
            return "dynamic_progression_source_expression_tracked", source_trace_detail or source_symbol, "Source/NexusForever.Script.Main"
        return "progression_source_pending_resolution", source_trace_detail or source_symbol, "Source/NexusForever.Script.Main;wildstar_client_mysql"

    def evidence_status(evidence_kind: str, reference_link_status: str, owner_status: str) -> str:
        if reference_link_status in {"direct_objective_row_missing", "typed_objective_no_client_match", "quest_row_missing", "achievement_row_missing"}:
            return f"{evidence_kind}_missing_client_row_blocked"
        if reference_link_status in {"unresolved_symbol", "unresolved_quest_symbol", "unresolved_achievement_symbol"}:
            return f"{evidence_kind}_unresolved_symbol_blocked"
        if reference_link_status == "dynamic_quest_info":
            return "script_quest_add_dynamic_quest_info_pending_trace"
        if reference_link_status in {"dynamic_objective_expression", "typed_objective_dynamic_object"}:
            return f"{evidence_kind}_dynamic_runtime_context_pending_trace"
        if evidence_kind == "script_quest_objective_update":
            if owner_status in {"script_owner_matches_quest", "quest_state_guard_matches_quest"}:
                return "script_quest_objective_update_matched_pending_trigger_smoke"
            return "script_quest_objective_update_matched_pending_owner_review"
        if evidence_kind == "script_quest_typed_objective_update":
            if reference_link_status == "typed_objective_broad_match":
                return "script_quest_typed_objective_update_broad_match_pending_owner_review"
            if owner_status in {"script_owner_matches_quest", "quest_state_guard_matches_quest"}:
                return "script_quest_typed_objective_update_matched_pending_trigger_smoke"
            return "script_quest_typed_objective_update_matched_pending_owner_review"
        if evidence_kind == "script_quest_achieve":
            return "script_quest_achieve_target_matched_pending_state_smoke"
        if evidence_kind == "script_quest_mention":
            return "script_quest_mention_target_matched_pending_visibility_smoke"
        if evidence_kind == "script_quest_add":
            return "script_quest_add_target_matched_pending_acceptance_smoke"
        if evidence_kind == "script_achievement_grant":
            return "script_achievement_grant_target_matched_pending_unlock_smoke"
        return "script_quest_progression_pending_review"

    def blocker_summary(evidence_kind: str) -> str:
        if evidence_kind in {"script_quest_objective_update", "script_quest_typed_objective_update"}:
            return "Scripted quest objective progression hook is tracked, but retail completion needs exact trigger timing, objective state, repeat/overcredit behavior, reward side effects, and quest smoke."
        if evidence_kind == "script_quest_add":
            return "Scripted quest grant hook is tracked, but retail completion needs prerequisite, duplicate, visibility, accept-state, and quest-chain smoke."
        if evidence_kind == "script_quest_mention":
            return "Scripted quest mention hook is tracked, but retail completion needs visibility, prerequisite, UI, and follow-up quest smoke."
        if evidence_kind == "script_quest_achieve":
            return "Scripted quest achieve hook is tracked, but retail completion needs accepted-state gating, completion side effects, reward availability, and client smoke."
        return "Scripted achievement grant hook is tracked, but retail completion needs exact unlock conditions, duplicate behavior, quest/progression linkage, rewards/titles, and achievement UI smoke."

    def build_row(
        *,
        evidence_kind: str,
        scope: str,
        relative_path: str,
        stripped: str,
        call_start: int,
        script_owner_ids: list[int],
        script_creature_ids: list[int],
        script_filter_name: str,
        source_call: str,
        source_symbol: str,
        progression_targeting: str,
        matched_objectives: list[dict[str, str]],
        matched_quest_ids: list[int],
        reference_link_status: str,
        objective_id: int = 0,
        objective_type_id: int = 0,
        objective_type_name: str = "",
        object_id: int | str = "",
        update_count: str = "",
        achievement_id: int = 0,
        source_trace_detail: str = "",
    ) -> dict[str, object]:
        source_line = line_number(stripped, call_start)
        owner_status = owner_link_status(script_owner_ids, matched_quest_ids, source_trace_detail)
        selected_quest_id = choose_quest_id(script_owner_ids, matched_quest_ids)
        quest_status = quest_status_by_id.get(selected_quest_id, {})
        source_trace_status, trace_detail, source_trace_sources = trace_status(reference_link_status, source_symbol, source_trace_detail)
        matched_objective_ids = sorted(to_int(row.get("ID")) for row in matched_objectives if to_int(row.get("ID")))
        row = {
            "evidence_kind": evidence_kind,
            "script_scope": scope,
            "source_path": relative_path,
            "source_line": source_line,
            "script_owner_ids": join_ids(script_owner_ids),
            "script_creature_ids": join_ids(script_creature_ids),
            "script_filter_name": script_filter_name,
            "source_call": source_call,
            "source_symbol": source_symbol,
            "source_excerpt": source_excerpt(stripped, call_start),
            "progression_targeting": progression_targeting,
            "quest_id": selected_quest_id if selected_quest_id else "",
            "quest_title": quest_title(selected_quest_id),
            "quest_bucket": quest_status.get("bucket", ""),
            "quest_completion_status": quest_status.get("completion_status", ""),
            "objective_id": objective_id if objective_id else "",
            "objective_type_id": objective_type_id if objective_type_id else "",
            "objective_type_name": objective_type_name,
            "object_id": object_id,
            "update_count": update_count,
            "achievement_id": achievement_id if achievement_id else "",
            "achievement_title": achievement_title(achievement_id),
            "matched_quest_ids": join_limited(matched_quest_ids),
            "matched_quest_titles": ";".join(quest_title(quest_id) for quest_id in matched_quest_ids[:20] if quest_title(quest_id)),
            "matched_quest_objective_ids": join_limited(matched_objective_ids),
            "matched_objective_text": ";".join(objective_text(row) for row in matched_objectives[:20] if objective_text(row)),
            "reference_link_status": reference_link_status,
            "owner_link_status": owner_status,
            "source_trace_status": source_trace_status,
            "source_trace_detail": trace_detail,
            "source_trace_sources": source_trace_sources,
            "evidence_status": evidence_status(evidence_kind, reference_link_status, owner_status),
            "evidence_sources": "Source/NexusForever.Script.Main;wildstar_client_mysql/Quest2.tbl.sql;wildstar_client_mysql/QuestObjective.tbl.sql;wildstar_client_mysql/Achievement.tbl.sql;Source/NexusForever.Game/Quest;Source/NexusForever.Game/Achievement",
            "manual_validation": "pending",
            "completion_status": "not_retail_complete",
            "blocker_summary": blocker_summary(evidence_kind),
        }
        row.update(
            SCRIPT_QUEST_PROGRESSION_EVIDENCE_OVERRIDES.get(
                (relative_path, source_line, evidence_kind, source_symbol),
                {},
            )
        )
        return row

    def resolve_quest_add_target(expression: str, stripped: str, call_start: int, const_values: dict[str, int]) -> tuple[int, str, str, str]:
        expression = clean_expression(expression)
        get_info_match = re.search(r"\bGetQuestInfo\s*\((.*)\)\s*$", expression)
        if get_info_match:
            quest_id, symbol, link_status = resolve_numeric_reference(get_info_match.group(1), const_values)
            return quest_id, f"GetQuestInfo({symbol})", link_status, expression

        if re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", expression):
            prefix = stripped[:call_start]
            assignment_pattern = re.compile(
                rf"\b(?:IQuestInfo|var)\s+{re.escape(expression)}\s*=\s*[^;]*?\bGetQuestInfo\s*\(([^;)]*)\)\s*;",
                re.DOTALL,
            )
            matches = list(assignment_pattern.finditer(prefix))
            if matches:
                arg = matches[-1].group(1)
                quest_id, symbol, link_status = resolve_numeric_reference(arg, const_values)
                return quest_id, f"{expression}<-{symbol}", link_status, f"{expression}=GetQuestInfo({clean_expression(arg)})"

        quest_id, symbol, link_status = resolve_numeric_reference(expression, const_values)
        return quest_id, symbol, link_status, expression

    script_root = script_main
    scope = script_scope(script_root)
    for path in sorted(script_root.rglob("*.cs")):
        if "obj" in path.parts:
            continue
        text = path.read_text(encoding="utf-8", errors="replace")
        stripped = strip_csharp_comments_preserve_lines(text)
        relative_path = relative_display_path(path, script_root)
        contexts = script_filter_contexts(stripped)
        const_values = {match.group(1): to_int(match.group(2)) for match in const_pattern.finditer(stripped)}

        for call_start, call_args in iter_invocations(stripped, "ObjectiveUpdate"):
            if is_method_declaration_line(stripped, call_start, "ObjectiveUpdate"):
                continue
            args = split_top_level(call_args)
            if not args:
                continue
            script_owner_ids, script_creature_ids, script_filter_name = script_filter_context(contexts, stripped, call_start)

            objective_type_id = 0
            objective_type_name = ""
            if "QuestObjectiveType." in args[0]:
                objective_type_id, objective_type_name = resolve_objective_type(args[0])
                object_id, object_symbol, object_link_status = resolve_numeric_reference(args[1], const_values) if len(args) > 1 else (0, "", "source_expression_empty")
                update_count = clean_expression(args[2]) if len(args) > 2 else ""
                matched_objectives = objectives_by_type_object.get((objective_type_id, object_id), []) if objective_type_id and object_id else []
                if matched_objectives and any(owner_id in quest_by_id for owner_id in script_owner_ids):
                    owner_filtered = [
                        row
                        for row in matched_objectives
                        if set(script_owner_ids).intersection(to_int(str(claim.get("quest_id"))) for claim in objective_claims.get(to_int(row.get("ID")), []))
                    ]
                    matched_objectives = owner_filtered or matched_objectives
                matched_quest_ids = quest_ids_for_objectives(matched_objectives)
                guard_quest_ids = quest_state_guard_ids_for_call(contexts, stripped, call_start, const_values)
                if not matched_quest_ids:
                    matched_quest_ids = guard_quest_ids
                reference_link_status = (
                    "typed_objective_row_matched"
                    if 0 < len(matched_objectives) <= 20
                    else "typed_objective_broad_match"
                    if len(matched_objectives) > 20
                    else "typed_objective_dynamic_object"
                    if object_link_status.startswith("source_expression")
                    else "typed_objective_no_client_match"
                )
                output.append(
                    build_row(
                        evidence_kind="script_quest_typed_objective_update",
                        scope=scope,
                        relative_path=relative_path,
                        stripped=stripped,
                        call_start=call_start,
                        script_owner_ids=script_owner_ids,
                        script_creature_ids=script_creature_ids,
                        script_filter_name=script_filter_name,
                        source_call="ObjectiveUpdate",
                        source_symbol=f"QuestObjectiveType.{objective_type_name}" if objective_type_name else clean_expression(args[0]),
                        progression_targeting="typed_quest_objective",
                        matched_objectives=matched_objectives,
                        matched_quest_ids=matched_quest_ids,
                        reference_link_status=reference_link_status,
                        objective_type_id=objective_type_id,
                        objective_type_name=objective_type_name,
                        object_id=object_id if object_id else object_symbol,
                        update_count=update_count,
                        source_trace_detail=f"object_id={object_symbol};object_link_status={object_link_status};guard_quest_ids={join_ids(guard_quest_ids)}",
                    )
                )
                continue

            objective_id, source_symbol, link_status = resolve_numeric_reference(args[0], const_values)
            update_count = clean_expression(args[1]) if len(args) > 1 else ""
            matched_objectives = [objective_by_id[objective_id]] if objective_id in objective_by_id else []
            matched_quest_ids = quest_ids_for_objectives(matched_objectives)
            reference_link_status = (
                "direct_objective_row_matched"
                if matched_objectives
                else "direct_objective_row_missing"
                if objective_id
                else "dynamic_objective_expression"
                if link_status.startswith("source_expression")
                else "unresolved_symbol"
            )
            objective = matched_objectives[0] if len(matched_objectives) == 1 else {}
            objective_type_id = to_int(objective.get("type")) if objective else 0
            output.append(
                build_row(
                    evidence_kind="script_quest_objective_update",
                    scope=scope,
                    relative_path=relative_path,
                    stripped=stripped,
                    call_start=call_start,
                    script_owner_ids=script_owner_ids,
                    script_creature_ids=script_creature_ids,
                    script_filter_name=script_filter_name,
                    source_call="ObjectiveUpdate",
                    source_symbol=source_symbol,
                    progression_targeting="direct_quest_objective" if objective_id else "dynamic_objective",
                    matched_objectives=matched_objectives,
                    matched_quest_ids=matched_quest_ids,
                    reference_link_status=reference_link_status,
                    objective_id=objective_id,
                    objective_type_id=objective_type_id,
                    objective_type_name=objective_type_names.get(objective_type_id, ""),
                    object_id=to_int(objective.get("data")) if objective else "",
                    update_count=update_count,
                    source_trace_detail=f"objective_expression={clean_expression(args[0])};link_status={link_status}",
                )
            )

        quest_call_specs = {
            "QuestAchieve": "script_quest_achieve",
            "QuestMention": "script_quest_mention",
        }
        for method_name, evidence_kind in quest_call_specs.items():
            for call_start, call_args in iter_invocations(stripped, method_name):
                if is_method_declaration_line(stripped, call_start, method_name):
                    continue
                args = split_top_level(call_args)
                if not args:
                    continue
                script_owner_ids, script_creature_ids, script_filter_name = script_filter_context(contexts, stripped, call_start)
                quest_id, source_symbol, link_status = resolve_numeric_reference(args[0], const_values)
                matched_quest_ids = [quest_id] if quest_id in quest_by_id else []
                reference_link_status = "quest_row_matched" if matched_quest_ids else "quest_row_missing" if quest_id else "unresolved_quest_symbol"
                output.append(
                    build_row(
                        evidence_kind=evidence_kind,
                        scope=scope,
                        relative_path=relative_path,
                        stripped=stripped,
                        call_start=call_start,
                        script_owner_ids=script_owner_ids,
                        script_creature_ids=script_creature_ids,
                        script_filter_name=script_filter_name,
                        source_call=method_name,
                        source_symbol=source_symbol,
                        progression_targeting="quest_id",
                        matched_objectives=[],
                        matched_quest_ids=matched_quest_ids,
                        reference_link_status=reference_link_status,
                        source_trace_detail=f"quest_expression={clean_expression(args[0])};link_status={link_status}",
                    )
                )

        for call_start, call_args in iter_invocations(stripped, "QuestAdd"):
            if is_method_declaration_line(stripped, call_start, "QuestAdd"):
                continue
            args = split_top_level(call_args)
            if not args:
                continue
            script_owner_ids, script_creature_ids, script_filter_name = script_filter_context(contexts, stripped, call_start)
            quest_id, source_symbol, link_status, source_trace_detail = resolve_quest_add_target(args[0], stripped, call_start, const_values)
            matched_quest_ids = [quest_id] if quest_id in quest_by_id else []
            reference_link_status = "quest_row_matched" if matched_quest_ids else "quest_row_missing" if quest_id else "dynamic_quest_info"
            output.append(
                build_row(
                    evidence_kind="script_quest_add",
                    scope=scope,
                    relative_path=relative_path,
                    stripped=stripped,
                    call_start=call_start,
                    script_owner_ids=script_owner_ids,
                    script_creature_ids=script_creature_ids,
                    script_filter_name=script_filter_name,
                    source_call="QuestAdd",
                    source_symbol=source_symbol,
                    progression_targeting="quest_info",
                    matched_objectives=[],
                    matched_quest_ids=matched_quest_ids,
                    reference_link_status=reference_link_status,
                    source_trace_detail=f"quest_info_source={source_trace_detail};link_status={link_status}",
                )
            )

        for call_start, call_args in iter_invocations(stripped, "GrantAchievement"):
            if is_method_declaration_line(stripped, call_start, "GrantAchievement"):
                continue
            args = split_top_level(call_args)
            if not args:
                continue
            script_owner_ids, script_creature_ids, script_filter_name = script_filter_context(contexts, stripped, call_start)
            achievement_id, source_symbol, link_status = resolve_numeric_reference(args[0], const_values)
            achievement = achievement_by_id.get(achievement_id)
            matched_quest_ids = achievement_quest_ids(achievement)
            reference_link_status = "achievement_row_matched" if achievement else "achievement_row_missing" if achievement_id else "unresolved_achievement_symbol"
            output.append(
                build_row(
                    evidence_kind="script_achievement_grant",
                    scope=scope,
                    relative_path=relative_path,
                    stripped=stripped,
                    call_start=call_start,
                    script_owner_ids=script_owner_ids,
                    script_creature_ids=script_creature_ids,
                    script_filter_name=script_filter_name,
                    source_call="GrantAchievement",
                    source_symbol=source_symbol,
                    progression_targeting="achievement_id",
                    matched_objectives=[],
                    matched_quest_ids=matched_quest_ids,
                    reference_link_status=reference_link_status,
                    achievement_id=achievement_id,
                    source_trace_detail=f"achievement_expression={clean_expression(args[0])};link_status={link_status}",
                )
            )

    return sorted(
        output,
        key=lambda item: (
            str(item["script_scope"]),
            str(item["source_path"]),
            to_int(str(item["source_line"])),
            str(item["evidence_kind"]),
            str(item["source_symbol"]),
        ),
    )


def build_script_runtime_action_evidence_rows(
    script_roots: list[Path],
    spells: list[dict[str, str]] | None = None,
    worlds: list[dict[str, str]] | None = None,
    world_locations: list[dict[str, str]] | None = None,
) -> list[dict[str, object]]:
    owner_pattern = re.compile(r"ScriptFilterOwnerId\(([^)]+)\)")
    script_name_pattern = re.compile(r"ScriptFilterScriptName\(\"([^\"]+)\"\)")
    const_pattern = re.compile(r"\bconst\s+(?:s?byte|u?short|u?int|u?long)\s+([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(\d+)u?\s*;")
    generic_create_pattern = re.compile(r"\b[A-Za-z_][A-Za-z0-9_\.]*\s*\.\s*CreateEntity\s*<\s*([A-Za-z_][A-Za-z0-9_<>.,\s]*)\s*>\s*\(")
    method_categories = {
        "CastSpell": ("script_spell_cast", "spell4_id", "script_spell_cast_pending_spell_effect_targeting_smoke"),
        "TeleportTo": ("script_teleport", "world_or_location", "script_teleport_pending_destination_access_smoke"),
        "TeleportToLocal": ("script_local_teleport", "local_position", "script_local_teleport_pending_destination_access_smoke"),
        "EnqueueAdd": ("script_entity_add_to_map", "entity_or_position", "script_entity_add_to_map_pending_spawn_lifecycle_smoke"),
        "RemoveFromMap": ("script_entity_remove_from_map", "entity_or_guid", "script_entity_remove_from_map_pending_cleanup_smoke"),
        "Finish": ("script_public_event_finish", "public_event_team", "script_public_event_finish_pending_reward_completion_smoke"),
    }
    spell_by_id = {to_int(row.get("ID")): row for row in spells or []}
    world_by_id = {to_int(row.get("ID")): row for row in worlds or []}
    world_location_by_id = {to_int(row.get("ID")): row for row in world_locations or []}
    output: list[dict[str, object]] = []

    def script_scope(script_root: Path) -> str:
        try:
            return "script_main" if script_root.samefile(DEFAULT_SCRIPT_MAIN) else "script_instance"
        except OSError:
            return script_root.name

    def owner_ids(text: str) -> list[int]:
        ids: set[int] = set()
        for match in owner_pattern.finditer(text):
            ids.update(to_int(value) for value in re.findall(r"\d+", match.group(1)) if to_int(value))
        return sorted(ids)

    def line_number(text: str, index: int) -> int:
        return text.count("\n", 0, index) + 1

    def source_excerpt(text: str, index: int) -> str:
        line_start = text.rfind("\n", 0, index) + 1
        line_end = text.find("\n", index)
        if line_end == -1:
            line_end = len(text)
        return re.sub(r"\s+", " ", text[line_start:line_end].strip())

    def clean_expression(expression: str) -> str:
        expression = expression.strip()
        expression = re.sub(r"^\(\s*ushort\s*\)", "", expression).strip()
        expression = re.sub(r"^\(\s*uint\s*\)", "", expression).strip()
        if re.fullmatch(r"\d+[uU]", expression):
            expression = expression[:-1]
        return expression

    def iter_invocations(text: str, method_name: str) -> Iterator[tuple[int, str]]:
        pattern = re.compile(rf"\b{re.escape(method_name)}\s*\(")
        for match in pattern.finditer(text):
            depth = 1
            index = match.end()
            start = index
            quote = ""
            escaped = False
            while index < len(text):
                char = text[index]
                if quote:
                    if escaped:
                        escaped = False
                    elif char == "\\":
                        escaped = True
                    elif char == quote:
                        quote = ""
                elif char in {'"', "'"}:
                    quote = char
                elif char == "(":
                    depth += 1
                elif char == ")":
                    depth -= 1
                    if depth == 0:
                        yield match.start(), text[start:index]
                        break
                index += 1

    def resolve_reference(expression: str, const_values: dict[str, int]) -> tuple[str, object, str]:
        expression = clean_expression(expression)
        if expression in const_values:
            return expression, const_values[expression], "numeric_constant_resolved"
        if re.fullmatch(r"\d+", expression):
            return expression, to_int(expression), "numeric_literal_resolved"
        if expression:
            return expression, "", "source_expression_tracked"
        return "", "", "source_expression_empty"

    def is_method_declaration_line(text: str, call_start: int, method_name: str) -> bool:
        line = source_excerpt(text, call_start)
        return re.match(rf"(?:public|private|protected|internal)\s+.*\b{re.escape(method_name)}\s*\(", line) is not None

    def resolve_helper_argument_reference(
        expression: str,
        stripped: str,
        helper_method: str,
        const_values: dict[str, int],
    ) -> tuple[str, object, str] | None:
        if not re.search(rf"\b{re.escape(helper_method)}\s*\(\s*uint\s+{re.escape(expression)}\s*\)", stripped):
            return None

        resolved_symbols: list[tuple[str, int]] = []
        for call_start, call_args in iter_invocations(stripped, helper_method):
            if is_method_declaration_line(stripped, call_start, helper_method):
                continue
            args = split_top_level(call_args)
            if not args:
                continue
            symbol, reference_id, link_status = resolve_reference(args[0], const_values)
            if link_status in {"numeric_constant_resolved", "numeric_literal_resolved"} and to_int(str(reference_id)):
                resolved_symbols.append((symbol, to_int(str(reference_id))))

        unique = sorted(set(resolved_symbols), key=lambda item: (item[1], item[0]))
        if len(unique) == 1:
            symbol, reference_id = unique[0]
            return f"{expression}<-{symbol}", reference_id, "helper_numeric_constant_resolved"
        return None

    def world_names(world_ids: Iterable[int]) -> str:
        return ";".join(world_by_id[world_id].get("assetPath", "") for world_id in sorted(set(world_ids)) if world_id in world_by_id)

    def world_location_trace_status(ids: Iterable[int], prefix: str) -> tuple[str, str]:
        location_ids = sorted({location_id for location_id in ids if location_id})
        if not location_ids:
            return f"{prefix}_worldlocation_source_pending_trace", "world_location_ids="
        matched_locations = [location_id for location_id in location_ids if location_id in world_location_by_id]
        missing_locations = [location_id for location_id in location_ids if location_id not in world_location_by_id]
        world_ids = sorted({to_int(world_location_by_id[location_id].get("worldId")) for location_id in matched_locations if to_int(world_location_by_id[location_id].get("worldId"))})
        missing_world_ids = [world_id for world_id in world_ids if world_id not in world_by_id]
        if missing_locations:
            status = f"{prefix}_worldlocation_rows_missing"
        elif missing_world_ids:
            status = f"{prefix}_world_rows_missing"
        else:
            status = f"{prefix}_worldlocation_rows_matched"
        detail = (
            f"world_location_ids={join_ids(location_ids)};matched_world_location_count={len(matched_locations)};"
            f"world_ids={join_ids(world_ids)};worlds={world_names(world_ids)}"
        )
        if missing_locations:
            detail += f";missing_world_location_ids={join_ids(missing_locations)}"
        if missing_world_ids:
            detail += f";missing_world_ids={join_ids(missing_world_ids)}"
        return status, detail

    def starter_departure_world_ids(relative_path: str) -> list[int]:
        if relative_path.endswith(r"Q10528EscapePod.cs"):
            return [426, 990]
        if relative_path.endswith(r"Q10530EscapePod.cs"):
            return [870, 1387]
        return []

    def source_trace(
        action_category: str,
        relative_path: str,
        stripped: str,
        const_values: dict[str, int],
        source_symbol: str,
        reference_id: object,
        client_reference_status: str,
    ) -> tuple[str, str, str]:
        numeric_id = to_int(str(reference_id))
        if action_category == "script_spell_cast" and source_symbol.startswith("spellId<-"):
            return (
                "starter_tutorial_helper_spell_constant_traced",
                f"CastSpell helper parameter traced to {source_symbol};client_reference_status={client_reference_status}",
                "Source/NexusForever.Script.Main/Tutorial/StarterTutorialQuestScript.cs;wildstar_client_mysql/Spell4.tbl.sql",
            )
        if numeric_id:
            return "literal_or_constant_client_reference_tracked", f"reference_id={numeric_id};client_reference_status={client_reference_status}", "Source/NexusForever.Script.*;wildstar_client_mysql"

        if action_category == "script_spell_cast":
            if relative_path.endswith(r"Source\NexusForever.Script.Main\AI\CombatAI.cs") and source_symbol == "spell4Id":
                return (
                    "combat_ai_auto_attack_spell4_runtime_table_guarded",
                    "CombatAI.DoAutoAttack reads profile autoAttacks and validates gameTableManager.Spell4.GetEntry(spell4Id) before CastSpell.",
                    "Source/NexusForever.Script.Main/AI/CombatAI.cs;Source/NexusForever.Script.Main/AI/DefaultCombatProfileProvider.cs;Source/NexusForever.Script.Main/AI/CombatKits.json;wildstar_client_mysql/Spell4.tbl.sql",
                )
            if relative_path.endswith(r"Source\NexusForever.Script.Main\AI\CombatAI.cs") and source_symbol == "profile.AggroSpell4Id":
                return (
                    "combat_ai_aggro_spell_profile_source_tracked",
                    "CombatAI.OnEnterRange casts profile.AggroSpell4Id when nonzero; profile provenance is DefaultCombatProfileProvider/manual profiles and still needs per-profile smoke.",
                    "Source/NexusForever.Script.Main/AI/CombatAI.cs;Source/NexusForever.Script.Main/AI/DefaultCombatProfileProvider.cs;Source/NexusForever.Script.Main/AI/CombatProfiles.json;Source/NexusForever.Script.Main/AI/CombatKits.json",
                )
            return "dynamic_spell_reference_pending_source_trace", source_symbol, "Source/NexusForever.Script.*;wildstar_client_mysql/Spell4.tbl.sql"

        if action_category == "script_teleport":
            departure_world_ids = starter_departure_world_ids(relative_path)
            if departure_world_ids:
                missing_world_ids = [world_id for world_id in departure_world_ids if world_id not in world_by_id]
                status = "starter_departure_routing_world_rows_missing" if missing_world_ids else "starter_departure_routing_world_rows_matched"
                detail = f"world_ids={join_ids(departure_world_ids)};worlds={world_names(departure_world_ids)}"
                if missing_world_ids:
                    detail += f";missing_world_ids={join_ids(missing_world_ids)}"
                return (
                    status,
                    detail,
                    "Source/NexusForever.Game.Static/Tutorial/StarterTutorialDepartureRouting.cs;Source/NexusForever.Game.Tests/Quests/StarterTutorialDepartureRoutingTests.cs;wildstar_client_mysql/World.tbl.sql",
                )
            if relative_path.endswith(r"WorldLocationTeleporterEntityScript.cs") and source_symbol == "destination.WorldId":
                location_ids = [to_int(value) for value in re.findall(r"\[\s*\d+u\s*\]\s*=\s*(\d+)u", stripped)]
                status, detail = world_location_trace_status(location_ids, "world_location_teleporter")
                return status, detail, "Source/NexusForever.Script.Main/Transport/WorldLocationTeleporterEntityScript.cs;wildstar_client_mysql/WorldLocation2.tbl.sql;wildstar_client_mysql/World.tbl.sql"
            if relative_path.endswith(r"WorldLocationTeleporterEntityScript.cs") and source_symbol == "world.Id":
                world_ids = sorted({to_int(value) for value in re.findall(r"new\s+DirectTransportDestination\s*\(\s*(\d+)", stripped)})
                missing_world_ids = [world_id for world_id in world_ids if world_id not in world_by_id]
                status = "direct_transport_world_rows_missing" if missing_world_ids else "direct_transport_world_rows_matched"
                detail = f"world_ids={join_ids(world_ids)};worlds={world_names(world_ids)}"
                if missing_world_ids:
                    detail += f";missing_world_ids={join_ids(missing_world_ids)}"
                return status, detail, "Source/NexusForever.Script.Main/Transport/WorldLocationTeleporterEntityScript.cs;wildstar_client_mysql/World.tbl.sql"
            if relative_path.endswith(r"TutorialCombatProjectorEntityScript.cs") and source_symbol == "destination.WorldId":
                status, detail = world_location_trace_status(
                    [const_values.get("ExileCombatSimulationWorldLocationId", 0), const_values.get("DominionCombatSimulationWorldLocationId", 0)],
                    "tutorial_combat_projector",
                )
                return status, detail, "Source/NexusForever.Script.Main/Tutorial/TutorialCombatProjectorEntityScript.cs;wildstar_client_mysql/WorldLocation2.tbl.sql;wildstar_client_mysql/World.tbl.sql"
            if relative_path.endswith(r"TutorialHousingProjectorEntityScript.cs") and source_symbol == "destination.WorldId":
                status, detail = world_location_trace_status([const_values.get("SkyplotEntryWorldLocationId", 0)], "tutorial_housing_projector")
                return status, detail, "Source/NexusForever.Script.Main/Tutorial/TutorialHousingProjectorEntityScript.cs;wildstar_client_mysql/WorldLocation2.tbl.sql;wildstar_client_mysql/World.tbl.sql"
            return "dynamic_world_reference_pending_source_trace", source_symbol, "Source/NexusForever.Script.*;wildstar_client_mysql/World.tbl.sql"

        if action_category == "script_local_teleport":
            if source_symbol.startswith("new Vector3("):
                return "literal_local_position_source_tracked", source_symbol, "Source/NexusForever.Script.*"
            if source_symbol == "entrance.Position":
                return (
                    "matching_map_entrance_runtime_lookup_tracked",
                    "Teleport destination comes from matchingDataManager.GetMapEntrance(map.Entry.Id, team); retail completion still needs entrance row and PvP respawn/end smoke.",
                    "Source/NexusForever.Script.Instance/Arena;Source/NexusForever.Game/Matching",
                )
            return "dynamic_local_position_pending_source_trace", source_symbol, "Source/NexusForever.Script.*"

        if action_category == "script_entity_create":
            return "runtime_entity_type_source_tracked", source_symbol, "Source/NexusForever.Script.*"
        if action_category == "script_entity_add_to_map":
            return "runtime_entity_add_source_tracked", source_symbol, "Source/NexusForever.Script.*"
        if action_category == "script_entity_remove_from_map":
            return "runtime_entity_remove_source_tracked", "RemoveFromMap target is the call receiver.", "Source/NexusForever.Script.*"
        if action_category == "script_public_event_finish":
            return "public_event_finish_team_source_tracked", source_symbol, "Source/NexusForever.Script.*"
        return "source_trace_pending", source_symbol, "Source/NexusForever.Script.*"

    def client_reference(
        action_category: str,
        source_symbol: str,
        reference_id: object,
    ) -> tuple[str, str, str]:
        numeric_id = to_int(str(reference_id))
        if action_category == "script_spell_cast":
            if not numeric_id:
                return "dynamic_spell_reference_pending_source_trace", "", "Source/NexusForever.Script.*;wildstar_client_mysql/Spell4.tbl.sql"
            spell = spell_by_id.get(numeric_id)
            if spell:
                return "spell4_row_matched", spell.get("description", ""), "wildstar_client_mysql/Spell4.tbl.sql"
            return "spell4_row_missing", "", "wildstar_client_mysql/Spell4.tbl.sql"

        if action_category == "script_teleport":
            if not numeric_id:
                return "dynamic_world_reference_pending_source_trace", "", "Source/NexusForever.Script.*;wildstar_client_mysql/World.tbl.sql"
            world = world_by_id.get(numeric_id)
            if world:
                return "world_row_matched", world.get("assetPath", ""), "wildstar_client_mysql/World.tbl.sql"
            return "world_row_missing", "", "wildstar_client_mysql/World.tbl.sql"

        if action_category == "script_local_teleport":
            if source_symbol.startswith("new Vector3("):
                return "literal_local_position_tracked", source_symbol, "Source/NexusForever.Script.*"
            return "dynamic_local_position_pending_source_trace", source_symbol, "Source/NexusForever.Script.*"

        if action_category == "script_entity_create":
            return "runtime_entity_type_tracked", source_symbol, "Source/NexusForever.Script.*"
        if action_category == "script_entity_add_to_map":
            return "runtime_entity_add_expression_tracked", source_symbol, "Source/NexusForever.Script.*"
        if action_category == "script_entity_remove_from_map":
            return "runtime_entity_remove_receiver_tracked", source_symbol, "Source/NexusForever.Script.*"
        if action_category == "script_public_event_finish":
            return "public_event_team_expression_tracked", source_symbol, "Source/NexusForever.Script.*"
        return "source_expression_tracked", source_symbol, "Source/NexusForever.Script.*"

    def build_row(
        scope: str,
        relative_path: str,
        stripped: str,
        call_start: int,
        script_owner_ids: list[int],
        script_filter_name: str,
        source_call: str,
        action_category: str,
        reference_kind: str,
        source_symbol: str,
        reference_id: object,
        reference_link_status: str,
        evidence_status: str,
    ) -> dict[str, object]:
        client_reference_status, client_reference_name, client_reference_sources = client_reference(action_category, source_symbol, reference_id)
        source_trace_status, source_trace_detail, source_trace_sources = source_trace(
            action_category,
            relative_path,
            stripped,
            const_values,
            source_symbol,
            reference_id,
            client_reference_status,
        )
        source_line = line_number(stripped, call_start)
        row = {
            "evidence_kind": "script_runtime_action",
            "script_scope": scope,
            "source_path": relative_path,
            "source_line": source_line,
            "script_owner_ids": join_ids(script_owner_ids),
            "script_filter_name": script_filter_name,
            "source_call": source_call,
            "action_category": action_category,
            "reference_kind": reference_kind,
            "source_symbol": source_symbol,
            "reference_id": reference_id,
            "reference_link_status": reference_link_status,
            "client_reference_status": client_reference_status,
            "client_reference_name": client_reference_name,
            "client_reference_sources": client_reference_sources,
            "source_trace_status": source_trace_status,
            "source_trace_detail": source_trace_detail,
            "source_trace_sources": source_trace_sources,
            "source_excerpt": source_excerpt(stripped, call_start),
            "evidence_status": evidence_status,
            "evidence_sources": "Source/NexusForever.Script.Main;Source/NexusForever.Script.Instance",
            "manual_validation": "pending",
            "completion_status": "not_retail_complete",
            "blocker_summary": "Scripted runtime action is tracked from source, but retail completion needs exact trigger timing, target selection, payload/effect semantics, cleanup/replay behavior, and content smoke.",
        }
        row.update(
            SCRIPT_RUNTIME_ACTION_EVIDENCE_OVERRIDES.get(
                (
                    relative_path,
                    source_line,
                    action_category,
                    source_call,
                    source_symbol,
                ),
                {},
            )
        )
        return row

    for script_root in script_roots:
        for path in sorted(script_root.rglob("*.cs")):
            if "obj" in path.parts:
                continue
            text = path.read_text(encoding="utf-8", errors="replace")
            stripped = strip_csharp_comments_preserve_lines(text)
            relative_path = relative_display_path(path, script_root)
            scope = script_scope(script_root)
            script_owner_ids = owner_ids(text)
            script_name_match = script_name_pattern.search(text)
            script_filter_name = script_name_match.group(1) if script_name_match else ""
            const_values = {match.group(1): to_int(match.group(2)) for match in const_pattern.finditer(stripped)}

            for match in generic_create_pattern.finditer(stripped):
                generic_type = re.sub(r"\s+", "", match.group(1))
                output.append(
                    build_row(
                        scope,
                        relative_path,
                        stripped,
                        match.start(),
                        script_owner_ids,
                        script_filter_name,
                        "CreateEntity",
                        "script_entity_create",
                        "entity_type",
                        generic_type,
                        "",
                        "generic_entity_type_tracked",
                        "script_entity_create_pending_spawn_initialise_lifecycle_smoke",
                    )
                )

            for method_name, (action_category, reference_kind, evidence_status) in method_categories.items():
                for call_start, call_args in iter_invocations(stripped, method_name):
                    args = split_top_level(call_args)
                    expression = args[0] if args else ""
                    source_symbol, reference_id, reference_link_status = resolve_reference(expression, const_values)
                    if action_category == "script_spell_cast" and reference_link_status == "source_expression_tracked":
                        traced_reference = resolve_helper_argument_reference(source_symbol, stripped, "CastPlayerSpell", const_values)
                        if traced_reference:
                            source_symbol, reference_id, reference_link_status = traced_reference
                    output.append(
                        build_row(
                            scope,
                            relative_path,
                            stripped,
                            call_start,
                            script_owner_ids,
                            script_filter_name,
                            method_name,
                            action_category,
                            reference_kind,
                            source_symbol,
                            reference_id,
                            reference_link_status,
                            evidence_status,
                        )
                    )

    return sorted(
        output,
        key=lambda item: (
            str(item["action_category"]),
            str(item["script_scope"]),
            str(item["source_path"]),
            to_int(str(item["source_line"])),
            str(item["source_symbol"]),
        ),
    )


def build_instance_script_handler_evidence_rows(
    instance_rows: list[dict[str, object]],
    script_instance: Path,
) -> list[dict[str, object]]:
    instance_by_path: dict[str, dict[str, object]] = {}
    local_paths: set[Path] = set()
    for instance in instance_rows:
        for script_path in split_joined_values(instance.get("script_paths", "")):
            instance_by_path[script_path] = instance
            try:
                local_path = Path(script_path).relative_to("Source/NexusForever.Script.Instance")
            except ValueError:
                local_path = Path(script_path)
            instance_by_path[str(local_path)] = instance
            instance_by_path[str(Path("Source/NexusForever.Script.Instance") / local_path)] = instance
            local_paths.add(local_path)

    tracked_paths = {script_instance / local_path for local_path in local_paths}
    owner_pattern = re.compile(r"ScriptFilterOwnerId\(([^)]+)\)")
    creature_pattern = re.compile(r"ScriptFilterCreatureId\(([^)]+)\)")
    script_name_pattern = re.compile(r"ScriptFilterScriptName\(\"([^\"]+)\"\)")
    class_pattern = re.compile(
        r"(?P<header>(?:\s*\[[^\]]+\]\s*)*)"
        r"(?P<access>public|internal|private|protected)?\s*"
        r"(?:abstract\s+|sealed\s+|partial\s+)*class\s+"
        r"(?P<class_name>[A-Za-z_][A-Za-z0-9_]*)"
        r"(?P<tail>[^{]*)\{",
        re.MULTILINE,
    )
    method_pattern = re.compile(
        r"(?P<access>public|protected|private|internal)\s+"
        r"(?:override\s+|virtual\s+|abstract\s+|static\s+|async\s+)*"
        r"(?P<return_type>[A-Za-z_][A-Za-z0-9_<>,\[\]\.? ]*)\s+"
        r"(?P<method_name>On[A-Za-z_][A-Za-z0-9_]*)\s*"
        r"\((?P<args>[^)]*)\)",
        re.MULTILINE,
    )

    def matching_brace_index(text: str, open_brace_index: int) -> int:
        depth = 0
        index = open_brace_index
        quote = ""
        escaped = False
        while index < len(text):
            char = text[index]
            if quote:
                if escaped:
                    escaped = False
                elif char == "\\":
                    escaped = True
                elif char == quote:
                    quote = ""
            elif char in {'"', "'"}:
                quote = char
            elif char == "{":
                depth += 1
            elif char == "}":
                depth -= 1
                if depth == 0:
                    return index
            index += 1
        return -1

    def line_number(text: str, index: int) -> int:
        return text.count("\n", 0, index) + 1

    def filter_ids(header: str, pattern: re.Pattern[str]) -> list[int]:
        output: list[int] = []
        for match in pattern.finditer(header):
            output.extend(to_int(value) for value in re.findall(r"\d+", match.group(1)) if to_int(value))
        return sorted(set(output))

    def handler_category(method_name: str) -> str:
        if method_name in {"OnLoad", "OnUnload"}:
            return "script_lifecycle"
        if method_name in {"OnAddToMap", "OnRemoveFromMap"}:
            return "map_entity_lifecycle"
        if method_name.startswith("OnPublicEvent"):
            return "public_event_lifecycle"
        if method_name.startswith("OnPvpMatch") or method_name == "OnMatchFinish":
            return "match_lifecycle"
        if "Cinematic" in method_name:
            return "cinematic_lifecycle"
        if "EnterRange" in method_name or "ExitRange" in method_name:
            return "range_trigger_lifecycle"
        if method_name in {"OnActivate", "OnInteract", "OnUse"}:
            return "entity_interaction"
        if "Death" in method_name or "Damage" in method_name or "Health" in method_name or "Combat" in method_name:
            return "combat_lifecycle"
        return "script_callback"

    def handler_script_kind(class_name: str, class_tail: str, path: Path) -> str:
        if class_name.endswith("MapScript") or path.name.endswith("MapScript.cs"):
            return "map_script"
        if "IPublicEventScript" in class_tail or class_name.endswith("EventScript") or class_name.endswith("SubEventScript"):
            return "public_event_script"
        if "IUnitScript" in class_tail or "IWorldEntityScript" in class_tail:
            return "entity_script"
        if "ISpellScript" in class_tail or "SpellScript" in class_name:
            return "spell_script"
        return "runtime_script"

    def owner_link_status(instance: dict[str, object], owner_ids: list[int]) -> str:
        world_id = to_int(str(instance.get("world_id", "")))
        public_event_ids = set(split_joined_ids(instance.get("public_event_ids", "")))
        owner_set = set(owner_ids)
        if world_id in owner_set:
            return "script_owner_matches_instance_world"
        if owner_set.intersection(public_event_ids):
            return "script_owner_matches_instance_public_event"
        if owner_ids:
            return "script_owner_related_instance_dependency"
        return "script_owner_not_declared"

    output: list[dict[str, object]] = []
    for path in sorted(tracked_paths):
        if not path.exists() or "obj" in path.parts:
            continue
        relative_path = relative_display_path(path, script_instance)
        instance = instance_by_path.get(relative_path)
        if not instance:
            prefixed_path = str(Path("Source/NexusForever.Script.Instance") / relative_path)
            instance = instance_by_path.get(prefixed_path)
        if not instance:
            continue
        stripped = strip_csharp_comments_preserve_lines(path.read_text(encoding="utf-8", errors="replace"))
        for class_match in class_pattern.finditer(stripped):
            open_brace_index = class_match.end() - 1
            close_brace_index = matching_brace_index(stripped, open_brace_index)
            if close_brace_index == -1:
                continue
            header = class_match.group("header") or ""
            class_name = class_match.group("class_name")
            class_tail = class_match.group("tail") or ""
            class_body = stripped[open_brace_index + 1 : close_brace_index]
            owner_ids = filter_ids(header, owner_pattern)
            creature_ids = filter_ids(header, creature_pattern)
            script_name_match = script_name_pattern.search(header)
            script_filter_name = script_name_match.group(1) if script_name_match else ""
            kind = handler_script_kind(class_name, class_tail, path)
            owner_status = owner_link_status(instance, owner_ids)
            for method_match in method_pattern.finditer(class_body):
                method_name = method_match.group("method_name")
                if method_match.group("access") == "private":
                    continue
                method_start = open_brace_index + 1 + method_match.start()
                category = handler_category(method_name)
                source_line = line_number(stripped, method_start)
                row = {
                    "content_type": instance["content_type"],
                    "world_id": instance["world_id"],
                    "instance_name": instance["name"],
                    "script_path": relative_path,
                    "source_line": source_line,
                    "script_class": class_name,
                    "script_kind": kind,
                    "script_owner_ids": join_ids(owner_ids),
                    "script_creature_ids": join_ids(creature_ids),
                    "script_filter_name": script_filter_name,
                    "handler_name": method_name,
                    "handler_category": category,
                    "handler_signature": re.sub(r"\s+", " ", method_match.group(0).strip()),
                    "owner_link_status": owner_status,
                    "evidence_status": f"instance_{category}_handler_pending_mechanics_smoke",
                    "evidence_sources": "Source/NexusForever.Script.Instance;wildstar_client_mysql/World.tbl.sql;wildstar_client_mysql/PublicEvent.tbl.sql;Decomp/Analysis/CONTENT_RETAIL_COMPLETENESS_TRACKER.md",
                    "manual_validation": "pending",
                    "completion_status": "not_retail_complete",
                    "blocker_summary": "Instance script handler is tracked, but retail completion needs exact trigger order, state transitions, target selection, cleanup behavior, rewards/loot side effects, and manual instance smoke.",
                }
                row.update(
                    INSTANCE_SCRIPT_HANDLER_EVIDENCE_OVERRIDES.get(
                        (to_int(str(instance.get("world_id", ""))), relative_path, source_line, method_name),
                        {},
                    )
                )
                output.append(row)

    return sorted(
        output,
        key=lambda item: (
            str(item["content_type"]),
            to_int(str(item["world_id"])),
            str(item["script_path"]),
            to_int(str(item["source_line"])),
            str(item["handler_name"]),
        ),
    )


def achievement_ids_by_category(achievements: list[dict[str, str]]) -> dict[int, list[int]]:
    by_category: dict[int, list[int]] = defaultdict(list)
    for row in achievements:
        category_id = to_int(row["achievementCategoryId"])
        if category_id:
            by_category[category_id].append(to_int(row["ID"]))
    return {category_id: sorted(ids) for category_id, ids in by_category.items()}


def classify_instance_milestone_scope(content_type: str, evidence_status: str) -> tuple[str, str]:
    if evidence_status == "observed_client_table_only":
        return (
            "inventory_only_client_table_only",
            "Build 16042 client World row remains visible, but lacks runtime script/owner proof; keep blocked until asset and retail status are proven or rejected.",
        )

    if content_type.startswith("unreleased_"):
        return (
            "inventory_only_unreleased_content",
            "Unreleased/datamined content is tracked for evidence and optional restoration, but is not counted toward build 16042 retail completeness.",
        )

    if content_type == "event_instance":
        return (
            "inventory_only_adjacent_scripted_content",
            "Adjacent scripted content is tracked for dependency evidence, but is not a dungeon/expedition/raid completion target for this milestone.",
        )

    if content_type in {"dungeon", "expedition", "raid", "world_story"}:
        return (
            "milestone_target_instance",
            "Dungeon, expedition, raid, or World Story instance content is inside the restoration milestone, while retail completion still requires row-specific proof.",
        )

    return (
        "inventory_only_related_content",
        "Related instance-like content is tracked for evidence context until a narrower milestone target is proven.",
    )


def build_instance_rows(
    strings: dict[int, str],
    worlds: list[dict[str, str]],
    public_events: list[dict[str, str]],
    public_event_objectives: list[dict[str, str]],
    matching_game_maps: list[dict[str, str]],
    matching_game_types: list[dict[str, str]],
    achievements: list[dict[str, str]],
    script_instance: Path,
) -> list[dict[str, object]]:
    world_by_id = {to_int(row["ID"]): row for row in worlds}
    matching_type_by_id = {to_int(row["ID"]): row for row in matching_game_types}
    map_scripts = load_map_scripts(script_instance)
    content_script_details = load_content_script_details(script_instance)
    achievements_by_category = achievement_ids_by_category(achievements)

    public_events_by_world: dict[int, list[int]] = defaultdict(list)
    for row in public_events:
        public_events_by_world[to_int(row["worldId"])].append(to_int(row["ID"]))

    objective_counts_by_event: Counter[int] = Counter()
    for row in public_event_objectives:
        objective_counts_by_event[to_int(row["publicEventId"])] += 1

    matching_by_world: dict[int, list[dict[str, str]]] = defaultdict(list)
    for row in matching_game_maps:
        matching_by_world[to_int(row["worldId"])].append(row)

    content_world_ids = {
        to_int(row["ID"])
        for row in worlds
        if to_int(row["type"]) in {DUNGEON_WORLD_TYPE, RAID_WORLD_TYPE}
    }
    for world_id, script in map_scripts.items():
        folder = str(script["folder"])
        if folder in {"Dungeon", "Raid", "EventInstance", "Expedition", "WorldStory", "Unreleased"}:
            content_world_ids.add(world_id)

    output: list[dict[str, object]] = []
    for world_id in sorted(content_world_ids):
        world = world_by_id.get(world_id, {})
        world_type = to_int(world.get("type"))
        script = map_scripts.get(world_id)
        folder = str(script["folder"]) if script else ""
        if folder:
            content_type = {
                "Dungeon": "dungeon",
                "Raid": "raid",
                "EventInstance": "event_instance",
                "Expedition": "expedition",
                "WorldStory": "world_story",
                "Unreleased": "unreleased_instance",
            }.get(folder, folder.lower())
        elif world_type == DUNGEON_WORLD_TYPE:
            content_type = "dungeon"
        elif world_type == RAID_WORLD_TYPE:
            content_type = "raid"
        else:
            content_type = "instance_related"

        matching_rows = matching_by_world.get(world_id, [])
        matching_type_ids = sorted({to_int(row["matchingGameTypeId"]) for row in matching_rows if to_int(row["matchingGameTypeId"])})
        match_type_enums = sorted({to_int(matching_type_by_id[type_id]["matchTypeEnum"]) for type_id in matching_type_ids if type_id in matching_type_by_id})
        achievement_categories = sorted({to_int(row["achievementCategoryId"]) for row in matching_rows if to_int(row["achievementCategoryId"])})
        content_type = INSTANCE_CONTENT_TYPE_OVERRIDES.get(world_id, content_type)
        related_achievements: set[int] = set()
        for category_id in achievement_categories:
            related_achievements.update(achievements_by_category.get(category_id, []))

        public_event_ids = sorted(set(public_events_by_world.get(world_id, [])) | set(script["public_events"] if script else []))
        objective_count = sum(objective_counts_by_event[event_id] for event_id in public_event_ids)

        if script:
            implementation_status = "mapped_wip_scaffold"
            evidence_status = "mapped_only_pending_manual_smoke"
            content_details = content_script_details.get(script["content_key"], {"paths": [script["path"]], "owners": set()})
            script_paths = sorted(content_details["paths"])  # type: ignore[index]
            script_owner_ids = sorted(content_details["owners"])  # type: ignore[index]
            blocker_summary = SCRIPTED_INSTANCE_BLOCKERS.get(
                world_id,
                "Mapped/WIP script-owned instance row; exact mechanics, routing, rewards, and manual smoke remain blocked.",
            )
        else:
            script_paths = []
            script_owner_ids = []
            implementation_status, blocker_summary = INSTANCE_REVIEW_ROWS.get(
                world_id,
                ("client_recorded_missing_runtime_script", "Client world row has no current runtime script; needs classification, evidence, and implementation."),
            )
            evidence_status = "observed_client_table_only"

        milestone_scope, milestone_scope_reason = classify_instance_milestone_scope(content_type, evidence_status)

        output.append(
            {
                "content_type": content_type,
                "world_id": world_id,
                "name": INSTANCE_NAME_OVERRIDES.get(world_id, text_by_id(strings, to_int(world.get("localizedTextIdName"))) or world.get("assetPath", "")),
                "asset_path": world.get("assetPath", ""),
                "world_type": world_type,
                "reward_rotation_content_id": to_int(world.get("rewardRotationContentId")),
                "public_event_ids": join_ids(public_event_ids),
                "public_event_objective_count": objective_count,
                "matching_game_map_ids": join_ids(to_int(row["ID"]) for row in matching_rows),
                "matching_game_type_ids": join_ids(matching_type_ids),
                "match_type_enums": join_ids(match_type_enums),
                "achievement_category_ids": join_ids(achievement_categories),
                "related_achievement_ids": join_ids(sorted(related_achievements)),
                "script_paths": join_ids(script_paths),
                "script_owner_ids": join_ids(script_owner_ids),
                "milestone_scope": milestone_scope,
                "milestone_scope_reason": milestone_scope_reason,
                "implementation_status": implementation_status,
                "evidence_status": evidence_status,
                "completion_status": "not_retail_complete",
                "evidence_sources": "wildstar_client_mysql/World.tbl.sql;wildstar_client_mysql/PublicEvent*.tbl.sql;wildstar_client_mysql/MatchingGame*.tbl.sql;wildstar_client_mysql/Achievement*.tbl.sql;Source/NexusForever.Script.Instance;Decomp/Analysis/LAUGHINGWS_*_SMOKE_REVIEW.md;Decomp/Analysis/LAUGHINGWS_INSTANCES_AND_MORE_AUDIT.md",
                "manual_validation": "pending",
                "blocker_summary": blocker_summary,
            }
        )
    return output


def build_instance_dependency_rows(
    strings: dict[int, str],
    instance_rows: list[dict[str, object]],
    public_events: list[dict[str, str]],
    public_event_objectives: list[dict[str, str]],
    matching_game_maps: list[dict[str, str]],
    matching_game_types: list[dict[str, str]],
    achievements: list[dict[str, str]],
    data_mapping_output: Path,
) -> list[dict[str, object]]:
    public_event_by_id = {to_int(row["ID"]): row for row in public_events}
    objectives_by_event: dict[int, list[dict[str, str]]] = defaultdict(list)
    for row in public_event_objectives:
        objectives_by_event[to_int(row["publicEventId"])].append(row)

    matching_by_world: dict[int, list[dict[str, str]]] = defaultdict(list)
    for row in matching_game_maps:
        matching_by_world[to_int(row["worldId"])].append(row)

    matching_type_by_id = {to_int(row["ID"]): row for row in matching_game_types}
    achievement_by_id = {to_int(row["ID"]): row for row in achievements}
    target_group_ids = {
        to_int(row.get("ID"))
        for row in load_csv_rows(data_mapping_output / "client_source_targetgroup_map.csv")
        if to_int(row.get("ID"))
    } if (data_mapping_output / "client_source_targetgroup_map.csv").exists() else set()
    objective_client_rows = {
        to_int(row.get("public_event_objective_id")): row
        for row in load_csv_rows(data_mapping_output / "public_event_objective_client_map.csv")
        if to_int(row.get("public_event_objective_id"))
    } if (data_mapping_output / "public_event_objective_client_map.csv").exists() else {}

    def common(instance: dict[str, object], dependency_type: str) -> dict[str, object]:
        return {
            "content_type": instance["content_type"],
            "world_id": instance["world_id"],
            "instance_name": instance["name"],
            "dependency_type": dependency_type,
            "instance_evidence_status": instance["evidence_status"],
            "completion_status": "not_retail_complete",
            "blocker_summary": instance["blocker_summary"],
        }

    def default_objective_evidence(objective: dict[str, str]) -> tuple[str, str, str, str]:
        objective_id = to_int(objective.get("ID"))
        event_id = to_int(objective.get("publicEventId"))
        map_row = objective_client_rows.get(objective_id, {})
        objective_type = to_int(
            map_row.get("objective_type")
            or objective.get("publicEventObjectiveTypeEnum")
        )
        object_id = to_int(map_row.get("objective_object_id") or objective.get("objectId"))
        count = to_int(map_row.get("objective_count") or objective.get("count"))
        flags = to_int(map_row.get("objective_flags") or objective.get("publicEventObjectiveFlags"))
        world_location_id = to_int(map_row.get("world_location_id") or objective.get("worldLocation2Id"))
        quest_direction_id = to_int(map_row.get("quest_direction_id") or objective.get("questDirectionId"))
        target_group_id = to_int(map_row.get("target_group_id_reward_pane") or objective.get("targetGroupIdRewardPane"))
        objective_text = (
            map_row.get("objective_text")
            or text_by_id(strings, to_int(objective.get("localizedTextId")))
            or text_by_id(strings, to_int(objective.get("localizedTextIdShort")))
        )
        objective_object_is_target_group = object_id in target_group_ids
        if objective_type in {
            PUBLIC_EVENT_KILL_TARGET_GROUP_OBJECTIVE_TYPE,
            PUBLIC_EVENT_KILL_CLUSTER_TARGET_GROUP_OBJECTIVE_TYPE,
            PUBLIC_EVENT_EXTERMINATE_OBJECTIVE_TYPE,
        } and object_id:
            target_group_id = object_id
        if objective_type in PUBLIC_EVENT_KILL_EVENT_UNIT_OBJECTIVE_TYPES and objective_object_is_target_group:
            target_group_id = object_id

        evidence_status = public_event_evidence_status(
            "public_event_objective",
            event_id in public_event_by_id,
            "matched",
            objective_id,
            objective_type=objective_type,
            objective_object_id=object_id,
            world_location_id=world_location_id,
            objective_object_is_target_group=objective_object_is_target_group,
        )
        if evidence_status == "datamapping_public_event_not_current_client_event_row_blocked":
            evidence_status = "mapped_instance_public_event_objective_blocked_missing_current_public_event_row"

        detail = [
            f"PublicEvent {event_id}",
            f"type {PUBLIC_EVENT_OBJECTIVE_TYPE_NAMES.get(objective_type, f'type {objective_type}')} ({objective_type})",
            f"ObjectId {object_id}",
            f"Count {count}",
            f"Flags {flags}",
        ]
        if world_location_id:
            detail.append(f"WorldLocation2 {world_location_id}")
        if quest_direction_id:
            detail.append(f"QuestDirection {quest_direction_id}")
        if target_group_id:
            detail.append(f"TargetGroup {target_group_id}")
        if objective_text:
            detail.append(f"text '{objective_text}'")

        if evidence_status.startswith("runtime_public_event_"):
            blocker_summary = (
                f"Instance public-event objective {objective_id} is mapped to a current client row ({'; '.join(detail)}). "
                f"The shared runtime public-event objective path for this objective family is implemented/tested where noted by "
                f"`{evidence_status}`, but this instance row is still not retail-complete until row-specific event/phase activation, "
                "spawn or trigger placement, cleanup/replay behavior, rewards/medals, and client smoke prove the producer for this content route."
            )
            evidence_sources = (
                "wildstar_client_mysql/PublicEventObjective.tbl.sql;Tools/DataMapping/output/public_event_objective_client_map.csv;"
                "Tools/DataMapping/output/client_source_targetgroup_map.csv;Source/NexusForever.Game/PublicEvent;Source/NexusForever.Game/Entity;"
                "Source/NexusForever.Script.Instance;Source/NexusForever.Game.Tests"
            )
            manual_validation = "runtime_path_tested_pending_row_specific_instance_smoke"
        else:
            blocker_summary = "Instance dependency row: " + public_event_objective_blocked_summary(
                objective_id,
                objective_type,
                object_id,
                count,
                world_location_id,
                quest_direction_id,
                target_group_id,
                objective_text,
                objective_object_is_target_group,
            )
            evidence_sources = (
                "wildstar_client_mysql/PublicEventObjective.tbl.sql;Tools/DataMapping/output/public_event_objective_client_map.csv;"
                "Tools/DataMapping/output/client_source_targetgroup_map.csv;Source/NexusForever.Game/PublicEvent/PublicEventManager.cs;"
                "Source/NexusForever.Script.Instance;Decomp/Analysis/CONTINUATION_GUIDE.md;Decomp/Analysis/BLOCKER_EVIDENCE_PLAN.md"
            )
            manual_validation = "blocked_pending_row_specific_runtime_producer_evidence"

        return evidence_status, evidence_sources, manual_validation, blocker_summary

    output: list[dict[str, object]] = []
    for instance in sorted(instance_rows, key=lambda item: to_int(str(item["world_id"]))):
        world_id = to_int(str(instance["world_id"]))
        for event_id in split_joined_ids(instance["public_event_ids"]):
            event = public_event_by_id.get(event_id)
            output.append(
                {
                    **common(instance, "public_event"),
                    "dependency_id": event_id,
                    "dependency_name": text_by_id(strings, to_int(event.get("localizedTextIdName") if event else None)),
                    "public_event_id": event_id,
                    "objective_type": "",
                    "object_id": to_int(event.get("worldLocation2Id") if event else None),
                    "count": "",
                    "flags": to_int(event.get("publicEventFlags") if event else None),
                    "world_zone_id": to_int(event.get("worldZoneId") if event else None),
                    "reward_rotation_content_id": to_int(event.get("rewardRotationContentId") if event else None),
                    "script_path": "",
                    "script_owner_ids": "",
                    "matching_game_type_id": "",
                    "match_type_enum": "",
                    "achievement_category_id": "",
                    "evidence_status": "client_public_event_row_pending_instance_smoke" if event else "script_declared_public_event_missing_client_row",
                    "evidence_sources": "wildstar_client_mysql/PublicEvent.tbl.sql;Source/NexusForever.Script.Instance",
                    "manual_validation": "pending",
                }
            )

            for objective in sorted(objectives_by_event.get(event_id, []), key=lambda item: to_int(item["ID"])):
                objective_id = to_int(objective["ID"])
                override = INSTANCE_OBJECTIVE_DEPENDENCY_OVERRIDES.get((world_id, objective_id), {})
                default_evidence_status, default_evidence_sources, default_manual_validation, default_blocker_summary = default_objective_evidence(objective)
                output.append(
                    {
                        **common(instance, "public_event_objective"),
                        "dependency_id": objective_id,
                        "dependency_name": text_by_id(strings, to_int(objective["localizedTextId"])) or text_by_id(strings, to_int(objective["localizedTextIdShort"])),
                        "public_event_id": event_id,
                        "objective_type": to_int(objective["publicEventObjectiveTypeEnum"]),
                        "object_id": to_int(objective["objectId"]),
                        "count": to_int(objective["count"]),
                        "flags": to_int(objective["publicEventObjectiveFlags"]),
                        "world_zone_id": "",
                        "reward_rotation_content_id": "",
                        "script_path": override.get("script_path", ""),
                        "script_owner_ids": override.get("script_owner_ids", ""),
                        "matching_game_type_id": "",
                        "match_type_enum": "",
                        "achievement_category_id": "",
                        "evidence_status": override.get("evidence_status", default_evidence_status),
                        "evidence_sources": override.get("evidence_sources", default_evidence_sources),
                        "manual_validation": override.get("manual_validation", default_manual_validation),
                        "blocker_summary": override.get("blocker_summary", default_blocker_summary),
                    }
                )

        for matching_map in sorted(matching_by_world.get(world_id, []), key=lambda item: to_int(item["ID"])):
            matching_map_id = to_int(matching_map["ID"])
            matching_type_id = to_int(matching_map["matchingGameTypeId"])
            matching_type = matching_type_by_id.get(matching_type_id, {})
            override = INSTANCE_MATCHING_MAP_DEPENDENCY_OVERRIDES.get((world_id, matching_map_id), {})
            output.append(
                {
                    **common(instance, "matching_game_map"),
                    "dependency_id": matching_map_id,
                    "dependency_name": text_by_id(strings, to_int(matching_map["localizedTextIdName"])),
                    "public_event_id": "",
                    "objective_type": "",
                    "object_id": to_int(matching_map["worldId"]),
                    "count": "",
                    "flags": to_int(matching_map["matchingGameMapEnumFlags"]),
                    "world_zone_id": "",
                    "reward_rotation_content_id": "",
                    "script_path": override.get("script_path", ""),
                    "script_owner_ids": override.get("script_owner_ids", ""),
                    "matching_game_type_id": matching_type_id,
                    "match_type_enum": to_int(matching_type.get("matchTypeEnum")),
                    "achievement_category_id": to_int(matching_map["achievementCategoryId"]),
                    "evidence_status": override.get(
                        "evidence_status",
                        "client_matching_map_row_pending_queue_and_instance_smoke",
                    ),
                    "evidence_sources": override.get(
                        "evidence_sources",
                        "wildstar_client_mysql/MatchingGameMap.tbl.sql;wildstar_client_mysql/MatchingGameType.tbl.sql;Source/NexusForever.Game/Matching",
                    ),
                    "manual_validation": override.get("manual_validation", "pending"),
                    "blocker_summary": override.get("blocker_summary", common(instance, "matching_game_map")["blocker_summary"]),
                }
            )

        for achievement_id in split_joined_ids(instance["related_achievement_ids"]):
            achievement = achievement_by_id.get(achievement_id)
            override = INSTANCE_ACHIEVEMENT_DEPENDENCY_OVERRIDES.get((world_id, achievement_id), {})
            output.append(
                {
                    **common(instance, "achievement"),
                    "dependency_id": achievement_id,
                    "dependency_name": text_by_id(strings, to_int(achievement.get("localizedTextIdTitle") if achievement else None)),
                    "public_event_id": "",
                    "objective_type": to_int(achievement.get("achievementTypeId") if achievement else None),
                    "object_id": to_int(achievement.get("objectId") if achievement else None),
                    "count": to_int(achievement.get("value") if achievement else None),
                    "flags": to_int(achievement.get("flags") if achievement else None),
                    "world_zone_id": to_int(achievement.get("worldZoneId") if achievement else None),
                    "reward_rotation_content_id": "",
                    "script_path": override.get("script_path", ""),
                    "script_owner_ids": override.get("script_owner_ids", ""),
                    "matching_game_type_id": "",
                    "match_type_enum": "",
                    "achievement_category_id": to_int(achievement.get("achievementCategoryId") if achievement else None),
                    "evidence_status": override.get(
                        "evidence_status",
                        "client_achievement_row_pending_progression_hook_smoke" if achievement else "missing_client_achievement_row",
                    ),
                    "evidence_sources": override.get(
                        "evidence_sources",
                        "wildstar_client_mysql/Achievement.tbl.sql;wildstar_client_mysql/MatchingGameMap.tbl.sql;Source/NexusForever.Game/Achievement/GlobalAchievementManager.cs",
                    ),
                    "manual_validation": override.get("manual_validation", "pending"),
                    "blocker_summary": override.get("blocker_summary", common(instance, "achievement")["blocker_summary"]),
                }
            )

        for script_path in split_joined_values(instance["script_paths"]):
            output.append(
                {
                    **common(instance, "script"),
                    "dependency_id": script_path,
                    "dependency_name": Path(script_path).stem,
                    "public_event_id": "",
                    "objective_type": "",
                    "object_id": "",
                    "count": "",
                    "flags": "",
                    "world_zone_id": "",
                    "reward_rotation_content_id": "",
                    "script_path": script_path,
                    "script_owner_ids": instance["script_owner_ids"],
                    "matching_game_type_id": "",
                    "match_type_enum": "",
                    "achievement_category_id": "",
                    "evidence_status": "runtime_script_present_pending_mechanics_and_smoke",
                    "evidence_sources": "Source/NexusForever.Script.Instance;wildstar_client_mysql/World.tbl.sql",
                    "manual_validation": "pending",
                }
            )

    return output


def load_instance_entity_comments(path: Path) -> dict[int, str]:
    if not path.exists():
        return {}

    comments: dict[int, str] = {}
    for line in path.read_text(encoding="utf-8", errors="replace").splitlines():
        match = re.match(r"^--\s+(\d+):\s*(.+)$", line)
        if match:
            comments[int(match.group(1))] = match.group(2).strip()
    return comments


def load_instance_entity_update_rows(path: Path) -> list[dict[str, str]]:
    if not path.exists():
        return []

    lines = path.read_text(encoding="utf-8", errors="replace").splitlines()
    rows: list[dict[str, str]] = []
    pending_comment = ""
    index = 0
    update_pattern = re.compile(
        r"SET\s+`(?P<field>[^`]+)`\s*=\s*(?P<value>-?\d+(?:\.\d+)?)\s+"
        r"WHERE\s+`world`\s*=\s*(?P<world>\d+)\s+AND\s+`creature`\s*=\s*(?P<creature>\d+).*?"
        r"ABS\(`x`\s*-\s*\((?P<x>-?\d+(?:\.\d+)?)\)\).*?"
        r"ABS\(`y`\s*-\s*\((?P<y>-?\d+(?:\.\d+)?)\)\).*?"
        r"ABS\(`z`\s*-\s*\((?P<z>-?\d+(?:\.\d+)?)\)\)",
        re.IGNORECASE | re.DOTALL,
    )

    while index < len(lines):
        line = lines[index]
        comment_match = re.match(r"^--\s+(?!\d+:)(.+)$", line)
        if comment_match:
            pending_comment = comment_match.group(1).strip()

        if re.match(r"^UPDATE\s+`entity`", line, re.IGNORECASE):
            block_lines = [line]
            index += 1
            while index < len(lines):
                block_lines.append(lines[index])
                if lines[index].rstrip().endswith(";"):
                    break
                index += 1
            block = "\n".join(block_lines)
            update_match = update_pattern.search(block)
            if not update_match:
                raise ValueError(f"Unsupported entity update format in {path}: {block}")

            row = {key: value for key, value in update_match.groupdict().items()}
            row["comment"] = pending_comment
            rows.append(row)
            pending_comment = ""

        index += 1

    return rows


def build_instance_entity_rows(
    instance_rows: list[dict[str, object]],
    seed_path: Path = INSTANCE_ENTITY_SQL,
) -> list[dict[str, object]]:
    entity_rows = [row for row in load_insert_rows(seed_path, "entity", INSTANCE_ENTITY_COLUMNS) if to_int(row["id"])]
    event_rows = [row for row in load_insert_rows(seed_path, "entity_event", INSTANCE_ENTITY_EVENT_COLUMNS) if to_int(row["id"])]
    script_rows = [row for row in load_insert_rows(seed_path, "entity_script", INSTANCE_ENTITY_SCRIPT_COLUMNS) if to_int(row["id"])]
    stat_rows = [row for row in load_insert_rows(seed_path, "entity_stats", INSTANCE_ENTITY_STATS_COLUMNS) if to_int(row["id"])]
    update_rows = load_instance_entity_update_rows(seed_path)
    comments = load_instance_entity_comments(seed_path)

    entity_by_id = {to_int(row["id"]): row for row in entity_rows}
    events_by_entity: dict[int, list[dict[str, str]]] = defaultdict(list)
    scripts_by_entity: dict[int, list[dict[str, str]]] = defaultdict(list)
    stats_by_entity: dict[int, list[dict[str, str]]] = defaultdict(list)
    for row in event_rows:
        events_by_entity[to_int(row["id"])].append(row)
    for row in script_rows:
        scripts_by_entity[to_int(row["id"])].append(row)
    for row in stat_rows:
        stats_by_entity[to_int(row["id"])].append(row)

    instance_by_world = {to_int(str(row["world_id"])): row for row in instance_rows}

    def context(world_id: int) -> tuple[object, object]:
        instance = instance_by_world.get(world_id)
        if instance:
            return instance["content_type"], instance["name"]
        if world_id:
            return "untracked_instance_world", ""
        return "untracked_instance_entity", ""

    def append_common(
        output: list[dict[str, object]],
        *,
        world_id: int,
        dependency_type: str,
        dependency_id: object,
        entity_id: object = "",
        creature_id: object = "",
        entity_type: object = "",
        area_id: object = "",
        event_id: object = "",
        phase: object = "",
        script_name: object = "",
        stat: object = "",
        value: object = "",
        entity: dict[str, str] | None = None,
        reconciliation_field: object = "",
        reconciliation_value: object = "",
        related_events: str = "",
        related_scripts: str = "",
        related_stats: str = "",
        source_comment: str = "",
        evidence_status: str,
        blocker_summary: str,
    ) -> None:
        content_type, instance_name = context(world_id)
        output.append(
            {
                "content_type": content_type,
                "world_id": world_id,
                "instance_name": instance_name,
                "dependency_type": dependency_type,
                "dependency_id": dependency_id,
                "entity_id": entity_id,
                "creature_id": creature_id,
                "entity_type": entity_type,
                "area_id": area_id,
                "event_id": event_id,
                "phase": phase,
                "script_name": script_name,
                "stat": stat,
                "value": value,
                "x": entity.get("x", "") if entity else "",
                "y": entity.get("y", "") if entity else "",
                "z": entity.get("z", "") if entity else "",
                "rx": entity.get("rx", "") if entity else "",
                "ry": entity.get("ry", "") if entity else "",
                "rz": entity.get("rz", "") if entity else "",
                "display_info": to_int(entity.get("displayInfo") if entity else None),
                "outfit_info": to_int(entity.get("outfitInfo") if entity else None),
                "faction1": to_int(entity.get("faction1") if entity else None),
                "faction2": to_int(entity.get("faction2") if entity else None),
                "quest_checklist_idx": to_int(entity.get("questChecklistIdx") if entity else None),
                "active_prop_id": to_int(entity.get("activePropId") if entity else None),
                "world_socket_id": to_int(entity.get("worldSocketId") if entity else None),
                "mode": to_int(entity.get("mode") if entity else None),
                "reconciliation_field": reconciliation_field,
                "reconciliation_value": reconciliation_value,
                "related_events": related_events,
                "related_scripts": related_scripts,
                "related_stats": related_stats,
                "source_comment": source_comment,
                "evidence_status": evidence_status,
                "evidence_sources": "Tools/DataMapping/sql/laughingws_instance_entity_wip_seed.sql;Tools/DataMapping/extract_laughingws_instance_entities.py;Source/NexusForever.Script.Instance;Decomp/Analysis/LAUGHINGWS_INSTANCES_AND_MORE_AUDIT.md",
                "manual_validation": "pending",
                "completion_status": "not_retail_complete",
                "blocker_summary": blocker_summary,
            }
        )

    output: list[dict[str, object]] = []
    for entity_id in sorted(entity_by_id):
        entity = entity_by_id[entity_id]
        world_id = to_int(entity["world"])
        related_events = ";".join(
            f"{to_int(row['eventId'])}:{to_int(row['phase'])}"
            for row in sorted(events_by_entity.get(entity_id, []), key=lambda item: (to_int(item["eventId"]), to_int(item["phase"])))
        )
        related_scripts = ";".join(row["scriptName"] for row in sorted(scripts_by_entity.get(entity_id, []), key=lambda item: item["scriptName"]))
        related_stats = ";".join(
            f"{to_int(row['stat'])}={to_int(row['value'])}"
            for row in sorted(stats_by_entity.get(entity_id, []), key=lambda item: (to_int(item["stat"]), to_int(item["value"])))
        )
        append_common(
            output,
            world_id=world_id,
            dependency_type="entity",
            dependency_id=entity_id,
            entity_id=entity_id,
            creature_id=to_int(entity["creature"]),
            entity_type=to_int(entity["type"]),
            area_id=to_int(entity["area"]),
            entity=entity,
            related_events=related_events,
            related_scripts=related_scripts,
            related_stats=related_stats,
            source_comment=comments.get(entity_id, ""),
            evidence_status=(
                "reviewed_laughingws_instance_entity_pending_spawn_and_mechanics_smoke"
                if world_id in instance_by_world
                else "reviewed_laughingws_instance_entity_untracked_world"
            ),
            blocker_summary="Reviewed instance placement is tracked, but retail completion needs spawn lifecycle, interaction/combat behavior, choreography, reward/loot hooks, and manual instance smoke.",
        )

    for row in sorted(event_rows, key=lambda item: (to_int(item["id"]), to_int(item["eventId"]), to_int(item["phase"]))):
        entity_id = to_int(row["id"])
        entity = entity_by_id.get(entity_id)
        append_common(
            output,
            world_id=to_int(entity.get("world") if entity else None),
            dependency_type="entity_event",
            dependency_id=f"{entity_id}:event:{to_int(row['eventId'])}:{to_int(row['phase'])}",
            entity_id=entity_id,
            creature_id=to_int(entity.get("creature") if entity else None),
            entity_type=to_int(entity.get("type") if entity else None),
            area_id=to_int(entity.get("area") if entity else None),
            event_id=to_int(row["eventId"]),
            phase=to_int(row["phase"]),
            entity=entity,
            source_comment=comments.get(entity_id, ""),
            evidence_status="reviewed_laughingws_entity_event_pending_phase_smoke",
            blocker_summary="Reviewed entity_event phase binding is tracked, but retail completion needs phase activation, visibility, cleanup timing, and manual instance smoke.",
        )

    for row in sorted(script_rows, key=lambda item: (to_int(item["id"]), item["scriptName"])):
        entity_id = to_int(row["id"])
        entity = entity_by_id.get(entity_id)
        append_common(
            output,
            world_id=to_int(entity.get("world") if entity else None),
            dependency_type="entity_script",
            dependency_id=f"{entity_id}:script:{row['scriptName']}",
            entity_id=entity_id,
            creature_id=to_int(entity.get("creature") if entity else None),
            entity_type=to_int(entity.get("type") if entity else None),
            area_id=to_int(entity.get("area") if entity else None),
            script_name=row["scriptName"],
            entity=entity,
            source_comment=comments.get(entity_id, ""),
            evidence_status="reviewed_laughingws_entity_script_pending_mechanics_smoke",
            blocker_summary="Reviewed entity_script hook is tracked, but retail completion needs exact combat/interaction mechanics, objective credit timing, and manual instance smoke.",
        )

    for row in sorted(stat_rows, key=lambda item: (to_int(item["id"]), to_int(item["stat"]), to_int(item["value"]))):
        entity_id = to_int(row["id"])
        entity = entity_by_id.get(entity_id)
        append_common(
            output,
            world_id=to_int(entity.get("world") if entity else None),
            dependency_type="entity_stats",
            dependency_id=f"{entity_id}:stat:{to_int(row['stat'])}",
            entity_id=entity_id,
            creature_id=to_int(entity.get("creature") if entity else None),
            entity_type=to_int(entity.get("type") if entity else None),
            area_id=to_int(entity.get("area") if entity else None),
            stat=to_int(row["stat"]),
            value=to_int(row["value"]),
            entity=entity,
            source_comment=comments.get(entity_id, ""),
            evidence_status="reviewed_laughingws_entity_stat_pending_combat_smoke",
            blocker_summary="Reviewed entity stat override is tracked, but retail completion needs combat scaling, health/level behavior, and manual instance smoke.",
        )

    for row in sorted(update_rows, key=lambda item: (to_int(item["world"]), to_int(item["creature"]), item["field"], item["x"], item["y"], item["z"])):
        world_id = to_int(row["world"])
        append_common(
            output,
            world_id=world_id,
            dependency_type="official_entity_reconciliation",
            dependency_id=f"{row['world']}:{row['creature']}:{row['x']}:{row['y']}:{row['z']}:{row['field']}",
            creature_id=to_int(row["creature"]),
            area_id=to_int(row["value"]) if row["field"] == "area" else "",
            entity={
                "x": row["x"],
                "y": row["y"],
                "z": row["z"],
            },
            reconciliation_field=row["field"],
            reconciliation_value=row["value"],
            evidence_status="reviewed_official_entity_reconciliation_pending_smoke",
            source_comment=row["comment"],
            blocker_summary="Coordinate-keyed official entity reconciliation is tracked, but retail completion needs official import parity, objective timing, cleanup, and manual Evil from the Ether smoke.",
        )

    return output


def build_instance_reward_rows(
    instance_rows: list[dict[str, object]],
    instance_dependency_rows: list[dict[str, object]],
    reward_rotation_content: list[dict[str, str]],
    reward_rotation_items: list[dict[str, str]],
    reward_rotation_modifiers: list[dict[str, str]],
    reward_rotation_essences: list[dict[str, str]],
    match_type_reward_rotation_content: list[dict[str, str]],
    matching_random_rewards: list[dict[str, str]],
) -> list[dict[str, object]]:
    content_by_id = {to_int(row["ID"]): row for row in reward_rotation_content}
    match_rotation_by_enum: dict[int, list[dict[str, str]]] = defaultdict(list)
    random_rewards_by_enum: dict[int, list[dict[str, str]]] = defaultdict(list)
    for row in match_type_reward_rotation_content:
        match_rotation_by_enum[to_int(row["matchTypeEnum"])].append(row)
    for row in matching_random_rewards:
        random_rewards_by_enum[to_int(row["matchTypeEnum"])].append(row)

    catalog_item_ids = join_ids(sorted(to_int(row["ID"]) for row in reward_rotation_items))
    catalog_modifier_ids = join_ids(sorted(to_int(row["ID"]) for row in reward_rotation_modifiers))
    catalog_essence_ids = join_ids(sorted(to_int(row["ID"]) for row in reward_rotation_essences))

    def append_row(
        output: list[dict[str, object]],
        *,
        instance: dict[str, object],
        reward_source: str,
        source_id: object,
        source_name: object,
        reward_rotation_content_id: int = 0,
        match_type_enum: object = "",
        world_difficulty_enum: object = "",
        reward_item_type: object = "",
        reward_item_object: object = "",
        item2_id: object = "",
        item_count: object = "",
        currency_type_id: object = "",
        currency_value: object = "",
        xp_earned: object = "",
        item2_id_level_scale: object = "",
        item_count_level_scale: object = "",
        currency_type_id_level_scale: object = "",
        currency_value_level_scale: object = "",
        xp_earned_level_scale: object = "",
        evidence_status: str,
        blocker_summary: str,
    ) -> None:
        content = content_by_id.get(reward_rotation_content_id, {})
        output.append(
            {
                "content_type": instance["content_type"],
                "world_id": instance["world_id"],
                "instance_name": instance["name"],
                "reward_source": reward_source,
                "source_id": source_id,
                "source_name": source_name,
                "reward_rotation_content_id": reward_rotation_content_id or "",
                "reward_rotation_content_type": to_int(content.get("contentTypeEnum") if content else None) if reward_rotation_content_id else "",
                "match_type_enum": match_type_enum,
                "world_difficulty_enum": world_difficulty_enum,
                "reward_item_type": reward_item_type,
                "reward_item_object": reward_item_object,
                "item2_id": item2_id,
                "item_count": item_count,
                "currency_type_id": currency_type_id,
                "currency_value": currency_value,
                "xp_earned": xp_earned,
                "item2_id_level_scale": item2_id_level_scale,
                "item_count_level_scale": item_count_level_scale,
                "currency_type_id_level_scale": currency_type_id_level_scale,
                "currency_value_level_scale": currency_value_level_scale,
                "xp_earned_level_scale": xp_earned_level_scale,
                "global_reward_rotation_item_ids": catalog_item_ids,
                "global_reward_rotation_modifier_ids": catalog_modifier_ids,
                "global_reward_rotation_essence_ids": catalog_essence_ids,
                "evidence_status": evidence_status,
                "evidence_sources": "wildstar_client_mysql/World.tbl.sql;wildstar_client_mysql/PublicEvent.tbl.sql;wildstar_client_mysql/MatchingGameMap.tbl.sql;wildstar_client_mysql/MatchTypeRewardRotationContent.tbl.sql;wildstar_client_mysql/MatchingRandomReward.tbl.sql;wildstar_client_mysql/RewardRotation*.tbl.sql;Source/NexusForever.Game/Account/Reward",
                "manual_validation": "pending",
                "completion_status": "not_retail_complete",
                "blocker_summary": blocker_summary,
            }
        )

    instance_by_world = {to_int(str(row["world_id"])): row for row in instance_rows}
    output: list[dict[str, object]] = []

    for instance in sorted(instance_rows, key=lambda item: to_int(str(item["world_id"]))):
        reward_rotation_content_id = to_int(str(instance["reward_rotation_content_id"]))
        if reward_rotation_content_id:
            append_row(
                output,
                instance=instance,
                reward_source="world_reward_rotation_content",
                source_id=instance["world_id"],
                source_name=instance["name"],
                reward_rotation_content_id=reward_rotation_content_id,
                evidence_status="client_world_reward_rotation_content_pending_schedule_claim_smoke",
                blocker_summary="World reward-rotation content is tracked, but retail completion needs schedule selection, grant state, claim behavior, reward presentation, and instance smoke.",
            )

    for dependency in sorted(instance_dependency_rows, key=lambda row: (to_int(str(row["world_id"])), str(row["dependency_type"]), str(row["dependency_id"]))):
        world_id = to_int(str(dependency["world_id"]))
        instance = instance_by_world.get(world_id)
        if not instance:
            continue

        if dependency["dependency_type"] == "public_event":
            reward_rotation_content_id = to_int(str(dependency["reward_rotation_content_id"]))
            if reward_rotation_content_id:
                append_row(
                    output,
                    instance=instance,
                    reward_source="public_event_reward_rotation_content",
                    source_id=dependency["dependency_id"],
                    source_name=dependency["dependency_name"],
                    reward_rotation_content_id=reward_rotation_content_id,
                    evidence_status="client_public_event_reward_rotation_content_pending_event_reward_smoke",
                    blocker_summary="Public-event reward-rotation content is tracked, but retail completion needs event completion, schedule selection, reward grant, and client reward presentation smoke.",
                )

        if dependency["dependency_type"] == "matching_game_map":
            match_type_enum = to_int(str(dependency["match_type_enum"]))
            for match_rotation in sorted(match_rotation_by_enum.get(match_type_enum, []), key=lambda row: to_int(row["ID"])):
                for column, difficulty in (
                    ("rewardRotationContentIdRandomNormal", "random_normal"),
                    ("rewardRotationContentIdRandomVeteran", "random_veteran"),
                ):
                    reward_rotation_content_id = to_int(match_rotation[column])
                    if not reward_rotation_content_id:
                        continue
                    append_row(
                        output,
                        instance=instance,
                        reward_source=f"match_type_reward_rotation_content_{difficulty}",
                        source_id=dependency["dependency_id"],
                        source_name=dependency["dependency_name"],
                        reward_rotation_content_id=reward_rotation_content_id,
                        match_type_enum=match_type_enum,
                        evidence_status="client_match_type_reward_rotation_content_pending_queue_reward_smoke",
                        blocker_summary="Match-type reward-rotation content is tracked, but retail completion needs queue completion, random/veteran selection, schedule grant, and client reward presentation smoke.",
                    )

            for random_reward in sorted(random_rewards_by_enum.get(match_type_enum, []), key=lambda row: to_int(row["ID"])):
                append_row(
                    output,
                    instance=instance,
                    reward_source="matching_random_reward",
                    source_id=random_reward["ID"],
                    source_name=dependency["dependency_name"],
                    match_type_enum=match_type_enum,
                    world_difficulty_enum=to_int(random_reward["worldDifficultyEnum"]),
                    item2_id=to_int(random_reward["item2Id"]),
                    item_count=to_int(random_reward["itemCount"]),
                    currency_type_id=to_int(random_reward["currencyTypeId"]),
                    currency_value=to_int(random_reward["currencyValue"]),
                    xp_earned=to_int(random_reward["xpEarned"]),
                    item2_id_level_scale=to_int(random_reward["item2IdLevelScale"]),
                    item_count_level_scale=to_int(random_reward["itemCountLevelScale"]),
                    currency_type_id_level_scale=to_int(random_reward["currencyTypeIdLevelScale"]),
                    currency_value_level_scale=to_int(random_reward["currencyValueLevelScale"]),
                    xp_earned_level_scale=to_int(random_reward["xpEarnedLevelScale"]),
                    evidence_status="client_matching_random_reward_pending_queue_reward_smoke",
                    blocker_summary="Matching random reward row is tracked, but retail completion needs queue completion, reward roll/selection, grant behavior, and client reward presentation smoke.",
                )

    return output


def write_csv(path: Path, rows: list[dict[str, object]]) -> None:
    if not rows:
        raise ValueError(f"No rows generated for {path}")
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("w", encoding="utf-8", newline="") as handle:
        writer = csv.DictWriter(handle, fieldnames=list(rows[0].keys()))
        writer.writeheader()
        writer.writerows(rows)


def combine_evidence_sources(*values: object) -> str:
    sources: list[str] = []
    seen: set[str] = set()
    for value in values:
        for source in str(value).split(";"):
            source = source.strip()
            if not source or source in seen:
                continue
            seen.add(source)
            sources.append(source)
    return ";".join(sources)


def has_value(value: object) -> bool:
    text = str(value).strip()
    return text not in {"", "0"}


def has_test_source(value: object) -> bool:
    text = str(value)
    return ".Tests" in text or "/Tests/" in text.replace("\\", "/")


def score_quest_queue_candidate(row: dict[str, object], child_rows: list[dict[str, object]] | None = None) -> int:
    if str(row.get("completion_status", "")) != "not_retail_complete":
        return 0
    child_rows = child_rows or []

    bucket = str(row.get("bucket", ""))
    status = str(row.get("evidence_status", ""))
    evidence_sources = str(row.get("evidence_sources", ""))
    score = 0
    base_score = 0

    if bucket in {"curated_partial_stub_script"} or "blocked" in bucket or "partial" in bucket:
        return 0
    if status == MAPPED_ONLY_NO_OBJECTIVE_QUEST_STATUS and not any(
        has_value(row.get(column, ""))
        for column in ("script_paths", "quest2_reward_ids", "related_achievement_ids")
    ):
        return 0

    if status.startswith("implemented_with_focused_tests"):
        base_score = 50
    elif status.startswith("runtime_q"):
        base_score = 45
    elif bucket == "generic_with_script":
        base_score = 25
    elif bucket == "no_objectives" and has_value(row.get("script_paths", "")):
        base_score = 20

    if base_score == 0:
        return 0
    score += base_score

    if has_value(row.get("script_paths", "")):
        score += 15
    if has_test_source(evidence_sources):
        score += 15
    if has_value(row.get("objective_ids", "")):
        score += 10
    if has_value(row.get("quest2_reward_ids", "")):
        score += 10
    if has_value(row.get("related_achievement_ids", "")):
        score += 8
    if has_value(row.get("quest_virtual_loot_groups", "")):
        score += 5
    if "pending_manual_smoke" in status or "pending_world_smoke" in status:
        score += 5
    runtime_child_count = sum(
        1
        for child in child_rows
        if str(child.get("evidence_status", "")).startswith("runtime_q")
    )
    score += min(runtime_child_count * 5, 40)
    if any(has_test_source(child.get("evidence_sources", "")) for child in child_rows):
        score += 15
    if any("reward" in str(child.get("evidence_status", "")) for child in child_rows):
        score += 5
    if any("achievement" in str(child.get("evidence_status", "")) for child in child_rows):
        score += 5
    if any("credit_tested" in str(child.get("evidence_status", "")) for child in child_rows):
        score += 5

    return score


def quest_reward_evidence_blocker_note(rows: list[dict[str, object]]) -> str:
    notes = []
    for row in sorted(rows, key=lambda item: (to_int(str(item.get("source_reward_id"))), to_int(str(item.get("client_reward_object_id"))))):
        canonical_note = f" canonical_reward_ids {row.get('canonical_reward_ids')}" if row.get("canonical_reward_ids") else ""
        notes.append(
            "source_reward_id "
            f"{row.get('source_reward_id')} Item2 {row.get('client_reward_object_id')} "
            f"game_reward_id {row.get('game_reward_id')}{canonical_note}"
        )
    return join_sample(notes, 4)


def quest_reward_evidence_blocker_ids(rows: list[dict[str, object]]) -> str:
    ids = []
    for row in sorted(rows, key=lambda item: (to_int(str(item.get("source_reward_id"))), to_int(str(item.get("client_reward_object_id"))))):
        canonical_ids = row.get("canonical_reward_ids")
        canonical_suffix = f"->{canonical_ids}" if canonical_ids else ""
        ids.append(f"{row.get('source_reward_id')}:{row.get('client_reward_object_id')}:{row.get('game_reward_id')}{canonical_suffix}")
    return join_sample(ids, 8)


def is_current_unfinished_child_evidence_row(row: dict[str, object]) -> bool:
    quest_link_status = str(row.get("quest_link_status", "current_quest"))
    completion_status = str(row.get("completion_status", "not_retail_complete"))
    return quest_link_status == "current_quest" and completion_status == "not_retail_complete"


def is_objective_evidence_blocker(row: dict[str, object]) -> bool:
    if not is_current_unfinished_child_evidence_row(row):
        return False
    status = str(row.get("evidence_status", ""))
    return any(token in status for token in ("unmatched", "blocked", "pending_text_order_smoke", "pending_review"))


def is_zone_evidence_blocker(row: dict[str, object]) -> bool:
    if not is_current_unfinished_child_evidence_row(row):
        return False
    if str(row.get("enabled", "")).lower() == "false":
        return False
    status = str(row.get("evidence_status", ""))
    return any(token in status for token in ("partial_match", "unmatched", "blocked", "pending_zone_review", "pending_runtime_visibility_smoke"))


def is_creature_evidence_blocker(row: dict[str, object]) -> bool:
    if not is_current_unfinished_child_evidence_row(row):
        return False
    exemption_key = (
        to_int(str(row.get("quest_id"))),
        str(row.get("relation_type", "")),
        to_int(str(row.get("source_relation_id"))),
    )
    if exemption_key in QUEST_CREATURE_RELATION_BLOCKER_EXEMPTIONS:
        return False
    status = str(row.get("evidence_status", ""))
    match_status = str(row.get("match_status", ""))
    if to_int(str(row.get("datamapping_unpromoted_spawn_count"))) > 0:
        return True
    return (
        "unmatched" in status
        or "ambiguous" in status
        or "pending_review" in status
        or "pending_spawn" in status
        or "pending_smoke" in status
        or "pending_client_smoke" in status
        or "pending_proof" in status
        or "ambiguous" in match_status
    )


