def quest_queue_reason(
    row: dict[str, object],
    child_rows: list[dict[str, object]] | None = None,
    reward_evidence_blockers: list[dict[str, object]] | None = None,
    objective_evidence_blockers: list[dict[str, object]] | None = None,
    zone_evidence_blockers: list[dict[str, object]] | None = None,
    creature_evidence_blockers: list[dict[str, object]] | None = None,
) -> str:
    child_rows = child_rows or []
    reward_evidence_blockers = reward_evidence_blockers or []
    objective_evidence_blockers = objective_evidence_blockers or []
    zone_evidence_blockers = zone_evidence_blockers or []
    creature_evidence_blockers = creature_evidence_blockers or []
    reasons: list[str] = []
    status = str(row.get("evidence_status", ""))
    if status.startswith("implemented_with_focused_tests"):
        reasons.append("focused runtime tests already cited")
    elif status.startswith("runtime_q"):
        reasons.append("row-specific runtime evidence already cited")
    runtime_child_count = sum(1 for child in child_rows if str(child.get("evidence_status", "")).startswith("runtime_q"))
    if runtime_child_count:
        reasons.append(f"{runtime_child_count} child runtime/test evidence rows")
    if reward_evidence_blockers:
        reasons.append(f"{len(reward_evidence_blockers)} reward-evidence mismatch blocker row(s)")
    if objective_evidence_blockers:
        reasons.append(f"{len(objective_evidence_blockers)} objective-evidence blocker row(s)")
    if zone_evidence_blockers:
        reasons.append(f"{len(zone_evidence_blockers)} zone-evidence blocker row(s)")
    if creature_evidence_blockers:
        reasons.append(f"{len(creature_evidence_blockers)} creature-evidence blocker row(s)")
    if has_value(row.get("script_paths", "")):
        reasons.append(f"script owner `{join_sample(split_joined_values(row.get('script_paths', '')), 3)}`")
    if has_value(row.get("objective_ids", "")):
        reasons.append(f"objectives `{join_sample(split_joined_values(row.get('objective_ids', '')), 6)}`")
    if has_value(row.get("quest2_reward_ids", "")):
        reasons.append(f"rewards `{join_sample(split_joined_values(row.get('quest2_reward_ids', '')), 6)}`")
    if has_value(row.get("related_achievement_ids", "")):
        reasons.append(f"achievements `{join_sample(split_joined_values(row.get('related_achievement_ids', '')), 6)}`")
    return "; ".join(reasons) if reasons else "mapped row with pending validation blockers"


def score_instance_queue_candidate(
    row: dict[str, object],
    producers_by_event: dict[int, list[dict[str, object]]],
    handlers_by_world: dict[int, list[dict[str, object]]],
) -> int:
    if str(row.get("completion_status", "")) != "not_retail_complete":
        return 0
    if not has_value(row.get("script_paths", "")):
        return 0

    event_ids = split_joined_ids(row.get("public_event_ids", ""))
    producer_count = sum(len(producers_by_event.get(event_id, [])) for event_id in event_ids)
    handler_count = len(handlers_by_world.get(to_int(str(row.get("world_id"))), []))
    score = 30
    score += min(to_int(str(row.get("public_event_objective_count"))), 60) // 3
    score += min(producer_count, 30)
    score += min(handler_count, 20)
    if has_value(row.get("related_achievement_ids", "")):
        score += 10
    if has_value(row.get("matching_game_map_ids", "")):
        score += 10
    score += INSTANCE_QUEUE_SCORE_BONUS.get(to_int(str(row.get("world_id"))), 0)
    return score


def queue_priority(score: int) -> str:
    if score >= 100:
        return "P0"
    if score >= 75:
        return "P1"
    return "P2"


