INSTANCE_QUEUE_SCORE_BONUS = {
    382: 25,
    2980: 25,
    3041: 50,
}


def slugify_queue_value(value: object) -> str:
    slug = re.sub(r"[^A-Za-z0-9]+", "-", str(value).lower()).strip("-")
    return slug or "content"


def dotnet_test_command(filter_expression: str) -> str:
    return f'dotnet test Source\\NexusForever.Game.Tests\\NexusForever.Game.Tests.csproj -v minimal --nologo --filter "{filter_expression}"'


def powershell_array(values: Iterable[int | str]) -> str:
    return ",".join(str(value) for value in values if str(value) not in {"", "0"})


def queue_notes(**values: object) -> str:
    parts = []
    for key, value in values.items():
        text = str(value)
        if text in {"", "0"}:
            continue
        parts.append(f"{key}={text}")
    return "; ".join(parts)


def quest_validation_bundle_name(row: dict[str, object]) -> str:
    return f"quest-{row['quest_id']}-{slugify_queue_value(row['name'])}"


def quest_narrow_test_filter(row: dict[str, object]) -> str:
    quest_id = to_int(str(row.get("quest_id")))
    filters = [f"FullyQualifiedName~Q{quest_id}"]
    extra_filter = QUEST_EXTRA_TEST_FILTERS.get(quest_id)
    if extra_filter:
        filters.append(extra_filter)
    return "|".join(filters)


def ordered_unique(values: Iterable[int]) -> list[int]:
    seen: set[int] = set()
    result: list[int] = []
    for value in values:
        if not value or value in seen:
            continue
        seen.add(value)
        result.append(value)
    return result


def quest_harness_command(row: dict[str, object], world_ids: Iterable[int] = ()) -> str:
    quest_id = to_int(str(row.get("quest_id")))
    objective_ids = split_joined_ids(row.get("objective_ids", ""))
    world_ids = ordered_unique([*QUEST_VALIDATION_WORLD_IDS.get(quest_id, ()), *world_ids])
    command_parts = [
        ".\\Decomp\\Analysis\\Start-BlockerEvidenceHarness.ps1",
        f'-BundleName "{quest_validation_bundle_name(row)}"',
        '-ClientDirectory "I:\\WildStar"',
    ]
    if world_ids:
        command_parts.append(f"-WorldIds {powershell_array(world_ids)}")
    if objective_ids:
        command_parts.append(f"-ObjectiveIds {powershell_array(objective_ids)}")
    command_parts.extend(
        [
            '-NegativeCases "missing quest objective", "wrong world/objective", "repeat interaction after completion"',
            f'-Notes "{queue_notes(quest_id=row["quest_id"], rewards=row["quest2_reward_ids"], achievements=row["related_achievement_ids"])}"',
            "-PromptForRootPassword",
        ]
    )
    return " ".join(command_parts)


def instance_validation_bundle_name(row: dict[str, object]) -> str:
    return f"instance-{row['world_id']}-{slugify_queue_value(row['name'])}"


def instance_narrow_test_filter(row: dict[str, object]) -> str:
    world_id = to_int(str(row.get("world_id")))
    return INSTANCE_TEST_FILTERS.get(world_id, f"FullyQualifiedName~{slugify_queue_value(row['name']).replace('-', '')}")


def instance_harness_preset(content_type: object) -> str:
    if str(content_type) == "raid":
        return "-RaidEventSmoke"
    if str(content_type) == "expedition":
        return "-ExpeditionSmoke"
    if str(content_type) == "dungeon":
        return "-DungeonSmoke"
    return ""


def instance_harness_command(row: dict[str, object], objective_ids: list[object]) -> str:
    public_event_ids = split_joined_ids(row.get("public_event_ids", ""))
    objective_ids = [to_int(str(value)) for value in objective_ids if to_int(str(value))]
    preset = instance_harness_preset(row.get("content_type", ""))
    command_parts = [
        ".\\Decomp\\Analysis\\Start-BlockerEvidenceHarness.ps1",
        f'-BundleName "{instance_validation_bundle_name(row)}"',
        '-ClientDirectory "I:\\WildStar"',
        f"-WorldIds {row['world_id']}",
    ]
    if preset:
        command_parts.append(preset)
    if public_event_ids:
        command_parts.append(f"-PublicEventIds {powershell_array(public_event_ids)}")
    if objective_ids:
        command_parts.append(f"-ObjectiveIds {powershell_array(objective_ids)}")
    command_parts.extend(
        [
            '-NegativeCases "missing public event/objective", "wrong phase or trigger", "repeat interaction after completion"',
            f'-Notes "{queue_notes(world_id=row["world_id"], public_events=row["public_event_ids"], achievements=row["related_achievement_ids"])}"',
            "-PromptForRootPassword",
        ]
    )
    return " ".join(command_parts)


def quest_confidence_level(row: dict[str, object]) -> str:
    status = str(row.get("evidence_status", ""))
    if status.startswith("implemented_with_focused_tests"):
        return "implemented_pending_manual_smoke"
    if status.startswith("runtime_q"):
        return "row_specific_runtime_evidence_pending_client_smoke"
    if has_value(row.get("script_paths", "")):
        return "mapped_scripted_row_pending_world_smoke"
    return "mapped_pending_validation"


def instance_confidence_level(row: dict[str, object]) -> str:
    if str(row.get("implementation_status", "")) == "mapped_wip_scaffold":
        return "mapped_wip_scaffold_with_script_evidence"
    return "observed_client_row_pending_implementation"


def instance_queue_reason(
    row: dict[str, object],
    producers_by_event: dict[int, list[dict[str, object]]],
    handlers_by_world: dict[int, list[dict[str, object]]],
) -> str:
    event_ids = split_joined_ids(row.get("public_event_ids", ""))
    producer_count = sum(len(producers_by_event.get(event_id, [])) for event_id in event_ids)
    handler_count = len(handlers_by_world.get(to_int(str(row.get("world_id"))), []))
    reasons = [
        f"public events `{join_sample(event_ids, 6)}`",
        f"{to_int(str(row.get('public_event_objective_count')))} objective rows",
        f"{producer_count} scripted objective producers",
        f"{handler_count} tracked script handlers",
    ]
    if has_value(row.get("related_achievement_ids", "")):
        reasons.append(f"achievements `{join_sample(split_joined_values(row.get('related_achievement_ids', '')), 6)}`")
    return "; ".join(reasons)


def build_next_restoration_slice_queue(
    quest_rows: list[dict[str, object]],
    instance_rows: list[dict[str, object]],
    quest_objective_rows: list[dict[str, object]],
    quest_reward_rows: list[dict[str, object]],
    quest_reward_evidence_rows: list[dict[str, object]],
    quest_creature_rows: list[dict[str, object]],
    quest_objective_evidence_rows: list[dict[str, object]],
    quest_zone_evidence_rows: list[dict[str, object]],
    quest_world_dependency_rows: list[dict[str, object]],
    quest_achievement_rows: list[dict[str, object]],
    script_objective_producer_evidence_rows: list[dict[str, object]],
    instance_script_handler_evidence_rows: list[dict[str, object]],
    instance_dependency_rows: list[dict[str, object]],
    instance_entity_rows: list[dict[str, object]],
    output_dir: Path,
    quest_limit: int = 12,
    instance_limit: int = 11,
) -> list[dict[str, object]]:
    coverage = display_path(output_dir)
    producers_by_event: dict[int, list[dict[str, object]]] = defaultdict(list)
    for producer in script_objective_producer_evidence_rows:
        for event_id in split_joined_ids(producer.get("matched_public_event_ids", "")):
            producers_by_event[event_id].append(producer)

    handlers_by_world: dict[int, list[dict[str, object]]] = defaultdict(list)
    for handler in instance_script_handler_evidence_rows:
        handlers_by_world[to_int(str(handler.get("world_id")))].append(handler)

    public_event_objectives_by_world: dict[int, list[int]] = defaultdict(list)
    for dependency in instance_dependency_rows:
        if str(dependency.get("dependency_type")) != "public_event_objective":
            continue
        world_id = to_int(str(dependency.get("world_id")))
        objective_id = to_int(str(dependency.get("dependency_id")))
        if world_id and objective_id:
            public_event_objectives_by_world[world_id].append(objective_id)

    seed_entity_count_by_world: Counter[int] = Counter()
    for entity_row in instance_entity_rows:
        if str(entity_row.get("dependency_type")) != "entity":
            continue
        world_id = to_int(str(entity_row.get("world_id")))
        if world_id:
            seed_entity_count_by_world[world_id] += 1

    quest_child_rows_by_quest: dict[int, list[dict[str, object]]] = defaultdict(list)
    for child in quest_objective_rows + quest_reward_rows + quest_world_dependency_rows + quest_achievement_rows:
        quest_id = to_int(str(child.get("quest_id")))
        if quest_id:
            quest_child_rows_by_quest[quest_id].append(child)

    quest_reward_evidence_blockers_by_quest: dict[int, list[dict[str, object]]] = defaultdict(list)
    for reward_evidence in quest_reward_evidence_rows:
        if "game_reward_id_mismatch" not in str(reward_evidence.get("evidence_status", "")):
            continue
        quest_id = to_int(str(reward_evidence.get("quest_id")))
        if quest_id:
            quest_reward_evidence_blockers_by_quest[quest_id].append(reward_evidence)

    quest_objective_evidence_blockers_by_quest: dict[int, list[dict[str, object]]] = defaultdict(list)
    for objective_evidence in quest_objective_evidence_rows:
        if not is_objective_evidence_blocker(objective_evidence):
            continue
        quest_id = to_int(str(objective_evidence.get("quest_id")))
        if quest_id:
            quest_objective_evidence_blockers_by_quest[quest_id].append(objective_evidence)

    quest_zone_evidence_blockers_by_quest: dict[int, list[dict[str, object]]] = defaultdict(list)
    for zone_evidence in quest_zone_evidence_rows:
        if not is_zone_evidence_blocker(zone_evidence):
            continue
        quest_id = to_int(str(zone_evidence.get("quest_id")))
        if quest_id:
            quest_zone_evidence_blockers_by_quest[quest_id].append(zone_evidence)

    quest_creature_evidence_blockers_by_quest: dict[int, list[dict[str, object]]] = defaultdict(list)
    for creature in quest_creature_rows:
        if not is_creature_evidence_blocker(creature):
            continue
        quest_id = to_int(str(creature.get("quest_id")))
        if quest_id:
            quest_creature_evidence_blockers_by_quest[quest_id].append(creature)

    quest_world_ids_by_quest: dict[int, list[int]] = defaultdict(list)
    for dependency in quest_world_dependency_rows:
        quest_id = to_int(str(dependency.get("quest_id")))
        world_id = to_int(str(dependency.get("world_id")))
        if quest_id and world_id:
            quest_world_ids_by_quest[quest_id].append(world_id)

    candidates: list[dict[str, object]] = []
    scored_quests = [
        (score_quest_queue_candidate(row, quest_child_rows_by_quest.get(to_int(str(row.get("quest_id"))), [])), row)
        for row in quest_rows
    ]
    for score, row in sorted(scored_quests, key=lambda item: (-item[0], to_int(str(item[1].get("quest_id")))))[:quest_limit]:
        if score <= 0:
            continue
        quest_id = to_int(str(row.get("quest_id")))
        child_rows = quest_child_rows_by_quest.get(to_int(str(row.get("quest_id"))), [])
        reward_evidence_blockers = quest_reward_evidence_blockers_by_quest.get(quest_id, [])
        reward_evidence_blocker_note = quest_reward_evidence_blocker_note(reward_evidence_blockers)
        reward_evidence_blocker_ids = quest_reward_evidence_blocker_ids(reward_evidence_blockers)
        objective_evidence_blockers = quest_objective_evidence_blockers_by_quest.get(quest_id, [])
        objective_evidence_blocker_note = quest_objective_evidence_blocker_note(objective_evidence_blockers)
        objective_evidence_blocker_ids = quest_objective_evidence_blocker_ids(objective_evidence_blockers)
        zone_evidence_blockers = quest_zone_evidence_blockers_by_quest.get(quest_id, [])
        zone_evidence_blocker_note = quest_zone_evidence_blocker_note(zone_evidence_blockers)
        zone_evidence_blocker_ids = quest_zone_evidence_blocker_ids(zone_evidence_blockers)
        creature_evidence_blockers = quest_creature_evidence_blockers_by_quest.get(quest_id, [])
        creature_evidence_blocker_note = quest_creature_evidence_blocker_note(creature_evidence_blockers)
        creature_evidence_blocker_ids = quest_creature_evidence_blocker_ids(creature_evidence_blockers)
        narrow_test_filter = quest_narrow_test_filter(row)
        narrow_test_command = dotnet_test_command(narrow_test_filter)
        required_validation = "Client-visible dialog/receiver flow, objective credit timing, reward grant/presentation, achievement/progression UI, chain/prerequisite behavior, and negative cases named by the source row blockers."
        if reward_evidence_blocker_note:
            required_validation += f" Also reconcile DataMapping/Jabbithole reward-id provenance for {reward_evidence_blocker_note}."
        if objective_evidence_blocker_note:
            required_validation += f" Also reconcile Jabbithole objective evidence for {objective_evidence_blocker_note}."
        if zone_evidence_blocker_note:
            required_validation += f" Also review zone bridge/routing evidence for {zone_evidence_blocker_note}."
        if creature_evidence_blocker_note:
            required_validation += f" Also resolve creature bridge/spawn evidence for {creature_evidence_blocker_note}."
        tracker_paths = f"{coverage / QUEST_CSV_NAME};{coverage / QUEST_OBJECTIVE_CSV_NAME};{coverage / QUEST_REWARD_CSV_NAME};{coverage / QUEST_ACHIEVEMENT_CSV_NAME}"
        if reward_evidence_blockers:
            tracker_paths = f"{tracker_paths};{coverage / QUEST_REWARD_EVIDENCE_CSV_NAME}"
        if objective_evidence_blockers:
            tracker_paths = f"{tracker_paths};{coverage / QUEST_OBJECTIVE_EVIDENCE_CSV_NAME}"
        if zone_evidence_blockers:
            tracker_paths = f"{tracker_paths};{coverage / QUEST_ZONE_EVIDENCE_CSV_NAME}"
        if creature_evidence_blockers:
            tracker_paths = f"{tracker_paths};{coverage / QUEST_CREATURE_CSV_NAME}"
        blocker_summary = f"Queue candidate only; retail completion still blocked by source row blockers: {row['blocker_summary']}"
        if reward_evidence_blocker_note:
            blocker_summary += f" Reward-evidence blocker(s): {reward_evidence_blocker_note} require source provenance review before using Jabbithole game_reward_id values as canonical reward-id proof."
        if objective_evidence_blocker_note:
            blocker_summary += f" Objective-evidence blocker(s): {objective_evidence_blocker_note} require objective bridge/text/order review."
        if zone_evidence_blocker_note:
            blocker_summary += f" Zone-evidence blocker(s): {zone_evidence_blocker_note} require zone bridge and runtime visibility review."
        if creature_evidence_blocker_note:
            blocker_summary += f" Creature-evidence blocker(s): {creature_evidence_blocker_note} require Creature2 bridge, spawn/dialog, and objective-credit review."
        related_ids = f"objectives={row['objective_ids']};rewards={row['quest2_reward_ids']};achievements={row['related_achievement_ids']}"
        if reward_evidence_blocker_ids:
            related_ids += f";reward_evidence_blockers={reward_evidence_blocker_ids}"
        if objective_evidence_blocker_ids:
            related_ids += f";objective_evidence_blockers={objective_evidence_blocker_ids}"
        if zone_evidence_blocker_ids:
            related_ids += f";zone_evidence_blockers={zone_evidence_blocker_ids}"
        if creature_evidence_blocker_ids:
            related_ids += f";creature_evidence_blockers={creature_evidence_blocker_ids}"
        candidates.append(
            {
                "slice_id": f"quest-{row['quest_id']}",
                "lane": "quest",
                "priority": queue_priority(score),
                "content_type": "quest",
                "content_id": row["quest_id"],
                "content_name": row["name"],
                "priority_score": score,
                "source_inventory": QUEST_CSV_NAME,
                "source_row_key": f"quest_id={row['quest_id']}",
                "candidate_reason": quest_queue_reason(
                    row,
                    child_rows,
                    reward_evidence_blockers,
                    objective_evidence_blockers,
                    zone_evidence_blockers,
                    creature_evidence_blockers,
                ),
                "related_ids": related_ids,
                "objective_row_count": "",
                "scripted_producer_count": "",
                "scripted_producer_objective_count": "",
                "scripted_producer_coverage": "",
                "handler_count": "",
                "seed_entity_count": "",
                "confidence_level": quest_confidence_level(row),
                "restoration_goal": "Promote this quest row from mapped/implemented evidence toward verified row-specific gameplay validation without claiming retail completion.",
                "next_action": "Rerun focused quest tests, then capture row-specific client smoke for the remaining blocker fields.",
                "validation_bundle_name": quest_validation_bundle_name(row),
                "narrow_test_filter": narrow_test_filter,
                "narrow_test_command": narrow_test_command,
                "harness_command": quest_harness_command(row, quest_world_ids_by_quest.get(quest_id, [])),
                "required_validation": required_validation,
                "required_tests": narrow_test_command,
                "tracker_paths": tracker_paths,
                "owner_paths": row["script_paths"],
                "suggested_validation": 'dotnet test Source\\NexusForever.Game.Tests\\NexusForever.Game.Tests.csproj -v minimal --nologo --filter "FullyQualifiedName~Quest"; then capture row-specific client smoke for dialog, objective credit, reward, achievement, and chain blockers.',
                "evidence_status": "next_slice_candidate_pending_quest_validation",
                "evidence_sources": combine_evidence_sources(
                    "Decomp/Analysis/CONTENT_RETAIL_COMPLETENESS_TRACKER.md",
                    coverage / QUEST_CSV_NAME,
                    row["evidence_sources"],
                    *(child.get("evidence_sources", "") for child in child_rows),
                    *(blocker.get("evidence_sources", "") for blocker in reward_evidence_blockers),
                    *(blocker.get("evidence_sources", "") for blocker in objective_evidence_blockers),
                    *(blocker.get("evidence_sources", "") for blocker in zone_evidence_blockers),
                    *(blocker.get("evidence_sources", "") for blocker in creature_evidence_blockers),
                ),
                "manual_validation": "pending",
                "completion_status": "not_retail_complete",
                "blocker_summary": blocker_summary,
            }
        )

    scored_instances = [
        (score_instance_queue_candidate(row, producers_by_event, handlers_by_world), row)
        for row in instance_rows
        if str(row.get("milestone_scope", "milestone_target_instance")) == "milestone_target_instance"
    ]
    for score, row in sorted(scored_instances, key=lambda item: (-item[0], to_int(str(item[1].get("world_id")))))[:instance_limit]:
        if score <= 0:
            continue
        event_ids = split_joined_ids(row.get("public_event_ids", ""))
        producer_objectives = [
            producer.get("objective_id", "")
            for event_id in event_ids
            for producer in producers_by_event.get(event_id, [])
        ]
        producer_objective_ids = {
            to_int(str(objective_id))
            for objective_id in producer_objectives
            if to_int(str(objective_id))
        }
        world_id = to_int(str(row.get("world_id")))
        validation_objectives = public_event_objectives_by_world.get(world_id, []) or [to_int(str(value)) for value in producer_objectives if to_int(str(value))]
        narrow_test_filter = instance_narrow_test_filter(row)
        narrow_test_command = dotnet_test_command(narrow_test_filter)
        handler_paths = [
            handler.get("script_path", "")
            for handler in handlers_by_world.get(world_id, [])
        ]
        objective_row_count = to_int(str(row.get("public_event_objective_count")))
        scripted_producer_count = len(producer_objectives)
        scripted_producer_objective_count = len(producer_objective_ids)
        handler_count = len(handlers_by_world.get(world_id, []))
        seed_entity_count = seed_entity_count_by_world.get(world_id, 0)
        candidates.append(
            {
                "slice_id": f"instance-{row['world_id']}",
                "lane": "instance",
                "priority": queue_priority(score),
                "content_type": row["content_type"],
                "content_id": row["world_id"],
                "content_name": row["name"],
                "priority_score": score,
                "source_inventory": INSTANCE_CSV_NAME,
                "source_row_key": f"world_id={row['world_id']}",
                "candidate_reason": instance_queue_reason(row, producers_by_event, handlers_by_world),
                "related_ids": f"public_events={row['public_event_ids']};producer_objectives={join_sample(producer_objectives, 12)};achievements={row['related_achievement_ids']}",
                "objective_row_count": objective_row_count,
                "scripted_producer_count": scripted_producer_count,
                "scripted_producer_objective_count": scripted_producer_objective_count,
                "scripted_producer_coverage": f"{scripted_producer_objective_count}/{objective_row_count}" if objective_row_count else "",
                "handler_count": handler_count,
                "seed_entity_count": seed_entity_count,
                "confidence_level": instance_confidence_level(row),
                "restoration_goal": "Promote this instance row from mapped/WIP scaffold toward verified encounter mechanics and validation bundles without claiming retail completion.",
                "next_action": "Rerun focused instance/public-event tests, then capture manual instance smoke for the named encounter blockers.",
                "validation_bundle_name": instance_validation_bundle_name(row),
                "narrow_test_filter": narrow_test_filter,
                "narrow_test_command": narrow_test_command,
                "harness_command": instance_harness_command(row, validation_objectives),
                "required_validation": "Boss mechanics, public-event phase/objective order, trigger placement and cleanup, portals/queue/difficulty behavior, rewards, loot, achievements, and manual client smoke.",
                "required_tests": narrow_test_command,
                "tracker_paths": f"{coverage / INSTANCE_CSV_NAME};{coverage / INSTANCE_DEPENDENCY_CSV_NAME};{coverage / SCRIPT_OBJECTIVE_PRODUCER_EVIDENCE_CSV_NAME};{coverage / INSTANCE_SCRIPT_HANDLER_EVIDENCE_CSV_NAME}",
                "owner_paths": join_sample(split_joined_values(row.get("script_paths", "")) + handler_paths, 8),
                "suggested_validation": 'dotnet test Source\\NexusForever.Game.Tests\\NexusForever.Game.Tests.csproj -v minimal --nologo --filter "FullyQualifiedName~Instances|FullyQualifiedName~PublicEvents"; then capture manual instance smoke for boss mechanics, phase order, rewards, loot, achievements, and portal/queue flow.',
                "evidence_status": "next_slice_candidate_pending_instance_validation",
                "evidence_sources": combine_evidence_sources(
                    "Decomp/Analysis/CONTENT_RETAIL_COMPLETENESS_TRACKER.md",
                    coverage / INSTANCE_CSV_NAME,
                    coverage / SCRIPT_OBJECTIVE_PRODUCER_EVIDENCE_CSV_NAME,
                    row["evidence_sources"],
                ),
                "manual_validation": "pending",
                "completion_status": "not_retail_complete",
                "blocker_summary": f"Queue candidate only; retail completion still blocked by source row blockers: {row['blocker_summary']}",
            }
        )

    return [
        {"queue_rank": rank, **row}
        for rank, row in enumerate(
            sorted(candidates, key=lambda item: (-to_int(str(item["priority_score"])), str(item["lane"]), to_int(str(item["content_id"])))),
            start=1,
        )
    ]


def open_instance_blocker_row(row: dict[str, object]) -> bool:
    if str(row.get("completion_status", "not_retail_complete")) != "not_retail_complete":
        return False
    status = str(row.get("evidence_status", ""))
    return any(token in status for token in ("pending", "blocked", "wip", "mapped_only", "reviewed"))


