def is_script_runtime_action_blocker(row: dict[str, object]) -> bool:
    if str(row.get("script_scope", "")) != "script_instance":
        return False
    return open_instance_blocker_row(row)


def make_next_slice_blocker_row(
    queue_row: dict[str, object],
    blocker_rank: int,
    category: str,
    source_inventory: str,
    blocker_type: str,
    source_row: dict[str, object],
) -> dict[str, object]:
    source_row_key = blocker_row_source_key(source_row, category)
    evidence_sources = source_row.get("evidence_sources", "")
    if category == "script_runtime_action":
        evidence_sources = combine_evidence_sources(
            evidence_sources,
            source_row.get("client_reference_sources", ""),
            source_row.get("source_trace_sources", ""),
        )
    return {
        "queue_rank": queue_row["queue_rank"],
        "slice_id": queue_row["slice_id"],
        "lane": queue_row["lane"],
        "priority": queue_row["priority"],
        "content_type": queue_row["content_type"],
        "content_id": queue_row["content_id"],
        "content_name": queue_row["content_name"],
        "blocker_rank": blocker_rank,
        "blocker_id": f"{queue_row['slice_id']}:{category}:{source_row_key}",
        "blocker_category": category,
        "blocker_type": blocker_type,
        "source_inventory": source_inventory,
        "source_row_key": source_row_key,
        "related_ids": blocker_related_ids(source_row, category),
        "confidence_level": queue_row.get("confidence_level", ""),
        "required_validation": queue_row.get("required_validation", ""),
        "next_action": blocker_next_action(category),
        "tracker_paths": source_inventory,
        "owner_paths": queue_row.get("owner_paths", ""),
        "evidence_status": source_row.get("evidence_status", ""),
        "evidence_sources": combine_evidence_sources(evidence_sources, queue_row.get("evidence_sources", "")),
        "manual_validation": source_row.get("manual_validation", "pending") or "pending",
        "completion_status": source_row.get("completion_status", "not_retail_complete") or "not_retail_complete",
        "blocker_summary": source_row.get("blocker_summary", "") or queue_row.get("blocker_summary", ""),
    }


def build_next_restoration_slice_blockers(
    next_slice_queue_rows: list[dict[str, object]],
    quest_reward_evidence_rows: list[dict[str, object]],
    quest_reward_rows: list[dict[str, object]],
    quest_objective_rows: list[dict[str, object]],
    quest_creature_rows: list[dict[str, object]],
    quest_objective_evidence_rows: list[dict[str, object]],
    quest_zone_evidence_rows: list[dict[str, object]],
    quest_world_dependency_rows: list[dict[str, object]],
    quest_achievement_rows: list[dict[str, object]],
    quest_prerequisite_rows: list[dict[str, object]],
    quest_loot_rows: list[dict[str, object]],
    script_quest_progression_evidence_rows: list[dict[str, object]],
    quest_script_rows: list[dict[str, object]],
    quest_episode_evidence_rows: list[dict[str, object]],
    instance_dependency_rows: list[dict[str, object]],
    public_event_evidence_rows: list[dict[str, object]],
    instance_portal_evidence_rows: list[dict[str, object]],
    instance_rows: list[dict[str, object]],
    script_event_flow_evidence_rows: list[dict[str, object]],
    script_presentation_evidence_rows: list[dict[str, object]],
    script_objective_producer_evidence_rows: list[dict[str, object]],
    script_runtime_action_evidence_rows: list[dict[str, object]],
    instance_entity_rows: list[dict[str, object]],
    instance_reward_rows: list[dict[str, object]],
    instance_script_handler_evidence_rows: list[dict[str, object]],
) -> list[dict[str, object]]:
    quest_queue_by_id = {
        to_int(str(row.get("content_id"))): row
        for row in next_slice_queue_rows
        if str(row.get("lane")) == "quest"
    }
    instance_queue_by_world = {
        to_int(str(row.get("content_id"))): row
        for row in next_slice_queue_rows
        if str(row.get("lane")) == "instance"
    }
    queue_rows_by_public_event: defaultdict[int, list[dict[str, object]]] = defaultdict(list)
    seen_public_event_slices: set[tuple[int, str]] = set()
    for row in instance_dependency_rows:
        if str(row.get("dependency_type", "")) != "public_event":
            continue
        queue_row = instance_queue_by_world.get(to_int(str(row.get("world_id"))))
        if not queue_row:
            continue
        public_event_id = to_int(str(row.get("public_event_id"))) or to_int(str(row.get("dependency_id")))
        if not public_event_id:
            continue
        event_slice_key = (public_event_id, str(queue_row.get("slice_id", "")))
        if event_slice_key in seen_public_event_slices:
            continue
        seen_public_event_slices.add(event_slice_key)
        queue_rows_by_public_event[public_event_id].append(queue_row)

    queue_rows_by_script_path: defaultdict[str, list[dict[str, object]]] = defaultdict(list)
    seen_script_path_slices: set[tuple[str, str]] = set()
    for row in instance_rows:
        queue_row = instance_queue_by_world.get(to_int(str(row.get("world_id"))))
        if not queue_row:
            continue
        for script_path in split_joined_values(row.get("script_paths", "")):
            path_slice_key = (script_path, str(queue_row.get("slice_id", "")))
            if path_slice_key in seen_script_path_slices:
                continue
            seen_script_path_slices.add(path_slice_key)
            queue_rows_by_script_path[script_path].append(queue_row)

    blockers: list[dict[str, object]] = []
    rank_by_slice: Counter[str] = Counter()

    def append_blocker(queue_row: dict[str, object], category: str, source_inventory: str, blocker_type: str, source_row: dict[str, object]) -> None:
        slice_id = str(queue_row["slice_id"])
        rank_by_slice[slice_id] += 1
        blockers.append(make_next_slice_blocker_row(queue_row, rank_by_slice[slice_id], category, source_inventory, blocker_type, source_row))

    for row in quest_reward_evidence_rows:
        if "game_reward_id_mismatch" not in str(row.get("evidence_status", "")):
            continue
        queue_row = quest_queue_by_id.get(to_int(str(row.get("quest_id"))))
        if queue_row:
            append_blocker(queue_row, "quest_reward_evidence", QUEST_REWARD_EVIDENCE_CSV_NAME, str(row.get("reward_kind", "reward_mismatch")), row)

    for row in quest_objective_rows:
        if not is_quest_objective_blocker(row):
            continue
        queue_row = quest_queue_by_id.get(to_int(str(row.get("quest_id"))))
        if queue_row:
            append_blocker(
                queue_row,
                "quest_objective",
                QUEST_OBJECTIVE_CSV_NAME,
                str(row.get("objective_type") or "quest_objective"),
                row,
            )

    for row in quest_objective_evidence_rows:
        if not is_objective_evidence_blocker(row):
            continue
        queue_row = quest_queue_by_id.get(to_int(str(row.get("quest_id"))))
        if queue_row:
            append_blocker(queue_row, "quest_objective_evidence", QUEST_OBJECTIVE_EVIDENCE_CSV_NAME, str(row.get("match_status", "objective_evidence")), row)

    for row in quest_zone_evidence_rows:
        if not is_zone_evidence_blocker(row):
            continue
        queue_row = quest_queue_by_id.get(to_int(str(row.get("quest_id"))))
        if queue_row:
            append_blocker(queue_row, "quest_zone_evidence", QUEST_ZONE_EVIDENCE_CSV_NAME, str(row.get("match_status", "zone_evidence")), row)

    for row in quest_creature_rows:
        if not is_creature_evidence_blocker(row):
            continue
        queue_row = quest_queue_by_id.get(to_int(str(row.get("quest_id"))))
