def annotate_next_slice_queue_blocker_details(
    next_slice_queue_rows: list[dict[str, object]],
    next_slice_blocker_rows: list[dict[str, object]],
) -> list[dict[str, object]]:
    blockers_by_slice: defaultdict[str, list[dict[str, object]]] = defaultdict(list)
    for blocker in next_slice_blocker_rows:
        blockers_by_slice[str(blocker.get("slice_id", ""))].append(blocker)

    output: list[dict[str, object]] = []
    for queue_row in next_slice_queue_rows:
        slice_id = str(queue_row.get("slice_id", ""))
        blockers = sorted(blockers_by_slice.get(slice_id, []), key=lambda item: to_int(str(item.get("blocker_rank"))))
        category_counts = Counter(str(blocker.get("blocker_category", "")) for blocker in blockers)
        annotated = dict(queue_row)
        annotated["blocker_detail_count"] = len(blockers)
        annotated["blocker_count_by_category"] = format_named_counts(category_counts)
        annotated["blocker_detail_filter"] = f"slice_id={slice_id}"
        annotated["first_blocker_ids"] = join_text_sample((blocker.get("blocker_id", "") for blocker in blockers))
        annotated.update(next_slice_queue_actionability_fields(annotated, len(blockers), category_counts))
        output.append(annotated)

    return output


def parse_producer_coverage(value: object) -> tuple[int, int] | None:
    text = str(value or "").strip()
    if not text or "/" not in text:
        return None
    covered_text, total_text = text.split("/", 1)
    covered = to_int(covered_text)
    total = to_int(total_text)
    if total <= 0:
        return None
    return covered, total


def primary_blocker_category(category_counts: Counter[str]) -> str:
    if not category_counts:
        return ""
    return sorted(category_counts.items(), key=lambda item: (-item[1], item[0]))[0][0]


def blocking_evidence_source_for_category(category: str) -> str:
    if not category:
        return "client_smoke"
    if category.endswith("_evidence") or category in {"quest_creature", "instance_entity", "instance_portal_evidence"}:
        return "datamapping_review"
    if category.startswith("script_") or category in {"quest_script", "instance_script_handler"}:
        return "runtime_test"
    if any(token in category for token in ("reward", "loot", "achievement")):
        return "client_smoke"
    if category in {"instance_dependency", "quest_world_dependency", "quest_objective", "quest_prerequisite"}:
        return "client_smoke"
    return "client_smoke"


def next_slice_queue_actionability_fields(
    queue_row: dict[str, object],
    blocker_count: int,
    category_counts: Counter[str],
) -> dict[str, object]:
    split_reasons: list[str] = []
    if blocker_count > NEXT_SLICE_SPLIT_BLOCKER_DETAIL_THRESHOLD:
        split_reasons.append("blocker_count_gt_100")

    coverage = parse_producer_coverage(queue_row.get("scripted_producer_coverage", ""))
    producer_gap = False
    if coverage is not None:
        covered, total = coverage
        if covered * 100 < total * NEXT_SLICE_SPLIT_PRODUCER_COVERAGE_PERCENT:
            producer_gap = True
            split_reasons.append("producer_coverage_lt_50pct")

    implementation_surface = str(queue_row.get("owner_paths", "")).strip()
    split_required = bool(split_reasons)
    if split_required:
        actionability_state = "split_required_producer_gap" if producer_gap else "split_required_high_blocker_volume"
    elif str(queue_row.get("lane", "")) == "quest" and str(queue_row.get("confidence_level", "")) == "mapped_scripted_row_pending_world_smoke":
        actionability_state = "quest_mapping_then_smoke"
    elif str(queue_row.get("lane", "")) == "quest":
        actionability_state = "quest_validation_ready"
    elif str(queue_row.get("lane", "")) == "instance":
        actionability_state = "instance_validation_ready"
    elif implementation_surface:
        actionability_state = "validation_ready"
    else:
        actionability_state = "mapped_only"

    primary_category = primary_blocker_category(category_counts)
    return {
        "actionability_state": actionability_state,
        "split_required": "true" if split_required else "false",
        "split_reason": ";".join(split_reasons),
        "primary_blocker_category": primary_category,
        "implementation_surface": implementation_surface,
        "retail_claim_allowed": "false",
        "required_evidence_level": "Mapped" if producer_gap else "Verified",
        "blocking_evidence_source": blocking_evidence_source_for_category(primary_category),
    }


def format_top_statuses(counter: Counter[str], limit: int = 6) -> str:
    parts: list[str] = []
    most_common = counter.most_common()
    for status, count in most_common[:limit]:
        parts.append(f"`{status}` ({count})")
    omitted = most_common[limit:]
    if omitted:
        omitted_rows = sum(count for _, count in omitted)
        row_word = "row" if omitted_rows == 1 else "rows"
        status_word = "status" if len(omitted) == 1 else "statuses"
        parts.append(f"omitted statuses: {omitted_rows} {row_word} across {len(omitted)} {status_word}")
    return "; ".join(parts)


